import { utf8Length } from './codec.js';
import { ReinsError } from './protocol.js';
import type { Link } from './protocol.js';

type Msg = string | Uint8Array;

/** Inbound messages held while nobody listens. Beyond this the link closes rather than grow without bound. */
const MAX_INBOUND_QUEUE = 4096;
/** Inbound bytes (UTF-8 bytes of text, length of binary) held while nobody listens, at most. */
const MAX_INBOUND_BYTES = 16 * 1024 * 1024;

function msgBytes(m: Msg): number {
  return typeof m === 'string' ? utf8Length(m) : m.length;
}

/**
 * Shared Link machinery. Inbound messages queue while `onmessage` is null and are
 * delivered in order, asynchronously, once a handler is assigned. The queue is bounded by
 * count and by bytes (`limitInbound` tightens or restores the bound); past either the link
 * closes and the queue is dropped. `onclose` fires exactly once, after queued messages
 * have been handed to a handler; if no `onclose` handler is set when the link closes, it
 * fires when one is assigned.
 */
export abstract class QueueLink implements Link {
  #handler: ((data: Msg) => void) | null = null;
  #onclose: (() => void) | null = null;
  #queue: Msg[] = [];
  #queuedBytes = 0;
  #maxMessages = MAX_INBOUND_QUEUE;
  #maxBytes = MAX_INBOUND_BYTES;
  #flushScheduled = false;
  #draining = false;
  #closed = false;
  #closeFired = false;

  get onmessage(): ((data: Msg) => void) | null {
    return this.#handler;
  }
  set onmessage(fn: ((data: Msg) => void) | null) {
    this.#handler = fn;
    if (fn && this.#queue.length) this.#scheduleFlush();
  }
  get onclose(): (() => void) | null {
    return this.#onclose;
  }
  set onclose(fn: (() => void) | null) {
    this.#onclose = fn;
    if (fn && this.#closed && !this.#closeFired) queueMicrotask(() => this.#maybeFireClose());
  }
  get open(): boolean {
    return !this.#closed;
  }
  abstract readonly bufferedAmount: number;

  /**
   * Bound the inbound queue to `maxMessages` messages and `maxBytes` bytes (each at most
   * the link's default); without arguments, restore the defaults. A queue already past a
   * new bound closes the link.
   */
  limitInbound(maxMessages?: number, maxBytes?: number): void {
    const pick = (v: number | undefined, max: number) => (typeof v === 'number' && Number.isFinite(v) && v >= 0 ? Math.min(Math.floor(v), max) : max);
    this.#maxMessages = pick(maxMessages, MAX_INBOUND_QUEUE);
    this.#maxBytes = pick(maxBytes, MAX_INBOUND_BYTES);
    if (this.#queue.length > this.#maxMessages || this.#queuedBytes > this.#maxBytes) this.#overflow();
  }

  send(data: Msg): void {
    if (this.#closed) return;
    this.transmit(data);
  }

  close(): void {
    if (this.#closed) return;
    this.markClosed();
    this.shutdown();
  }

  /** Put one message on the wire. */
  protected abstract transmit(data: Msg): void;
  /** Release the transport after a local close. */
  protected abstract shutdown(): void;

  /** A message arrived from the transport. */
  protected receive(data: Msg): void {
    if (this.#closed) return;
    if (this.#handler && this.#queue.length === 0 && !this.#draining) {
      this.#invoke(data);
      return;
    }
    const n = msgBytes(data);
    if (this.#queue.length >= this.#maxMessages || this.#queuedBytes + n > this.#maxBytes) {
      this.#overflow();
      return;
    }
    this.#queue.push(data);
    this.#queuedBytes += n;
    if (this.#handler) this.#scheduleFlush();
  }

  /** The queue went past its bound: drop what it holds and close. */
  #overflow(): void {
    this.#queue = [];
    this.#queuedBytes = 0;
    this.close();
  }

  /** The link is closed (locally or by the transport). Idempotent. */
  protected markClosed(): void {
    if (this.#closed) return;
    this.#closed = true;
    queueMicrotask(() => this.#maybeFireClose());
  }

  #invoke(data: Msg): void {
    try {
      this.#handler?.(data);
    } catch {
      // A throwing handler must not break delivery of later messages.
    }
  }

  #scheduleFlush(): void {
    if (this.#flushScheduled) return;
    this.#flushScheduled = true;
    queueMicrotask(() => {
      this.#flushScheduled = false;
      this.#drain();
    });
  }

  #drain(): void {
    if (this.#draining) return;
    this.#draining = true;
    try {
      while (this.#queue.length && this.#handler) {
        const m = this.#queue.shift()!;
        this.#queuedBytes = Math.max(0, this.#queuedBytes - msgBytes(m));
        this.#invoke(m);
      }
    } finally {
      this.#draining = false;
    }
    this.#maybeFireClose();
  }

  #maybeFireClose(): void {
    if (!this.#closed || this.#closeFired || !this.#onclose) return;
    if (this.#queue.length && this.#handler) {
      this.#scheduleFlush();
      return;
    }
    this.#closeFired = true;
    const fn = this.#onclose;
    try {
      fn();
    } catch {
      // ignore
    }
  }
}

// ───────────────────────────── in-memory pair ─────────────────────────────

class PairEnd extends QueueLink {
  peer: PairEnd | null = null;
  readonly bufferedAmount = 0;
  protected transmit(data: Msg): void {
    const copy = typeof data === 'string' ? data : data.slice();
    const peer = this.peer;
    if (peer) queueMicrotask(() => peer.deliver(copy));
  }
  protected shutdown(): void {
    const peer = this.peer;
    // Queued behind every message already in flight, so the far end sees them first.
    if (peer) queueMicrotask(() => peer.remoteClosed());
  }
  deliver(data: Msg): void {
    this.receive(data);
  }
  remoteClosed(): void {
    this.markClosed();
  }
}

/** Two connected in-memory links. Delivery is asynchronous and ordered; closing either end closes both. */
export function linkPair(): [Link, Link] {
  const a = new PairEnd();
  const b = new PairEnd();
  a.peer = b;
  b.peer = a;
  return [a, b];
}

// ───────────────────────────── WebSocket ─────────────────────────────

/**
 * The part of a WebSocket that `wsLink` uses. Satisfied by the browser and Node global
 * `WebSocket` and by the `ws` package's socket.
 */
export interface WebSocketLike {
  readonly readyState: number;
  binaryType?: string;
  readonly bufferedAmount?: number;
  send(data: string | Uint8Array): void;
  close(code?: number, reason?: string): void;
  onopen: ((ev: any) => void) | null;
  onmessage: ((ev: any) => void) | null;
  onclose: ((ev: any) => void) | null;
  onerror: ((ev: any) => void) | null;
}

const WS_CONNECTING = 0;
const WS_OPEN = 1;

/** Binary payload as a standalone Uint8Array, or null when `v` is not binary. */
function toBytes(v: unknown): Uint8Array | null {
  if (v instanceof ArrayBuffer) return new Uint8Array(v.slice(0));
  if (ArrayBuffer.isView(v)) return new Uint8Array(v.buffer, v.byteOffset, v.byteLength).slice();
  return null;
}

class WsLink extends QueueLink {
  #ws: WebSocketLike;
  constructor(ws: WebSocketLike) {
    super();
    this.#ws = ws;
  }
  get bufferedAmount(): number {
    const n = this.#ws.bufferedAmount;
    return typeof n === 'number' ? n : 0;
  }
  protected transmit(data: Msg): void {
    if (this.#ws.readyState !== WS_OPEN) return;
    try {
      this.#ws.send(data);
    } catch {
      this.close();
    }
  }
  protected shutdown(): void {
    try {
      this.#ws.close(1000);
    } catch {
      // already closing
    }
  }
  inbound(ev: { data?: unknown } | undefined): void {
    const d = ev?.data;
    if (typeof d === 'string') this.receive(d);
    else {
      const bytes = toBytes(d);
      if (bytes) this.receive(bytes);
    }
  }
  remoteClosed(): void {
    this.markClosed();
  }
}

/**
 * Wrap a WebSocket. Resolves once the socket is open (at once if it already is); rejects
 * with `E_GONE` if it errors or closes before opening.
 */
export function wsLink(ws: WebSocketLike): Promise<Link> {
  try {
    ws.binaryType = 'arraybuffer';
  } catch {
    // not settable on this implementation
  }
  const link = new WsLink(ws);
  ws.onmessage = (ev) => link.inbound(ev);
  const opened = () => {
    ws.onopen = null;
    ws.onerror = () => {};
    ws.onclose = () => link.remoteClosed();
  };
  if (ws.readyState === WS_OPEN) {
    opened();
    return Promise.resolve(link);
  }
  if (ws.readyState !== WS_CONNECTING) return Promise.reject(new ReinsError('E_GONE', 'connection closed'));
  return new Promise((resolve, reject) => {
    const failed = () => {
      ws.onopen = ws.onerror = ws.onclose = ws.onmessage = null;
      try {
        ws.close();
      } catch {
        // ignore
      }
      reject(new ReinsError('E_GONE', 'connection failed'));
    };
    ws.onopen = () => {
      opened();
      resolve(link);
    };
    ws.onerror = failed;
    ws.onclose = failed;
  });
}

// ───────────────────────────── MessagePort ─────────────────────────────

/** The part of a MessagePort that `portLink` uses. */
export interface MessagePortLike {
  postMessage(data: unknown): void;
  onmessage: ((ev: any) => void) | null;
  start?(): void;
  close?(): void;
}

class PortLink extends QueueLink {
  #port: MessagePortLike;
  readonly bufferedAmount = 0;
  constructor(port: MessagePortLike) {
    super();
    this.#port = port;
    port.onmessage = (ev) => this.#inbound(ev);
    port.start?.();
  }
  protected transmit(data: Msg): void {
    try {
      this.#port.postMessage(typeof data === 'string' ? data : data.slice());
    } catch {
      this.close();
    }
  }
  protected shutdown(): void {
    try {
      // `null` is neither a text nor a binary frame: it tells the far end we closed.
      this.#port.postMessage(null);
    } catch {
      // ignore
    }
    this.#port.onmessage = null;
    try {
      this.#port.close?.();
    } catch {
      // ignore
    }
  }
  #inbound(ev: { data?: unknown } | undefined): void {
    const d = ev?.data;
    if (d === null) {
      this.#port.onmessage = null;
      this.markClosed();
      try {
        this.#port.close?.();
      } catch {
        // ignore
      }
      return;
    }
    if (typeof d === 'string') this.receive(d);
    else {
      const bytes = toBytes(d);
      if (bytes) this.receive(bytes);
    }
  }
}

/**
 * Wrap a MessagePort. Text frames travel as strings, binary frames as Uint8Array. Closing
 * posts `null`, which the far end's `portLink` takes as a close.
 */
export function portLink(port: MessagePortLike): Link {
  return new PortLink(port);
}
