import { CHAT_RELAY, LEVELS, METHOD_SCOPE, NAME_PATTERN, POLICY_PRESETS, ReinsError, SCOPES } from './protocol.js';
import type { ChatRelay, Decision, Exposure, Level, Policy, PolicyInput, PolicyProfile, Risk, Scope } from './protocol.js';
import { hasOwn, isPlainObject } from './util.js';

const DECISIONS: readonly Decision[] = ['allow', 'confirm', 'deny'];
const PROFILES: readonly PolicyProfile[] = ['open', 'guarded', 'kiosk'];
const EXPOSURES: readonly Exposure[] = ['auto', 'annotated', 'none'];
const RISKS: readonly Risk[] = ['safe', 'sensitive', 'dangerous'];
const PREFIX_PATTERN = /^[a-z][a-z0-9_]*(\.[a-z][a-z0-9_]*)*\.\*$/;

const TOP_KEYS = ['profile', 'scopes', 'attach', 'risk', 'actions', 'exposure', 'privateInput', 'coordinates', 'framed', 'nav', 'chatRelay', 'rates', 'pointerRate', 'ttlMs', 'idleMs', 'human', 'consent'];

function fail(field: string, why: string): never {
  throw new ReinsError('E_BAD_ARGS', `policy.${field}: ${why}`);
}

function clonePolicy(p: Policy): Policy {
  return {
    ...p,
    scopes: [...p.scopes],
    risk: { ...p.risk },
    actions: { ...p.actions },
    nav: [...p.nav],
    rates: { ...p.rates },
    human: { ...p.human, levels: [...p.human.levels] },
    consent: { ...p.consent },
  };
}

function decision(v: unknown, field: string): Decision {
  if (!DECISIONS.includes(v as Decision)) fail(field, 'must be allow, confirm or deny');
  return v as Decision;
}
function bool(v: unknown, field: string): boolean {
  if (typeof v !== 'boolean') fail(field, 'must be a boolean');
  return v;
}
function nonNeg(v: unknown, field: string): number {
  if (typeof v !== 'number' || !Number.isFinite(v) || v < 0) fail(field, 'must be a non-negative number');
  return v;
}
function positive(v: unknown, field: string): number {
  if (typeof v !== 'number' || !Number.isFinite(v) || v <= 0) fail(field, 'must be a positive number');
  return v;
}
function subObject(v: unknown, field: string, keys: readonly string[]): Record<string, unknown> {
  if (!isPlainObject(v)) fail(field, 'must be an object');
  for (const k of Object.keys(v)) if (!keys.includes(k)) fail(`${field}.${k}`, 'unknown field');
  return v;
}

/**
 * A validated deep copy of a preset with overrides applied. No input means `guarded`.
 * An object input starts from `input.profile` (default `guarded`); nested objects merge
 * one level deep, arrays replace. Unknown fields and bad values throw `E_BAD_ARGS`.
 */
export function resolvePolicy(input?: PolicyInput): Policy {
  if (input === undefined) return clonePolicy(POLICY_PRESETS.guarded);
  if (typeof input === 'string') {
    if (!PROFILES.includes(input)) fail('profile', 'unknown profile');
    return clonePolicy(POLICY_PRESETS[input]);
  }
  if (!isPlainObject(input)) fail('profile', 'policy must be a profile name or an object');
  const o = input as Record<string, unknown>;
  for (const k of Object.keys(o)) if (!TOP_KEYS.includes(k)) fail(k, 'unknown field');

  const profile = o.profile === undefined ? 'guarded' : (o.profile as PolicyProfile);
  if (!PROFILES.includes(profile)) fail('profile', 'unknown profile');
  const p = clonePolicy(POLICY_PRESETS[profile]);

  if (o.scopes !== undefined) {
    if (!Array.isArray(o.scopes) || !o.scopes.every((s) => SCOPES.includes(s as Scope))) fail('scopes', 'must list known scopes');
    p.scopes = capScopes(o.scopes as Scope[]);
  }
  if (o.attach !== undefined) p.attach = decision(o.attach, 'attach');
  if (o.risk !== undefined) {
    const r = subObject(o.risk, 'risk', RISKS);
    for (const k of Object.keys(r)) if (r[k] !== undefined) p.risk[k as Risk] = decision(r[k], `risk.${k}`);
  }
  if (o.actions !== undefined) {
    if (!isPlainObject(o.actions)) fail('actions', 'must be an object');
    const a = o.actions;
    for (const k of Object.keys(a)) {
      // NAME_PATTERN never admits __proto__; `constructor` is stored as an own key and read with hasOwn.
      if (k.length > 66 || (!NAME_PATTERN.test(k) && !PREFIX_PATTERN.test(k))) fail(`actions[${JSON.stringify(k.slice(0, 64))}]`, 'must be an action name or a prefix ending in .*');
      Object.defineProperty(p.actions, k, { value: decision(a[k], `actions.${k}`), enumerable: true, writable: true, configurable: true });
    }
  }
  if (o.exposure !== undefined) {
    if (!EXPOSURES.includes(o.exposure as Exposure)) fail('exposure', 'must be auto, annotated or none');
    p.exposure = o.exposure as Exposure;
  }
  if (o.privateInput !== undefined) p.privateInput = bool(o.privateInput, 'privateInput');
  if (o.coordinates !== undefined) p.coordinates = bool(o.coordinates, 'coordinates');
  if (o.framed !== undefined) p.framed = bool(o.framed, 'framed');
  if (o.nav !== undefined) {
    if (!Array.isArray(o.nav) || !o.nav.every((x) => typeof x === 'string' && x.startsWith('/') && !x.startsWith('//'))) fail('nav', 'must be path prefixes starting with /');
    p.nav = [...(o.nav as string[])];
  }
  if (o.chatRelay !== undefined) {
    // The two values a policy held before there were three still read as what they meant.
    const v = o.chatRelay === true ? 'on' : o.chatRelay === false ? 'off' : o.chatRelay;
    if (!CHAT_RELAY.includes(v as ChatRelay)) fail('chatRelay', 'must be off, person or on');
    p.chatRelay = v as ChatRelay;
  }
  if (o.rates !== undefined) {
    const r = subObject(o.rates, 'rates', SCOPES);
    for (const k of Object.keys(r)) if (r[k] !== undefined) p.rates[k as Scope] = nonNeg(r[k], `rates.${k}`);
  }
  if (o.pointerRate !== undefined) p.pointerRate = nonNeg(o.pointerRate, 'pointerRate');
  if (o.ttlMs !== undefined) p.ttlMs = positive(o.ttlMs, 'ttlMs');
  if (o.idleMs !== undefined) p.idleMs = positive(o.idleMs, 'idleMs');
  if (o.human !== undefined) {
    const h = subObject(o.human, 'human', ['yieldMs', 'pause', 'stop', 'levels', 'panel']);
    if (h.yieldMs !== undefined) p.human.yieldMs = nonNeg(h.yieldMs, 'human.yieldMs');
    if (h.pause !== undefined) p.human.pause = bool(h.pause, 'human.pause');
    if (h.stop !== undefined) p.human.stop = bool(h.stop, 'human.stop');
    if (h.levels !== undefined) {
      const l = h.levels;
      if (!Array.isArray(l) || !l.every((x) => LEVELS.includes(x as Level))) fail('human.levels', `must list known levels (${LEVELS.join(', ')})`);
      p.human.levels = LEVELS.filter((x) => l.includes(x));
    }
    if (h.panel !== undefined) p.human.panel = bool(h.panel, 'human.panel');
  }
  if (o.consent !== undefined) {
    const c = subObject(o.consent, 'consent', ['timeoutMs', 'remember']);
    if (c.timeoutMs !== undefined) p.consent.timeoutMs = positive(c.timeoutMs, 'consent.timeoutMs');
    if (c.remember !== undefined) {
      if (c.remember !== 'never' && c.remember !== 'session') fail('consent.remember', 'must be never or session');
      p.consent.remember = c.remember;
    }
  }
  return p;
}

/** Strictness order: allow < confirm < deny. Anything unrecognised counts as deny. */
function rank(d: Decision): number {
  const i = DECISIONS.indexOf(d);
  return i < 0 ? 2 : i;
}

export function stricter(a: Decision, b: Decision): Decision {
  return DECISIONS[Math.max(rank(a), rank(b))]!;
}

/** Override by exact name, then by the longest matching `prefix.*`, then by risk tier. Fails closed to `deny`. */
export function decideAction(policy: Policy, action: { name: string; risk: Risk }): Decision {
  const overrides = policy.actions;
  if (hasOwn(overrides, action.name)) return DECISIONS[rank(overrides[action.name]!)]!;
  let best: string | undefined;
  for (const key of Object.keys(overrides)) {
    if (!key.endsWith('.*')) continue;
    const prefix = key.slice(0, -1); // keeps the dot: "cart."
    if (action.name.startsWith(prefix) && (best === undefined || key.length > best.length)) best = key;
  }
  if (best !== undefined) return DECISIONS[rank(overrides[best]!)]!;
  return hasOwn(policy.risk, action.risk) ? DECISIONS[rank(policy.risk[action.risk])]! : 'deny';
}

/**
 * The levels on offer to the person for one grant: `strict` and `ask` always (neither lets an
 * agent do more than the policy does), and each of `auto` and `bypass` that every given list
 * names (the surface policy's `human.levels` and the hub's). Least to most permissive.
 */
export function capLevels(...lists: readonly (readonly Level[])[]): Level[] {
  return LEVELS.filter((l) => l === 'ask' || l === 'strict' || lists.every((c) => Array.isArray(c) && c.includes(l)));
}

/**
 * The settings of an earlier grant that stay for the next grant of the same agent, read from
 * what a surface (or a hub) sent: only what tightens. `granted` are the scopes of the new
 * grant and `actions` the names the surface declares; anything else, and anything malformed,
 * is left out. Never throws.
 */
export function keptSettings(v: unknown, granted: readonly Scope[], actions: Iterable<string>): { level: 'strict' | undefined; rules: Map<string, 'confirm' | 'deny'>; off: Scope[] } {
  const out = { level: undefined as 'strict' | undefined, rules: new Map<string, 'confirm' | 'deny'>(), off: [] as Scope[] };
  if (!isPlainObject(v)) return out;
  if (hasOwn(v, 'level') && v.level === 'strict') out.level = 'strict';
  const rules = hasOwn(v, 'rules') ? v.rules : undefined;
  if (isPlainObject(rules)) {
    for (const name of actions) {
      const d = hasOwn(rules, name) ? rules[name] : undefined;
      if (d === 'confirm' || d === 'deny') out.rules.set(name, d);
    }
  }
  const off = hasOwn(v, 'off') ? v.off : undefined;
  if (Array.isArray(off)) out.off = granted.filter((x) => off.includes(x));
  return out;
}

/**
 * What a hub's policy decides for each action of a surface, by action name: the hub sends
 * this with `attach` as `decisions` (SPEC section 8), so that the surface knows which actions
 * the hub confirms (`c:1`) and which it refuses.
 */
export function actionDecisions(policy: Policy, actions: readonly { name: string; risk: Risk }[]): Record<string, Decision> {
  const out: Record<string, Decision> = {};
  // Own properties only, set by definition: an action may be called `constructor`.
  for (const a of actions) Object.defineProperty(out, a.name, { value: decideAction(policy, a), enumerable: true, writable: true, configurable: true });
  return out;
}

/**
 * The hub's decision for one action, read from the `decisions` of an `attach` request.
 * Anything missing or malformed (no object, no own entry for the name, a value that is no
 * decision) is `confirm`: a hub that does not say may confirm anything.
 */
export function hubDecision(decisions: unknown, name: string): Decision {
  if (!isPlainObject(decisions) || !hasOwn(decisions, name)) return 'confirm';
  const d = decisions[name];
  return d === 'allow' || d === 'confirm' || d === 'deny' ? d : 'confirm';
}

/**
 * May the person's rule `allow` waive a prompt the policy demands for an action of this
 * risk: only where a level on offer would waive the same prompt. That is `auto` or `bypass`
 * for an action that is not dangerous, and `bypass` for a dangerous one.
 */
export function allowRulePermitted(risk: Risk, offered: readonly Level[]): boolean {
  if (offered.includes('bypass')) return true;
  return (risk === 'safe' || risk === 'sensitive') && offered.includes('auto');
}

export interface ActQuery {
  /** What the surface's policy says for the action (`decideAction`). */
  base: Decision;
  risk: Risk;
  /** The request carries `c:1`: the hub's policy demands a confirmation. */
  c?: boolean;
  /** The level the person set for this grant. */
  level: Level;
  /** The person's rule for this action under this grant, if there is one. */
  rule?: Decision;
  /** The levels on offer for this grant (`capLevels`). */
  offered: readonly Level[];
}

export interface ActVerdict {
  /**
   * `run`: no prompt. `prompt`: ask the person. `denied`: the policy says no (`E_DENIED`).
   * `blocked`: the person's rule says no (`E_CONSENT`).
   */
  outcome: 'run' | 'prompt' | 'denied' | 'blocked';
  /**
   * With `run`, why nobody is asked. `policy`: no prompt was needed. `level` or `rule`: one
   * was needed and what the person set waived it.
   */
  by?: 'policy' | 'level' | 'rule';
  /**
   * With `prompt`: approvals of this action may be remembered (`consent.remember: session`).
   * False under the level `strict` and under a rule `confirm`, which ask every time. A
   * request that carries `c:1` is never answered from memory, whatever this says.
   */
  remember?: boolean;
}

/**
 * Whether an `act` request runs, asks or is refused (SPEC section 12, "Levels and rules"),
 * from the policy's decision, the request's `c:1`, and what the person set for the grant.
 *
 *  1. The policy decision, made `confirm` at least by `c:1`. `deny` is final: `denied`.
 *  2. The person's rule `deny`: `blocked`.
 *  3. A prompt is needed when the decision is `confirm`, the level is `strict`, or the rule is `confirm`.
 *  4. A needed prompt is waived by the rule `allow`, by the level `bypass`, and by the level
 *     `auto` unless the risk is `dangerous`. A rule beats the level.
 *  5. The rule `allow` waives a prompt the policy demands only where `allowRulePermitted`.
 *
 * Anything unrecognised fails closed: an unknown decision or rule counts as `deny`, an
 * unknown risk as `dangerous`, an unknown level as `strict`, and `auto` or `bypass` that
 * is not on offer as `ask`.
 */
export function decideAct(q: ActQuery): ActVerdict {
  const base = q.c ? stricter(q.base, 'confirm') : DECISIONS[rank(q.base)]!;
  if (base === 'deny') return { outcome: 'denied' };
  const rule = q.rule === undefined ? undefined : DECISIONS[rank(q.rule)]!;
  if (rule === 'deny') return { outcome: 'blocked' };
  const offered = Array.isArray(q.offered) ? q.offered : [];
  let level: Level = LEVELS.includes(q.level) ? q.level : 'strict';
  if ((level === 'auto' || level === 'bypass') && !offered.includes(level)) level = 'ask';
  const risk: Risk = q.risk === 'safe' || q.risk === 'sensitive' ? q.risk : 'dangerous';

  if (base !== 'confirm' && level !== 'strict' && rule !== 'confirm') return { outcome: 'run', by: 'policy' };
  if (rule === 'confirm') return { outcome: 'prompt', remember: false };
  if (rule === 'allow' && (base !== 'confirm' || allowRulePermitted(risk, offered))) return { outcome: 'run', by: 'rule' };
  if (level === 'bypass' || (level === 'auto' && risk !== 'dangerous')) return { outcome: 'run', by: 'level' };
  return { outcome: 'prompt', remember: level !== 'strict' };
}

/** Intersection of `requested` with every given cap, in canonical scope order. An undefined cap does not restrict. */
export function capScopes(requested: Scope[], ...caps: (Scope[] | undefined)[]): Scope[] {
  return SCOPES.filter((s) => requested.includes(s) && caps.every((c) => c === undefined || c.includes(s)));
}

export function methodScope(m: string): Scope | undefined {
  return hasOwn(METHOD_SCOPE, m) ? METHOD_SCOPE[m] : undefined;
}

function pathUnder(path: string, prefix: string): boolean {
  if (prefix.endsWith('/')) return path.startsWith(prefix);
  return path === prefix || path.startsWith(`${prefix}/`);
}

/**
 * May `nav.go` open `url` from a page at `pageUrl`. The URL is resolved against the page
 * and must be `http:`/`https:`, same-origin, without credentials, and its normalised path
 * must sit under one of `policy.nav` (`/shop` covers `/shop` and `/shop/x`, not `/shopping`).
 * Paths carrying encoded dots, slashes or backslashes are refused.
 */
export function navAllowed(policy: Policy, url: string, pageUrl: string): boolean {
  if (!Array.isArray(policy.nav) || policy.nav.length === 0) return false;
  if (typeof url !== 'string' || typeof pageUrl !== 'string') return false;
  let page: URL;
  let target: URL;
  try {
    page = new URL(pageUrl);
    target = new URL(url, page);
  } catch {
    return false;
  }
  const web = (u: URL) => u.protocol === 'http:' || u.protocol === 'https:';
  if (!web(page) || !web(target)) return false;
  if (target.origin !== page.origin) return false;
  if (target.username || target.password) return false;
  const path = target.pathname;
  if (/%(2e|2f|5c)/i.test(path)) return false;
  return policy.nav.some((prefix) => typeof prefix === 'string' && prefix.startsWith('/') && pathUnder(path, prefix));
}

/**
 * The schemes whose URLs have a web origin (SPEC 5, "Origins"). A URL library gives these
 * the same origin everywhere; for every other scheme it is `null` in some engines and not
 * in others, which is why nothing below asks it.
 */
const WEB_SCHEMES: ReadonlySet<string> = new Set(['http:', 'https:', 'ws:', 'wss:', 'ftp:']);

/** The origin of every `file:` URL. */
const FILE_ORIGIN = 'file://';

/**
 * `scheme://host` or `scheme://host:port`, lower case, as an app origin is written. The host
 * is whatever Chromium keeps of one: `app://-` and `app://.` are origins it reports (the
 * defaults of common Electron serving libraries), and so is a host that ends in a dot.
 */
const APP_ORIGIN = /^([a-z][a-z0-9+.-]*):\/\/([a-z0-9._-]+)(?::([1-9][0-9]{0,4}))?$/;

interface AppOrigin {
  scheme: string;
  host: string;
  port: string;
}

/** The parts of an app origin, or null when `s` is not one: a web scheme and `file` have forms of their own. */
function appOrigin(s: string): AppOrigin | null {
  const m = APP_ORIGIN.exec(s);
  if (!m) return null;
  const scheme = m[1]!;
  if (scheme === 'file' || scheme === 'blob' || WEB_SCHEMES.has(`${scheme}:`)) return null;
  if (m[3] !== undefined && Number(m[3]) > 65_535) return null;
  return { scheme, host: m[2]!, port: m[3] ?? '' };
}

/**
 * The origin of a URL as Reins compares origins (SPEC 5, "Origins"), or null when `url`
 * is not a URL:
 *
 *   http:, https:, ws:, wss:, ftp:   the web origin, `scheme://host[:port]`
 *   file:                            `file://`, whatever the host and path
 *   blob:                            the web origin of an http(s) URL after `blob:`, else `null`
 *   any other scheme                 the app origin `scheme://host[:port]` when the URL has a
 *                                    host after `//` (credentials dropped, lower case), else `null`
 *
 * The authority of an app-scheme URL is read from the text, so the answer does not depend
 * on which engine parsed it.
 */
export function urlOrigin(url: string): string | null {
  if (typeof url !== 'string') return null;
  let u: URL;
  try {
    u = new URL(url);
  } catch {
    return null;
  }
  if (WEB_SCHEMES.has(u.protocol)) return u.origin;
  if (u.protocol === 'file:') return FILE_ORIGIN;
  if (u.protocol === 'blob:') {
    try {
      const inner = new URL(u.href.slice('blob:'.length));
      return inner.protocol === 'http:' || inner.protocol === 'https:' ? inner.origin : 'null';
    } catch {
      return 'null';
    }
  }
  const rest = u.href.slice(u.protocol.length);
  if (!rest.startsWith('//')) return 'null';
  let authority = rest.slice(2);
  const end = authority.search(/[/?#]/);
  if (end !== -1) authority = authority.slice(0, end);
  const at = authority.lastIndexOf('@');
  if (at !== -1) authority = authority.slice(at + 1);
  const o = `${u.protocol}//${authority.toLowerCase()}`;
  return appOrigin(o) !== null ? o : 'null';
}

/**
 * Does `url` have the origin of the connection it came over (`hello.surface.url`, SPEC 5)?
 * Its origin must equal `origin`. A connection whose origin is `null` takes any URL that
 * has no web origin, since an opaque origin does not say where its page was loaded from.
 */
export function urlHasOrigin(url: string, origin: string): boolean {
  const o = urlOrigin(url);
  if (o === null || typeof origin !== 'string') return false;
  if (origin !== 'null') return o === origin;
  return o === 'null' || o === FILE_ORIGIN || appOrigin(o) !== null;
}

/** Serialised origin of `s`, or null when `s` is not a bare web origin (path, query, credentials, or another scheme). */
function bareOrigin(s: string, allowSlash: boolean): string | null {
  let u: URL;
  try {
    u = new URL(s);
  } catch {
    return null;
  }
  // Only web schemes: an engine that reports an origin for an app scheme must not widen `*`.
  if (!WEB_SCHEMES.has(u.protocol)) return null;
  if (u.origin === 'null' || u.username || u.password || u.search || u.hash) return null;
  if (u.pathname !== '/' && u.pathname !== '') return null;
  if (!allowSlash && s.endsWith('/')) return null;
  return u.origin;
}

const PORT_WILDCARD = /^([a-zA-Z][a-zA-Z0-9+.-]*):\/\/(\[[0-9a-fA-F:.]+\]|[^/:@\[\]]+):\*$/;

/** One optional trailing `/` off an allowlist entry, as an exact web entry may carry one. */
function entryText(p: string): string {
  return (p.endsWith('/') && !p.endsWith('//') ? p.slice(0, -1) : p).toLowerCase();
}

/**
 * Does `origin` match one of `patterns`: an exact origin, `scheme://host:*` for any
 * port of that host, or `*`. `*` matches web origins only: `file://`, an app origin
 * (`app://notes`) and the opaque origin `null` match only an entry that names them.
 */
export function originAllowed(origin: string, patterns: string[]): boolean {
  if (typeof origin !== 'string' || !Array.isArray(patterns)) return false;
  if (origin === 'null') return patterns.includes('null');
  if (origin === FILE_ORIGIN) return patterns.some((p) => p === FILE_ORIGIN || p === `${FILE_ORIGIN}/`);
  const app = appOrigin(origin);
  if (app !== null) {
    for (const p of patterns) {
      if (typeof p !== 'string') continue;
      const m = PORT_WILDCARD.exec(p);
      if (m) {
        if (m[1]!.toLowerCase() === app.scheme && m[2]!.toLowerCase() === app.host) return true;
        continue;
      }
      const e = appOrigin(entryText(p));
      if (e !== null && e.scheme === app.scheme && e.host === app.host && e.port === app.port) return true;
    }
    return false;
  }
  const o = bareOrigin(origin, false);
  if (o === null) return false;
  const u = new URL(o);
  for (const p of patterns) {
    if (typeof p !== 'string') continue;
    if (p === '*') return true;
    const m = PORT_WILDCARD.exec(p);
    if (m) {
      let host: URL;
      try {
        host = new URL(`${m[1]}://${m[2]}`);
      } catch {
        continue;
      }
      if (host.protocol === u.protocol && host.hostname === u.hostname) return true;
      continue;
    }
    const exact = bareOrigin(p, true);
    if (exact !== null && exact === o) return true;
  }
  return false;
}
