/**
 * How the overlay shows strings it did not write: an agent's name, a reason, arguments, chat
 * text. Whatever an agent or the hub wrote is shown so that what the person reads cannot
 * differ from what the string holds, and an agent's name is set apart from the overlay's own
 * words wherever the two stand in one sentence.
 */

/** At most `max` code points (never splitting a surrogate pair), with an ellipsis when shortened. */
export function truncate(s: string, max: number): string {
  const cps = Array.from(s);
  return cps.length > max ? `${cps.slice(0, max - 1).join('')}…` : s;
}

/**
 * Code points that do not show as themselves: every control, format, surrogate, private-use
 * and unassigned code point (\p{C}), every separator but the plain space (\p{Z}: no-break and
 * other look-alike spaces, line and paragraph separators), every default-ignorable code point
 * (zero-width and joiner characters, bidi controls, variation selectors, tag characters,
 * fillers) and U+2800, the blank braille pattern. An allowlist by exclusion: anything in
 * these classes is escaped, whatever new code points Unicode adds to them.
 */
const UNSEEN = new RegExp('[\\p{C}\\p{Z}\\p{Default_Ignorable_Code_Point}\\u2800]', 'gu');

function escape(c: string): string {
  return `\\u{${c.codePointAt(0)!.toString(16).toUpperCase()}}`;
}

/**
 * Combining marks stack: a letter with sixty of them is drawn far above and below its own
 * line, over whatever stands there. A base carries at most this many; the rest of a run is
 * written as escapes, like everything else that does not show as itself.
 */
export const MARKS_MAX = 2;
const MARK_RUN = new RegExp(`\\p{M}{${MARKS_MAX + 1},}`, 'gu');

/**
 * `s` with every code point that would not show as itself written as a visible `\u{XXXX}`
 * escape, so what the person reads cannot differ from what the string holds, and with every
 * combining mark beyond the second in a row written that way too, so that no text paints over
 * the lines around it. Used for every string an agent or the hub wrote that the overlay
 * displays: names, reasons, arguments, toasts, labels, chat.
 */
export function visible(s: string): string {
  return s
    .replace(UNSEEN, (c) => (c === ' ' ? c : escape(c)))
    .replace(MARK_RUN, (run) => {
      const marks = Array.from(run);
      return marks.slice(0, MARKS_MAX).join('') + marks.slice(MARKS_MAX).map(escape).join('');
    });
}

/** `visible`, keeping line breaks as line breaks (for multi-line text such as toasts and chat). */
export function visibleLines(s: string): string {
  return s.split('\n').map(visible).join('\n');
}

/** The quotation marks `agentLabel` puts around a name. Inside a name they are written as escapes. */
const QUOTES = /[“”]/g;

export interface AgentLabelOptions {
  /**
   * Lead with "AI agent". For a sentence where the quoted name alone could be read as the
   * page's or the overlay's own words ("AI agent “Claude” (a1) wants to ...").
   */
  lead?: boolean;
  /** The longest name shown, in code points. Default 60. */
  max?: number;
}

/**
 * How the overlay names an agent wherever a decision is asked or words are attributed: the
 * name in quotation marks, then the agent's session id in brackets, as in `“Claude” (a1)`.
 *
 * The name is the agent's own text, so it is quoted: whatever it says, it reads as a name
 * and not as part of the sentence around it. It is shown through `visible`, and a quotation
 * mark inside it is written as an escape, so a name cannot close its own quotes. The session
 * id is the hub's, not the agent's: two agents that chose one name still differ by it.
 */
export function agentLabel(name: string, id: string, o: AgentLabelOptions = {}): string {
  const shown = visible(truncate(typeof name === 'string' ? name : '', o.max ?? 60)).replace(QUOTES, escape);
  const sid = visible(truncate(typeof id === 'string' ? id : '', 12)).replace(/[()]/g, escape);
  const quoted = shown === '' ? 'unnamed' : `“${shown}”`;
  const label = sid === '' ? quoted : `${quoted} (${sid})`;
  return o.lead ? `AI agent ${label}` : label;
}
