/**
 * Reins protocol v0.1: the wire contract.
 *
 * This file is the single source of truth for frames, methods, errors and the data
 * shapes shared by the hub, the driver and the agent SDK. docs/SPEC.md describes the
 * behaviour behind these shapes. If the two ever disagree, fix both in one change.
 *
 * Types and constants only. No logic lives here.
 */

// ───────────────────────────── versions and constants ─────────────────────────────

export const PROTOCOL_VERSION = '0.1';
export const SUPPORTED_VERSIONS: readonly string[] = ['0.1'];
/** WebSocket subprotocol every peer must request and the hub must select. */
export const WS_SUBPROTOCOL = 'reins.v1';
/** Default hub port on loopback ("REIN" on a phone keypad). */
export const DEFAULT_PORT = 7346;

export type Role = 'agent' | 'surface';

// ───────────────────────────── scopes, risk, decisions ─────────────────────────────

/** Canonical order. Scope lists on the wire are always sorted in this order. */
export const SCOPES = ['observe', 'act', 'ui', 'cursor', 'show', 'nav', 'chat'] as const;
export type Scope = (typeof SCOPES)[number];

/** Risk tier an app assigns to each of its actions. */
export type Risk = 'safe' | 'sensitive' | 'dangerous';
/** Outcome of a policy check. Strictness order: allow < confirm < deny. */
export type Decision = 'allow' | 'confirm' | 'deny';

/**
 * How much the person is asked about one agent's actions, least to most permissive. The
 * person picks it per grant, in the driver's panel; every grant starts at `ask`.
 *
 *   strict  every action asks, also one the policy allows
 *   ask     the policy decides: `confirm` asks
 *   auto    nothing asks, except an action whose risk is `dangerous`
 *   bypass  nothing asks
 *
 * No level relaxes a policy `deny`. See `decideAct` and SPEC section 12.
 */
export const LEVELS = ['strict', 'ask', 'auto', 'bypass'] as const;
export type Level = (typeof LEVELS)[number];
/** The level every grant starts at. */
export const DEFAULT_LEVEL: Level = 'ask';

// ───────────────────────────── errors ─────────────────────────────

export const ERROR_CODES = [
  'E_BAD_FRAME', // malformed frame, unknown frame type, protocol violation
  'E_VERSION', // no protocol version in common
  'E_AUTH', // missing or wrong proof
  'E_ORIGIN', // origin not allowed for this role
  'E_TOO_LARGE', // frame, manifest or result over a size limit
  'E_UNKNOWN_METHOD',
  'E_BAD_ARGS', // params fail validation
  'E_NO_SURFACE', // unknown surface id
  'E_NOT_ATTACHED', // no live grant for this surface
  'E_SCOPE', // grant lacks the scope this method needs
  'E_DENIED', // policy says no
  'E_CONSENT', // a human declined, or the consent prompt timed out
  'E_PAUSED', // the human paused agent control
  'E_RATE', // rate limit hit
  'E_NO_TARGET', // handle does not resolve to a live, exposed element
  'E_TIMEOUT', // the other side did not answer in time
  'E_GONE', // surface or agent disconnected mid-request
  'E_BUSY', // too many sessions, surfaces or streams
  'E_INTERNAL', // unexpected failure; the message never carries internals
] as const;
export type ErrorCode = (typeof ERROR_CODES)[number];

export interface WireError {
  code: ErrorCode;
  /** Short, human-readable, safe to show to a model. Never a stack trace. */
  msg: string;
  data?: unknown;
}

export class ReinsError extends Error {
  readonly code: ErrorCode;
  readonly data?: unknown;
  constructor(code: ErrorCode, msg: string, data?: unknown) {
    super(msg);
    this.name = 'ReinsError';
    this.code = code;
    this.data = data;
  }
  toWire(): WireError {
    return this.data === undefined ? { code: this.code, msg: this.message } : { code: this.code, msg: this.message, data: this.data };
  }
}

// ───────────────────────────── limits ─────────────────────────────

export interface Limits {
  /** Max UTF-8 bytes of one text frame. */
  maxText: number;
  /** Max bytes of one binary frame. */
  maxBinary: number;
  /** Idle interval after which a side sends `ping`. A peer silent for 2.5x this is dropped. */
  heartbeatMs: number;
  /** Default time to wait for a `res`. */
  reqTimeoutMs: number;
  /** Extra time the hub allows a request that is waiting on a human consent prompt. */
  consentTimeoutMs: number;
}

export const DEFAULT_LIMITS: Limits = {
  maxText: 262_144,
  maxBinary: 16_384,
  heartbeatMs: 15_000,
  reqTimeoutMs: 15_000,
  consentTimeoutMs: 60_000,
};

export const MAX_MANIFEST_BYTES = 65_536;
export const MAX_ACTIONS = 256;
export const MAX_VIEWS = 64;
export const MAX_RESULT_BYTES = 32_768;
export const MAX_NAME_CHARS = 120;
export const MAX_VALUE_CHARS = 200;
/** Grants a surface holds at once. A further `attach` is refused with `E_BUSY` (SPEC 8). */
export const MAX_SURFACE_SESSIONS = 32;
/** Action, view and state names: dot-separated lowercase identifiers, at most 64 chars. */
export const NAME_PATTERN = /^[a-z][a-z0-9_]*(\.[a-z][a-z0-9_]*)*$/;
/** The only colour syntax an agent may send (cursor colour). */
export const COLOR_PATTERN = /^#(?:[0-9a-fA-F]{3}|[0-9a-fA-F]{6})$/;

// ───────────────────────────── manifest ─────────────────────────────

/**
 * Schema-lite: the subset of JSON Schema used for action and view params.
 * Objects reject properties that are not declared.
 */
export type Schema =
  | { type: 'string'; description?: string; enum?: string[]; minLength?: number; maxLength?: number; pattern?: string }
  | { type: 'number' | 'integer'; description?: string; minimum?: number; maximum?: number }
  | { type: 'boolean'; description?: string }
  | { type: 'array'; description?: string; items: Schema; minItems?: number; maxItems?: number }
  | { type: 'object'; description?: string; properties: Record<string, Schema>; required?: string[] };

export interface AppInfo {
  /** Stable app id, matches NAME_PATTERN with `-` also allowed, e.g. `brew-kiosk`. Used as `kid` for surface keys. */
  id: string;
  name: string;
  version?: string;
  description?: string;
}

export interface ActionDef {
  name: string;
  description: string;
  /** Always an object schema when present. */
  params?: Schema;
  risk: Risk;
  /** One line describing the result, for the prompt card. */
  returns?: string;
}

export interface ViewDef {
  name: string;
  description: string;
  params?: Schema;
}

export interface StateDef {
  name: string;
  description?: string;
}

export type PolicyProfile = 'open' | 'guarded' | 'kiosk';
/** Which elements the UI tree exposes. Strictness order: auto < annotated < none. */
export type Exposure = 'auto' | 'annotated' | 'none';

/** What a surface tells the hub and agents about itself. Sent in `hello`. */
export interface Manifest {
  /** Protocol version the manifest was written for. */
  reins: string;
  app: AppInfo;
  actions: ActionDef[];
  views: ViewDef[];
  state: StateDef[];
  exposure: Exposure;
  /** Policy profile the surface runs, advertised so agents know what to expect. */
  profile: PolicyProfile;
}

// ───────────────────────────── policy ─────────────────────────────

export interface Policy {
  profile: PolicyProfile;
  /** Ceiling on the scopes a grant may carry. */
  scopes: Scope[];
  /** How an attach request is decided. */
  attach: Decision;
  /** Decision per risk tier. */
  risk: Record<Risk, Decision>;
  /** Per-action overrides. Key is an exact action name or a prefix ending in `.*`. Exact beats prefix, longer prefix beats shorter. */
  actions: Record<string, Decision>;
  exposure: Exposure;
  /** May `ui.type` write into private fields (passwords, card numbers, one-time codes). */
  privateInput: boolean;
  /** May `cursor.move` take raw viewport coordinates. `ui.*` never takes coordinates. */
  coordinates: boolean;
  /**
   * May the driver run in a page that sits inside a frame. The page around a frame decides
   * what the person sees of it, and can cover the consent prompt and the indicator, so every
   * profile says no. Set it only for a page that controls who may embed it.
   */
  framed: boolean;
  /** Same-origin path prefixes `nav.go` may open. Empty means navigation is off. */
  nav: string[];
  /**
   * Chat: who decides whether the agents in a page's room hear each other. The person sees
   * every message in any case, and every agent in the room hears the person.
   *   `off`     no agent hears another.
   *   `person`  no agent hears another until the person switches "Agents can hear each
   *             other" on in the Chat tab, for the agents the tab names at that moment.
   *   `on`      every agent in the room hears the others.
   * A hub's policy holds the same field and the stricter of the two applies (`off` before
   * `person` before `on`). In a policy file `true` reads as `on` and `false` as `off`.
   */
  chatRelay: ChatRelay;
  /** Max requests per second, per agent per surface, by scope. Enforced by the hub. */
  rates: Record<Scope, number>;
  /** Max pointer-stream points per second. Enforced by the hub. */
  pointerRate: number;
  /** Grant lifetime. */
  ttlMs: number;
  /** A grant with no request for this long expires. */
  idleMs: number;
  human: {
    /** After real user input, input-synthesising commands wait this long. 0 turns yielding off. */
    yieldMs: number;
    /** Show a Pause control. */
    pause: boolean;
    /** Show a Stop control that revokes the grant. */
    stop: boolean;
    /**
     * Levels the person may switch a grant to. `strict` and `ask` are always available, listed
     * or not: neither lets an agent do more. A hub's list caps a surface's: the person is
     * offered `auto` and `bypass` only where both list them.
     */
    levels: Level[];
    /** The indicator opens the permissions panel (levels, per-action rules, scope switches, activity). */
    panel: boolean;
  };
  consent: {
    /** A prompt nobody answers is a refusal after this long. */
    timeoutMs: number;
    /** `session`: an approved action is not asked again under the same grant. */
    remember: 'never' | 'session';
  };
}

/** A profile name, or a profile plus overrides. Nested objects merge one level deep. */
export type PolicyInput =
  | PolicyProfile
  | (Partial<Omit<Policy, 'human' | 'consent' | 'risk' | 'rates' | 'chatRelay'>> & {
      /** `true` is `on` and `false` is `off`: what policies written before the three values hold. */
      chatRelay?: ChatRelay | boolean;
      human?: Partial<Policy['human']>;
      consent?: Partial<Policy['consent']>;
      risk?: Partial<Policy['risk']>;
      rates?: Partial<Policy['rates']>;
    });

const HOUR = 3_600_000;
const MIN = 60_000;

