// ───────────────────────────── surfaces, agents, grants ─────────────────────────────

export interface AgentInfo {
  /** Hub-assigned session id, e.g. `a1`. */
  id: string;
  /** Display name the agent gave in `hello`, shown to the user in consent prompts. */
  name: string;
}

export interface SurfaceInfo {
  /** Hub-assigned surface id, e.g. `s1`. */
  s: string;
  origin: string;
  url: string;
  title: string;
  app: AppInfo;
  profile: PolicyProfile;
  /** base64url SHA-256 of the canonical manifest JSON. */
  digest: string;
  /** Whether the asking agent holds a live grant on this surface. */
  attached: boolean;
  /**
   * True only when the surface proved a surface key the hub holds for `app.id` (its
   * session is sealed). False for an unkeyed surface: its app id is only a claim.
   */
  verified: boolean;
}

export interface Grant {
  id: string;
  s: string;
  scopes: Scope[];
  /** Expiry, epoch milliseconds. */
  exp: number;
}

export interface HubInfo {
  name: string;
  ver: string;
  v: string[];
  profile: PolicyProfile;
  surfaces: number;
  agents: number;
}

// ───────────────────────────── observation ─────────────────────────────

/** A handle (`e12`), a semantic id (`#cart.checkout`), never a selector. */
export type Target = string;
export interface Point {
  /** Viewport CSS pixels. */
  x: number;
  y: number;
}

export type UiState = 'disabled' | 'checked' | 'selected' | 'expanded' | 'focused' | 'required' | 'invalid' | 'readonly' | 'private';

/** One exposed element of the page. */
export interface UiNode {
  /** Handle, stable for the element's lifetime: `e` + base36 counter. */
  h: string;
  role: string;
  /** Semantic id from `data-reins-id`, addressable as `#id`. */
  id?: string;
  /** Accessible name, at most MAX_NAME_CHARS. */
  name?: string;
  /** Current value, at most MAX_VALUE_CHARS. Never present on private fields. */
  val?: string;
  st?: UiState[];
  /** Handle of the nearest exposed ancestor. */
  p?: string;
  /** Viewport box [x, y, w, h] in whole CSS pixels. Only when the request asked for boxes. */
  box?: [number, number, number, number];
}

/** `set` adds or replaces a whole node. `del` removes one. */
export type TreeOp = { op: 'set'; n: UiNode } | { op: 'del'; h: string };

export interface Observation {
  /** Revision of the UI tree this answer brings the agent to. */
  rev: number;
  /** Present on a delta: the revision `ops` applies to. Absent on a full snapshot. */
  base?: number;
  /** Full snapshot, in document order. */
  nodes?: UiNode[];
  /** Delta against `base`. */
  ops?: TreeOp[];
  url: string;
  title: string;
  /** Viewport [width, height] in CSS pixels. */
  vp: [number, number];
  /** True while the human has paused agent control. */
  paused?: boolean;
}

// ───────────────────────────── chat ─────────────────────────────

/** Who said a chat message: the person at the page, or an attached agent (its session id and display name). */
export type ChatFrom = { kind: 'person' } | { kind: 'agent'; id: string; name: string };

/** `policy.chatRelay`, strictest first. */
export const CHAT_RELAY = ['off', 'person', 'on'] as const;
export type ChatRelay = (typeof CHAT_RELAY)[number];

/**
 * `to: "person"`: an agent's message for the person alone. No agent is sent it, whatever the
 * room relays. No hub hands out this word as a session id.
 */
export const CHAT_TO_PERSON = 'person';

/** One message of a page's chat room. */
export interface ChatMessage {
  /**
   * Counts up from 1 on each page load, for each agent, over the messages that agent may
   * read: one agent's ids say nothing about what was said to others, and they go on counting
   * when its grant is replaced. A label for `chat.read {since}`, nothing more.
   */
  id: number;
  from: ChatFrom;
  /** 1 to CHAT_MAX_TEXT characters, trimmed. Data wherever it is shown or handed to a model. */
  text: string;
  /** When the surface took the message, epoch milliseconds. */
  ts: number;
  /**
   * The agent session the message is addressed to, or `person` (CHAT_TO_PERSON) on an agent's
   * message for the person alone. Absent: everyone in the room who hears the speaker.
   */
  to?: string;
}

export interface ChatReadResult {
  /** Oldest first. */
  messages: ChatMessage[];
  /** Pass as `since` to read what came after. */
  next: number;
}

/** What an agent says it is doing, shown next to its name in the chat tab. */
export const CHAT_STATES = ['idle', 'thinking', 'working'] as const;
export type ChatState = (typeof CHAT_STATES)[number];

/** Longest chat message, in characters, after trimming. */
export const CHAT_MAX_TEXT = 4000;
/** Longest status note, in characters, after white space is collapsed. */
export const CHAT_MAX_NOTE = 80;
/** Messages a room keeps. Beyond it the oldest goes. */
export const CHAT_TRANSCRIPT_MAX = 200;
/** `chat.read`: messages in one answer, by default and at most. */
export const CHAT_READ_DEFAULT = 20;
export const CHAT_READ_MAX = 50;
/** `chat.read`: an answer takes no further message once its messages hold this many bytes of JSON. */
export const CHAT_READ_BYTES = 131_072;
/** A status other than `idle` reads `idle` again when it was not renewed for this long. */
export const CHAT_STATUS_TTL_MS = 120_000;

// ───────────────────────────── methods ─────────────────────────────

export const UI_KEYS = ['Enter', 'Escape', 'Tab', 'Backspace', 'Delete', 'Space', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'PageUp', 'PageDown', 'Home', 'End'] as const;
export type UiKey = (typeof UI_KEYS)[number];

export type ToastKind = 'info' | 'ok' | 'warn';

export interface UiResult {
  /** Tree revision after the command ran. */
  rev: number;
}

/** `p` carries `s` (the surface id) on the agent side. The hub strips it before forwarding. */
type OnSurface<P> = P & { s: string };

/** Requests an agent sends to the hub. */
export interface AgentMethods {
  // answered by the hub
  'hub.info': { p: Record<string, never>; r: HubInfo };
  'surfaces.list': { p: Record<string, never>; r: { surfaces: SurfaceInfo[] } };
  'surface.attach': { p: OnSurface<{ scopes: Scope[]; reason?: string }>; r: AttachResult };
  'surface.detach': { p: OnSurface<object>; r: Record<string, never> };
  'stream.open': { p: OnSurface<{ kind: 'pointer' }>; r: { ch: number; credit: number } };
  'stream.close': { p: { ch: number }; r: Record<string, never> };
  // forwarded to the surface: scope `observe`
  observe: { p: OnSurface<{ since?: number; boxes?: boolean }>; r: Observation };
  read: { p: OnSurface<{ h?: Target; max?: number }>; r: { text: string; truncated: boolean } };
  'state.get': { p: OnSurface<{ name?: string }>; r: { state: Record<string, unknown> } };
  sub: { p: OnSurface<{ topics: Topic[] }>; r: { topics: Topic[] } };
  unsub: { p: OnSurface<{ topics: Topic[] }>; r: { topics: Topic[] } };
  // scope `act`
  act: { p: OnSurface<{ a: string; args?: Record<string, unknown> }>; r: { result?: unknown; rev: number } };
  // scope `ui`
  'ui.click': { p: OnSurface<{ h: Target }>; r: UiResult };
  'ui.type': { p: OnSurface<{ h: Target; text: string; clear?: boolean; enter?: boolean }>; r: UiResult };
  'ui.select': { p: OnSurface<{ h: Target; value: string }>; r: UiResult };
  'ui.scroll': { p: OnSurface<{ h?: Target; dx?: number; dy?: number; to?: 'top' | 'bottom' | 'view' }>; r: UiResult };
  'ui.key': { p: OnSurface<{ key: UiKey; h?: Target }>; r: UiResult };
  // scope `cursor` (visual only: never dispatches input events)
  'cursor.move': { p: OnSurface<{ to: Target | Point; ms?: number; wait?: boolean }>; r: Point };
  'cursor.set': { p: OnSurface<{ visible?: boolean; label?: string; color?: string }>; r: Record<string, never> };
  // scope `show`
  'show.toast': { p: OnSurface<{ text: string; kind?: ToastKind; ms?: number }>; r: Record<string, never> };
  'show.highlight': { p: OnSurface<{ h: Target; label?: string; ms?: number }>; r: Record<string, never> };
  'show.view': { p: OnSurface<{ view: string; data?: unknown }>; r: { result?: unknown } };
  'show.clear': { p: OnSurface<object>; r: Record<string, never> };
  // scope `nav`
  'nav.go': { p: OnSurface<{ url: string }>; r: Record<string, never> };
  // scope `chat`: the room in the page's panel, between the person and the attached agents
  // `to`: another agent's session id, or `person` for the person alone. Only `text` and `to` are forwarded.
  'chat.say': { p: OnSurface<{ text: string; to?: string }>; r: { id: number } };
  'chat.read': { p: OnSurface<{ since?: number; max?: number }>; r: ChatReadResult };
  'chat.status': { p: OnSurface<{ state: ChatState; note?: string }>; r: Record<string, never> };
}
export type AgentMethod = keyof AgentMethods;

/**
 * What the person tightened for an agent before, and that stays for a new grant of the same
 * agent (SPEC section 8, "What the person tightened stays"): the level `strict`, the rules
 * `confirm` and `deny`, and the scopes they switched off. Never anything that lets an agent do
 * more: no `auto`, no `bypass`, no rule `allow`.
 */
export interface KeptSettings {
  level?: 'strict';
  rules?: Record<string, 'confirm' | 'deny'>;
  /** Scopes that were granted and are switched off. */
  off?: Scope[];
}

export interface AttachResult {
  /** `grant.scopes` holds the scopes in force: those granted, without the ones that stay switched off. */
  grant: Grant;
  surface: SurfaceInfo;
  manifest: Manifest;
  /** The grant starts with these, which the person set for this agent before; absent when there are none. */
  kept?: KeptSettings;
}

/** Methods the hub answers itself. Everything else in AgentMethods is forwarded. */
export const HUB_METHODS: readonly AgentMethod[] = ['hub.info', 'surfaces.list', 'surface.attach', 'surface.detach', 'stream.open', 'stream.close'];

/** Scope each forwarded method needs. `stream.open` needs `cursor` as well. */
export const METHOD_SCOPE: Readonly<Record<string, Scope>> = {
  observe: 'observe',
  read: 'observe',
  'state.get': 'observe',
  sub: 'observe',
  unsub: 'observe',
  act: 'act',
  'ui.click': 'ui',
  'ui.type': 'ui',
  'ui.select': 'ui',
  'ui.scroll': 'ui',
  'ui.key': 'ui',
  'cursor.move': 'cursor',
  'cursor.set': 'cursor',
  'stream.open': 'cursor',
  'show.toast': 'show',
  'show.highlight': 'show',
  'show.view': 'show',
  'show.clear': 'show',
  'nav.go': 'nav',
  'chat.say': 'chat',
  'chat.read': 'chat',
  'chat.status': 'chat',
};

/** Methods that change nothing: served while the human has paused control and while a consent prompt is up. */
export const READ_ONLY_METHODS: readonly string[] = ['observe', 'read', 'state.get', 'sub', 'unsub', 'chat.read'];

/**
 * Methods that put words in the chat tab and change nothing else. They are served while
 * control is paused, so that an agent can still answer the person. While a consent prompt is
 * up they are refused with `E_BUSY`, like every method that is not read-only: nothing talks
 * over a decision.
 */
export const CHAT_SPEAK_METHODS: readonly string[] = ['chat.say', 'chat.status'];

/**
 * Requests the hub sends to a surface. Forwarded agent methods arrive with the same
 * name and params minus `s`, with `ag` set on the frame. The ones below exist only on this leg.
 */
export interface SurfaceMethods {
  /**
   * `levels` is the hub policy's `human.levels`: the surface offers the person only what both
   * sides list. `decisions` is the hub policy's decision for each action of the surface's
   * manifest, by name: which actions the hub confirms (`c:1`) and which it refuses. A surface
   * that gets none assumes the hub may confirm any action. `cred` is the id of the agent's
   * credential: what the hub knows of who the agent is, whatever session id or name it has
   * this time. A surface that gets none cannot tell one agent from another. In the answer,
   * `scopes` are the scopes granted and `kept` is what stays of the person's earlier settings.
   */
  attach: {
    p: { agent: AgentInfo; scopes: Scope[]; reason?: string; levels?: Level[]; decisions?: Record<string, Decision>; chatRelay?: ChatRelay; cred?: string };
    r: { scopes: Scope[]; ttlMs: number; kept?: KeptSettings };
  };
  /**
   * The hub did not relay a message of the person to the agent `ag` names (its budget for that
   * agent was used up, the audit log could not take the record, or the frame did not fit).
   * `id` is the id the message has for that agent. The surface shows the message as not
   * delivered to it. Sent for messages of the person only.
   */
  'chat.undelivered': { p: { id: number }; r: Record<string, never> };
  detach: { p: { why: 'agent' | 'hub' | 'expired' }; r: Record<string, never> };
  'stream.open': { p: { kind: 'pointer'; ch: number }; r: { credit: number } };
  'stream.close': { p: { ch: number }; r: Record<string, never> };
}

// ───────────────────────────── events ─────────────────────────────

export const TOPICS = ['ui', 'state', 'user', 'nav', 'grant', 'surface', 'chat'] as const;
export type Topic = (typeof TOPICS)[number];
/** Topics an agent opts into with `sub`. `grant`, `surface` and `chat` are always delivered. */
export const SUBSCRIBABLE_TOPICS: readonly Topic[] = ['ui', 'state', 'user', 'nav'];

export interface EventPayloads {
  /** The UI tree changed. Carries only the new revision: call `observe` for the delta. */
  ui: { rev: number };
  /** RFC 7396 merge patch against the value this agent last received for `name`. */
  state: { name: string; patch: unknown };
  /**
   * `override`, `pause`, `resume`: what the person is doing on the page. `level`, `rule` and
   * `relay` are what the person set for one agent in the panel, always sent with `ag`: the
   * level of its grant, a rule for one action (`d` null when the rule was removed), and
   * whether the person lets it hear, and be heard by, the other agents in the chat they
   * switched on (`policy.chatRelay` is `person`).
   */
  user: { kind: 'override' | 'pause' | 'resume' } | { kind: 'level'; level: Level } | { kind: 'rule'; a: string; d: Decision | null } | { kind: 'relay'; on: boolean };
  nav: { url: string; title: string };
  /**
   * Surface to hub: the human pressed Stop (`revoked`), or switched scopes of one grant off
   * or back on (`scopes`, with `ag`, the scopes now in force). Hub to agent: `revoked`,
   * `expired`, or `scopes` with the scopes the grant now carries.
   */
  grant: { kind: 'revoked' | 'expired' } | { kind: 'scopes'; scopes: Scope[] };
  /** Hub to every agent. */
  surface: { kind: 'added' | 'gone' | 'changed'; surface: SurfaceInfo };
  /**
   * One message of the page's chat room, for the one agent named by `ag`: the person's, or
   * another agent's where the room relays those. Never the agent's own. `id` is the id the
   * message has for that agent.
   */
  chat: ChatMessage;
}

// ───────────────────────────── text frames ─────────────────────────────

/** First frame on every connection, hub to peer. */
export interface ChallengeFrame {
  t: 'challenge';
  /** Versions the hub speaks, newest first. */
  v: string[];
  /** base64url, 32 random bytes, fresh per connection. */
  nonce: string;
  hub: { name: string; ver: string };
}

export interface SurfaceHello {
  manifest: Manifest;
  url: string;
  title: string;
}

export interface HelloFrame {
  t: 'hello';
  /** The version the peer picked from the challenge. */
  v: string;
  role: Role;
  name: string;
  /** base64url, 32 random bytes, fresh per connection. */
  cnonce: string;
  /** Required for agents. Required for surfaces when the hub demands surface keys. */
  auth?: { kid: string; proof: string };
  /** Required when role is `surface`. */
  surface?: SurfaceHello;
}

export interface WelcomeFrame {
  t: 'welcome';
  v: string;
  /** Session id: `aN` for agents, `sN` for surfaces. A label, never a credential. */
  session: string;
  role: Role;
  limits: Limits;
  /** Present when the peer authenticated: the hub proves it holds the same key. */
  proof?: string;
}

export interface ReqFrame {
  t: 'req';
  /** Unique per sender per connection, counting up from 1. */
  id: number;
  m: string;
  p?: Record<string, unknown>;
  /** Hub to surface only: the agent session this request acts for. */
  ag?: string;
  /** Hub to surface only: the hub's policy demands a human confirmation for this request. */
  c?: 1;
}

export interface ResOkFrame {
  t: 'res';
  re: number;
  ok: true;
  r?: unknown;
}
export interface ResErrFrame {
  t: 'res';
  re: number;
  ok: false;
  e: WireError;
}
export type ResFrame = ResOkFrame | ResErrFrame;

export interface EvtFrame {
  t: 'evt';
  topic: Topic;
  /** Hub to agent: which surface the event is about. */
  s?: string;
  /** Surface to hub: deliver to this agent only. Without it the event goes to every attached agent. */
  ag?: string;
  d?: unknown;
}

/** Stream receiver to sender: `credit` more units may be sent on `ch`. */
export interface FlowFrame {
  t: 'flow';
  ch: number;
  credit: number;
}

export interface PingFrame {
  t: 'ping';
  /** Sender's clock, echoed back unchanged. */
  ts: number;
}
export interface PongFrame {
  t: 'pong';
  ts: number;
}

/** Sent right before closing, in either direction. */
export interface ByeFrame {
  t: 'bye';
  code: ErrorCode | 'OK';
  msg?: string;
}

export type Frame = ChallengeFrame | HelloFrame | WelcomeFrame | ReqFrame | ResFrame | EvtFrame | FlowFrame | PingFrame | PongFrame | ByeFrame;
export type FrameType = Frame['t'];

// ───────────────────────────── handshake proofs ─────────────────────────────

/**
 * proof = base64url(HMAC-SHA256(key, `${context}\n${role}\n${kid}\n${nonce}\n${cnonce}`))
 * `key` is the UTF-8 bytes of the shared secret. The peer uses AUTH_CONTEXT.peer,
 * the hub answers with AUTH_CONTEXT.hub over the same fields.
 */
export const AUTH_CONTEXT = { peer: 'reins.v1.auth', hub: 'reins.v1.hub' } as const;

// ───────────────────────────── sealed sessions ─────────────────────────────

/**
 * Directional session keys, derived when the peer authenticated with a key:
 * th = base64url(SHA-256(L(c) || c || L(h) || h || L(w) || w)): c, h, w are the UTF-8 bytes of the
 * challenge, hello and welcome frames exactly as sent, L(x) the byte length of x as a u32 BE;
 * k_dir = HMAC-SHA256(key, `${SEAL_CONTEXT[dir]}\n${nonce}\n${cnonce}\n${th}`), raw 32 bytes.
 * `peer` seals what the peer sends, `hub` what the hub sends.
 */
export const SEAL_CONTEXT = { peer: 'reins.v1.seal.peer', hub: 'reins.v1.seal.hub' } as const;

/**
 * Key confirmation: the peer's first sealed frame is `ping {ts}`, the hub's first is the
 * matching `pong {ts}`. Either side gives up after this long and closes.
 */
export const SEAL_CONFIRM_MS = 5_000;

/** The kind byte in a seal MAC input: `t` for text, `b` for binary. */
export const SEAL_KIND = { text: 0x74, binary: 0x62 } as const;

/** Raw MAC length: trails every sealed binary message. */
export const SEAL_MAC_BYTES = 32;

/** base64url (unpadded) MAC length: leads every sealed text message, followed by SEAL_SEPARATOR. */
export const SEAL_MAC_TEXT_LENGTH = 43;

/** Separates the MAC from the text in a sealed text message. */
export const SEAL_SEPARATOR = '.';

/** WebSocket close codes the hub uses. */
export const WS_CLOSE = { normal: 1000, policy: 1008, tooLarge: 1009, auth: 4401, origin: 4403, version: 4406, busy: 4429 } as const;

// ───────────────────────────── binary frames: the pointer stream ─────────────────────────────

/**
 * Pointer frame layout, little-endian:
 *
 *   0  u8   kind    BIN_POINTER
 *   1  u8   flags   PTR_FLAG_*
 *   2  u16  ch      stream channel from `stream.open`
 *   4  u32  seq     sequence number of the first point; each point adds 1
 *   8  u16  n       number of points
 *  10  n x { u16 x, u16 y, u16 dt }
 *
 * x and y are viewport fractions scaled to 0..65535. dt is milliseconds since the previous point.
 */
export const BIN_POINTER = 0x01;
/** The receiver and the hub may drop this frame under pressure. */
export const PTR_FLAG_DROPPABLE = 0x01;
/** Last frame of a stroke. Never dropped. */
export const PTR_FLAG_END = 0x02;
export const PTR_HEADER_BYTES = 10;
export const PTR_POINT_BYTES = 6;
export const PTR_MAX_POINTS = Math.floor((DEFAULT_LIMITS.maxBinary - PTR_HEADER_BYTES) / PTR_POINT_BYTES);
/** Credit a surface grants when a pointer stream opens, in points. */
export const PTR_INITIAL_CREDIT = 512;

export interface PointerPoint {
  /** Viewport fraction, 0..1. */
  x: number;
  y: number;
  /** Milliseconds since the previous point, 0..65535. */
  dt: number;
}

export interface PointerFrame {
  ch: number;
  seq: number;
  flags: number;
  points: PointerPoint[];
}

// ───────────────────────────── links ─────────────────────────────

/**
 * A bidirectional, ordered, reliable message pipe. WebSocket, MessagePort and the
 * in-memory pair all present this shape, so every layer above is transport-agnostic.
 *
 * Contract: while `onmessage` is null, inbound messages are queued; assigning a handler
 * delivers the queue in order before anything newer. `onclose` fires exactly once.
 */
export interface Link {
  send(data: string | Uint8Array): void;
  close(): void;
  onmessage: ((data: string | Uint8Array) => void) | null;
  onclose: (() => void) | null;
  /** Bytes queued for sending and not yet on the wire. 0 when the transport cannot tell. */
  readonly bufferedAmount: number;
  readonly open: boolean;
  /**
   * Optional. Bound the inbound queue (messages held while `onmessage` is null) to
   * `maxMessages` messages and `maxBytes` bytes; past either the link closes. Called with
   * no arguments, restores the link's defaults. The hub uses a small bound until a
   * connection has authenticated.
   */
  limitInbound?(maxMessages?: number, maxBytes?: number): void;
}
