/** Minimal listener set. A throwing listener never affects the others. */
export class Emitter<E extends string = string> {
  #map = new Map<E, Set<(d: any) => void>>();

  on(event: E, fn: (d: any) => void): () => void {
    let set = this.#map.get(event);
    if (!set) this.#map.set(event, (set = new Set()));
    set.add(fn);
    return () => {
      set.delete(fn);
    };
  }

  emit(event: E, d?: unknown): void {
    const set = this.#map.get(event);
    if (!set) return;
    for (const fn of [...set]) {
      try {
        fn(d);
      } catch {
        // listener errors stay with the listener
      }
    }
  }
}

/** Keep a timer from holding a Node process open. No-op in browsers. */
export function unref<T>(timer: T): T {
  (timer as { unref?: () => void } | undefined)?.unref?.();
  return timer;
}
