import {
  BIN_POINTER,
  DEFAULT_LIMITS,
  PTR_HEADER_BYTES,
  PTR_MAX_POINTS,
  PTR_POINT_BYTES,
  ReinsError,
} from './protocol.js';
import type { Frame, PointerFrame, PointerPoint, WireError } from './protocol.js';
import { isPlainObject } from './util.js';

// ───────────────────────────── text frames ─────────────────────────────

export function encodeFrame(f: Frame): string {
  return JSON.stringify(f);
}

/** UTF-8 byte length of a string, without allocating. Lone surrogates count 3 (U+FFFD). */
export function utf8Length(text: string): number {
  let n = 0;
  for (let i = 0; i < text.length; i++) {
    const c = text.charCodeAt(i);
    if (c < 0x80) n += 1;
    else if (c < 0x800) n += 2;
    else if (c >= 0xd800 && c <= 0xdbff && i + 1 < text.length) {
      const d = text.charCodeAt(i + 1);
      if (d >= 0xdc00 && d <= 0xdfff) {
        n += 4;
        i++;
      } else n += 3;
    } else n += 3;
  }
  return n;
}

function bad(why: string): never {
  throw new ReinsError('E_BAD_FRAME', `bad frame: ${why}`);
}

type Obj = Record<string, unknown>;

function str(o: Obj, k: string): string {
  const v = o[k];
  if (typeof v !== 'string') bad(`${k} must be a string`);
  return v;
}
function optStr(o: Obj, k: string): string | undefined {
  return o[k] === undefined ? undefined : str(o, k);
}
function num(o: Obj, k: string): number {
  const v = o[k];
  if (typeof v !== 'number' || !Number.isFinite(v)) bad(`${k} must be a number`);
  return v;
}
function int(o: Obj, k: string): number {
  const v = num(o, k);
  if (!Number.isSafeInteger(v) || v < 0) bad(`${k} must be a non-negative integer`);
  return v;
}
function obj(o: Obj, k: string): Obj {
  const v = o[k];
  if (!isPlainObject(v)) bad(`${k} must be an object`);
  return v;
}
function optObj(o: Obj, k: string): Obj | undefined {
  return o[k] === undefined ? undefined : obj(o, k);
}
function role(o: Obj): 'agent' | 'surface' {
  const v = o.role;
  if (v !== 'agent' && v !== 'surface') bad('role must be agent or surface');
  return v;
}
/** Copy of `o` holding only the keys whose value is not undefined. */
function compact<T>(o: Obj): T {
  const out: Obj = {};
  for (const k of Object.keys(o)) if (o[k] !== undefined) out[k] = o[k];
  return out as T;
}

/**
 * Parse and shape-check one text frame. The size limit is enforced before parsing.
 * Returns a fresh frame carrying only the fields the protocol defines; unknown fields
 * are dropped. Throws `E_TOO_LARGE` or `E_BAD_FRAME`.
 */
export function decodeFrame(text: string, maxBytes: number = DEFAULT_LIMITS.maxText): Frame {
  if (typeof text !== 'string') bad('not text');
  // Every UTF-16 unit is at least one UTF-8 byte, so a long string fails without a full count.
  if (text.length > maxBytes || utf8Length(text) > maxBytes) throw new ReinsError('E_TOO_LARGE', 'frame too large');
  let raw: unknown;
  try {
    raw = JSON.parse(text);
  } catch {
    bad('invalid JSON');
  }
  if (!isPlainObject(raw)) bad('not an object');
  const o = raw;
  switch (o.t) {
    case 'challenge': {
      const v = o.v;
      if (!Array.isArray(v) || !v.every((x) => typeof x === 'string')) bad('v must be a string array');
      const hub = obj(o, 'hub');
      return { t: 'challenge', v: [...(v as string[])], nonce: str(o, 'nonce'), hub: { name: str(hub, 'name'), ver: str(hub, 'ver') } };
    }
    case 'hello': {
      const auth = optObj(o, 'auth');
      const surface = optObj(o, 'surface');
      return compact<Frame>({
        t: 'hello',
        v: str(o, 'v'),
        role: role(o),
        name: str(o, 'name'),
        cnonce: str(o, 'cnonce'),
        auth: auth && { kid: str(auth, 'kid'), proof: str(auth, 'proof') },
        surface: surface && { manifest: obj(surface, 'manifest'), url: str(surface, 'url'), title: str(surface, 'title') },
      });
    }
    case 'welcome': {
      const l = obj(o, 'limits');
      return compact<Frame>({
        t: 'welcome',
        v: str(o, 'v'),
        session: str(o, 'session'),
        role: role(o),
        limits: {
          maxText: num(l, 'maxText'),
          maxBinary: num(l, 'maxBinary'),
          heartbeatMs: num(l, 'heartbeatMs'),
          reqTimeoutMs: num(l, 'reqTimeoutMs'),
          consentTimeoutMs: num(l, 'consentTimeoutMs'),
        },
        proof: optStr(o, 'proof'),
      });
    }
    case 'req': {
      if (o.c !== undefined && o.c !== 1) bad('c must be 1');
      return compact<Frame>({ t: 'req', id: int(o, 'id'), m: str(o, 'm'), p: optObj(o, 'p'), ag: optStr(o, 'ag'), c: o.c });
    }
    case 'res': {
      const re = int(o, 're');
      if (o.ok === true) return compact<Frame>({ t: 'res', re, ok: true, r: o.r });
      if (o.ok !== false) bad('ok must be a boolean');
      const e = obj(o, 'e');
      return compact<Frame>({ t: 'res', re, ok: false, e: compact<WireError>({ code: str(e, 'code'), msg: str(e, 'msg'), data: e.data }) });
    }
    case 'evt':
      return compact<Frame>({ t: 'evt', topic: str(o, 'topic'), s: optStr(o, 's'), ag: optStr(o, 'ag'), d: o.d });
    case 'flow':
      return { t: 'flow', ch: int(o, 'ch'), credit: num(o, 'credit') };
    case 'ping':
      return { t: 'ping', ts: num(o, 'ts') };
    case 'pong':
      return { t: 'pong', ts: num(o, 'ts') };
    case 'bye':
      return compact<Frame>({ t: 'bye', code: str(o, 'code'), msg: optStr(o, 'msg') });
    default:
      bad('unknown frame type');
  }
}

// ───────────────────────────── binary frames ─────────────────────────────

/** Kind byte of a binary frame, or -1 for an empty one. */
export function binaryKind(bytes: Uint8Array): number {
  return bytes.length > 0 ? bytes[0]! : -1;
}

function clamp01(v: number): number {
  return Number.isFinite(v) ? Math.min(1, Math.max(0, v)) : 0;
}
function clampU16(v: number): number {
  return Number.isFinite(v) ? Math.min(0xffff, Math.max(0, Math.round(v))) : 0;
}

/** Encode a pointer frame. x and y are clamped to 0..1, dt to 0..65535 ms. */
export function encodePointer(f: PointerFrame): Uint8Array {
  const n = f.points.length;
  if (n > PTR_MAX_POINTS) throw new ReinsError('E_TOO_LARGE', 'too many points in one frame');
  const out = new Uint8Array(PTR_HEADER_BYTES + n * PTR_POINT_BYTES);
  const dv = new DataView(out.buffer);
  dv.setUint8(0, BIN_POINTER);
  dv.setUint8(1, f.flags & 0xff);
  dv.setUint16(2, f.ch & 0xffff, true);
  dv.setUint32(4, f.seq >>> 0, true);
  dv.setUint16(8, n, true);
  let off = PTR_HEADER_BYTES;
  for (const p of f.points) {
    dv.setUint16(off, Math.round(clamp01(p.x) * 0xffff), true);
    dv.setUint16(off + 2, Math.round(clamp01(p.y) * 0xffff), true);
    dv.setUint16(off + 4, clampU16(p.dt), true);
    off += PTR_POINT_BYTES;
  }
  return out;
}

/** Decode a pointer frame. Throws `E_BAD_FRAME` on a wrong kind or a length that does not match `n`. */
export function decodePointer(bytes: Uint8Array): PointerFrame {
  if (!(bytes instanceof Uint8Array) || bytes.length < PTR_HEADER_BYTES) bad('pointer frame too short');
  const dv = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  if (dv.getUint8(0) !== BIN_POINTER) bad('not a pointer frame');
  const n = dv.getUint16(8, true);
  if (bytes.length !== PTR_HEADER_BYTES + n * PTR_POINT_BYTES) bad('pointer frame length mismatch');
  const points: PointerPoint[] = [];
  let off = PTR_HEADER_BYTES;
  for (let i = 0; i < n; i++) {
    points.push({ x: dv.getUint16(off, true) / 0xffff, y: dv.getUint16(off + 2, true) / 0xffff, dt: dv.getUint16(off + 4, true) });
    off += PTR_POINT_BYTES;
  }
  return { ch: dv.getUint16(2, true), seq: dv.getUint32(4, true), flags: dv.getUint8(1), points };
}
