import { CreditWindow, PTR_FLAG_DROPPABLE, PTR_FLAG_END, PTR_MAX_POINTS, PointerCoalescer, ReinsError, encodePointer } from '@offensiveadhd/reins/core';
import { unref } from './emitter.js';

export interface PointerStream {
  /** Viewport fractions 0..1. `dt` is ms since the previous point; default: time since the previous push. */
  push(x: number, y: number, dt?: number): void;
  /** Send everything queued, then a final END frame and `stream.close`. */
  end(): Promise<void>;
  readonly stats: { sent: number; dropped: number };
}

/** What a stream needs from its owner. */
export interface PointerHost {
  sendBinary(bytes: Uint8Array): void;
  closeChannel(ch: number): Promise<void>;
  /** Called when the stream is finished, so the owner stops routing `flow` frames to it. */
  release(ch: number): void;
  waitMs: number;
}

const FLUSH_MS = 8;

const now = (): number => (typeof performance !== 'undefined' ? performance.now() : Date.now());

export class PointerStreamImpl implements PointerStream {
  #ch: number;
  #host: PointerHost;
  #credit: CreditWindow;
  #queue = new PointerCoalescer();
  #seq = 0;
  #sent = 0;
  #last: number | undefined;
  #timer: ReturnType<typeof setTimeout> | undefined;
  #ending: Promise<void> | undefined;
  #wake: (() => void) | undefined;
  #dead: ReinsError | undefined;

  constructor(ch: number, initialCredit: number, host: PointerHost) {
    this.#ch = ch;
    this.#host = host;
    this.#credit = new CreditWindow(initialCredit);
  }

  get stats(): { sent: number; dropped: number } {
    return { sent: this.#sent, dropped: this.#queue.dropped };
  }

  push(x: number, y: number, dt?: number): void {
    if (this.#ending || this.#dead) return;
    const t = now();
    const delta = dt ?? (this.#last === undefined ? 0 : Math.round(t - this.#last));
    this.#last = t;
    this.#queue.push({ x, y, dt: delta });
    this.#schedule();
  }

  /** Credit arrived from the surface. */
  addCredit(n: number): void {
    this.#credit.grant(n);
    if (this.#wake) this.#wake();
    else this.#flush();
  }

  /** The connection is gone: fail a pending end() and stop. */
  fail(err: ReinsError): void {
    this.#dead = err;
    if (this.#timer !== undefined) clearTimeout(this.#timer);
    this.#timer = undefined;
    this.#wake?.();
  }

  #schedule(): void {
    if (this.#timer !== undefined) return;
    this.#timer = unref(
      setTimeout(() => {
        this.#timer = undefined;
        this.#flush();
      }, FLUSH_MS),
    );
  }

  #send(points: ReturnType<PointerCoalescer['take']>, flags: number): void {
    this.#host.sendBinary(encodePointer({ ch: this.#ch, seq: this.#seq, flags, points }));
    this.#seq += points.length;
    this.#sent += points.length;
  }

  /** Send as many droppable frames as the credit allows. */
  #flush(): void {
    if (this.#ending || this.#dead) return;
    try {
      while (this.#queue.size > 0 && this.#credit.available > 0) {
        const n = Math.min(this.#credit.available, PTR_MAX_POINTS, this.#queue.size);
        const pts = this.#queue.take(n);
        this.#credit.consume(pts.length);
        this.#send(pts, PTR_FLAG_DROPPABLE);
      }
    } catch {
      // the link is closing; the close handler fails the stream
    }
  }

  end(): Promise<void> {
    return (this.#ending ??= this.#end());
  }

  async #end(): Promise<void> {
    if (this.#timer !== undefined) clearTimeout(this.#timer);
    this.#timer = undefined;
    let closing = false;
    try {
      for (;;) {
        if (this.#dead) throw this.#dead;
        const size = this.#queue.size;
        if (size === 0) {
          this.#send([], PTR_FLAG_END);
          break;
        }
        const avail = this.#credit.available;
        if (avail > 0) {
          const n = Math.min(avail, PTR_MAX_POINTS, size);
          const last = n === size;
          const pts = this.#queue.take(n);
          this.#credit.consume(pts.length);
          this.#send(pts, last ? PTR_FLAG_END : PTR_FLAG_DROPPABLE);
          if (last) break;
          continue;
        }
        await this.#waitForCredit();
      }
      closing = true;
      await this.#host.closeChannel(this.#ch);
    } catch (e) {
      // Still tell the hub the stream is over: one it never hears the end of stays counted
      // against the session. Not when the close itself failed, or the link is gone.
      if (!closing && !this.#dead) await this.#host.closeChannel(this.#ch).catch(() => undefined);
      throw e;
    } finally {
      this.#host.release(this.#ch);
    }
  }

  #waitForCredit(): Promise<void> {
    return new Promise<void>((resolve, reject) => {
      const timer = unref(
        setTimeout(() => {
          this.#wake = undefined;
          reject(new ReinsError('E_TIMEOUT', 'no pointer credit'));
        }, this.#host.waitMs),
      );
      this.#wake = () => {
        clearTimeout(timer);
        this.#wake = undefined;
        resolve();
      };
    });
  }
}
