/**
 * Synthesised input for `ui.*` commands, and the watcher that gives real input priority.
 *
 * Synthesised events are never trusted, so the watcher, the consent prompt and the
 * indicator ignore them. Values are written through the native prototype setter so
 * frameworks that track `value` (React and friends) notice the change.
 */
import { ReinsError } from '@offensiveadhd/reins/core';
import type { Point, UiKey } from '@offensiveadhd/reins/core';
import { isTrusted, listen, unlisten } from './primordials.js';
import { isEditable } from './tree.js';

type Win = Window & typeof globalThis;

function winOf(el: Element): Win {
  const w = el.ownerDocument.defaultView;
  if (!w) throw new ReinsError('E_NO_TARGET', 'target is not in a window');
  return w as Win;
}

export function centerOf(el: Element): Point {
  try {
    const r = el.getBoundingClientRect();
    return { x: Math.round((r.left || 0) + (r.width || 0) / 2), y: Math.round((r.top || 0) + (r.height || 0) / 2) };
  } catch {
    return { x: 0, y: 0 };
  }
}

function mouse(el: Element, type: string, pt: Point, buttons: number): boolean {
  const w = winOf(el);
  const init: MouseEventInit & PointerEventInit = {
    bubbles: true,
    cancelable: true,
    composed: true,
    clientX: pt.x,
    clientY: pt.y,
    button: 0,
    buttons,
    detail: type === 'click' || type.endsWith('down') || type.endsWith('up') ? 1 : 0,
  };
  let ev: Event;
  if (type.startsWith('pointer')) {
    if (typeof w.PointerEvent !== 'function') return true;
    ev = new w.PointerEvent(type, { ...init, pointerId: 1, pointerType: 'mouse', isPrimary: true });
  } else ev = new w.MouseEvent(type, init);
  return el.dispatchEvent(ev);
}

function focusable(el: Element): boolean {
  return typeof (el as HTMLElement).focus === 'function';
}

function focus(el: Element): void {
  if (focusable(el)) {
    try {
      (el as HTMLElement).focus({ preventScroll: true });
    } catch {
      // ignore
    }
  }
}

export function scrollIntoView(el: Element): void {
  try {
    el.scrollIntoView?.({ block: 'nearest', inline: 'nearest' });
  } catch {
    // ignore: no layout
  }
}

/** Pointer, mouse and click events on `el`, at `pt`. */
export function click(el: Element, pt: Point): void {
  mouse(el, 'pointerover', pt, 0);
  mouse(el, 'mouseover', pt, 0);
  const down = mouse(el, 'pointerdown', pt, 1);
  const mdown = down ? mouse(el, 'mousedown', pt, 1) : false;
  if (mdown) focus(el);
  mouse(el, 'pointerup', pt, 0);
  if (down) mouse(el, 'mouseup', pt, 0);
  mouse(el, 'click', pt, 0);
}

function valueSetter(el: Element): ((v: string) => void) | null {
  const w = winOf(el);
  const proto = el.localName === 'textarea' ? w.HTMLTextAreaElement?.prototype : el.localName === 'select' ? w.HTMLSelectElement?.prototype : w.HTMLInputElement?.prototype;
  const desc = proto ? Object.getOwnPropertyDescriptor(proto, 'value') : undefined;
  if (desc?.set) {
    const set = desc.set;
    return (v: string) => set.call(el, v);
  }
  return null;
}

/** Write `v` the way a person's typing would: native setter, then `input` and `change`. */
export function setValue(el: HTMLInputElement | HTMLTextAreaElement, v: string, data: string): void {
  const set = valueSetter(el);
  if (set) set(v);
  else el.value = v;
  fireInput(el, data);
  fire(el, 'change');
}

function fire(el: Element, type: string): void {
  el.dispatchEvent(new (winOf(el).Event)(type, { bubbles: true, cancelable: false, composed: type === 'input' }));
}

function fireInput(el: Element, data: string | null, inputType = 'insertText'): void {
  const w = winOf(el);
  let ev: Event;
  try {
    ev = typeof w.InputEvent === 'function' ? new w.InputEvent('input', { bubbles: true, composed: true, inputType, data }) : new w.Event('input', { bubbles: true, composed: true });
  } catch {
    ev = new w.Event('input', { bubbles: true, composed: true });
  }
  el.dispatchEvent(ev);
}

export function typeText(el: Element, text: string, clear: boolean): void {
  focus(el);
  if (el.localName === 'input' || el.localName === 'textarea') {
    const f = el as HTMLInputElement | HTMLTextAreaElement;
    let next = clear ? text : f.value + text;
    const max = f.maxLength;
    if (typeof max === 'number' && max >= 0 && next.length > max) next = next.slice(0, max);
    setValue(f, next, text);
    return;
  }
  if (isEditable(el)) {
    if (clear) el.textContent = text;
    else el.append(el.ownerDocument.createTextNode(text));
    fireInput(el, text);
    return;
  }
  throw new ReinsError('E_BAD_ARGS', 'target does not take text');
}

const KEY_CODES: Record<UiKey, { key: string; code: string; keyCode: number }> = {
  Enter: { key: 'Enter', code: 'Enter', keyCode: 13 },
  Escape: { key: 'Escape', code: 'Escape', keyCode: 27 },
  Tab: { key: 'Tab', code: 'Tab', keyCode: 9 },
  Backspace: { key: 'Backspace', code: 'Backspace', keyCode: 8 },
  Delete: { key: 'Delete', code: 'Delete', keyCode: 46 },
  Space: { key: ' ', code: 'Space', keyCode: 32 },
  ArrowUp: { key: 'ArrowUp', code: 'ArrowUp', keyCode: 38 },
  ArrowDown: { key: 'ArrowDown', code: 'ArrowDown', keyCode: 40 },
  ArrowLeft: { key: 'ArrowLeft', code: 'ArrowLeft', keyCode: 37 },
  ArrowRight: { key: 'ArrowRight', code: 'ArrowRight', keyCode: 39 },
  PageUp: { key: 'PageUp', code: 'PageUp', keyCode: 33 },
  PageDown: { key: 'PageDown', code: 'PageDown', keyCode: 34 },
  Home: { key: 'Home', code: 'Home', keyCode: 36 },
  End: { key: 'End', code: 'End', keyCode: 35 },
};

function keyEvent(el: Element, type: string, k: UiKey): boolean {
  const w = winOf(el);
  const c = KEY_CODES[k];
  const ev = new w.KeyboardEvent(type, { key: c.key, code: c.code, bubbles: true, cancelable: true, composed: true });
  // keyCode/which are read-only legacy fields many handlers still check.
  for (const f of ['keyCode', 'which'] as const) {
    try {
      Object.defineProperty(ev, f, { get: () => c.keyCode });
    } catch {
      // ignore
    }
  }
  return el.dispatchEvent(ev);
}

/** Submit the form that owns `el`, the way pressing Enter in a field would. */
export function submitForm(el: Element): void {
  const form = (el as HTMLInputElement).form ?? el.closest('form');
  if (!form) return;
  if (typeof form.requestSubmit === 'function') {
    try {
      form.requestSubmit();
      return;
    } catch {
      // fall back below
    }
  }
  const ev = new (winOf(el).Event)('submit', { bubbles: true, cancelable: true });
  if (form.dispatchEvent(ev)) {
    try {
      form.submit();
    } catch {
      // ignore
    }
  }
}

/** Focusable elements in tab order, for Tab emulation. */
function tabbables(scope: Element, ok: (e: Element) => boolean): HTMLElement[] {
  const all = Array.from(scope.querySelectorAll('a[href],button,input,select,textarea,summary,[tabindex],[contenteditable]')) as HTMLElement[];
  const list = all.filter((e) => ok(e) && !(e as HTMLButtonElement).disabled && (e.getAttribute('tabindex') ?? '0') !== '-1');
  const positive = list.filter((e) => e.tabIndex > 0).sort((a, b) => a.tabIndex - b.tabIndex);
  return [...positive, ...list.filter((e) => !(e.tabIndex > 0))];
}

/**
 * Dispatch one key on `el`, then perform the common default action the browser would
 * not perform for a synthetic event: activate, submit, edit, move focus, step a select, scroll.
 */
export function pressKey(el: Element, k: UiKey, scope: Element, exposed: (e: Element) => boolean): void {
  const go = keyEvent(el, 'keydown', k);
  if (k === 'Enter' || k === 'Space') keyEvent(el, 'keypress', k);
  keyEvent(el, 'keyup', k);
  if (!go) return;
  const tag = el.localName;
  const type = tag === 'input' ? ((el as HTMLInputElement).type || 'text').toLowerCase() : '';
  const textField = (tag === 'input' && !['checkbox', 'radio', 'button', 'submit', 'reset', 'image', 'range', 'color', 'file'].includes(type)) || tag === 'textarea';
  switch (k) {
    case 'Enter':
      if (tag === 'button' || tag === 'a' || tag === 'summary' || (tag === 'input' && ['button', 'submit', 'reset', 'image'].includes(type))) click(el, centerOf(el));
      else if (tag === 'input' && textField) submitForm(el);
      return;
    case 'Space':
      if (tag === 'button' || tag === 'summary' || (tag === 'input' && ['checkbox', 'radio', 'button', 'submit', 'reset'].includes(type))) click(el, centerOf(el));
      else if (textField) typeText(el, ' ', false);
      return;
    case 'Backspace':
    case 'Delete':
      if (textField) {
        const f = el as HTMLInputElement;
        let start = f.value.length;
        let end = start;
        try {
          if (typeof f.selectionStart === 'number' && typeof f.selectionEnd === 'number') {
            start = f.selectionStart;
            end = f.selectionEnd;
          }
        } catch {
          // selection not supported on this type
        }
        if (start === end) {
          if (k === 'Backspace') start = Math.max(0, start - 1);
          else end = Math.min(f.value.length, end + 1);
        }
        const set = valueSetter(el);
        const next = f.value.slice(0, start) + f.value.slice(end);
        if (set) set(next);
        else f.value = next;
        fireInput(el, null, k === 'Backspace' ? 'deleteContentBackward' : 'deleteContentForward');
      }
      return;
    case 'Tab': {
      const list = tabbables(scope, exposed);
      if (!list.length) return;
      const i = list.indexOf(el as HTMLElement);
      focus(list[(i + 1) % list.length]!);
      return;
    }
    case 'ArrowUp':
    case 'ArrowDown':
      if (tag === 'select') {
        const s = el as HTMLSelectElement;
        const step = k === 'ArrowDown' ? 1 : -1;
        let i = s.selectedIndex + step;
        while (i >= 0 && i < s.options.length && s.options[i]!.disabled) i += step;
        if (i >= 0 && i < s.options.length && i !== s.selectedIndex) {
          s.selectedIndex = i;
          fireInput(s, null);
          fire(s, 'change');
        }
        return;
      }
      if (!textField) scrollBy(el, 0, k === 'ArrowDown' ? 40 : -40);
      return;
    case 'PageUp':
    case 'PageDown':
      if (!textField) scrollBy(el, 0, (k === 'PageDown' ? 1 : -1) * Math.max(100, (winOf(el).innerHeight || 600) * 0.85));
      return;
    case 'Home':
    case 'End':
      if (!textField) scrollTo(el, k === 'Home' ? 'top' : 'bottom');
      return;
    default:
      return;
  }
}

export function selectOption(el: Element, value: string): void {
  if (el.localName !== 'select') throw new ReinsError('E_BAD_ARGS', 'target is not a select');
  const s = el as HTMLSelectElement;
  const opts = Array.from(s.options);
  let i = opts.findIndex((o) => o.value === value);
  if (i < 0) i = opts.findIndex((o) => (o.label || o.text || '').replace(/\s+/g, ' ').trim() === value.trim());
  if (i < 0) throw new ReinsError('E_BAD_ARGS', 'no such option');
  if (opts[i]!.disabled) throw new ReinsError('E_BAD_ARGS', 'option is disabled');
  focus(s);
  if (s.multiple) opts[i]!.selected = true;
  else s.selectedIndex = i;
  fireInput(s, null);
  fire(s, 'change');
}

function scrollable(el: Element): boolean {
  const w = winOf(el);
  if (el.scrollHeight <= el.clientHeight && el.scrollWidth <= el.clientWidth) return false;
  try {
    const cs = w.getComputedStyle(el);
    return /(auto|scroll|overlay)/.test(`${cs.overflowY} ${cs.overflowX} ${cs.overflow}`);
  } catch {
    return false;
  }
}

/** The element itself or its nearest scrollable ancestor; null means the page. */
function scroller(el: Element | null): Element | null {
  for (let e = el; e && e !== e.ownerDocument.documentElement && e !== e.ownerDocument.body; e = e.parentElement) if (scrollable(e)) return e;
  return null;
}

export function scrollBy(el: Element | null, dx: number, dy: number, win?: Window): void {
  const s = scroller(el);
  if (s) {
    if (typeof s.scrollBy === 'function') s.scrollBy({ left: dx, top: dy });
    else {
      s.scrollLeft += dx;
      s.scrollTop += dy;
    }
    return;
  }
  const w = win ?? (el ? winOf(el) : null);
  try {
    w?.scrollBy({ left: dx, top: dy });
  } catch {
    // no layout
  }
}

export function scrollTo(el: Element | null, to: 'top' | 'bottom', win?: Window): void {
  const s = scroller(el);
  if (s) {
    s.scrollTop = to === 'top' ? 0 : s.scrollHeight;
    return;
  }
  const w = win ?? (el ? winOf(el) : null);
  if (!w) return;
  try {
    const h = w.document.documentElement?.scrollHeight ?? 0;
    w.scrollTo({ left: w.scrollX ?? 0, top: to === 'top' ? 0 : h });
  } catch {
    // no layout
  }
}

/** Human input that counts: trusted pointer, key, wheel and touch events. Bare hover does not. */
const HUMAN_EVENTS = ['pointerdown', 'pointerup', 'pointermove', 'mousedown', 'keydown', 'wheel', 'touchstart', 'touchmove'] as const;
/** If the person keeps going this long, a waiting `ui.*` command gives up with E_PAUSED. */
export const HUMAN_GIVE_UP_MS = 5000;

/**
 * Watches for real input in the capture phase. Each new burst (input after a quiet
 * period of `yieldMs`) calls `onBurst` once. `ui.*` commands wait for quiet.
 */
export class HumanWatch {
  #win: Window;
  #yieldMs: () => number;
  #onBurst: () => void;
  #isOverlay: (e: Event) => boolean;
  #last = -Infinity;
  #on = false;
  #handler = (e: Event) => this.#event(e);

  constructor(win: Window, yieldMs: () => number, onBurst: () => void, isOverlay: (e: Event) => boolean) {
    this.#win = win;
    this.#yieldMs = yieldMs;
    this.#onBurst = onBurst;
    this.#isOverlay = isOverlay;
  }

  start(): void {
    if (this.#on) return;
    this.#on = true;
    // Through the functions kept at load, like the overlay's own listeners (primordials.ts).
    for (const t of HUMAN_EVENTS) listen(this.#win, t, this.#handler, { capture: true, passive: true });
  }
  stop(): void {
    if (!this.#on) return;
    this.#on = false;
    for (const t of HUMAN_EVENTS) unlisten(this.#win, t, this.#handler, { capture: true });
  }

  #event(e: Event): void {
    // The native trusted flag: an object that says it is trusted is not the person.
    if (!isTrusted(e)) return;
    if ((e.type === 'pointermove' || e.type === 'mousemove') && !((e as MouseEvent).buttons > 0)) return;
    if (this.#isOverlay(e)) return;
    this.mark();
  }

  /** Record one human input now. */
  mark(t = Date.now()): void {
    const quiet = t - this.#last > Math.max(0, this.#yieldMs());
    this.#last = t;
    if (quiet) {
      try {
        this.#onBurst();
      } catch {
        // ignore
      }
    }
  }

  /** No human input for `yieldMs`: the human-priority rule allows synthetic input now. */
  get idle(): boolean {
    const yieldMs = this.#yieldMs();
    return !(yieldMs > 0) || Date.now() - this.#last >= yieldMs;
  }

  /** Wait until no human input for `yieldMs`. E_PAUSED if the person keeps going for 5 s. */
  async quiet(): Promise<void> {
    const yieldMs = this.#yieldMs();
    if (!(yieldMs > 0)) return;
    const start = Date.now();
    for (;;) {
      const wait = this.#last + yieldMs - Date.now();
      if (wait <= 0) return;
      if (Date.now() - start >= HUMAN_GIVE_UP_MS) throw new ReinsError('E_PAUSED', 'the user is using the page');
      await new Promise((r) => setTimeout(r, Math.min(wait, HUMAN_GIVE_UP_MS - (Date.now() - start)) + 1));
    }
  }
}
