/**
 * Chat (SPEC 9, 12 and 13): the checks every side makes on a chat message before it shows it,
 * relays it or hands it to a model. The shapes are in protocol.ts.
 *
 * A chat text is data wherever it goes. These functions only say whether a value has the
 * shape of one; they give it no meaning.
 */
import { wellFormed } from './crypto.js';
import { CHAT_MAX_NOTE, CHAT_MAX_TEXT, CHAT_RELAY, CHAT_STATES, CHAT_TO_PERSON } from './protocol.js';
import type { ChatFrom, ChatMessage, ChatRelay, ChatState } from './protocol.js';
import { isPlainObject } from './util.js';

/** Longest agent id or name a chat message may carry: what the hub hands out, with room to spare. */
const MAX_ID_CHARS = 64;
const MAX_NAME_CHARS = 120;

const LONE_SURROGATE = /[\uD800-\uDBFF](?![\uDC00-\uDFFF])|(?<![\uD800-\uDBFF])[\uDC00-\uDFFF]/g;

/**
 * The text of a chat message, as it is kept: white space trimmed from both ends, 1 to
 * CHAT_MAX_TEXT characters, well-formed Unicode. Undefined for anything else. Nothing inside
 * the text is changed: line breaks stay, and whoever shows it escapes what does not show.
 */
export function chatText(v: unknown): string | undefined {
  if (typeof v !== 'string') return undefined;
  // Cheap bound first: a megabyte of white space is not trimmed to find out it was too long.
  if (v.length > CHAT_MAX_TEXT * 4) return undefined;
  const t = v.trim();
  if (t.length < 1 || t.length > CHAT_MAX_TEXT || !wellFormed(t)) return undefined;
  return t;
}

/**
 * What the person typed, made well-formed: a lone surrogate (half of a pair, which a paste can
 * leave behind) becomes U+FFFD. A sealed session refuses to carry ill-formed text, so without
 * this the person's message would be shown and never delivered.
 */
export function chatWellFormed(text: string): string {
  return wellFormed(text) ? text : text.replace(LONE_SURROGATE, '�');
}

/**
 * A status note as it is kept: one line (every run of white space and control characters
 * becomes one space), at most CHAT_MAX_NOTE characters. An empty or missing note is the
 * empty string. Undefined when the value is no string, is too long, or is ill-formed.
 */
export function chatNote(v: unknown): string | undefined {
  if (v === undefined) return '';
  if (typeof v !== 'string' || v.length > CHAT_MAX_NOTE * 4) return undefined;
  const t = v.replace(/[\s\p{Cc}]+/gu, ' ').trim();
  if (t.length > CHAT_MAX_NOTE || !wellFormed(t)) return undefined;
  return t;
}

export function isChatState(v: unknown): v is ChatState {
  return (CHAT_STATES as readonly unknown[]).includes(v);
}

function chatFrom(v: unknown): ChatFrom | undefined {
  if (!isPlainObject(v)) return undefined;
  if (v.kind === 'person') return { kind: 'person' };
  if (v.kind !== 'agent') return undefined;
  const { id, name } = v;
  if (typeof id !== 'string' || id.length < 1 || id.length > MAX_ID_CHARS) return undefined;
  if (typeof name !== 'string' || name.length > MAX_NAME_CHARS || !wellFormed(name)) return undefined;
  return { kind: 'agent', id, name };
}

/** A value of `policy.chatRelay`, or undefined for anything else. `true` is `on`, `false` is `off`. */
export function chatRelayMode(v: unknown): ChatRelay | undefined {
  if (v === true) return 'on';
  if (v === false) return 'off';
  return (CHAT_RELAY as readonly unknown[]).includes(v) ? (v as ChatRelay) : undefined;
}

/** The stricter of two `chatRelay` values: `off` before `person` before `on`. */
export function stricterRelay(a: ChatRelay, b: ChatRelay): ChatRelay {
  return CHAT_RELAY[Math.min(CHAT_RELAY.indexOf(a), CHAT_RELAY.indexOf(b))] ?? 'off';
}

/**
 * The agent id a chat line carries, made safe to print in a line of one's own: letters,
 * digits and `. _ -` stay, every other character becomes `?`, and it is cut at 64. An id
 * a hub hands out (`a7`) comes through unchanged.
 */
export function chatIdShown(id: string): string {
  return String(id).slice(0, MAX_ID_CHARS).replace(/[^A-Za-z0-9._-]/g, '?') || '?';
}

/** Where a chat text is cut into lines: every line break, and the separators U+001C to U+001E that some line splitters end a line at. */
const DATA_BREAK = new RegExp(`\\r\\n|[\\n\\r\\v\\f\\x1c-\\x1e\\x85${String.fromCharCode(0x2028, 0x2029)}]`);
/** Control characters (tab aside) and the line separators. */
const DATA_CONTROL = new RegExp(`[\\x00-\\x08\\x0a-\\x1f\\x7f-\\x9f${String.fromCharCode(0x2028, 0x2029)}]`, 'g');

/** `s` on one line, with every control character but tab written as a visible `\u{XX}` escape: none reaches a model, or a terminal, raw. */
export function chatPlain(s: string): string {
  return s.replace(DATA_CONTROL, (c) => `\\u{${c.charCodeAt(0).toString(16).toUpperCase()}}`);
}

/**
 * A chat text as the lines a model is handed: each behind `| `, with no control character
 * left in it. A program that hands chat text to a model writes a line of its own first, saying
 * who spoke, and then these: nothing in a message can then pass for a line of the program's.
 */
export function chatDataLines(text: string): string[] {
  return text.split(DATA_BREAK).map((l) => `| ${chatPlain(l)}`);
}

export interface ChatAudienceQuery {
  /**
   * The ids of the agents that hear each other now, all of them in `members`. Under
   * `chatRelay: "on"` every member; under `"person"` the ones the person switched on; under
   * `"off"` none.
   */
  relay: readonly string[];
  /** Who speaks: the person, or the agent with this id. An agent that speaks is in `members`. */
  from: 'person' | { agent: string };
  /** Whom the message is addressed to: an agent, by id, or `person` on an agent's message. Absent: everyone. */
  to?: string;
  /** The ids of the agents in the room now: those whose grant holds `chat`, switched on. */
  members: readonly string[];
}

/**
 * `post`: the message is kept, and `hear` are the agents it is sent to, in room order.
 * `nobody`: a message of the person that no agent in the room would hear; it is not kept.
 * `refuse`: an agent's `to` that cannot be honoured, with the error code for its `chat.say`.
 */
export type ChatAudience = { outcome: 'post'; hear: string[] } | { outcome: 'nobody' } | { outcome: 'refuse'; code: 'E_BAD_ARGS' | 'E_DENIED' };

/**
 * Who hears a chat message (SPEC 12, "Chat"). The person sees every message in any case;
 * this says which agents are sent it.
 *
 *  1. The person speaks to the agent `to` names, when it is in the room, or without `to` to
 *     every agent in the room. With nobody to hear it the message is not kept.
 *  2. An agent's message with `to: "person"` is kept and sent to no agent, whatever the room
 *     relays.
 *  3. An agent's message with any other `to` is refused with `E_DENIED` when the speaker is
 *     not among the agents that hear each other, whoever `to` names, and with `E_BAD_ARGS`
 *     when `to` names no other agent among them. Otherwise it goes to that agent alone.
 *  4. An agent's message without `to` goes to every other agent that hears the speaker, and
 *     to no agent when the speaker is not among the agents that hear each other.
 *
 * The speaker is never among those who hear it.
 */
export function chatAudience(q: ChatAudienceQuery): ChatAudience {
  const members = Array.isArray(q.members) ? q.members : [];
  if (q.from === 'person') {
    const hear = q.to === undefined ? [...members] : members.includes(q.to) ? [q.to] : [];
    return hear.length ? { outcome: 'post', hear } : { outcome: 'nobody' };
  }
  const me = q.from.agent;
  // Only members hear anybody: an id in `relay` that is not in the room counts for nothing.
  const relay = Array.isArray(q.relay) ? members.filter((m) => q.relay.includes(m)) : [];
  if (q.to === CHAT_TO_PERSON) return { outcome: 'post', hear: [] };
  if (q.to !== undefined) {
    // Refused before the name is looked at, so the answer says nothing about who is attached.
    if (!relay.includes(me)) return { outcome: 'refuse', code: 'E_DENIED' };
    if (q.to === me || !relay.includes(q.to)) return { outcome: 'refuse', code: 'E_BAD_ARGS' };
    return { outcome: 'post', hear: [q.to] };
  }
  return { outcome: 'post', hear: relay.includes(me) ? relay.filter((m) => m !== me) : [] };
}

/**
 * A chat message taken off the wire, rebuilt from its checked fields: a positive integer id,
 * a sender of a known kind, a text within the bounds, a finite time, and `to` when it is a
 * short string. Undefined when any of them does not hold. Unknown fields are dropped.
 */
export function chatMessage(v: unknown): ChatMessage | undefined {
  if (!isPlainObject(v)) return undefined;
  const { id, ts, to } = v;
  if (typeof id !== 'number' || !Number.isSafeInteger(id) || id < 1) return undefined;
  if (typeof ts !== 'number' || !Number.isFinite(ts)) return undefined;
  const from = chatFrom(v.from);
  const text = chatText(v.text);
  // A text that trimming would change did not come from a room that keeps the rule.
  if (from === undefined || text === undefined || text !== v.text) return undefined;
  const m: ChatMessage = { id, from, text, ts };
  if (to !== undefined) {
    if (typeof to !== 'string' || to.length < 1 || to.length > MAX_ID_CHARS) return undefined;
    m.to = to;
  }
  return m;
}
