import { AUTH_CONTEXT, ReinsError } from './protocol.js';
import type { Role } from './protocol.js';

const ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_';
const LOOKUP = (() => {
  const t = new Int16Array(128).fill(-1);
  for (let i = 0; i < ALPHABET.length; i++) t[ALPHABET.charCodeAt(i)] = i;
  return t;
})();

const enc = new TextEncoder();

function subtle(): SubtleCrypto {
  const c = (globalThis as { crypto?: Crypto }).crypto;
  if (!c || !c.subtle) throw new ReinsError('E_INTERNAL', 'WebCrypto is not available');
  return c.subtle;
}

/** base64url without padding. */
export function b64urlEncode(bytes: Uint8Array): string {
  let out = '';
  let i = 0;
  for (; i + 2 < bytes.length; i += 3) {
    const n = (bytes[i]! << 16) | (bytes[i + 1]! << 8) | bytes[i + 2]!;
    out += ALPHABET[(n >> 18) & 63]! + ALPHABET[(n >> 12) & 63]! + ALPHABET[(n >> 6) & 63]! + ALPHABET[n & 63]!;
  }
  const rest = bytes.length - i;
  if (rest === 1) {
    const n = bytes[i]! << 16;
    out += ALPHABET[(n >> 18) & 63]! + ALPHABET[(n >> 12) & 63]!;
  } else if (rest === 2) {
    const n = (bytes[i]! << 16) | (bytes[i + 1]! << 8);
    out += ALPHABET[(n >> 18) & 63]! + ALPHABET[(n >> 12) & 63]! + ALPHABET[(n >> 6) & 63]!;
  }
  return out;
}

/** Decode base64url. Trailing `=` padding is tolerated; any other character outside the alphabet throws `E_BAD_ARGS`. */
export function b64urlDecode(text: string): Uint8Array {
  if (typeof text !== 'string') throw new ReinsError('E_BAD_ARGS', 'invalid base64url');
  let s = text;
  let pad = 0;
  while (s.endsWith('=') && pad < 2) {
    s = s.slice(0, -1);
    pad++;
  }
  if (s.length % 4 === 1 || (pad > 0 && (s.length + pad) % 4 !== 0)) throw new ReinsError('E_BAD_ARGS', 'invalid base64url');
  const out = new Uint8Array(Math.floor((s.length * 3) / 4));
  let o = 0;
  let acc = 0;
  let bits = 0;
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    const v = c < 128 ? LOOKUP[c]! : -1;
    if (v < 0) throw new ReinsError('E_BAD_ARGS', 'invalid base64url');
    acc = (acc << 6) | v;
    bits += 6;
    if (bits >= 8) {
      bits -= 8;
      out[o++] = (acc >> bits) & 0xff;
    }
  }
  return out;
}

/** `bytes` random bytes (default 32) from the platform CSPRNG, base64url. */
export function randomToken(bytes = 32): string {
  const c = (globalThis as { crypto?: Crypto }).crypto;
  if (!c) throw new ReinsError('E_INTERNAL', 'WebCrypto is not available');
  if (!Number.isSafeInteger(bytes) || bytes < 1 || bytes > 65_536) throw new ReinsError('E_BAD_ARGS', 'invalid token length');
  return b64urlEncode(c.getRandomValues(new Uint8Array(bytes)));
}

/** SHA-256, base64url. Strings are hashed as UTF-8. */
export async function sha256(data: string | Uint8Array): Promise<string> {
  const bytes = typeof data === 'string' ? enc.encode(data) : new Uint8Array(data);
  return b64urlEncode(new Uint8Array(await subtle().digest('SHA-256', bytes)));
}

/** HMAC-SHA256 keyed by the UTF-8 bytes of `key`, over the UTF-8 bytes of `msg`. base64url. */
export async function hmacSha256(key: string, msg: string): Promise<string> {
  const k = await subtle().importKey('raw', enc.encode(key), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
  return b64urlEncode(new Uint8Array(await subtle().sign('HMAC', k, enc.encode(msg))));
}

/**
 * Compare two strings in time that depends only on their lengths. Returns false for
 * non-strings. Proofs have a fixed length, so the length leak reveals nothing secret.
 */
export function timingSafeEqual(a: string, b: string): boolean {
  if (typeof a !== 'string' || typeof b !== 'string') return false;
  const n = Math.max(a.length, b.length);
  let diff = a.length ^ b.length;
  for (let i = 0; i < n; i++) diff |= (a.charCodeAt(i) | 0) ^ (b.charCodeAt(i) | 0);
  return diff === 0;
}

/**
 * Whether a string is well-formed UTF-16: no lone surrogates. UTF-8 encoding maps every
 * lone surrogate to U+FFFD, so two different ill-formed strings would share one MAC. Such a
 * string is never sealed, opened or used in a proof.
 */
export function wellFormed(s: string): boolean {
  const native = (s as { isWellFormed?: () => boolean }).isWellFormed;
  if (typeof native === 'function') return native.call(s);
  return !/[\uD800-\uDBFF](?![\uDC00-\uDFFF])|(?<![\uD800-\uDBFF])[\uDC00-\uDFFF]/.test(s);
}

type ProofFields = { role: Role; kid: string; nonce: string; cnonce: string };

function proofInput(context: string, f: ProofFields): string {
  const parts = [f.role, f.kid, f.nonce, f.cnonce];
  // A newline inside a field would make the message ambiguous; so would a lone surrogate.
  if (parts.some((p) => typeof p !== 'string' || p.includes('\n') || !wellFormed(p))) throw new ReinsError('E_AUTH', 'invalid proof fields');
  return `${context}\n${parts.join('\n')}`;
}

/** The proof a peer sends in `hello.auth.proof`. */
export async function peerProof(key: string, f: ProofFields): Promise<string> {
  return hmacSha256(key, proofInput(AUTH_CONTEXT.peer, f));
}

/** The proof the hub sends in `welcome.proof`. */
export async function hubProof(key: string, f: ProofFields): Promise<string> {
  return hmacSha256(key, proofInput(AUTH_CONTEXT.hub, f));
}
