// ───────────────────────────── public types ─────────────────────────────

export interface CommandContext {
  agent: AgentInfo;
  scopes: Scope[];
}

export interface ConsentRequest {
  kind: 'attach' | 'action';
  agent: AgentInfo;
  scopes?: Scope[];
  action?: ActionDef;
  args?: unknown;
  reason?: string;
  /** Present, and false, when the driver could not verify the hub (no key and no app-built link). */
  hubVerified?: false;
  /**
   * On an attach request: what the person tightened for this agent before, which stays for
   * the new grant whatever the answer to this request says about scopes (one line each).
   */
  kept?: string[];
}

export interface DriverOptions {
  app: AppInfo;
  /** ws URL, default ws://127.0.0.1:7346 */
  hub?: string;
  /** Use this link instead of a WebSocket. */
  link?: Link;
  /** Surface key, when the hub requires one. */
  key?: string;
  /** Default 'guarded'. */
  policy?: PolicyInput;
  /** Replaces the built-in consent prompt. */
  consent?: (req: ConsentRequest) => Promise<boolean>;
  /** Show the control indicator while an agent is attached. Default true. */
  indicator?: boolean;
  /** Reconnect after an unexpected close, with backoff 0.5 s to 10 s. Default true. */
  reconnect?: boolean;
  /** Subtree to expose, default document.body. */
  root?: Element;
}

export type DriverStatus = 'idle' | 'connecting' | 'ready' | 'controlled' | 'paused' | 'offline';
export type DriverEvent = 'status' | 'attach' | 'detach' | 'command' | 'level' | 'rule' | 'scopes' | 'chat';

/**
 * What the app hears of a chat message (`on('chat', ...)`): who said it and how long it is.
 * Never the text, which stays in the driver's panel; and nothing in this API posts one.
 */
export interface ChatNotice {
  id: number;
  from: { kind: 'person' } | { kind: 'agent'; id: string; name: string };
  /** The length of the text, in characters. */
  chars: number;
  /** The agent the message was addressed to, when it was not for everyone. */
  to?: string;
}

/** One attached agent and what the person set for it. A copy: changing it changes nothing. */
export interface AttachedAgent {
  agent: AgentInfo;
  /** The level the person set for this grant. `ask` until they change it. */
  level: Level;
  /** The scopes in force now. */
  scopes: Scope[];
  /** The scopes granted at attach: `scopes`, and those the person has switched off. */
  granted: Scope[];
  /** The person's rules for this agent, by action name. */
  rules: Record<string, Decision>;
}

export interface Driver {
  action<A = any>(def: ActionDef, handler: (args: A, ctx: CommandContext) => unknown | Promise<unknown>): this;
  view<D = any>(def: ViewDef, render: (data: D, ctx: CommandContext) => unknown | Promise<unknown>): this;
  state(name: string, get: () => unknown, description?: string): this;
  notify(name?: string): void;
  connect(): Promise<void>;
  disconnect(): void;
  on(event: DriverEvent, fn: (e: any) => void): () => void;
  readonly status: DriverStatus;
  readonly manifest: Manifest;
  readonly policy: Policy;
  /**
   * True while connected to a hub the driver verified: it holds `options.key` and the hub
   * proved the same key in `welcome`, or the app passed `options.link`. False otherwise.
   */
  readonly hubVerified: boolean;
  /**
   * The attached agents, each with its level, scopes and rules. Read-only: the level, the
   * rules and the scope switches change only by the person's own input in the panel, and
   * nothing in this API sets them.
   */
  agents(): AttachedAgent[];
  pause(): void;
  resume(): void;
  stop(): void;
}

// ───────────────────────────── internals ─────────────────────────────

interface Session {
  ag: string;
  agent: AgentInfo;
  /** The scopes in force now: `granted` without those the person switched off. */
  scopes: Scope[];
  /** The scopes granted at attach. The person's switches never go beyond them. */
  granted: Scope[];
  /** The level the person set for this grant. A new grant starts at `ask`. */
  level: Level;
  /** The levels on offer: `strict` and `ask`, and `auto` and `bypass` where the policy and the hub both list them. */
  offered: Level[];
  /**
   * What the hub's policy decides for each of this app's actions, as the hub said in
   * `attach` (`decisions`): which actions it confirms (`c:1`) and which it refuses. Null when
   * it did not say: the hub may then confirm anything, and what the person may loosen is
   * worked out as if it confirmed every action.
   */
  hub: Map<string, Decision> | null;
  /** The person's rules for this agent, by action name. They end with the grant. */
  rules: Map<string, Decision>;
  /** The tree and revision this agent last received from `observe`. */
  nodes: UiNode[] | null;
  rev: number;
  subs: Set<Topic>;
  /** State values last sent to this agent, for merge patches. */
  sent: Map<string, unknown>;
  /** Actions approved under this grant (`consent.remember: 'session'`). */
  approved: Set<string>;
  /** Stands for this grant in the chat room: a new grant has a new one, and reads nothing of the old. */
  chat: object;
  /**
   * Who the agent is, as far as this surface can tell: the id of its credential, which a
   * verified hub sends with `attach`. Empty when it cannot tell (no id, or a hub it did not
   * verify): all such agents are one to it.
   */
  cred: string;
}

/**
 * What the person tightened for one agent: the level `strict`, the rules `confirm` and `deny`,
 * scopes switched off. Kept for as long as the page lives, and put on every new grant of the
 * same agent. Nothing that lets an agent do more is ever in it.
 */
interface Tightened {
  strict: boolean;
  rules: Map<string, 'confirm' | 'deny'>;
  off: Set<Scope>;
}

/** Credentials whose tightenings are kept apart; beyond that they are kept together, which only asks more. */
const MAX_KEPT_CREDS = 256;

interface Stream {
  ch: number;
  ag: string;
  granter: CreditGranter;
  nextSeq: number | undefined;
}

/** What a handler reports back about a command, for the activity log. */
interface CommandNote {
  /** An action ran without the policy alone allowing it: who let it. */
  by?: NonNullable<ActivityEntry['by']>;
}

type Handler = (s: Session, p: Record<string, unknown>, f: ReqFrame, note: CommandNote) => unknown;

const DEFAULT_HUB = `ws://127.0.0.1:${DEFAULT_PORT}/`;
const TARGET_MAX = 130;
const MAX_TEXT = 10_000;
const MAX_READ = 8000;
const UI_EVENT_INTERVAL_MS = 100;
const NAV_POLL_MS = 1000;
/** Consent prompts pending at once: one per agent, four in total. */
const MAX_PROMPTS = 4;
/** How long a pointer frame may reuse the last overlay visibility check. */
const OVERLAY_CHECK_CACHE_MS = 250;
/** The Activity tab is redrawn at most this often. */
const ACTIVITY_DRAW_MS = 200;
/**
 * After a refused or timed-out prompt, no new prompt of the same kind (an agent's action
 * prompts; attach prompts surface-wide) for 2 s, doubling with each further refusal up to
 * 60 s; an approval resets it. Three explicit refusals in a row of one agent's action
 * prompts revoke that agent's grant.
 */
const COOL_OFF_BASE_MS = 2000;
const COOL_OFF_MAX_MS = 60_000;
const REVOKE_AFTER_DENIALS = 3;
/** Agents tracked for cool-off at once; the oldest entry goes first. */
const MAX_COOL_OFF_ENTRIES = 64;

interface CoolOff {
  /** No new prompt before this time (ms since epoch). */
  until: number;
  /** Refusals (explicit or timed out) since the last approval. */
  level: number;
  /** Explicit refusals since the last approval. */
  denials: number;
}

function hasOwn(o: object, k: string): boolean {
  return Object.prototype.hasOwnProperty.call(o, k);
}
function isObj(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}
function bad(msg: string): never {
  throw new ReinsError('E_BAD_ARGS', msg);
}
function get(p: Record<string, unknown>, k: string): unknown {
  return hasOwn(p, k) ? p[k] : undefined;
}
function optStr(p: Record<string, unknown>, k: string, max: number): string | undefined {
  const v = get(p, k);
  if (v === undefined) return undefined;
  if (typeof v !== 'string') bad(`${k}: expected string`);
  if (v.length > max) bad(`${k}: longer than ${max}`);
  return v;
}
function reqStr(p: Record<string, unknown>, k: string, max: number): string {
  const v = optStr(p, k, max);
  if (v === undefined) bad(`${k}: required`);
  return v;
}
function optNum(p: Record<string, unknown>, k: string, min: number, max: number, int = false): number | undefined {
  const v = get(p, k);
  if (v === undefined) return undefined;
  if (typeof v !== 'number' || !Number.isFinite(v)) bad(`${k}: expected number`);
  if (int && !Number.isInteger(v)) bad(`${k}: expected integer`);
  if (v < min || v > max) bad(`${k}: out of range`);
  return v;
}
function optBool(p: Record<string, unknown>, k: string): boolean | undefined {
  const v = get(p, k);
  if (v === undefined) return undefined;
  if (typeof v !== 'boolean') bad(`${k}: expected boolean`);
  return v;
}
function clamp(v: number, lo: number, hi: number): number {
  return Math.min(hi, Math.max(lo, v));
}
function jsonClone<T>(v: T): T {
  if (v === undefined) return v;
  const s = JSON.stringify(v);
  return (s === undefined ? undefined : JSON.parse(s)) as T;
}

/** Keys whose default action edits a text field (Space types a space). */
const EDIT_KEYS = new Set(['Backspace', 'Delete', 'Space']);

function isReadOnly(el: Element): boolean {
  return (el as HTMLInputElement).readOnly === true || el.getAttribute('aria-readonly') === 'true';
}

/** Some element inside `el` is private (marked, a private field, or remembered as either). */
function hasPrivateInside(el: Element): boolean {
  for (const e of Array.from(el.querySelectorAll('*'))) if (isPrivateSelf(e)) return true;
  return false;
}

/** A thrown handler error as a safe wire error. */
function fromHandler(e: unknown, what: string): ReinsError {
  if (e instanceof ReinsError) return e;
  if (isObj(e) || e instanceof Error) {
    const o = e as { name?: unknown; code?: unknown; message?: unknown };
    if (o.name === 'ReinsError' && typeof o.code === 'string' && (ERROR_CODES as readonly string[]).includes(o.code) && typeof o.message === 'string') {
      return new ReinsError(o.code as ErrorCode, o.message.slice(0, 200));
    }
  }
  console.error(`[reins] ${what} failed:`, e);
  return new ReinsError('E_INTERNAL', `${what} failed`);
}

/** A handler result as bounded JSON, or undefined. */
function resultJson(v: unknown): unknown {
  if (v === undefined) return undefined;
  let s: string | undefined;
  try {
    s = JSON.stringify(v);
  } catch {
    throw new ReinsError('E_INTERNAL', 'result is not JSON');
  }
  if (s === undefined) return undefined;
  if (utf8Length(s) > MAX_RESULT_BYTES) throw new ReinsError('E_TOO_LARGE', 'result larger than 32 KiB');
  return JSON.parse(s);
}

class ReinsDriver implements Driver {
  #o: DriverOptions;
  #policy: Policy;
  #win: Window & typeof globalThis;
  #doc: Document;
  #root: Element | null = null;

  #actions = new Map<string, { def: ActionDef; run: (args: any, ctx: CommandContext) => unknown }>();
  #views = new Map<string, { def: ViewDef; run: (data: any, ctx: CommandContext) => unknown }>();
  #states = new Map<string, { def: StateDef; get: () => unknown }>();
  #manifest: Manifest | null = null;
  #listeners = new Map<string, Set<(e: any) => void>>();

  // connection
  #want = false;
  #conn: 'idle' | 'connecting' | 'ready' | 'offline' = 'idle';
  #epoch = 0;
  #link: Link | null = null;
  #peer: Peer | null = null;
  #limits: Limits = DEFAULT_LIMITS;
  #linkUsed = false;
  #attempt = 0;
  #retryTimer: ReturnType<typeof setTimeout> | null = null;
  #hbTimer: ReturnType<typeof setInterval> | null = null;
  #pinging = false;
  #waiter: { resolve(): void; reject(e: unknown): void } | null = null;
  #connecting: Promise<void> | null = null;
  #lastStatus: DriverStatus = 'idle';

  // sessions and page state
  #sessions = new Map<string, Session>();
  #streams = new Map<number, Stream>();
  #paused = false;
  #tree: UiTree;
  #frames: Frames;
  #queue: CommandQueue;
  #overlay: Overlay | null = null;
  #motion: CursorMotion | null = null;
  #human: HumanWatch;
  #cursorOn = false;
  #cursorLabelSet = false;
  /** The agent that last showed or moved the cursor. */
  #cursorAg: string | undefined;
  /** The last commands, newest last, for the Activity tab: names and outcomes only. */
  #activity: ActivityEntry[] = [];
  #activityTimer: ReturnType<typeof setTimeout> | null = null;
  #activityDrawn = -Infinity;
  /** The app's actions with the policy's decision for each, as the panel lists them. */
  #panelActions: PanelModel['actions'] | null = null;
  /** The page's chat room. It lives as long as this driver, in memory only. */
  #room: ChatRoom;
  /**
   * Whether this surface has chat at all: the policy grants the scope, and there is a panel
   * the person can open. Without a place to read and answer, no grant gets `chat`.
   */
  #chatOn: boolean;
  #chatTimer: ReturnType<typeof setTimeout> | null = null;
  /** App actions an agent asked for that are running now: the chat composer takes no input meanwhile. */
  #chatHeld = 0;
  #consentChain: Promise<void> = Promise.resolve();
  /** Consent prompts pending per agent. */
  #asking = new Map<string, number>();
  #askingTotal = 0;
  /** Cool-off after refused action prompts, per agent (see COOL_OFF_*). */
  #coolOff = new Map<string, CoolOff>();
  /** Cool-off after refused attach prompts, one for the whole surface. */
  #attachCoolOff: CoolOff = { until: 0, level: 0, denials: 0 };
  /** Whether the current hub connection is verified (see `hubVerified`). */
  #hubVerified = false;
  /** Stop was used on this page: every later attach needs at least `confirm`. */
  #stopped = false;
  /** What the person tightened, by credential id (`''`: the agents this surface cannot tell apart). */
  #kept = new Map<string, Tightened>();
  /** More credentials came than are kept apart: what is kept under `''` then holds for every agent. */
  #keptShared = false;
  /** The hub changed what the room relays and the person's switch went with it: the Chat tab says so until they have seen it. */
  #relayReset = false;
  /** Consent requests an app's own handler has not answered yet, each with its deadline by the clock. */
  #customAsks = new Set<{ until: number; expire(): void }>();
  #refreshDue = 0;
  #activityDue = 0;
  #stopGen = 0;
  #overlayOkAt = -Infinity;
  #overlayOk = true;

  // DOM watching
  #domOn = false;
  #mo: MutationObserver | null = null;
  #refreshTimer: ReturnType<typeof setTimeout> | null = null;
  #uiTimer: ReturnType<typeof setTimeout> | null = null;
  #uiSentRev = -1;
  #uiSentAt = -Infinity;
  #navTimer: ReturnType<typeof setInterval> | null = null;
  #navUrl = '';
  #navTitle = '';
  #timers = new Set<ReturnType<typeof setTimeout>>();
  #onDomChange = () => this.#scheduleRefresh();
  /**
   * Keep privacy sticky: an element that was private when it changed stays private, and a
   * text entry that takes the place of a removed private field is private too. Removals are
   * noted before insertions, so a swap within one record is recognised.
   */
  #onMutations = (records: MutationRecord[]) => {
    for (const r of records) {
      if (r.type !== 'childList') continue;
      const parent = r.target.nodeType === 1 ? (r.target as Element) : null;
      for (const n of Array.from(r.removedNodes)) if (n.nodeType === 1) notePrivateRemoved(n as Element, parent);
    }
    for (const r of records) {
      if (r.type === 'attributes') {
        const t = r.target as Element;
        if (wasPrivateAttr(t, r.attributeName, r.oldValue)) markPrivate(t, r.attributeName !== 'data-reins');
      } else if (r.type === 'childList') {
        const parent = r.target.nodeType === 1 ? (r.target as Element) : null;
        for (const n of Array.from(r.addedNodes)) if (n.nodeType === 1) notePrivateAdded(n as Element, parent);
      }
    }
    this.#scheduleRefresh();
  };

  /** Handle mutations not yet delivered, so the tree never sees a change before its privacy note. */
  #flushMutations(): void {
    const mo = this.#mo;
    if (!mo || typeof mo.takeRecords !== 'function') return;
    const recs = mo.takeRecords();
    if (recs.length) this.#onMutations(recs);
  }
  #onNav = () => this.#checkNav();
  #onVisibility = () => {
    if (!this.#frames.live) this.#motion?.finish();
  };

  constructor(options: DriverOptions) {
    if (!isObj(options) || !isObj(options.app)) throw new ReinsError('E_BAD_ARGS', 'createDriver: options.app is required');
    this.#o = { ...options };
    this.#policy = resolvePolicy(options.policy);
    if (this.#policy.profile === 'kiosk' && options.link === undefined && !this.#hasKey) {
      // Nobody is there to confirm an unverified hub, so a kiosk must authenticate it.
      throw new ReinsError('E_BAD_ARGS', 'createDriver: the kiosk profile needs options.key (the surface key) to verify the hub, or an app-built options.link');
    }
    const doc = options.root?.ownerDocument ?? globalThis.document;
    if (!doc || !doc.defaultView) throw new Error('@offensiveadhd/reins/driver needs a browser document');
    this.#doc = doc;
    this.#win = doc.defaultView as Window & typeof globalThis;
    this.#chatOn = this.#policy.scopes.includes('chat') && this.#policy.human.panel && options.indicator !== false;
    // No agent hears another until an attach has told what the hub's policy allows (#attach).
    this.#room = new ChatRoom('off');
    this.#frames = new Frames(this.#win);
    this.#queue = new CommandQueue(this.#frames);
    this.#tree = new UiTree({
      root: () => this.#root,
      exposure: this.#policy.exposure,
      isOverlay: (el) => this.#overlay !== null && this.#overlay.isOverlay(el),
    });
    this.#human = new HumanWatch(
      this.#win,
      () => this.#policy.human.yieldMs,
      () => this.#onHumanBurst(),
      (e) => this.#overlay !== null && typeof e.composedPath === 'function' && e.composedPath().includes(this.#overlay.host),
    );
  }

  // ───────── registration ─────────

  #checkOpen(kind: string, name: unknown): void {
    if (this.#want || this.#manifest) throw new Error(`@offensiveadhd/reins/driver: register ${kind}s before connect()`);
    if (typeof name !== 'string') throw new ReinsError('E_BAD_ARGS', `${kind} name must be a string`);
  }

  action<A = any>(def: ActionDef, handler: (args: A, ctx: CommandContext) => unknown | Promise<unknown>): this {
    this.#checkOpen('action', def?.name);
    if (this.#actions.has(def.name)) throw new ReinsError('E_BAD_ARGS', `duplicate action ${def.name}`);
    if (typeof handler !== 'function') throw new ReinsError('E_BAD_ARGS', 'action handler must be a function');
    this.#actions.set(def.name, { def: jsonClone(def), run: handler });
    return this;
  }

  view<D = any>(def: ViewDef, render: (data: D, ctx: CommandContext) => unknown | Promise<unknown>): this {
    this.#checkOpen('view', def?.name);
    if (this.#views.has(def.name)) throw new ReinsError('E_BAD_ARGS', `duplicate view ${def.name}`);
    if (typeof render !== 'function') throw new ReinsError('E_BAD_ARGS', 'view renderer must be a function');
    this.#views.set(def.name, { def: jsonClone(def), run: render });
    return this;
  }

  state(name: string, getter: () => unknown, description?: string): this {
    this.#checkOpen('state', name);
    if (this.#states.has(name)) throw new ReinsError('E_BAD_ARGS', `duplicate state ${name}`);
    if (typeof getter !== 'function') throw new ReinsError('E_BAD_ARGS', 'state getter must be a function');
    const def: StateDef = { name };
    if (description !== undefined) def.description = description;
    this.#states.set(name, { def, get: getter });
    return this;
  }

  #buildManifest(): Manifest {
    return validateManifest({
      reins: PROTOCOL_VERSION,
      app: this.#o.app,
      actions: [...this.#actions.values()].map((a) => a.def),
      views: [...this.#views.values()].map((v) => v.def),
      state: [...this.#states.values()].map((s) => s.def),
      exposure: this.#policy.exposure,
      profile: this.#policy.profile,
    });
  }

  get manifest(): Manifest {
    return jsonClone(this.#manifest ?? this.#buildManifest());
  }
  get policy(): Policy {
    return jsonClone(this.#policy);
  }
  get hubVerified(): boolean {
    return this.#hubVerified;
  }
  agents(): AttachedAgent[] {
    return [...this.#sessions.values()].map((s) => ({
      agent: { ...s.agent },
      level: s.level,
      scopes: [...s.scopes],
      granted: [...s.granted],
      rules: Object.fromEntries(s.rules),
    }));
  }
  get #hasKey(): boolean {
    return typeof this.#o.key === 'string' && this.#o.key.length > 0;
  }

  // ───────── events ─────────

  on(event: DriverEvent, fn: (e: any) => void): () => void {
    let set = this.#listeners.get(event);
    if (!set) this.#listeners.set(event, (set = new Set()));
    set.add(fn);
    return () => set!.delete(fn);
  }

  #emit(event: DriverEvent, e: unknown): void {
    for (const fn of [...(this.#listeners.get(event) ?? [])]) {
      try {
        fn(e);
      } catch (err) {
        console.error('[reins] listener failed:', err);
      }
    }
  }

  get status(): DriverStatus {
    if (this.#conn !== 'ready') return this.#conn;
    if (this.#paused) return 'paused';
    return this.#sessions.size ? 'controlled' : 'ready';
  }

  #statusChanged(): void {
    const s = this.status;
    if (s === this.#lastStatus) return;
    this.#lastStatus = s;
    this.#emit('status', s);
  }

  #setConn(c: 'idle' | 'connecting' | 'ready' | 'offline'): void {
    this.#conn = c;
    this.#statusChanged();
  }

  // ───────── connection ─────────

  connect(): Promise<void> {
    if (this.#connecting) return this.#connecting;
    // Inside a frame the embedding page decides what the person sees: it can cover or overlay
    // the consent prompt and the indicator, and the driver cannot tell. So a framed page stays
    // off the hub altogether, before anything is sent or shown, unless the app's policy opts in.
    if (!this.#policy.framed && this.#framed) {
      return Promise.reject(new ReinsError('E_DENIED', 'this page is inside a frame, where the page around it could cover the consent prompt; open it in its own tab, or set policy.framed'));
    }
    try {
      this.#manifest = this.#buildManifest();
    } catch (e) {
      return Promise.reject(e);
    }
    this.#want = true;
    this.#root = this.#o.root ?? this.#doc.body ?? this.#doc.documentElement;
    this.#startDom();
    this.#connecting = new Promise<void>((resolve, reject) => {
      this.#waiter = { resolve, reject };
    });
    // A caller that never awaits must not see an unhandled rejection.
    this.#connecting.catch(() => {});
    void this.#tryOpen();
    return this.#connecting;
  }

  /** The driver's document is not the top-level one of its tab. A window that cannot be asked counts as framed. */
  get #framed(): boolean {
    try {
      return this.#win.top !== this.#win;
    } catch {
      return true;
    }
  }

  get #ownsSocket(): boolean {
    return this.#o.link === undefined;
  }

  async #tryOpen(): Promise<void> {
    this.#retryTimer = null;
    try {
      await this.#open();
      this.#attempt = 0;
      const w = this.#waiter;
      this.#waiter = null;
      w?.resolve();
    } catch (e) {
      if (!this.#want) return;
      this.#setConn('offline');
      if (this.#ownsSocket && this.#o.reconnect !== false) this.#scheduleRetry();
      else {
        const w = this.#waiter;
        this.#waiter = null;
        w?.reject(e);
      }
    }
  }

  #scheduleRetry(): void {
    if (!this.#want || this.#retryTimer) return;
    const base = Math.min(10_000, 500 * 2 ** Math.min(this.#attempt, 5));
    this.#attempt++;
    const delay = base + Math.random() * Math.min(1000, base * 0.3);
    this.#retryTimer = setTimeout(() => void this.#tryOpen(), delay);
  }

  async #open(): Promise<void> {
    const epoch = ++this.#epoch;
    this.#hubVerified = false;
    this.#setConn('connecting');
    let link: Link;
    if (this.#o.link) {
      if (this.#linkUsed) throw new ReinsError('E_GONE', 'link already used');
      this.#linkUsed = true;
      link = this.#o.link;
    } else {
      const WS = this.#win.WebSocket ?? globalThis.WebSocket;
      if (typeof WS !== 'function') throw new ReinsError('E_GONE', 'WebSocket unavailable');
      link = await wsLink(new WS(this.#o.hub ?? DEFAULT_HUB, WS_SUBPROTOCOL));
    }
    if (epoch !== this.#epoch || !this.#want) {
      link.close();
      throw new ReinsError('E_GONE', 'connection superseded');
    }
    this.#link = link;
    const manifest = this.#manifest!;
    const hello: Parameters<typeof clientConnect>[1] = {
      role: 'surface',
      name: this.#o.app.name,
      kid: this.#o.app.id,
      surface: { manifest, url: this.#win.location.href, title: this.#doc.title },
    };
    if (this.#o.key !== undefined) hello.key = this.#o.key;
    const conn = await clientConnect(link, hello);
    const welcome = conn.welcome;
    link = conn.link;
    this.#link = link;
    if (epoch !== this.#epoch || !this.#want) {
      link.close();
      throw new ReinsError('E_GONE', 'connection superseded');
    }
    // With a key, clientConnect resolves only once the hub proved the key and confirmed the
    // sealed session. An app-built link needs no proof.
    this.#hubVerified = this.#o.link !== undefined || conn.sealed;
    this.#limits = { ...DEFAULT_LIMITS, ...welcome.limits };
    this.#navUrl = this.#win.location.href;
    this.#navTitle = this.#doc.title;
    this.#peer = new Peer(
      link,
      {
        request: (m, p, f) => this.#request(m, p, f),
        binary: (b) => this.#onBinary(b),
        close: () => this.#onClose(epoch),
      },
      { limits: this.#limits },
    );
    this.#startHeartbeat();
    this.#setConn('ready');
  }

  #startHeartbeat(): void {
    this.#stopHeartbeat();
    const hb = this.#limits.heartbeatMs > 0 ? this.#limits.heartbeatMs : DEFAULT_LIMITS.heartbeatMs;
    this.#hbTimer = setInterval(() => {
      const peer = this.#peer;
      if (!peer || peer.closed) return;
      const idle = Date.now() - peer.lastSeen;
      if (idle > 2.5 * hb) {
        // The hub went silent: drop the link; the close handler reconnects.
        this.#link?.close();
        return;
      }
      if (idle >= hb && !this.#pinging) {
        this.#pinging = true;
        peer
          .ping(hb)
          .catch(() => {})
          .finally(() => (this.#pinging = false));
      }
    }, clamp(hb / 3, 250, 5000));
  }

  #stopHeartbeat(): void {
    if (this.#hbTimer) clearInterval(this.#hbTimer);
    this.#hbTimer = null;
    this.#pinging = false;
  }

  #onClose(epoch: number): void {
    if (epoch !== this.#epoch) return;
    this.#peer = null;
    this.#link = null;
    this.#stopHeartbeat();
    this.#dropAll('hub');
    if (!this.#want) return;
    this.#setConn('offline');
    if (this.#ownsSocket && this.#o.reconnect !== false) this.#scheduleRetry();
  }

  disconnect(): void {
    const wasWanted = this.#want;
    this.#want = false;
    this.#epoch++;
    if (this.#retryTimer) clearTimeout(this.#retryTimer);
    this.#retryTimer = null;
    this.#stopHeartbeat();
    const peer = this.#peer;
    this.#peer = null;
    const link = this.#link;
    this.#link = null;
    this.#dropAll('hub', false);
    try {
      if (peer && !peer.closed) peer.bye('OK');
      else link?.close();
    } catch {
      // ignore
    }
    const w = this.#waiter;
    this.#waiter = null;
    w?.reject(new ReinsError('E_GONE', 'disconnected'));
    this.#connecting = null;
    this.#stopDom();
    this.#queue.close();
    this.#queue.reopen();
    if (wasWanted || this.#conn !== 'idle') this.#setConn('idle');
  }

  // ───────── DOM watching ─────────

  #startDom(): void {
    if (this.#domOn) return;
    this.#domOn = true;
    // The panel hooks run only from trusted input on the overlay's own controls.
    this.#overlay = new Overlay(
      this.#doc,
      {
        pause: () => this.pause(),
        resume: () => this.resume(),
        stop: () => this.stop(),
        setLevel: (ag, level) => this.#setLevel(ag, level),
        setRule: (ag, action, rule) => this.#setRule(ag, action, rule),
        setScope: (ag, scope, on) => this.#setScope(ag, scope, on),
        disconnect: (ag) => this.#disconnectOne(ag),
        say: (text, to) => this.#personSay(text, to),
        relay: (ags, on) => this.#setRelay(ags, on),
        // Typing to the agent is using the page: synthetic input yields to it (SPEC 12, human control).
        typing: () => this.#human.mark(),
      },
      { chat: this.#chatOn },
    );
    this.#overlay.mount();
    this.#motion = new CursorMotion(this.#frames, this.#overlay, () => this.#vp());
    this.#refreshIndicator();
    this.#overlay.activity(this.#activity);
    this.#drawChat();
    const root = this.#root;
    notePrivate(root);
    if (root && typeof this.#win.MutationObserver === 'function') {
      this.#mo = new this.#win.MutationObserver(this.#onMutations);
      this.#mo.observe(root, { subtree: true, childList: true, attributes: true, characterData: true, attributeOldValue: true });
    }
    root?.addEventListener('input', this.#onDomChange, true);
    root?.addEventListener('change', this.#onDomChange, true);
    this.#doc.addEventListener('focusin', this.#onDomChange, true);
    this.#doc.addEventListener('focusout', this.#onDomChange, true);
    this.#doc.addEventListener('visibilitychange', this.#onVisibility);
    this.#win.addEventListener('popstate', this.#onNav);
    this.#win.addEventListener('hashchange', this.#onNav);
    this.#navTimer = setInterval(this.#onNav, NAV_POLL_MS);
    this.#human.start();
  }

  #stopDom(): void {
    if (!this.#domOn) return;
    this.#domOn = false;
    this.#mo?.disconnect();
    this.#mo = null;
    const root = this.#root;
    root?.removeEventListener('input', this.#onDomChange, true);
    root?.removeEventListener('change', this.#onDomChange, true);
    this.#doc.removeEventListener('focusin', this.#onDomChange, true);
    this.#doc.removeEventListener('focusout', this.#onDomChange, true);
    this.#doc.removeEventListener('visibilitychange', this.#onVisibility);
    this.#win.removeEventListener('popstate', this.#onNav);
    this.#win.removeEventListener('hashchange', this.#onNav);
    if (this.#navTimer) clearInterval(this.#navTimer);
    this.#navTimer = null;
    if (this.#refreshTimer) clearTimeout(this.#refreshTimer);
    this.#refreshTimer = null;
    if (this.#uiTimer) clearTimeout(this.#uiTimer);
    this.#uiTimer = null;
    for (const t of this.#timers) clearTimeout(t);
    this.#timers.clear();
    if (this.#activityTimer) clearTimeout(this.#activityTimer);
    this.#activityTimer = null;
    if (this.#chatTimer) clearTimeout(this.#chatTimer);
    this.#chatTimer = null;
    this.#human.stop();
    this.#motion?.stop();
    this.#motion = null;
    this.#overlay?.destroy();
    this.#overlay = null;
    this.#cursorOn = false;
    this.#cursorLabelSet = false;
    this.#cursorAg = undefined;
  }

  #later(fn: () => void, ms: number): void {
    const t = setTimeout(() => {
      this.#timers.delete(t);
      fn();
    }, ms);
    this.#timers.add(t);
  }

  #vp(): [number, number] {
    const de = this.#doc.documentElement;
    return [Math.round(this.#win.innerWidth || de?.clientWidth || 0), Math.round(this.#win.innerHeight || de?.clientHeight || 0)];
  }

  #scheduleRefresh(): void {
    if (!this.#domOn) return;
    // A timer that is long overdue never fired: start over.
    if (this.#refreshTimer && Date.now() < this.#refreshDue + 1000) return;
    if (this.#refreshTimer) clearTimeout(this.#refreshTimer);
    this.#refreshTimer = null;
    let wanted = false;
    for (const s of this.#sessions.values()) if (this.#hears(s, 'ui')) wanted = true;
    if (!wanted) return;
    this.#refreshDue = Date.now() + UI_EVENT_INTERVAL_MS;
    this.#refreshTimer = setTimeout(() => {
      this.#refreshTimer = null;
      this.#refresh();
      this.#checkNav();
    }, UI_EVENT_INTERVAL_MS);
  }

  /** Rebuild the tree; tell subscribers when the revision moved. */
  #refresh(): number {
    if (!this.#sessions.size) return this.#tree.rev;
    this.#flushMutations();
    const rev = this.#tree.snapshot(false).rev;
    this.#uiChanged();
    return rev;
  }

  #uiChanged(): void {
    if (this.#uiTimer) return;
    const wait = this.#uiSentAt + UI_EVENT_INTERVAL_MS - Date.now();
    if (wait > 0) {
      this.#uiTimer = setTimeout(() => {
        this.#uiTimer = null;
        this.#sendUi();
      }, wait);
      return;
    }
    this.#sendUi();
  }

  #sendUi(): void {
    const rev = this.#tree.rev;
    if (rev === this.#uiSentRev) return;
    this.#uiSentRev = rev;
    this.#uiSentAt = Date.now();
    for (const s of this.#sessions.values()) if (this.#hears(s, 'ui')) this.#send('ui', { rev }, s.ag);
  }

  /** Subscribed, and still holding the scope the topic needs: `observe` for all but `user`. */
  #hears(s: Session, topic: Topic): boolean {
    return s.subs.has(topic) && (topic === 'user' || s.scopes.includes('observe'));
  }

  #checkNav(): void {
    if (!this.#peer || this.#peer.closed) return;
    // A window that is being taken down has no location any more (a browser never takes it
    // from a live one: the property is unforgeable). There is nothing to report then.
    const url = (this.#win as { location?: Location }).location?.href;
    if (typeof url !== 'string') return;
    const title = this.#doc.title;
    if (url === this.#navUrl && title === this.#navTitle) return;
    this.#navUrl = url;
    this.#navTitle = title;
    // Broadcast: the hub learns the new URL and title, and relays to agents.
    this.#send('nav', { url, title });
  }

  #send(topic: Topic, d: unknown, ag?: string): void {
    const peer = this.#peer;
    if (!peer || peer.closed) return;
    try {
      peer.event(topic, d, ag === undefined ? {} : { ag });
    } catch (e) {
      console.warn(`[reins] could not send ${topic} event:`, e instanceof ReinsError ? e.message : e);
    }
  }

  // ───────── sessions, indicator, human control ─────────

  #refreshIndicator(): void {
    const sessions = [...this.#sessions.values()];
    const names = sessions.map((s) => s.agent.name);
    this.#overlay?.indicator({
      show: this.#o.indicator !== false && names.length > 0,
      names,
      ids: sessions.map((s) => s.ag),
      paused: this.#paused,
      canPause: this.#policy.human.pause,
      canStop: this.#policy.human.stop,
      unverified: !this.#hubVerified,
      panel: this.#policy.human.panel,
      levels: sessions.map((s) => s.level),
      ...this.#waivingRules(sessions),
    });
    this.#overlay?.permissions(this.#panelModel());
    this.#statusChanged();
  }

  /**
   * The person's `allow` rules that waive a prompt right now, over all sessions: without the
   * rule the action would ask. With one for a dangerous action they do what `bypass` does,
   * otherwise what `auto` does, and the indicator shows them like that level.
   */
  #waivingRules(sessions: Session[]): { rules?: { n: number; like: 'auto' | 'bypass'; approved: number } } {
    let n = 0;
    let approved = 0;
    let like: 'auto' | 'bypass' = 'auto';
    for (const s of sessions) {
      for (const [name, rule] of s.rules) {
        const def = this.#actions.get(name)?.def;
        if (rule !== 'allow' || !def) continue;
        const q = { base: this.#base(s, def), risk: def.risk, level: s.level, offered: s.offered };
        if (decideAct(q).outcome !== 'prompt' || decideAct({ ...q, rule }).outcome !== 'run') continue;
        n++;
        if (def.risk !== 'safe' && def.risk !== 'sensitive') like = 'bypass';
      }
      // An approval the surface remembers does the same as such a rule: the action runs
      // without asking. It is counted with them, so that the indicator is not calm.
      if (this.#policy.consent.remember !== 'session') continue;
      for (const name of s.approved) {
        const def = this.#actions.get(name)?.def;
        if (!def || s.rules.has(name)) continue;
        const v = decideAct({ base: this.#base(s, def), risk: def.risk, level: s.level, offered: s.offered });
        if (v.outcome !== 'prompt' || v.remember !== true || s.hub?.get(name) === 'confirm' || s.hub?.get(name) === 'deny') continue;
        approved++;
        if (def.risk !== 'safe' && def.risk !== 'sensitive') like = 'bypass';
      }
    }
    return n + approved > 0 ? { rules: { n, like, approved } } : {};
  }

  // ───────── what the person tightened stays ─────────

  /** What the person has tightened on this grant right now. */
  #tight(s: Session): Tightened {
    const rules = new Map<string, 'confirm' | 'deny'>();
    for (const [name, d] of s.rules) if (d === 'confirm' || d === 'deny') rules.set(name, d);
    return { strict: s.level === 'strict', rules, off: new Set(s.granted.filter((x) => !s.scopes.includes(x))) };
  }

  /** The kept entry for a credential, made when there is none. Past the bound, the shared one. */
  #keptEntry(cred: string): Tightened {
    let k = this.#kept.get(cred);
    if (k) return k;
    if (cred !== '' && this.#kept.size >= MAX_KEPT_CREDS) {
      this.#keptShared = true;
      return this.#keptEntry('');
    }
    k = { strict: false, rules: new Map(), off: new Set() };
    this.#kept.set(cred, k);
    return k;
  }

  /**
   * Keep what the person tightened on this grant for the next grant of the same agent. Called
   * whenever the person changes something and when the grant ends, however it ends: nothing
   * the agent does (attach again, detach, let it run out, come back under another name) takes
   * a tightening away. Only adds; what the person lifts is taken out where they lift it.
   */
  #keep(s: Session): void {
    const t = this.#tight(s);
    if (!t.strict && t.rules.size === 0 && t.off.size === 0) return;
    const k = this.#keptEntry(s.cred);
    if (t.strict) k.strict = true;
    for (const [name, d] of t.rules) if (d === 'deny' || k.rules.get(name) !== 'deny') k.rules.set(name, d);
    for (const x of t.off) k.off.add(x);
  }

  /**
   * What stays for a new grant of this credential: what was kept for it, and what the person
   * has set on its grants that are live now. Where the two differ, the stricter.
   */
  #keptFor(cred: string): Tightened {
    const out: Tightened = { strict: false, rules: new Map(), off: new Set() };
    const add = (t: Tightened | undefined): void => {
      if (!t) return;
      if (t.strict) out.strict = true;
      for (const [name, d] of t.rules) if (d === 'deny' || out.rules.get(name) !== 'deny') out.rules.set(name, d);
      for (const x of t.off) out.off.add(x);
    };
    add(this.#kept.get(cred));
    if (cred !== '' && this.#keptShared) add(this.#kept.get(''));
    for (const s of this.#sessions.values()) if (s.cred === cred) add(this.#tight(s));
    return out;
  }

  /** What is kept, as the lines an attach prompt shows: the overlay's own words, and the app's action names. */
  #keptLines(t: Tightened, granted: readonly Scope[]): string[] {
    const lines: string[] = [];
    if (t.strict) lines.push('Level Strict: it asks you before every action');
    for (const [name, d] of t.rules) if (this.#actions.has(name)) lines.push(`${d === 'deny' ? 'Blocked' : 'Asks every time'}: ${name}`);
    const off = granted.filter((x) => t.off.has(x));
    if (off.length) lines.push(`Switched off: ${off.join(', ')}`);
    return lines;
  }

  /**
   * The decision a request for this action meets before anything the person set: the
   * stricter of the app's policy and the hub's. Where the hub did not say what it decides,
   * it counts as confirming: this is what the panel shows and what the person may loosen.
   */
  #base(s: Session, def: ActionDef): Decision {
    return stricter(decideAction(this.#policy, def), s.hub ? (s.hub.get(def.name) ?? 'confirm') : 'confirm');
  }

  // ───────── what the person sets: level, rules, scope switches ─────────

  /** What the Permissions tab shows. Data only: the panel changes nothing except through the hooks below. */
  #panelModel(): PanelModel {
    this.#panelActions ??= [...this.#actions.values()].map((a) => ({ name: a.def.name, risk: a.def.risk, base: decideAction(this.#policy, a.def) }));
    return {
      agents: [...this.#sessions.values()].map((s) => ({
        ag: s.ag,
        name: s.agent.name,
        level: s.level,
        offered: [...s.offered],
        rules: Object.fromEntries(s.rules),
        hub: s.hub ? Object.fromEntries(s.hub) : null,
        remembered: [...s.approved],
        scopes: s.granted.map((scope) => ({ scope, on: s.scopes.includes(scope) })),
      })),
      actions: this.#panelActions,
      unverified: !this.#hubVerified,
      canStop: this.#policy.human.stop,
    };
  }

  /**
   * Does the hub confirm a request for this action: the request carries `c:1`, or the hub
   * said at attach that it confirms or refuses the action. The second holds the hub to its
   * word, so that what the panel shows as asking does ask.
   */
  #marked(s: Session, def: ActionDef, f: ReqFrame): boolean {
    const said = s.hub?.get(def.name);
    return f.c === 1 || said === 'confirm' || said === 'deny';
  }

  /** Where an `act` request stands for this agent now (SPEC 12, levels and rules). */
  #verdict(s: Session, def: ActionDef, c: boolean): ActVerdict {
    const rule = s.rules.get(def.name);
    // An action the hub said it refuses does not come from an honest hub at all.
    const base = s.hub?.get(def.name) === 'deny' ? 'deny' : decideAction(this.#policy, def);
    return decideAct({ base, risk: def.risk, c, level: s.level, offered: s.offered, ...(rule !== undefined && { rule }) });
  }

  /**
   * The person chose a level for one agent, in the panel. Only a level on offer for the
   * grant is taken. The hub and the agent are told; a prompt that is already showing or
   * queued stays as it is.
   */
  #setLevel(ag: string, level: Level): void {
    const s = this.#sessions.get(ag);
    if (!s || !this.#policy.human.panel || !LEVELS.includes(level) || !s.offered.includes(level) || s.level === level) return;
    // The person lifts Strict themselves: it is no longer kept for the agent's next grant.
    if (s.level === 'strict') {
      const k = this.#kept.get(s.cred);
      if (k) k.strict = false;
    }
    s.level = level;
    this.#keep(s);
    this.#send('user', { kind: 'level', level }, ag);
    this.#logYou(s, `Level set to ${LEVEL_LABEL[level]}`);
    this.#refreshIndicator();
    this.#emit('level', { agent: { ...s.agent }, level });
  }

  /**
   * The person set, or with `null` reset, a rule for one action of one agent: in the panel,
   * or with "Always allow" on a prompt. A rule covers the action with any arguments.
   *
   * `allow` on an action that the app or the hub asks about is taken only where a level on
   * offer would waive the same prompt, and nothing is taken for an action either of them
   * denies. Where the hub did not say what it asks about, it counts as asking about each.
   *
   * A reset takes the rule away and, with it, an approval remembered for the action
   * (`consent.remember: session`); so does the rule `confirm`. Otherwise an action the
   * person set back to asking would go on running from memory.
   */
  #setRule(ag: string, action: string, rule: Decision | null): boolean {
    const s = this.#sessions.get(ag);
    const entry = this.#actions.get(action);
    if (!s || !entry || !this.#policy.human.panel) return false;
    let forgot = false;
    if (rule === null) {
      forgot = s.approved.delete(action);
      if (!s.rules.delete(action)) {
        // Only an approval was forgotten: nothing the hub or the agent was told changes.
        if (forgot) {
          this.#logYou(s, `${action} asks again`);
          this.#refreshIndicator();
        }
        return forgot;
      }
    } else {
      if (rule !== 'allow' && rule !== 'confirm' && rule !== 'deny') return false;
      const base = this.#base(s, entry.def);
      if (base === 'deny') return false;
      if (rule === 'allow' && base === 'confirm' && !allowRulePermitted(entry.def.risk, s.offered)) return false;
      if (s.rules.get(action) === rule) return false;
      s.rules.set(action, rule);
      if (rule === 'confirm') s.approved.delete(action);
    }
    // What is kept for the agent's next grant follows the person's last word on this action.
    this.#kept.get(s.cred)?.rules.delete(action);
    this.#keep(s);
    this.#send('user', { kind: 'rule', a: action, d: rule }, ag);
    this.#logYou(s, rule === null ? `${action} follows the level again` : `${action} set to ${rule === 'allow' ? 'Allow' : rule === 'confirm' ? 'Ask' : 'Block'}`);
    this.#refreshIndicator();
    this.#emit('rule', { agent: { ...s.agent }, action, rule });
    return true;
  }

  /**
   * The person switched one scope of a grant off or back on. Never beyond what was granted
   * at attach. Without `cursor` the agent's pointer streams end and its cursor goes.
   */
  #setScope(ag: string, scope: Scope, on: boolean): void {
    const s = this.#sessions.get(ag);
    if (!s || !this.#policy.human.panel || !s.granted.includes(scope) || s.scopes.includes(scope) === on) return;
    s.scopes = capScopes(on ? [...s.scopes, scope] : s.scopes.filter((x) => x !== scope), s.granted);
    if (on) this.#kept.get(s.cred)?.off.delete(scope);
    this.#keep(s);
    if (!s.scopes.includes('cursor')) {
      for (const [ch, st] of this.#streams) if (st.ag === ag) this.#streams.delete(ch);
      if (this.#cursorAg === ag) {
        this.#motion?.halt();
        this.#setCursor(false);
      }
    }
    if (scope === 'chat') {
      // Out of the room while it is off: nothing said meanwhile is ever read by this agent.
      // Back in, it hears no other agent until the person says so again.
      if (on) this.#room.join(s.chat, s.ag, s.agent.name);
      else this.#relayChanged(this.#room.leave(s.chat), false, false);
      this.#drawChat();
    }
    this.#send('grant', { kind: 'scopes', scopes: [...s.scopes] }, ag);
    this.#logYou(s, `Scope ${scope} switched ${on ? 'on' : 'off'}`);
    this.#refreshIndicator();
    this.#emit('scopes', { agent: { ...s.agent }, scopes: [...s.scopes] });
  }

  /** Stop, for one agent: from the panel, where the policy has Stop at all. */
  #disconnectOne(ag: string): void {
    const s = this.#sessions.get(ag);
    if (!s || !this.#policy.human.stop) return;
    this.#logYou(s, 'Disconnected');
    this.#revoke(ag);
  }

  // ───────── chat ─────────

  /** Show the room in the Chat tab, and come back when the next status lapses. */
  #drawChat(): void {
    if (!this.#chatOn) return;
    this.#overlay?.chat({
      lines: this.#room.lines(),
      members: this.#room.members(),
      busy: this.#busy,
      unverified: !this.#hubVerified,
      relay: this.#room.mode,
      hearing: this.#room.hearing(),
      ...(this.#chatHeld > 0 && { held: true }),
      ...(this.#relayReset && { relayReset: true }),
    });
    if (this.#chatTimer) clearTimeout(this.#chatTimer);
    this.#chatTimer = null;
    const due = this.#room.nextLapse();
    if (due !== undefined && this.#domOn) {
      this.#chatTimer = setTimeout(() => {
        this.#chatTimer = null;
        this.#drawChat();
      }, due + 20);
    }
  }

  /** A message is in the room: send it to whoever may hear it, show it, and tell the app that there is one. */
  #posted(posted: Posted): void {
    // One event for each agent that may hear it, each naming that agent and carrying the id
    // the message has for it: the hub delivers a chat event to the grant it names and to
    // nobody else.
    for (const d of posted.deliver) this.#send('chat', d.msg, d.ag);
    this.#drawChat();
    const { line } = posted;
    this.#emit('chat', { id: line.id, from: { ...line.from }, chars: line.text.length, ...(line.to !== undefined && { to: line.to }) });
  }

  /**
   * The person switched "Agents can hear each other" in the Chat tab: on, for the agents the
   * confirm step named, or off for all of them. Taken only where the page's policy and the
   * hub's both leave it to the person (`chatRelay: "person"`), and never while a consent
   * prompt is up. The room checks the rest: every agent named is in the room, and at least
   * two then hear each other.
   */
  #setRelay(ags: readonly string[], on: boolean): void {
    if (!this.#chatOn || this.#busy || !this.#policy.human.panel) return;
    // The person chose again: what the tab said about the hub's change has been read.
    this.#relayReset = false;
    this.#relayChanged(on ? this.#room.include(ags) : this.#room.silence(), on, true);
  }

  /**
   * These agents now hear the others in the chat, or no longer do. The hub is told for each
   * grant (`evt user {kind:"relay"}` with `ag`), puts it on record and tells that agent.
   * `byPerson`: the person switched it; otherwise it followed from an agent leaving.
   */
  #relayChanged(ags: readonly string[], on: boolean, byPerson: boolean): void {
    for (const ag of ags) {
      const s = this.#sessions.get(ag);
      if (!s) continue;
      this.#send('user', { kind: 'relay', on }, ag);
      if (byPerson) this.#logYou(s, on ? 'Chat: may hear the other agents' : 'Chat: hears only you');
    }
    if (ags.length) this.#drawChat();
  }

  /** An app action an agent asked for starts (`1`) or has ended (`-1`): the composer is held meanwhile. */
  #holdChat(d: 1 | -1): void {
    const was = this.#chatHeld > 0;
    this.#chatHeld = Math.max(0, this.#chatHeld + d);
    if (this.#chatOn && was !== this.#chatHeld > 0) this.#drawChat();
  }

  /**
   * The person sent a message from the Chat tab. This is the only way a message of the
   * person comes to be, and the tab calls it from trusted input alone. Nothing is taken
   * while a consent prompt is up: the person answers that first, on the prompt itself.
   * A message changes no level, no rule and no scope, and answers no prompt.
   */
  #personSay(raw: string, to: string | undefined): boolean {
    if (!this.#chatOn || this.#busy) return false;
    const text = typeof raw === 'string' ? chatText(chatWellFormed(raw)) : undefined;
    if (text === undefined) return false;
    const posted = this.#room.personSay(text, typeof to === 'string' ? to : undefined);
    if (!posted) return false;
    this.#posted(posted);
    return true;
  }

  // ───────── the activity log ─────────

  #log(e: Omit<ActivityEntry, 't' | 'n'>): void {
    const last = this.#activity[this.#activity.length - 1];
    const t = Date.now();
    if (last && last.ag === e.ag && last.agent === e.agent && last.what === e.what && last.outcome === e.outcome && last.by === e.by && last.you === e.you) {
      last.t = t;
      last.n++;
    } else {
      this.#activity.push({ ...e, t, n: 1 });
      if (this.#activity.length > ACTIVITY_MAX) this.#activity.splice(0, this.#activity.length - ACTIVITY_MAX);
    }
    // Commands can come many a second: the tab is redrawn at most every ACTIVITY_DRAW_MS.
    // A timer that is long overdue never fired (they can be cleared from outside): draw now.
    if (this.#activityTimer && t < this.#activityDue + 1000) return;
    if (this.#activityTimer) clearTimeout(this.#activityTimer);
    const wait = this.#activityDrawn + ACTIVITY_DRAW_MS - t;
    const draw = () => {
      this.#activityTimer = null;
      this.#activityDrawn = Date.now();
      this.#overlay?.activity(this.#activity);
    };
    if (wait <= 0) draw();
    else {
      this.#activityDue = t + wait;
      this.#activityTimer = setTimeout(draw, wait);
    }
  }

  /** One command and how it ended: the method, or the name of a declared action. Never arguments. */
  #logCommand(s: Session, m: string, p: Record<string, unknown>, outcome: string, by?: ActivityEntry['by']): void {
    let what = m;
    // An action name the app did not declare is the agent's own text: it is not shown.
    if (m === 'act') what = typeof p.a === 'string' && this.#actions.has(p.a) ? p.a : 'act (unknown action)';
    const e: Omit<ActivityEntry, 't' | 'n'> = { agent: s.agent.name, ag: s.ag, what, outcome };
    if (by !== undefined) e.by = by;
    this.#log(e);
  }

  #logYou(s: Session, what: string): void {
    this.#log({ agent: s.agent.name, ag: s.ag, what, outcome: '', you: true });
  }

  #drop(ag: string, why: string, notify = true): void {
    const s = this.#sessions.get(ag);
    if (!s) return;
    // However the grant ends, what the person tightened on it stays for the agent's next one.
    this.#keep(s);
    this.#sessions.delete(ag);
    for (const [ch, st] of this.#streams) if (st.ag === ag) this.#streams.delete(ch);
    // An agent it leaves alone hears nobody any more: the hub is told for that one.
    this.#relayChanged(this.#room.leave(s.chat), false, false);
    this.#drawChat();
    this.#overlay?.cancel(ag);
    if (!this.#sessions.size) {
      this.#setCursor(false);
      this.#overlay?.clear();
    }
    this.#refreshIndicator();
    if (notify) this.#emit('detach', { agent: { ...s.agent }, why });
  }

  #dropAll(why: string, notify = true): void {
    for (const ag of [...this.#sessions.keys()]) this.#drop(ag, why, notify);
    this.#streams.clear();
    this.#overlay?.cancel();
  }

  #onHumanBurst(): void {
    for (const s of this.#sessions.values()) if (s.subs.has('user')) this.#send('user', { kind: 'override' }, s.ag);
  }

  pause(): void {
    if (this.#paused) return;
    this.#paused = true;
    // The cursor stops where it is; queued stream points are dropped, not played.
    this.#motion?.halt();
    this.#send('user', { kind: 'pause' });
    this.#refreshIndicator();
  }

  resume(): void {
    if (!this.#paused) return;
    this.#paused = false;
    this.#send('user', { kind: 'resume' });
    this.#refreshIndicator();
  }

  stop(): void {
    // From now on, until the page reloads, no agent attaches silently.
    this.#stopped = true;
    this.#stopGen++;
    // Refuse every pending prompt too, including attach requests not yet granted.
    this.#overlay?.cancel();
    this.#motion?.halt();
    for (const s of [...this.#sessions.values()]) this.#revoke(s.ag);
  }

  /** What Stop does for one agent: refuse its prompts, revoke its grant, drop its session. */
  #revoke(ag: string): void {
    this.#stopped = true;
    this.#overlay?.cancel(ag);
    if (!this.#sessions.has(ag)) return;
    this.#send('grant', { kind: 'revoked' }, ag);
    this.#drop(ag, 'user');
  }

  /**
   * A consent prompt is showing or queued: only read-only methods are served meanwhile. A
   * prompt past its deadline is a refusal from the moment anything asks: its timer need not
   * have fired (timer ids can be cleared from outside the driver's world).
   */
  get #busy(): boolean {
    if (this.#askingTotal > 0) {
      this.#overlay?.expire();
      const now = Date.now();
      for (const a of [...this.#customAsks]) if (now >= a.until) a.expire();
    }
    return this.#askingTotal > 0;
  }

  /**
   * Throws unless `s` is still the live session for its agent, still holds the scope `need`
   * (the person may have switched it off meanwhile) and control is not paused.
   */
  #live(s: Session, need: Scope): void {
    if (this.#sessions.get(s.ag) !== s) throw new ReinsError('E_NOT_ATTACHED', 'not attached');
    if (!s.scopes.includes(need)) throw new ReinsError('E_SCOPE', `grant lacks scope ${need}`);
    if (this.#paused) throw new ReinsError('E_PAUSED', 'the user paused agent control');
  }

  #requireIdle(): void {
    if (this.#busy) throw new ReinsError('E_BUSY', 'waiting for the person to answer a consent prompt');
  }

  /**
   * Is the indicator, with Pause and Stop, where the person can see and use it? `cached`
   * reuses a recent answer (pointer frames). Re-places the overlay as a side effect.
   */
  #overlayUsable(cached = false): boolean {
    const o = this.#overlay;
    if (!o) return true;
    const now = Date.now();
    if (cached && now - this.#overlayOkAt < OVERLAY_CHECK_CACHE_MS) return this.#overlayOk;
    this.#overlayOk = o.check();
    this.#overlayOkAt = now;
    return this.#overlayOk;
  }

  #requireOverlay(): void {
    if (!this.#overlayUsable()) throw new ReinsError('E_PAUSED', 'the AI indicator is covered or hidden on the page; commands wait until it is visible');
  }

  /**
   * The last check before a command acts, run synchronously right before it does, after
   * every wait (glide, consent prompt, yield): still attached, the scope `need` still on, not
   * paused, no consent prompt up (unless this is the action the person just approved), the
   * indicator usable, and for synthetic input, no recent human input.
   */
  #ready(s: Session, need: Scope, input = false, approved = false): void {
    this.#live(s, need);
    if (!approved) this.#requireIdle();
    this.#requireOverlay();
    if (input && !this.#human.idle) throw new ReinsError('E_PAUSED', 'the user is using the page');
    if (input) this.#keepChatFocus();
  }

  /**
   * The person's place in the chat composer is theirs. Called right before a command that may
   * move focus (synthetic input, an app action): when their focus is in the composer now, it is
   * given back as soon as the command's synchronous part has run, so that what they type next
   * does not land in a field the agent focused.
   */
  #keepChatFocus(): void {
    const o = this.#overlay;
    if (!o || !o.chatFocused) return;
    queueMicrotask(() => {
      if (this.#overlay === o) o.refocusChat();
    });
  }

  /**
   * The single privacy gate of every input-synthesising command: a private target (or a
   * label that forwards activation to a private control) is E_DENIED unless
   * `policy.privateInput`. So is a target whose activation changes a private control it
   * does not point at: a radio whose group has a private member (checking it unchecks the
   * other), and a reset control whose form holds a private field.
   */
  #guardPrivate(el: Element): void {
    if (this.#policy.privateInput) return;
    if (isPrivate(el)) throw new ReinsError('E_DENIED', 'private field');
    let control: Element | null = null;
    let button: Element | null = null;
    try {
      const label = el.closest('label') as HTMLLabelElement | null;
      control = label ? label.control : null;
      button = el.closest('button');
    } catch {
      control = null;
    }
    if (control && isPrivate(control)) throw new ReinsError('E_DENIED', 'private field');
    for (const c of [el, control, button]) if (c && this.#changesPrivate(c)) throw new ReinsError('E_DENIED', 'would change a private field');
  }

  /** Where Tab emulation may move focus: exposed elements, and private ones only under `privateInput`. */
  #tabStop = (e: Element): boolean => this.#tree.exposedNow(e) && (this.#policy.privateInput || !isPrivate(e));

  /** Activating `el` would change a private control elsewhere (radio group, form reset). */
  #changesPrivate(el: Element): boolean {
    const tag = el.localName;
    const type = tag === 'input' || tag === 'button' ? ((el as HTMLInputElement).type || '').toLowerCase() : '';
    if (tag === 'input' && type === 'radio') {
      const r = el as HTMLInputElement;
      if (!r.name) return false;
      // Compare names and form owners directly; no selector is built from page strings.
      for (const o of Array.from(el.ownerDocument.getElementsByName(r.name))) {
        if (o !== el && o.localName === 'input' && (o as HTMLInputElement).type === 'radio' && (o as HTMLInputElement).form === r.form && isPrivate(o)) return true;
      }
      return false;
    }
    if (type === 'reset') {
      const form = (el as HTMLInputElement | HTMLButtonElement).form;
      if (form) for (const f of Array.from(form.elements)) if (isPrivate(f)) return true;
    }
    return false;
  }

  #ctx(s: Session): CommandContext {
    return { agent: { ...s.agent }, scopes: [...s.scopes] };
  }

  // ───────── consent ─────────

  /**
   * Ask, with at most one pending prompt per agent and MAX_PROMPTS in total (else E_BUSY),
   * and not during a cool-off (else E_RATE). Records the answer for the cool-off; the third
   * explicit refusal in a row of one agent's action prompts revokes its grant.
   */
  async #consent(req: ConsentRequest, owner: string, always = false, extra: { remembers?: boolean; keptWhy?: string } = {}): Promise<'allow' | 'always' | 'no'> {
    const now = Date.now();
    const cool = req.kind === 'attach' ? this.#attachCoolOff : this.#coolOff.get(owner);
    if (cool && now < cool.until) throw new ReinsError('E_RATE', `the person refused a recent request; ask again in ${Math.ceil((cool.until - now) / 1000)} s`);
    if ((this.#asking.get(owner) ?? 0) > 0) throw new ReinsError('E_BUSY', 'a consent prompt for this agent is already pending');
    if (this.#askingTotal >= MAX_PROMPTS) throw new ReinsError('E_BUSY', 'too many consent prompts pending');
    this.#asking.set(owner, (this.#asking.get(owner) ?? 0) + 1);
    this.#askingTotal++;
    // While the person has a request to answer, the chat tab shows nothing an agent wrote, and
    // what the agents said they were doing is dropped: no words of an agent stand next to a
    // prompt, and none come back when it has gone.
    this.#room.quiet();
    this.#drawChat();
    let outcome: ConsentOutcome;
    try {
      outcome = await this.#ask(req, owner, always, extra);
    } finally {
      const n = (this.#asking.get(owner) ?? 1) - 1;
      if (n > 0) this.#asking.set(owner, n);
      else this.#asking.delete(owner);
      this.#askingTotal--;
      this.#drawChat();
    }
    if (this.#recordAnswer(req.kind, owner, outcome)) throw new ReinsError('E_CONSENT', 'the user declined three times in a row; access revoked');
    return outcome === 'allow' || outcome === 'always' ? outcome : 'no';
  }

  /** Update the cool-off for an answer; true when it revoked the agent's grant. */
  #recordAnswer(kind: ConsentRequest['kind'], owner: string, outcome: ConsentOutcome): boolean {
    if (outcome === 'cancel') return false;
    let cool: CoolOff | undefined;
    if (kind === 'attach') cool = this.#attachCoolOff;
    else {
      cool = this.#coolOff.get(owner);
      if (!cool) {
        if (outcome === 'allow' || outcome === 'always') return false;
        cool = { until: 0, level: 0, denials: 0 };
        if (this.#coolOff.size >= MAX_COOL_OFF_ENTRIES) this.#coolOff.delete(this.#coolOff.keys().next().value!);
        this.#coolOff.set(owner, cool);
      }
    }
    if (outcome === 'allow' || outcome === 'always') {
      cool.until = 0;
      cool.level = 0;
      cool.denials = 0;
      return false;
    }
    cool.level++;
    cool.until = Date.now() + Math.min(COOL_OFF_MAX_MS, COOL_OFF_BASE_MS * 2 ** Math.min(cool.level - 1, 10));
    if (outcome === 'deny') cool.denials++;
    if (kind === 'action' && cool.denials >= REVOKE_AFTER_DENIALS && this.#sessions.has(owner)) {
      cool.denials = 0;
      this.#revoke(owner);
      return true;
    }
    return false;
  }

  async #ask(req: ConsentRequest, owner: string, always: boolean, extra: { remembers?: boolean; keptWhy?: string }): Promise<ConsentOutcome> {
    const timeoutMs = this.#policy.consent.timeoutMs;
    const custom = this.#o.consent;
    if (custom) {
      const run = async (): Promise<ConsentOutcome> => {
        let timer: ReturnType<typeof setTimeout> | undefined;
        // The deadline is a time: `#busy` ends the wait when anything asks after it, so the
        // request is a refusal even where the timer below never fires.
        const pending = { until: Date.now() + timeoutMs, expire: (): void => {} };
        try {
          return await Promise.race([
            Promise.resolve()
              .then(() => custom(jsonClone(req)))
              .then((v): ConsentOutcome => (v === true && Date.now() < pending.until ? 'allow' : v === true ? 'timeout' : 'deny')),
            new Promise<ConsentOutcome>((r) => {
              pending.expire = () => r('timeout');
              this.#customAsks.add(pending);
              timer = setTimeout(() => r('timeout'), timeoutMs);
            }),
          ]);
        } catch (e) {
          // A failing handler is no answer from the person: it counts like a timeout.
          console.error('[reins] consent handler failed:', e);
          return 'timeout';
        } finally {
          this.#customAsks.delete(pending);
          if (timer) clearTimeout(timer);
        }
      };
      const p = this.#consentChain.then(run, run);
      this.#consentChain = p.then(
        () => {},
        () => {},
      );
      return p;
    }
    const overlay = this.#overlay;
    if (!overlay) return 'cancel';
    const view: ConsentView = { kind: req.kind, agentName: req.agent.name, agentId: req.agent.id, appName: this.#o.app.name };
    if (req.scopes) view.scopes = req.scopes;
    if (req.action) view.action = { name: req.action.name, description: req.action.description, risk: req.action.risk };
    if (req.args !== undefined) view.args = req.args;
    if (req.reason) view.reason = req.reason;
    if (req.hubVerified === false) view.unverifiedHub = true;
    if (always && req.kind === 'action') view.always = true;
    if (extra.remembers && req.kind === 'action') view.remembers = true;
    if (req.kept && req.kept.length) {
      view.kept = [...req.kept];
      if (extra.keptWhy) view.keptWhy = extra.keptWhy;
    }
    return overlay.ask(view, timeoutMs, owner);
  }

  // ───────── requests ─────────

  async #request(m: string, p: Record<string, unknown>, f: ReqFrame): Promise<unknown> {
    if (!isObj(p)) bad('params must be an object');
    this.#flushMutations();
    // The URL and title are looked at whenever a request arrives, not only when the poll's
    // timer fires: a timer may never fire.
    this.#checkNav();
    if (m === 'attach') return this.#attach(p, f);
    if (m === 'detach') {
      if (typeof f.ag === 'string') {
        // Also refuses a prompt still pending for an attach the hub gave up on.
        this.#overlay?.cancel(f.ag);
        this.#drop(f.ag, typeof p.why === 'string' ? p.why.slice(0, 16) : 'hub');
      }
      return {};
    }
    if (m === 'stream.close') return this.#streamClose(p, f);
    if (m === 'chat.undelivered') {
      // The hub did not hand a message of the person to this agent: the tab says so on the message.
      const to = typeof f.ag === 'string' ? this.#sessions.get(f.ag) : undefined;
      const id = p.id;
      if (to && typeof id === 'number' && Number.isSafeInteger(id) && this.#room.undelivered(to.chat, id)) this.#drawChat();
      return {};
    }
    const scope = methodScope(m);
    const handler = scope !== undefined && hasOwn(this.#handlers, m) ? this.#handlers[m] : undefined;
    if (!handler || scope === undefined) throw new ReinsError('E_UNKNOWN_METHOD', 'unknown method');
    // The surface checks for itself, in this order: grant, scope, pause, prompt up, params.
    const s = typeof f.ag === 'string' ? this.#sessions.get(f.ag) : undefined;
    if (!s) throw new ReinsError('E_NOT_ATTACHED', 'not attached');
    try {
      // `s.scopes` is what is in force now: a scope the person switched off is refused here.
      if (!s.scopes.includes(scope)) throw new ReinsError('E_SCOPE', `grant lacks scope ${scope}`);
      // Pause holds what changes the page. Saying something in the chat changes nothing there,
      // so a paused agent can still answer the person.
      if (this.#paused && !READ_ONLY_METHODS.includes(m) && !CHAT_SPEAK_METHODS.includes(m)) throw new ReinsError('E_PAUSED', 'the user paused agent control');
      // While the person is looking at a consent prompt nothing may change the page under it,
      // from any agent: what they approve is what runs. Nothing talks over it either.
      if (!READ_ONLY_METHODS.includes(m)) this.#requireIdle();
      if (!READ_ONLY_METHODS.includes(m)) this.#requireOverlay();
    } catch (e) {
      if (e instanceof ReinsError) this.#logCommand(s, m, p, e.code);
      throw e;
    }
    const info: Record<string, unknown> = { agent: { ...s.agent }, m };
    if (m === 'act' && typeof p.a === 'string') info.a = p.a.slice(0, 64);
    const note: CommandNote = {};
    try {
      const r = await handler(s, p, f, note);
      this.#emit('command', { ...info, ok: true, ...(note.by !== undefined && { by: note.by }) });
      this.#logCommand(s, m, p, 'ok', note.by);
      return r;
    } catch (e) {
      const err = e instanceof ReinsError ? e : fromHandler(e, m);
      this.#emit('command', { ...info, ok: false, code: err.code });
      this.#logCommand(s, m, p, err.code);
      throw err;
    }
  }

  async #attach(p: Record<string, unknown>, f: ReqFrame): Promise<{ scopes: Scope[]; ttlMs: number; kept?: KeptSettings }> {
    const ag = f.ag;
    if (typeof ag !== 'string' || ag.length === 0 || ag.length > 64) bad('ag: required');
    const a = get(p, 'agent');
    if (!isObj(a) || typeof a.name !== 'string') bad('agent: expected {id, name}');
    const agent: AgentInfo = { id: ag, name: clip(a.name.replace(/\s+/g, ' ').trim(), 80) || ag };
    const requested = get(p, 'scopes');
    if (!Array.isArray(requested) || requested.length > 16 || !requested.every((x) => typeof x === 'string')) bad('scopes: expected a list');
    const reasonRaw = optStr(p, 'reason', 2000);
    const reason = reasonRaw === undefined ? undefined : clip(reasonRaw.replace(/\s+/g, ' ').trim(), 240);
    // `chat` needs a room the person can open: a surface without the panel grants none.
    const scopes = capScopes(requested as Scope[], this.#policy.scopes).filter((x) => x !== 'chat' || this.#chatOn);
    if (!scopes.length) throw new ReinsError('E_SCOPE', 'no requested scope is allowed');
    // A surface holds a bounded number of grants: whatever the hub sends, the person's panel
    // lists no more agents than that. Refused before anybody is asked.
    const full = (): boolean => !this.#sessions.has(ag) && this.#sessions.size >= MAX_SURFACE_SESSIONS;
    if (full()) throw new ReinsError('E_BUSY', 'too many agents are attached to this page');
    // The hub's cap on the levels. Without a list from the hub, neither `auto` nor `bypass` is on offer.
    const hubLevels = get(p, 'levels');
    const offered: Level[] = this.#policy.human.panel ? capLevels(this.#policy.human.levels, Array.isArray(hubLevels) ? LEVELS.filter((l) => hubLevels.includes(l)) : []) : [DEFAULT_LEVEL];
    // What the hub's policy decides for each action of this app. A hub that does not say may
    // confirm anything; one entry that is missing or malformed counts as `confirm`.
    const said = get(p, 'decisions');
    const hub: Session['hub'] = isObj(said) ? new Map([...this.#actions.keys()].map((name) => [name, hubDecision(said, name)])) : null;
    // Who this is, as far as the surface can tell: the id of the agent's credential, from a
    // hub it verified. Without one, every agent is the same agent to it.
    const credRaw = get(p, 'cred');
    const cred = this.#hubVerified && typeof credRaw === 'string' && credRaw.length >= 1 && credRaw.length <= 64 ? credRaw : '';
    // What the person tightened for this agent before stays: for its next grant, whichever
    // way the last one ended, and under whatever session id or name it comes back.
    const before = this.#keptFor(cred);
    const beforeLines = this.#keptLines(before, scopes);
    let d = this.#policy.attach;
    if (f.c === 1) d = stricter(d, 'confirm');
    // An unverified hub, or a page where the person has used Stop, never gets a silent attach.
    if (!this.#hubVerified) d = stricter(d, 'confirm');
    if (this.#stopped) d = stricter(d, 'confirm');
    // Nor does an attach that follows a tightening where the surface cannot tell whether this
    // is the agent the person restricted: they are asked, and told what stays.
    if (cred === '' && beforeLines.length > 0) d = stricter(d, 'confirm');
    if (d === 'deny') throw new ReinsError('E_DENIED', 'attach denied by policy');
    this.#requireOverlay();
    if (d === 'confirm') {
      const epoch = this.#epoch;
      const stopGen = this.#stopGen;
      const req: ConsentRequest = { kind: 'attach', agent: { ...agent }, scopes: [...scopes] };
      if (reason) req.reason = reason;
      if (!this.#hubVerified) req.hubVerified = false;
      if (beforeLines.length) req.kept = beforeLines;
      const keptWhy = cred === '' ? 'This page cannot tell whether this is an agent you restricted before. What you set then stays for this one:' : 'What you set for this agent before stays:';
      const answer = await this.#consent(req, ag, false, { keptWhy });
      if (epoch !== this.#epoch) throw new ReinsError('E_GONE', 'connection closed');
      if (answer === 'no' || stopGen !== this.#stopGen) throw new ReinsError('E_CONSENT', 'the user declined');
      // Re-check after the wait: the indicator must be visible when the grant starts.
      this.#requireOverlay();
      if (full()) throw new ReinsError('E_BUSY', 'too many agents are attached to this page');
    }
    if (this.#sessions.has(ag)) this.#drop(ag, 'replaced', false);
    // A new grant, also one that replaces another. What let the agent do more ended with the
    // old one: the level is `ask` again, there are no `allow` rules and no remembered
    // approvals. What the person tightened stays: Strict, their Ask and Block rules, the
    // scopes they switched off. Read again now: they may have changed something while asked.
    const kept = this.#keptFor(cred);
    const session: Session = { ag, agent, scopes, granted: [...scopes], level: DEFAULT_LEVEL, offered, hub, rules: new Map(), nodes: null, rev: -1, subs: new Set(), sent: new Map(), approved: new Set(), chat: {}, cred };
    const stays: KeptSettings = {};
    if (kept.strict && offered.includes('strict')) {
      session.level = 'strict';
      stays.level = 'strict';
    }
    for (const [name, rule] of kept.rules) {
      const def = this.#actions.get(name)?.def;
      // An action the app or the hub denies needs no rule, and takes none.
      if (!def || this.#base(session, def) === 'deny') continue;
      session.rules.set(name, rule);
      Object.defineProperty((stays.rules ??= {}), name, { value: rule, enumerable: true, writable: true, configurable: true });
    }
    const off = scopes.filter((x) => kept.off.has(x));
    if (off.length) {
      session.scopes = scopes.filter((x) => !kept.off.has(x));
      stays.off = off;
    }
    this.#sessions.set(ag, session);
    this.#keep(session);
    // Who hears whom: the stricter of this page's policy and the hub's, which the hub sends
    // with every attach. A hub that sends none is taken to relay nothing.
    const hubRelay = get(p, 'chatRelay');
    // A hub that sends another value than before changes what the room relays, and with it
    // goes what the person switched on. Not silently: the hub is told `relay off` for each
    // agent that was switched on, and the Chat tab says what happened.
    const dropped = this.#room.setMode(stricterRelay(this.#policy.chatRelay, (CHAT_RELAY as readonly unknown[]).includes(hubRelay) ? (hubRelay as ChatRelay) : 'off'));
    if (dropped.changed) {
      this.#relayChanged(dropped.silenced, false, false);
      if (dropped.silenced.length > 0) this.#relayReset = true;
    }
    // In the room from now on: it reads nothing that was said before this moment, and under
    // `chatRelay: "person"` it hears no other agent until the person adds it.
    if (session.scopes.includes('chat')) this.#room.join(session.chat, ag, agent.name);
    this.#drawChat();
    const anyKept = stays.level !== undefined || stays.rules !== undefined || stays.off !== undefined;
    if (anyKept) this.#logYou(session, 'Kept what you set before');
    this.#refreshIndicator();
    this.#emit('attach', { agent: { ...agent }, scopes: [...session.scopes] });
    // The hub is told with the answer, so that the grant never exists there without them:
    // `scopes` are the scopes granted, `kept` what stays of the person's earlier settings.
    return anyKept ? { scopes, ttlMs: this.#policy.ttlMs, kept: stays } : { scopes, ttlMs: this.#policy.ttlMs };
  }

  // ───────── method handlers ─────────

  #handlers: Record<string, Handler> = {
    observe: (s, p) => this.#observe(s, p),
    read: (s, p) => {
      const h = optStr(p, 'h', TARGET_MAX);
      const max = Math.min(MAX_READ, optNum(p, 'max', 1, Number.MAX_SAFE_INTEGER, true) ?? 2000);
      const el = h === undefined ? null : this.#tree.resolve(h);
      return this.#tree.readText(el, max);
    },
    'state.get': (s, p) => {
      const name = optStr(p, 'name', 64);
      if (name !== undefined && !this.#states.has(name)) bad('unknown state');
      const state: Record<string, unknown> = {};
      // A state getter is the app's code, run here because an agent asked: the chat composer
      // takes no input while it runs, as with an action or a view.
      this.#holdChat(1);
      try {
        for (const n of name !== undefined ? [name] : [...this.#states.keys()]) {
          const v = this.#readState(n);
          Object.defineProperty(state, n, { value: v, enumerable: true, writable: true, configurable: true });
          s.sent.set(n, v);
        }
      } finally {
        this.#holdChat(-1);
      }
      return { state };
    },
    sub: (s, p) => {
      for (const t of this.#topics(p)) s.subs.add(t);
      return { topics: TOPICS.filter((t) => s.subs.has(t)) };
    },
    unsub: (s, p) => {
      for (const t of this.#topics(p)) s.subs.delete(t);
      return { topics: TOPICS.filter((t) => s.subs.has(t)) };
    },
    act: (s, p, f, note) => this.#act(s, p, f, note),
    'ui.click': (s, p) => {
      const h = reqStr(p, 'h', TARGET_MAX);
      return this.#ui(s, async () => {
        this.#guardPrivate(this.#target(h));
        const el = await this.#approach(h, s);
        this.#ready(s, 'ui', true);
        this.#guardPrivate(el);
        click(el, centerOf(el));
      });
    },
    'ui.type': (s, p) => {
      const h = reqStr(p, 'h', TARGET_MAX);
      const text = reqStr(p, 'text', MAX_TEXT);
      const clear = optBool(p, 'clear') ?? false;
      const enter = optBool(p, 'enter') ?? false;
      return this.#ui(s, async () => {
        const check = (el: Element) => {
          if (!isTextEntry(el)) bad('target does not take text');
          this.#guardPrivate(el);
          if (isReadOnly(el)) throw new ReinsError('E_NO_TARGET', 'target is read-only');
          // Replacing an editable's content would also wipe the private elements inside it.
          if (clear && !this.#policy.privateInput && isEditable(el) && hasPrivateInside(el)) throw new ReinsError('E_DENIED', 'target contains private content');
        };
        check(this.#target(h));
        const el = await this.#approach(h, s);
        this.#ready(s, 'ui', true);
        check(el);
        typeText(el, text, clear);
        if (enter) pressKey(el, 'Enter', this.#root!, this.#tabStop);
      });
    },
    'ui.select': (s, p) => {
      const h = reqStr(p, 'h', TARGET_MAX);
      const value = reqStr(p, 'value', 1000);
      return this.#ui(s, async () => {
        const check = (el: Element) => {
          if (el.localName !== 'select') bad('target is not a select');
          this.#guardPrivate(el);
        };
        check(this.#target(h));
        const el = await this.#approach(h, s);
        this.#ready(s, 'ui', true);
        check(el);
        selectOption(el, value);
      });
    },
    'ui.scroll': (s, p) => {
      const h = optStr(p, 'h', TARGET_MAX);
      const dx = optNum(p, 'dx', -1e6, 1e6);
      const dy = optNum(p, 'dy', -1e6, 1e6);
      const to = get(p, 'to');
      if (to !== undefined && to !== 'top' && to !== 'bottom' && to !== 'view') bad('to: expected top, bottom or view');
      if (to === 'view' && h === undefined) bad('h: required with to=view');
      if (to === undefined && !dx && !dy) bad('give dx, dy or to');
      return this.#ui(s, async () => {
        const el = h === undefined ? null : this.#target(h, true);
        if (el) this.#guardPrivate(el);
        if (to === 'view' && el) {
          try {
            el.scrollIntoView?.({ block: 'center', inline: 'nearest' });
          } catch {
            // no layout
          }
        } else if (to === 'top' || to === 'bottom') scrollTo(el, to, this.#win);
        if (dx || dy) scrollBy(el, dx ?? 0, dy ?? 0, this.#win);
      });
    },
    'ui.key': (s, p) => {
      const key = reqStr(p, 'key', 16);
      if (!(UI_KEYS as readonly string[]).includes(key)) bad('key: not a supported key');
      const h = optStr(p, 'h', TARGET_MAX);
      return this.#ui(s, async () => {
        let el: Element;
        if (h !== undefined) el = this.#target(h);
        else {
          const active = this.#doc.activeElement;
          // The focused element receives the key, exposed or not: a private one refuses it.
          if (active && active !== this.#doc.body) this.#guardPrivate(active);
          el = active && active !== this.#doc.body && this.#tree.exposedNow(active) ? active : (this.#doc.body ?? this.#root!);
        }
        // Every key, not only editing keys: arrows change a select, Enter submits, Space toggles.
        this.#guardPrivate(el);
        // Editing keys get the same read-only and disabled checks as ui.type.
        if (EDIT_KEYS.has(key) && (isReadOnly(el) || isDisabled(el))) throw new ReinsError('E_NO_TARGET', 'target is read-only');
        pressKey(el, key as UiKey, this.#root!, this.#tabStop);
      });
    },
    'cursor.move': (s, p) => this.#cursorMove(s, p),
    'cursor.set': (s, p) => {
      const visible = optBool(p, 'visible');
      const label = optStr(p, 'label', 40);
      const color = optStr(p, 'color', 7);
      if (color !== undefined && !COLOR_PATTERN.test(color)) bad('color: expected #rgb or #rrggbb');
      return this.#queue.push(() => {
        this.#ready(s, 'cursor');
        if (label !== undefined) {
          this.#overlay?.cursorLabel(label);
          this.#cursorLabelSet = true;
        }
        if (color !== undefined) this.#overlay?.cursorColor(color);
        if (visible !== undefined) this.#setCursor(visible, s);
        return {};
      });
    },
    'show.toast': (s, p) => {
      const text = reqStr(p, 'text', 2000);
      const kind = get(p, 'kind') ?? 'info';
      if (kind !== 'info' && kind !== 'ok' && kind !== 'warn') bad('kind: expected info, ok or warn');
      const ms = optNum(p, 'ms', 0, 600_000) ?? 4000;
      return this.#queue.push(() => {
        this.#ready(s, 'show');
        this.#overlay?.toast(clip(text, 500), kind as ToastKind, clamp(ms, 1000, 60_000), s.agent.name);
        return {};
      });
    },
    'show.highlight': (s, p) => {
      const h = reqStr(p, 'h', TARGET_MAX);
      const label = optStr(p, 'label', 80) ?? '';
      const ms = optNum(p, 'ms', 0, 600_000) ?? 3000;
      return this.#queue.push(() => {
        this.#ready(s, 'show');
        const el = this.#target(h, true);
        this.#overlay?.highlight(el, label, clamp(ms, 500, 60_000));
        return {};
      });
    },
    'show.view': (s, p) => this.#showView(s, p),
    'show.clear': (s) =>
      this.#queue.push(() => {
        this.#ready(s, 'show');
        this.#overlay?.clear();
        return {};
      }),
    'nav.go': (s, p) => {
      const url = reqStr(p, 'url', 2048);
      if (!navAllowed(this.#policy, url, this.#win.location.href)) throw new ReinsError('E_DENIED', 'navigation not allowed');
      return this.#queue.push(() => {
        this.#ready(s, 'nav');
        const href = this.#win.location.href;
        if (!navAllowed(this.#policy, url, href)) throw new ReinsError('E_DENIED', 'navigation not allowed');
        const target = new URL(url, href).href;
        // Answer first, then navigate, unless Stop, Pause, a consent prompt or a hidden
        // indicator came in between.
        this.#later(() => {
          if (this.#sessions.get(s.ag) !== s || !s.scopes.includes('nav') || this.#paused || this.#busy || !this.#overlayUsable()) return;
          this.#win.location.assign(target);
        }, 30);
        return {};
      });
    },
    // Chat is answered at once, like the read-only methods: it changes the chat tab and nothing
    // on the page, so it does not wait its turn behind commands that do.
    'chat.say': (s, p) => {
      const text = chatText(get(p, 'text'));
      if (text === undefined) bad(`text: expected 1 to ${CHAT_MAX_TEXT} characters`);
      const to = optStr(p, 'to', 64);
      if (to === '') bad('to: expected an agent id, or person');
      const posted = this.#room.agentSay(s.chat, text, to);
      this.#posted(posted);
      // The id the message has for the agent that said it.
      return { id: posted.id! };
    },
    'chat.read': (s, p) => {
      const since = optNum(p, 'since', 0, Number.MAX_SAFE_INTEGER, true);
      const max = optNum(p, 'max', 1, Number.MAX_SAFE_INTEGER, true);
      return this.#room.read(s.chat, since, max);
    },
    'chat.status': (s, p) => {
      const state = get(p, 'state');
      if (!isChatState(state)) bad('state: expected idle, thinking or working');
      const note = chatNote(get(p, 'note'));
      if (note === undefined) bad(`note: expected one line of at most ${CHAT_MAX_NOTE} characters`);
      this.#room.status(s.chat, state, note);
      this.#drawChat();
      return {};
    },
    'stream.open': (s, p) => {
      if (get(p, 'kind') !== 'pointer') bad('kind: expected pointer');
      // A pointer stream is raw coordinates by another name.
      if (!this.#policy.coordinates) throw new ReinsError('E_DENIED', 'raw coordinates are not allowed');
      const ch = optNum(p, 'ch', 0, 0xffff, true);
      if (ch === undefined) bad('ch: required');
      this.#streams.set(ch, { ch, ag: s.ag, granter: new CreditGranter(PTR_INITIAL_CREDIT), nextSeq: undefined });
      this.#setCursor(true, s);
      return { credit: PTR_INITIAL_CREDIT };
    },
  };

  #topics(p: Record<string, unknown>): Topic[] {
    const t = get(p, 'topics');
    if (!Array.isArray(t) || t.length > 8) bad('topics: expected a list');
    for (const x of t) if (!(SUBSCRIBABLE_TOPICS as readonly unknown[]).includes(x)) bad('topics: unknown topic');
    return t as Topic[];
  }

  #readState(name: string): unknown {
    const st = this.#states.get(name);
    if (!st) bad('unknown state');
    let v: unknown;
    try {
      v = jsonClone(st.get());
    } catch (e) {
      console.error(`[reins] state ${name} failed:`, e);
      throw new ReinsError('E_INTERNAL', 'state unavailable');
    }
    return v === undefined ? null : v;
  }

  notify(name?: string): void {
    if (!this.#peer || this.#peer.closed) return;
    const names = name === undefined ? [...this.#states.keys()] : this.#states.has(name) ? [name] : [];
    const targets = [...this.#sessions.values()].filter((s) => this.#hears(s, 'state'));
    if (!targets.length || !names.length) return;
    for (const n of names) {
      let value: unknown;
      try {
        value = this.#readState(n);
      } catch {
        continue;
      }
      for (const s of targets) {
        const patch = s.sent.has(n) ? mergeDiff(s.sent.get(n), value) : value;
        if (patch === undefined) continue;
        s.sent.set(n, value);
        this.#send('state', { name: n, patch }, s.ag);
      }
    }
  }

  #observe(s: Session, p: Record<string, unknown>): Observation {
    const since = optNum(p, 'since', 0, Number.MAX_SAFE_INTEGER, true);
    const boxes = optBool(p, 'boxes') ?? false;
    const snap = this.#tree.snapshot(boxes);
    this.#uiChanged();
    const o: Observation = { rev: snap.rev, url: this.#win.location.href, title: clip(this.#doc.title, 300), vp: this.#vp() };
    if (since !== undefined && s.nodes && since === s.rev) {
      o.base = since;
      o.ops = diffNodes(s.nodes, snap.nodes);
    } else o.nodes = snap.nodes;
    if (this.#paused) o.paused = true;
    s.nodes = snap.nodes;
    s.rev = snap.rev;
    return o;
  }

  async #act(s: Session, p: Record<string, unknown>, f: ReqFrame, note: CommandNote): Promise<{ result?: unknown; rev: number }> {
    const a = reqStr(p, 'a', 64);
    const entry = this.#actions.get(a);
    if (!entry) bad('unknown action');
    const args = get(p, 'args');
    // No `args` means no arguments. The handler is then given {}, so {} is what the schema
    // is asked about: an action that requires nothing runs, a required property fails by name.
    const err = validate(entry.def.params, args === undefined ? {} : args);
    if (err) bad(err);
    // The policy, the hub's `c:1`, and what the person set for this agent: one decision.
    const c = this.#marked(s, entry.def, f);
    const remembers = this.#policy.consent.remember === 'session';
    /** A remembered approval stands in for the person: never for `c:1`, under `strict` or under a rule `confirm`. */
    const remembered = (v: ActVerdict) => v.remember === true && remembers && !c && s.approved.has(a);
    const refuse = (v: ActVerdict): void => {
      if (v.outcome === 'denied') throw new ReinsError('E_DENIED', 'action denied by policy');
      // The person's own rule: no prompt, and nothing counted toward the cool-off.
      if (v.outcome === 'blocked') throw new ReinsError('E_CONSENT', 'the user blocked this action');
    };
    const v = this.#verdict(s, entry.def, c);
    refuse(v);
    // `approved` is the person's answer to a prompt for this very request. A level or a rule
    // that lets the action run is no such answer.
    let approved = false;
    let record = false;
    let by: CommandNote['by'] = v.outcome === 'run' && v.by !== 'policy' ? v.by : undefined;
    if (v.outcome === 'prompt') {
      if (remembered(v)) by = 'remembered';
      else {
        const req: ConsentRequest = { kind: 'action', agent: { ...s.agent }, action: jsonClone(entry.def), args: jsonClone(args) };
        // Where the approval will be remembered, the card says so before the person gives it.
        const answer = await this.#consent(req, s.ag, this.#mayOfferAlways(s, entry.def, c), { remembers: remembers && v.remember === true && !c });
        if (this.#sessions.get(s.ag) !== s) throw new ReinsError('E_NOT_ATTACHED', 'not attached');
        if (answer === 'no') throw new ReinsError('E_CONSENT', 'the user declined');
        if (answer === 'always') this.#setRule(s.ag, a, 'allow');
        approved = true;
        by = 'person';
        // Remembered only where it can answer a later request: one the hub does not mark.
        record = remembers && v.remember === true && !c;
      }
    }
    return this.#queue.push(async () => {
      // The action the person just approved may run while another agent's prompt is up;
      // anything else waits until no prompt is showing.
      this.#ready(s, 'act', false, approved);
      // What the person set may have changed while this request waited its turn. A Block set
      // meanwhile holds, also against an approval they gave before it: the later word counts.
      const now = this.#verdict(s, entry.def, c);
      refuse(now);
      // Without an approval of its own, it runs only if it would still run without asking.
      if (!approved && now.outcome === 'prompt' && !remembered(now)) throw new ReinsError('E_BUSY', 'the permission for this action changed while the request waited; send it again');
      if (by !== undefined) note.by = by;
      this.#keepChatFocus();
      let r: unknown;
      // What the app's handler puts into the focused field while it runs was chosen by the
      // agent (an editor's "insert text" action, say). The chat composer takes none of it:
      // it is read-only until the handler has ended.
      this.#holdChat(1);
      try {
        const pending = entry.run(args === undefined ? {} : args, this.#ctx(s));
        // Remember an approval only once the handler has actually been invoked.
        if (record) this.#remember(s, a);
        r = await pending;
      } catch (e) {
        if (record) this.#remember(s, a);
        throw fromHandler(e, 'action');
      } finally {
        this.#holdChat(-1);
      }
      const result = resultJson(r);
      const rev = this.#refresh();
      return result === undefined ? { rev } : { result, rev };
    });
  }

  /** Keep an approval for this grant, and show it in the panel: the action runs without asking from here on. */
  #remember(s: Session, action: string): void {
    if (s.approved.has(action)) return;
    s.approved.add(action);
    this.#refreshIndicator();
  }

  /**
   * May the prompt for this action offer "Always allow": only with the built-in prompt and
   * a panel where the person can see and undo the rule, and only where the rule would be
   * taken (`#setRule`).
   */
  #mayOfferAlways(s: Session, def: ActionDef, c: boolean): boolean {
    if (!this.#policy.human.panel || this.#o.indicator === false || this.#o.consent) return false;
    const base = stricter(this.#base(s, def), c ? 'confirm' : 'allow');
    return base !== 'confirm' || allowRulePermitted(def.risk, s.offered);
  }

  async #showView(s: Session, p: Record<string, unknown>): Promise<{ result?: unknown }> {
    const name = reqStr(p, 'view', 64);
    const entry = this.#views.get(name);
    if (!entry) bad('unknown view');
    const given = get(p, 'data');
    // No `data` for a view that takes an object is {}, as for `act`. A view without a
    // schema, or one whose data is not an object, keeps the missing value.
    const data = given === undefined && entry.def.params?.type === 'object' ? {} : given;
    const err = validate(entry.def.params, data);
    if (err) bad(err);
    return this.#queue.push(async () => {
      this.#ready(s, 'show');
      this.#keepChatFocus();
      let r: unknown;
      // A view's renderer is the app's code running on an agent's request, like an action's
      // handler: what it puts into the focused field was chosen by the agent. The chat
      // composer takes none of it.
      this.#holdChat(1);
      try {
        r = await entry.run(data, this.#ctx(s));
      } catch (e) {
        throw fromHandler(e, 'view');
      } finally {
        this.#holdChat(-1);
      }
      const result = resultJson(r);
      return result === undefined ? {} : { result };
    });
  }

  // ───────── ui and cursor ─────────

  /** Resolve a target for an input command: live, exposed and (unless `anyState`) enabled. */
  #target(h: string, anyState = false): Element {
    const el = this.#tree.resolve(h);
    if (!anyState && isDisabled(el)) throw new ReinsError('E_NO_TARGET', 'target is disabled');
    return el;
  }

  /** Run a `ui.*` command in the queue, after the person has stopped using the page. */
  #ui(s: Session, fn: () => Promise<void>): Promise<UiResult> {
    return this.#queue.push(async () => {
      this.#live(s, 'ui');
      await this.#human.quiet();
      // Synchronous from here into fn(): nothing can interleave before its first input
      // unless fn waits (a glide), and then fn checks again itself.
      this.#ready(s, 'ui', true);
      // Synthetic input runs the app's own handlers (a button that inserts text at the
      // focus): the chat composer takes no input while it does.
      this.#holdChat(1);
      try {
        await fn();
      } finally {
        this.#holdChat(-1);
      }
      return { rev: this.#refresh() };
    });
  }

  /**
   * Bring the target into view and, when the cursor is shown, glide to it and ripple. A
   * glide takes time: afterwards wait for the person to be idle again and re-check that the
   * session is live and not paused. The caller runs `#ready(s, true)` once more,
   * synchronously, right before it synthesises input.
   */
  async #approach(h: string, s: Session): Promise<Element> {
    let el = this.#target(h);
    scrollIntoView(el);
    if (this.#cursorOn && this.#motion) {
      await this.#motion.moveTo(this.#clampPt(centerOf(el)));
      this.#live(s, 'ui');
      await this.#human.quiet();
      this.#ready(s, 'ui', true);
      el = this.#target(h);
      const c = this.#clampPt(centerOf(el));
      this.#overlay?.ripple(c.x, c.y);
    }
    return el;
  }

  #clampPt(pt: Point): Point {
    const [w, h] = this.#vp();
    return { x: clamp(pt.x, 0, Math.max(0, w)), y: clamp(pt.y, 0, Math.max(0, h)) };
  }

  #setCursor(on: boolean, s?: Session): void {
    if (!this.#overlay || !this.#motion) return;
    if (on && !this.#cursorOn) {
      if (!this.#cursorLabelSet && s) this.#overlay.cursorLabel(s.agent.name.slice(0, 40));
      if (!this.#motion.placed) {
        const [w, h] = this.#vp();
        this.#motion.jump({ x: Math.round(w / 2), y: Math.round(h / 2) });
      }
    }
    if (!on) this.#motion.finish();
    if (!on) this.#cursorAg = undefined;
    else if (s) this.#cursorAg = s.ag;
    this.#cursorOn = on;
    this.#overlay.cursorVisible(on);
  }

  async #cursorMove(s: Session, p: Record<string, unknown>): Promise<Point> {
    const to = get(p, 'to');
    const ms = optNum(p, 'ms', 0, 600_000);
    const wait = optBool(p, 'wait') ?? true;
    let raw: Point | undefined;
    let h: string | undefined;
    if (typeof to === 'string') {
      if (to.length > TARGET_MAX) bad('to: too long');
      h = to;
    } else if (isObj(to) && typeof to.x === 'number' && typeof to.y === 'number' && Number.isFinite(to.x) && Number.isFinite(to.y)) {
      if (!this.#policy.coordinates) throw new ReinsError('E_DENIED', 'raw coordinates are not allowed');
      raw = { x: to.x, y: to.y };
    } else bad('to: expected a target or a point');
    const started = await this.#queue.push(() => {
      this.#ready(s, 'cursor');
      const pt = this.#clampPt(h !== undefined ? centerOf(this.#tree.resolve(h)) : raw!);
      this.#setCursor(true, s);
      const done = this.#motion ? this.#motion.moveTo(pt, ms === undefined ? undefined : Math.min(ms, MAX_GLIDE_MS)) : Promise.resolve(pt);
      return { pt, done };
    });
    if (!wait) return { x: Math.round(started.pt.x), y: Math.round(started.pt.y) };
    return started.done;
  }

  #streamClose(p: Record<string, unknown>, f: ReqFrame): Record<string, never> {
    const ch = optNum(p, 'ch', 0, 0xffff, true);
    if (ch === undefined) bad('ch: required');
    const st = this.#streams.get(ch);
    if (st && (f.ag === undefined || st.ag === f.ag)) this.#streams.delete(ch);
    return {};
  }

  #onBinary(bytes: Uint8Array): void {
    if (bytes.length < 1 || binaryKind(bytes) !== BIN_POINTER) return;
    let frame;
    try {
      frame = decodePointer(bytes);
    } catch {
      return;
    }
    const st = this.#streams.get(frame.ch);
    if (!st) return;
    const n = frame.points.length;
    const credit = () => {
      const c = st.granter.consumed(1);
      if (c > 0 && this.#streams.get(st.ch) === st) {
        try {
          this.#peer?.flow(st.ch, c);
        } catch {
          // ignore
        }
      }
    };
    const s = this.#sessions.get(st.ag);
    if (!s || this.#paused || this.#busy || !s.scopes.includes('cursor') || !this.#motion || !this.#policy.coordinates || !this.#overlayUsable(true)) {
      for (let i = 0; i < n; i++) credit();
      return;
    }
    const gap = st.nextSeq !== undefined && frame.seq !== st.nextSeq;
    st.nextSeq = (frame.seq + n) >>> 0;
    if (!this.#cursorOn || this.#cursorAg !== s.ag) this.#setCursor(true, s);
    this.#motion.push(frame.points, credit, gap);
  }
}

export function createDriver(options: DriverOptions): Driver {
  return new ReinsDriver(options);
}
