/**
 * The functions the driver's trusted-input path relies on, taken when this module loads.
 *
 * What this closes. A script in the page can replace `EventTarget.prototype.addEventListener`
 * to collect the overlay's listeners and call them with an object that says `isTrusted:
 * true`, or with a real click the person made somewhere else. The overlay registers its
 * listeners through the copies kept here, through a kept `Reflect.apply`, so such a hook is
 * handed none of them; and whether an event is the person's is read through the native getter
 * of `isTrusted`, taken from a real event instance, and only while the browser is delivering
 * the event to the control the listener belongs to. Forged events, and borrowed ones, through
 * hooks on the functions that register listeners: that, and no more.
 *
 * What it does not do. It is not a wall between the driver and script in the page. The driver
 * is ordinary script in the page's own JavaScript realm: it pushes prompts onto arrays, looks
 * sessions up in maps, sets attributes and reads properties through methods every script can
 * replace. A script that replaces `Array.prototype.push`, `Map.prototype.get` or
 * `Element.prototype.setAttribute` after the driver has attached is handed prompts to answer,
 * sessions to change and the closed shadow root itself, with no input from the person at all,
 * and it does not matter which of the two loaded first. Keeping every built-in the driver
 * touches would be another program, and still one realm. So script that runs in the page's
 * realm is outside what Reins defends against (docs/SECURITY.md, "does not protect against").
 *
 * Where there is a real boundary: in an app adopted by `reins-electron` the driver runs in an
 * isolated world with built-ins of its own. The page's script shares the document with it
 * (elements, styles, timers) and none of its objects. Timers are the exception worth a note:
 * their ids belong to the document, so a script of the page's world can clear the driver's
 * timers. Nothing in the driver relies on a timer firing to stay safe; every wait is a time
 * compared with the clock (`tick`).
 */

const G = globalThis as unknown as Record<string, any>;
const apply = Reflect.apply;
const getOwn = Object.getOwnPropertyDescriptor;
const define = Object.defineProperty;
const create = Object.create;

type Fn = (...args: any[]) => any;

interface Prims {
  /** `EventTarget.prototype.addEventListener` and its counterpart. */
  add: Fn;
  remove: Fn;
  /** The window these were taken from, and its own listener functions (a test DOM gives the window its own). */
  win: unknown;
  winAdd: Fn;
  winRemove: Fn;
  createElement: Fn | undefined;
  createElementNS: Fn | undefined;
  createTextNode: Fn | undefined;
  attachShadow: Fn | undefined;
  /**
   * The native getter of `isTrusted`. A browser defines it on every event instance and it
   * cannot be redefined. A DOM without it has no input that is the person's (see `isTrusted`).
   */
  trusted: Fn | undefined;
  currentTarget: Fn | undefined;
  stopPropagation: Fn | undefined;
  preventDefault: Fn | undefined;
  Event: Fn;
}

function capture(): Prims | null {
  const ET = G.EventTarget;
  const Ev = G.Event;
  if (typeof ET !== 'function' || typeof Ev !== 'function' || typeof ET.prototype?.addEventListener !== 'function') return null;
  let trusted: Fn | undefined;
  try {
    const d = getOwn(new Ev('reins'), 'isTrusted');
    if (d && typeof d.get === 'function' && d.configurable === false) trusted = d.get;
  } catch {
    trusted = undefined;
  }
  const fn = (o: any, k: string): Fn | undefined => (o && typeof o[k] === 'function' ? o[k] : undefined);
  const win = G.window;
  return {
    add: ET.prototype.addEventListener,
    remove: ET.prototype.removeEventListener,
    win,
    winAdd: fn(win, 'addEventListener') ?? ET.prototype.addEventListener,
    winRemove: fn(win, 'removeEventListener') ?? ET.prototype.removeEventListener,
    createElement: fn(G.Document?.prototype, 'createElement'),
    createElementNS: fn(G.Document?.prototype, 'createElementNS'),
    createTextNode: fn(G.Document?.prototype, 'createTextNode'),
    attachShadow: fn(G.Element?.prototype, 'attachShadow'),
    trusted,
    currentTarget: getOwn(Ev.prototype, 'currentTarget')?.get,
    stopPropagation: fn(Ev.prototype, 'stopPropagation'),
    preventDefault: fn(Ev.prototype, 'preventDefault'),
    Event: Ev,
  };
}

// Timers and clocks exist wherever this module can load.
const setT: Fn = G.setTimeout;
const clearT: Fn = G.clearTimeout;
const setI: Fn = G.setInterval;
const clearI: Fn = G.clearInterval;
const dateNow: Fn = Date.now;
const perf: unknown = G.performance;
const perfNow: Fn | undefined = typeof G.performance?.now === 'function' ? G.performance.now : undefined;

let P: Prims | null = capture();
/** Captured at load in a browser. Where the DOM came later (a test that installs one), on first use. */
function prims(): Prims | null {
  return (P ??= capture());
}

/** The browser's own trusted flag is in use: nothing here falls back to a method a page can replace. */
export function nativeTrust(): boolean {
  return prims()?.trusted !== undefined;
}

/**
 * Was this event made by the person's own input? Read through the native getter, which
 * throws for anything that is not a real event.
 *
 * A DOM without the native flag (happy-dom, jsdom) has no input that is the person's at
 * all. There a real event object that carries `isTrusted: true` counts, which is how the
 * tests stand in for a person; a plain object still does not.
 */
export function isTrusted(e: unknown): boolean {
  const p = prims();
  if (!p) return false;
  if (p.trusted) {
    try {
      return apply(p.trusted, e, []) === true;
    } catch {
      return false;
    }
  }
  return e instanceof p.Event && (e as Event).isTrusted === true;
}

/** The target whose listener is running, read through the native getter. Null for anything that is not an event being dispatched. */
function currentTargetOf(e: unknown): unknown {
  const p = prims();
  try {
    return p?.currentTarget ? apply(p.currentTarget, e, []) : (e as Event).currentTarget;
  } catch {
    return null;
  }
}

/**
 * The person's own input, being dispatched to `at` right now. A trusted event kept from
 * elsewhere and handed to a listener has another `currentTarget`, or none.
 */
export function trustedAt(e: unknown, at: EventTarget): boolean {
  return isTrusted(e) && currentTargetOf(e) === at;
}

/** `e.stopPropagation()`, through the method kept at load. Does nothing for what is not an event. */
export function stop(e: unknown): void {
  const f = prims()?.stopPropagation;
  try {
    if (f) apply(f, e, []);
    else (e as Event).stopPropagation();
  } catch {
    // not an event
  }
}

/** `e.preventDefault()`, through the method kept at load. */
export function prevent(e: unknown): void {
  const f = prims()?.preventDefault;
  try {
    if (f) apply(f, e, []);
    else (e as Event).preventDefault();
  } catch {
    // not an event
  }
}

type Options = boolean | { capture?: boolean; passive?: boolean; once?: boolean };

/** Options as an object without a prototype: nothing a page put on `Object.prototype` is read from it. */
function bare(o: Options | undefined): unknown {
  if (o === undefined || typeof o === 'boolean') return o;
  const out = create(null) as Record<string, unknown>;
  if (o.capture !== undefined) out.capture = o.capture;
  if (o.passive !== undefined) out.passive = o.passive;
  if (o.once !== undefined) out.once = o.once;
  return out;
}

function wire(which: 'add' | 'remove', target: EventTarget, type: string, fn: (e: any) => void, options?: Options): void {
  const p = prims();
  if (p) {
    const mine = target === p.win;
    const f = which === 'add' ? (mine ? p.winAdd : p.add) : mine ? p.winRemove : p.remove;
    if (p.trusted) {
      // A browser: the kept function or nothing.
      apply(f, target, [type, fn, bare(options)]);
      return;
    }
    try {
      apply(f, target, [type, fn, bare(options)]);
      return;
    } catch {
      // A test DOM whose target is not of the kind the kept function takes.
    }
  }
  if (which === 'add') target.addEventListener(type, fn, options);
  else target.removeEventListener(type, fn, options);
}

/** `target.addEventListener`, through the function kept at load. */
export function listen(target: EventTarget, type: string, fn: (e: any) => void, options?: Options): void {
  wire('add', target, type, fn, options);
}

export function unlisten(target: EventTarget, type: string, fn: (e: any) => void, options?: Options): void {
  wire('remove', target, type, fn, options);
}

function ownAdd(this: EventTarget, type: string, fn: (e: any) => void, options?: Options): void {
  listen(this, type, fn, options);
}
function ownRemove(this: EventTarget, type: string, fn: (e: any) => void, options?: Options): void {
  unlisten(this, type, fn, options);
}

/**
 * Give an element of the overlay its own `addEventListener` and `removeEventListener`, which
 * go through the kept functions. Code that builds on the overlay's elements (a panel tab)
 * and calls `el.addEventListener(...)` then registers its listener where a replaced
 * prototype method does not see it.
 */
export function seal<T extends EventTarget>(el: T): T {
  try {
    define(el, 'addEventListener', { value: ownAdd, writable: false, configurable: false, enumerable: false });
    define(el, 'removeEventListener', { value: ownRemove, writable: false, configurable: false, enumerable: false });
  } catch {
    // An element that cannot take own properties keeps the prototype's methods.
  }
  return el;
}

export function createElement<K extends keyof HTMLElementTagNameMap>(doc: Document, tag: K): HTMLElementTagNameMap[K] {
  const f = prims()?.createElement;
  if (f) {
    try {
      return seal(apply(f, doc, [tag]) as HTMLElementTagNameMap[K]);
    } catch (e) {
      if (nativeTrust()) throw e;
    }
  }
  return seal(doc.createElement(tag));
}

export function createElementNS(doc: Document, ns: string, tag: string): Element {
  const f = prims()?.createElementNS;
  if (f) {
    try {
      return seal(apply(f, doc, [ns, tag]) as Element);
    } catch (e) {
      if (nativeTrust()) throw e;
    }
  }
  return seal(doc.createElementNS(ns, tag));
}

export function createTextNode(doc: Document, text: string): Text {
  const f = prims()?.createTextNode;
  if (f) {
    try {
      return apply(f, doc, [text]) as Text;
    } catch (e) {
      if (nativeTrust()) throw e;
    }
  }
  return doc.createTextNode(text);
}

export function attachShadow(host: Element, init: ShadowRootInit): ShadowRoot {
  const f = prims()?.attachShadow;
  if (f) {
    try {
      return apply(f, host, [init]) as ShadowRoot;
    } catch (e) {
      if (nativeTrust()) throw e;
    }
  }
  return host.attachShadow(init);
}

export type Timer = ReturnType<typeof setTimeout>;

export function later(fn: () => void, ms: number): Timer {
  return apply(setT, undefined, [fn, ms]) as Timer;
}
export function cancelLater(t: Timer | undefined): void {
  if (t !== undefined) apply(clearT, undefined, [t]);
}
export function every(fn: () => void, ms: number): Timer {
  return apply(setI, undefined, [fn, ms]) as Timer;
}
export function cancelEvery(t: Timer | undefined): void {
  if (t !== undefined) apply(clearI, undefined, [t]);
}

/** `Date.now()`, as it was at load. */
export function now(): number {
  return apply(dateNow, Date, []) as number;
}

/** A clock that does not go back: `performance.now()` as it was at load, else `now()`. */
export function tick(): number {
  return perfNow ? (apply(perfNow, perf, []) as number) : now();
}
