/**
 * Timing: animation frames with a timer fallback, the page-command queue with its
 * per-frame budget, the cursor's one-shot glides and pointer-stream playback.
 *
 * requestAnimationFrame does not fire in a hidden tab, so every wait here races a timer
 * and, while the page is hidden, animations finish at once. Nothing waits on a frame alone.
 */
import { ReinsError, playbackRate } from '@offensiveadhd/reins/core';
import type { Point, PointerPoint } from '@offensiveadhd/reins/core';

/** Time budget for queued commands in one animation frame (SPEC 11). */
export const FRAME_BUDGET_MS = 6;
/** Longest wait for a frame before a timer takes over. */
const FRAME_FALLBACK_MS = 50;
/** Upper bound on any one cursor glide. */
export const MAX_GLIDE_MS = 3000;

export function now(): number {
  return typeof performance !== 'undefined' && typeof performance.now === 'function' ? performance.now() : Date.now();
}

/** SPEC 11: clamp(120 + 110 * log2(1 + d / 40), 120, 900) ms. */
export function glideMs(distance: number): number {
  const d = Number.isFinite(distance) && distance > 0 ? distance : 0;
  return Math.min(900, Math.max(120, 120 + 110 * Math.log2(1 + d / 40)));
}

export function easeInOut(t: number): number {
  return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
}

export class Frames {
  #win: Window;
  constructor(win: Window) {
    this.#win = win;
  }
  /** True when animation frames can be expected: rAF exists and the page is visible. */
  get live(): boolean {
    const doc = this.#win.document;
    return typeof this.#win.requestAnimationFrame === 'function' && (!doc || doc.visibilityState === undefined || doc.visibilityState === 'visible');
  }
  /** Resolves at the next animation frame, or after a short timer when frames are not coming. */
  next(): Promise<number> {
    return new Promise((resolve) => {
      let done = false;
      let raf: number | undefined;
      const fire = () => {
        if (done) return;
        done = true;
        clearTimeout(timer);
        if (raf !== undefined) {
          try {
            this.#win.cancelAnimationFrame?.(raf);
          } catch {
            // ignore
          }
        }
        resolve(now());
      };
      const live = this.live;
      const timer = setTimeout(fire, live ? FRAME_FALLBACK_MS : 16);
      if (live) {
        try {
          raf = this.#win.requestAnimationFrame(fire);
        } catch {
          raf = undefined;
        }
      }
    });
  }
}

type Job = { run: () => unknown; resolve: (v: unknown) => void; reject: (e: unknown) => void };

/**
 * Commands that change the page run one at a time in arrival order, starting at an
 * animation frame and yielding to the next frame once the current one has used 6 ms.
 */
export class CommandQueue {
  #frames: Frames;
  #jobs: Job[] = [];
  #running = false;
  #frameStart = -1;
  #closed = false;

  constructor(frames: Frames) {
    this.#frames = frames;
  }

  get size(): number {
    return this.#jobs.length;
  }

  push<T>(run: () => T | Promise<T>): Promise<T> {
    if (this.#closed) return Promise.reject(new ReinsError('E_GONE', 'driver stopped'));
    return new Promise<T>((resolve, reject) => {
      this.#jobs.push({ run, resolve: resolve as (v: unknown) => void, reject });
      if (!this.#running) void this.#pump();
    });
  }

  async #pump(): Promise<void> {
    this.#running = true;
    try {
      while (this.#jobs.length && !this.#closed) {
        if (this.#frameStart < 0 || now() - this.#frameStart >= FRAME_BUDGET_MS) this.#frameStart = await this.#frames.next();
        const job = this.#jobs.shift();
        if (!job) break;
        try {
          job.resolve(await job.run());
        } catch (e) {
          job.reject(e);
        }
      }
    } finally {
      this.#running = false;
      this.#frameStart = -1;
    }
  }

  /** Fail everything still queued. */
  close(): void {
    this.#closed = true;
    const jobs = this.#jobs.splice(0);
    for (const j of jobs) j.reject(new ReinsError('E_GONE', 'driver stopped'));
  }
  reopen(): void {
    this.#closed = false;
  }
}

/** Where the cursor is drawn. Implemented by the overlay. */
export interface CursorView {
  position(x: number, y: number): void;
}

interface Glide {
  from: Point;
  ctrl: Point;
  to: Point;
  t0: number;
  dur: number;
  done: (p: Point) => void;
}

interface Queued extends PointerPoint {
  /** Called once this point has been played (credit return). */
  played?: () => void;
}

/**
 * The cursor's position and its motion: one-shot glides along a quadratic Bezier with
 * ease-in-out timing, and pointer-stream playback with interpolation and catch-up.
 */
export class CursorMotion {
  #frames: Frames;
  #view: CursorView;
  #vp: () => [number, number];
  x = -100;
  y = -100;
  #placed = false;
  #glide: Glide | null = null;
  #points: Queued[] = [];
  /** Position the current stream segment starts from, and progress into the head point. */
  #segFrom: Point | null = null;
  #segT = 0;
  #ticking = false;
  #lastTick = 0;
  #stopped = false;

  constructor(frames: Frames, view: CursorView, viewport: () => [number, number]) {
    this.#frames = frames;
    this.#view = view;
    this.#vp = viewport;
  }

  get placed(): boolean {
    return this.#placed;
  }
  /** Milliseconds of stream motion still queued. */
  get queuedMs(): number {
    let ms = -this.#segT;
    for (const p of this.#points) ms += p.dt;
    return Math.max(0, ms);
  }
  get queuedPoints(): number {
    return this.#points.length;
  }

  #draw(x: number, y: number): void {
    this.x = x;
    this.y = y;
    this.#placed = true;
    this.#view.position(x, y);
  }

  /** Put the cursor somewhere without animating (first appearance). */
  jump(p: Point): void {
    this.#draw(p.x, p.y);
  }

  /**
   * Glide to `to`. Resolves with the end point when the motion ends, or with the
   * position reached when a newer glide or a stream replaces it.
   */
  moveTo(to: Point, ms?: number): Promise<Point> {
    const target = { x: Math.round(to.x), y: Math.round(to.y) };
    this.#endGlide();
    if (!this.#placed) {
      // First appearance: start a little up and to the left so the motion reads.
      const [w, h] = this.#vp();
      this.#draw(Math.max(0, Math.min(w, target.x - 160)), Math.max(0, Math.min(h, target.y - 110)));
    }
    const from = { x: this.x, y: this.y };
    const dx = target.x - from.x;
    const dy = target.y - from.y;
    const d = Math.hypot(dx, dy);
    const dur = Math.min(MAX_GLIDE_MS, Math.max(0, ms ?? glideMs(d)));
    if (d < 0.5 || dur <= 0 || !this.#frames.live || this.#stopped) {
      this.#draw(target.x, target.y);
      return Promise.resolve(target);
    }
    // A gentle arc: control point off the midpoint, perpendicular to the chord.
    const off = Math.min(80, d * 0.14) * (Math.random() < 0.5 ? -1 : 1);
    const ctrl = { x: from.x + dx / 2 - (dy / d) * off, y: from.y + dy / 2 + (dx / d) * off };
    return new Promise<Point>((resolve) => {
      this.#glide = { from, ctrl, to: target, t0: now(), dur, done: resolve };
      this.#points = this.#points.filter((p) => (p.played?.(), false));
      this.#segFrom = null;
      this.#segT = 0;
      this.#run();
    });
  }

  #endGlide(): void {
    const g = this.#glide;
    if (!g) return;
    this.#glide = null;
    g.done({ x: Math.round(this.x), y: Math.round(this.y) });
  }

  /** Queue stream points (viewport fractions). `gap` bridges a sequence gap with a straight segment. */
  push(points: PointerPoint[], played: (() => void) | undefined, gap: boolean): void {
    if (this.#stopped) {
      for (let i = 0; i < points.length; i++) played?.();
      return;
    }
    this.#endGlide();
    points.forEach((p, i) => {
      const q: Queued = { x: p.x, y: p.y, dt: i === 0 && gap ? Math.max(16, p.dt) : p.dt };
      if (played) q.played = played;
      this.#points.push(q);
    });
    // Bound the backlog: drop the oldest points beyond 4096 (their credit still returns).
    while (this.#points.length > 4096) {
      this.#points.shift()?.played?.();
      this.#segFrom = null;
      this.#segT = 0;
    }
    if (!this.#frames.live) this.finish();
    else this.#run();
  }

  /** Complete everything now: used while hidden and when stopping. */
  finish(): void {
    const g = this.#glide;
    if (g) {
      this.#draw(g.to.x, g.to.y);
      this.#endGlide();
    }
    if (this.#points.length) {
      const last = this.#points[this.#points.length - 1]!;
      const [w, h] = this.#vp();
      for (const p of this.#points.splice(0)) p.played?.();
      this.#draw(last.x * w, last.y * h);
      this.#segFrom = null;
      this.#segT = 0;
    }
  }

  /**
   * Stop where it is (Pause, Stop): end the glide at the current position and discard
   * queued stream points, returning their credit, without playing or jumping to them.
   */
  halt(): void {
    this.#endGlide();
    for (const p of this.#points.splice(0)) p.played?.();
    this.#segFrom = null;
    this.#segT = 0;
  }

  stop(): void {
    this.#stopped = true;
    this.finish();
  }
  restart(): void {
    this.#stopped = false;
  }

  #run(): void {
    if (this.#ticking) return;
    this.#ticking = true;
    this.#lastTick = now();
    void (async () => {
      try {
        while (!this.#stopped && (this.#glide || this.#points.length)) {
          const t = await this.#frames.next();
          if (!this.#frames.live) {
            this.finish();
            break;
          }
          this.#tick(t);
        }
      } finally {
        this.#ticking = false;
      }
    })();
  }

  #tick(t: number): void {
    const elapsed = Math.max(0, Math.min(250, t - this.#lastTick));
    this.#lastTick = t;
    const g = this.#glide;
    if (g) {
      const k = Math.min(1, (t - g.t0) / g.dur);
      const e = easeInOut(k);
      const u = 1 - e;
      this.#draw(u * u * g.from.x + 2 * u * e * g.ctrl.x + e * e * g.to.x, u * u * g.from.y + 2 * u * e * g.ctrl.y + e * e * g.to.y);
      if (k >= 1) {
        this.#draw(g.to.x, g.to.y);
        this.#endGlide();
      }
      return;
    }
    if (!this.#points.length) return;
    const [w, h] = this.#vp();
    let advance = elapsed * playbackRate(this.queuedMs);
    if (!this.#segFrom) this.#segFrom = { x: this.x, y: this.y };
    while (this.#points.length) {
      const head = this.#points[0]!;
      const left = head.dt - this.#segT;
      if (advance >= left) {
        advance -= left;
        this.#points.shift();
        this.#segFrom = { x: head.x * w, y: head.y * h };
        this.#segT = 0;
        head.played?.();
        this.#draw(this.#segFrom.x, this.#segFrom.y);
        continue;
      }
      this.#segT += advance;
      const k = head.dt > 0 ? this.#segT / head.dt : 1;
      this.#draw(this.#segFrom.x + (head.x * w - this.#segFrom.x) * k, this.#segFrom.y + (head.y * h - this.#segFrom.y) * k);
      break;
    }
  }
}
