import { DEFAULT_LEVEL, DEFAULT_LIMITS, DEFAULT_PORT, LEVELS, Peer, ReinsError, WS_SUBPROTOCOL, applyOps, capScopes, chatMessage, clientConnect, renderCard, renderObservation, wsLink } from '@offensiveadhd/reins/core';
import type {
  AttachResult,
  ChatMessage,
  ChatReadResult,
  ChatState,
  Decision,
  ErrorCode,
  EvtFrame,
  Grant,
  HubInfo,
  Level,
  Limits,
  Link,
  Manifest,
  Observation,
  Point,
  Scope,
  SurfaceInfo,
  Target,
  ToastKind,
  Topic,
  UiKey,
  UiNode,
} from '@offensiveadhd/reins/core';
import { Emitter, unref } from './emitter.js';
import { PointerStreamImpl } from './pointer.js';
import type { PointerHost, PointerStream } from './pointer.js';

export type { PointerStream } from './pointer.js';

export interface ConnectOptions {
  /** Hub WebSocket URL. Default `ws://127.0.0.1:7346`. */
  url?: string;
  /** Use this link instead of opening a WebSocket. */
  link?: Link;
  /** Credential id. Default `default`. */
  kid?: string;
  /** The secret. Else, in Node: REINS_TOKEN, the file named by REINS_TOKEN_FILE, `.reins/token`. */
  key?: string;
  /** Agent name shown to the user in consent prompts. Default `reins-agent`. */
  name?: string;
  /** Handshake timeout. Default 10 s. */
  handshakeTimeoutMs?: number;
}

export interface ReinsClient {
  readonly session: string;
  info(): Promise<HubInfo>;
  surfaces(): Promise<SurfaceInfo[]>;
  attach(s: string, opts?: { scopes?: Scope[]; reason?: string }): Promise<SurfaceHandle>;
  ping(): Promise<number>;
  on(event: 'surface' | 'close', fn: (e: any) => void): () => void;
  close(): void;
}

export interface SurfaceHandle {
  readonly info: SurfaceInfo;
  readonly manifest: Manifest;
  /** `grant.scopes` follows the person's scope switches: it holds the scopes in force now. */
  readonly grant: Grant;
  /**
   * The permission level the person last set for this grant on the page: `ask` until told
   * otherwise. It says how much the person is asked, and is theirs alone to change.
   */
  readonly level: Level;
  /** The rules the person set for single actions, by action name: `allow`, `confirm` (ask every time) or `deny`. */
  readonly rules: Readonly<Record<string, Decision>>;
  /**
   * The person switched "Agents can hear each other" on for this agent in the page's chat:
   * the other agents they switched on receive what it says there, unless it says it to the
   * person alone, and it receives what they say. False until the hub says so. On a page whose
   * policy lets all agents hear each other without the person's switch it stays false: there
   * every message without `to` reaches the other agents.
   */
  readonly chatRelay: boolean;
  /** The full current UI tree as of the last `observe`. Empty before the first one. */
  readonly nodes: UiNode[];
  /** False once the grant ended or the surface went away. */
  readonly attached: boolean;
  card(): string;
  observe(opts?: { full?: boolean; boxes?: boolean }): Promise<Observation>;
  observeText(opts?: { full?: boolean }): Promise<string>;
  read(h?: Target, max?: number): Promise<string>;
  /** `read`, with whether the text was cut at `max`. */
  readText(h?: Target, max?: number): Promise<{ text: string; truncated: boolean }>;
  state(name?: string): Promise<Record<string, unknown>>;
  act<R = unknown>(action: string, args?: object): Promise<R>;
  click(h: Target): Promise<void>;
  type(h: Target, text: string, opts?: { clear?: boolean; enter?: boolean }): Promise<void>;
  select(h: Target, value: string): Promise<void>;
  scroll(opts: { h?: Target; dx?: number; dy?: number; to?: 'top' | 'bottom' | 'view' }): Promise<void>;
  key(key: UiKey, h?: Target): Promise<void>;
  cursor: {
    move(to: Target | Point, opts?: { ms?: number; wait?: boolean }): Promise<Point>;
    show(label?: string, color?: string): Promise<void>;
    hide(): Promise<void>;
  };
  show: {
    toast(text: string, kind?: ToastKind, ms?: number): Promise<void>;
    highlight(h: Target, label?: string, ms?: number): Promise<void>;
    view(view: string, data?: unknown): Promise<unknown>;
    clear(): Promise<void>;
  };
  go(url: string): Promise<void>;
  pointer(): Promise<PointerStream>;
  /**
   * The chat room in the page's panel (scope `chat`). What the person says there is their
   * request to this agent, within what the grant allows: it approves no prompt and changes no
   * permission. What another agent says is that agent's text. Both are data to a model.
   */
  chat: {
    /**
     * Say something. The person sees it. Without `to`, the other agents hear it where the
     * page relays and the person lets them. `to: "person"` is for the person alone: no agent
     * is sent it. Any other `to` names one agent of the room by its session id.
     */
    say(text: string, opts?: { to?: string }): Promise<{ id: number }>;
    /**
     * What this agent may read, oldest first: the latest `max`, or with `since` what came
     * after that id. Ids count this agent's own messages only, from 1 on each page load.
     */
    read(opts?: { since?: number; max?: number }): Promise<ChatReadResult>;
    /** What the agent is doing, shown next to its name: `idle`, `thinking` or `working`, with a short note. */
    status(state: ChatState, note?: string): Promise<void>;
  };
  subscribe(topics: Topic[]): Promise<void>;
  /** `on('chat', fn)` gets each `ChatMessage` of the room as it comes, without a subscription. */
  on(event: Topic, fn: (d: any) => void): () => void;
  detach(): Promise<void>;
}

const DEFAULT_URL = `ws://127.0.0.1:${DEFAULT_PORT}`;
const DEFAULT_SCOPES: Scope[] = ['observe', 'act', 'cursor', 'show'];

/** Drop undefined fields so a request carries only what the caller set. */
function clean<T extends Record<string, unknown>>(o: T): T {
  for (const k of Object.keys(o)) if (o[k] === undefined) delete o[k];
  return o;
}

function isNode(): boolean {
  return typeof process !== 'undefined' && !!process.versions?.node;
}

async function openLink(options: ConnectOptions): Promise<Link> {
  if (options.link) return options.link;
  const WS = (globalThis as { WebSocket?: new (url: string, protocols?: string | string[]) => any }).WebSocket;
  if (!WS) throw new ReinsError('E_BAD_ARGS', 'no WebSocket available: pass options.link');
  let ws: any;
  try {
    ws = new WS(options.url ?? DEFAULT_URL, WS_SUBPROTOCOL);
  } catch {
    throw new ReinsError('E_BAD_ARGS', 'invalid hub URL');
  }
  return wsLink(ws);
}

async function resolveKey(options: ConnectOptions): Promise<string> {
  if (options.key) return options.key;
  if (isNode()) {
    const { findNodeKey } = await import('./keys.js');
    const k = await findNodeKey(options.url);
    if (k) return k;
  }
  throw new ReinsError('E_AUTH', 'no key: pass options.key' + (isNode() ? ', or set REINS_TOKEN or REINS_TOKEN_FILE; no running hub announced a token file for this URL, and there is no .reins/token here' : ''));
}

const HANDSHAKE_ERRORS = new WeakSet<object>();

/**
 * Whether `connect` threw this error during the handshake. Until the handshake succeeds the
 * other end is unauthenticated, so the message may be text that whatever answered on the hub's
 * port chose: show it as data. Errors raised before dialling (no key, bad URL) are the SDK's own.
 */
export function isHandshakeError(e: unknown): boolean {
  return typeof e === 'object' && e !== null && HANDSHAKE_ERRORS.has(e);
}

/** Connect to a hub, authenticate as an agent and return a client. */
export async function connect(options: ConnectOptions = {}): Promise<ReinsClient> {
  const key = await resolveKey(options);
  const link = await openLink(options);
  let conn;
  try {
    conn = await clientConnect(
      link,
      { role: 'agent', name: options.name ?? 'reins-agent', kid: options.kid ?? 'default', key },
      options.handshakeTimeoutMs === undefined ? {} : { timeoutMs: options.handshakeTimeoutMs },
    );
  } catch (e) {
    link.close();
    if (typeof e === 'object' && e !== null) HANDSHAKE_ERRORS.add(e);
    throw e;
  }
  // Every request and event after this travels on the sealed link.
  return new Client(conn.link, conn.welcome.session, conn.welcome.limits);
}

class Client implements ReinsClient {
  readonly session: string;
  #peer: Peer;
  #limits: Limits;
  #events = new Emitter<'surface' | 'close'>();
  #handles = new Map<string, Set<Handle>>();
  #streams = new Map<number, PointerStreamImpl>();
  #hb: ReturnType<typeof setTimeout> | undefined;
  #closed = false;

  constructor(link: Link, session: string, limits: Limits) {
    this.session = session;
    this.#limits = { ...DEFAULT_LIMITS, ...limits };
    this.#peer = new Peer(
      link,
      {
        event: (f) => this.#onEvent(f),
        flow: (f) => this.#streams.get(f.ch)?.addCredit(f.credit),
        close: (code, msg) => this.#onClose(code, msg),
      },
      { limits: this.#limits },
    );
    this.#heartbeat();
  }

  request<R = unknown>(m: string, p?: object, timeoutMs?: number): Promise<R> {
    return this.#peer.request<R>(m, p, timeoutMs === undefined ? {} : { timeoutMs });
  }

  /**
   * Time a request may wait when a consent prompt can be involved (`surface.attach`, `act`):
   * `reqTimeoutMs` for the hub's answer on top of the hub's whole wait for the surface
   * (`reqTimeoutMs + consentTimeoutMs`). The agent so outwaits the hub, and it is the hub
   * that says how a slow prompt ended: the surface's `E_CONSENT`, or the hub's `E_TIMEOUT`
   * when the surface did not answer in time (a hidden tab runs its timers late).
   */
  get consentTimeoutMs(): number {
    return 2 * this.#limits.reqTimeoutMs + this.#limits.consentTimeoutMs;
  }

  info(): Promise<HubInfo> {
    return this.request<HubInfo>('hub.info', {});
  }

  async surfaces(): Promise<SurfaceInfo[]> {
    const r = await this.request<{ surfaces: SurfaceInfo[] }>('surfaces.list', {});
    return r.surfaces;
  }

  async attach(s: string, opts: { scopes?: Scope[]; reason?: string } = {}): Promise<SurfaceHandle> {
    const scopes = capScopes(opts.scopes ?? DEFAULT_SCOPES);
    const r = await this.request<AttachResult>('surface.attach', clean({ s, scopes, reason: opts.reason }), this.consentTimeoutMs);
    const h = new Handle(this, r);
    let set = this.#handles.get(h.info.s);
    if (!set) this.#handles.set(h.info.s, (set = new Set()));
    set.add(h);
    return h;
  }

  ping(): Promise<number> {
    return this.#peer.ping();
  }

  on(event: 'surface' | 'close', fn: (e: any) => void): () => void {
    return this.#events.on(event, fn);
  }

  close(): void {
    this.#clearHeartbeat();
    this.#peer.bye('OK');
  }

  // ── used by handles ──

  forget(h: Handle): void {
    const set = this.#handles.get(h.info.s);
    set?.delete(h);
    if (set && set.size === 0) this.#handles.delete(h.info.s);
  }

  openStream(ch: number, credit: number): PointerStream {
    const host: PointerHost = {
      sendBinary: (b) => this.#peer.sendBinary(b),
      closeChannel: async (c) => {
        await this.request('stream.close', { ch: c });
      },
      release: (c) => {
        this.#streams.delete(c);
      },
      waitMs: this.#limits.reqTimeoutMs,
    };
    const st = new PointerStreamImpl(ch, credit, host);
    this.#streams.set(ch, st);
    return st;
  }

  #onEvent(f: EvtFrame): void {
    const d = f.d as { kind?: string; surface?: SurfaceInfo } | undefined;
    if (f.topic === 'surface') this.#events.emit('surface', d);
    const s = f.s ?? d?.surface?.s;
    if (s === undefined) return;
    const set = this.#handles.get(s);
    if (!set) return;
    for (const h of [...set]) h.deliver(f.topic, d);
  }

  #onClose(code: ErrorCode | 'OK' | 'E_GONE', msg?: string): void {
    this.#closed = true;
    this.#clearHeartbeat();
    for (const st of this.#streams.values()) st.fail(new ReinsError('E_GONE', 'connection closed'));
    this.#streams.clear();
    this.#events.emit('close', msg === undefined ? { code } : { code, msg });
  }

  /** After `heartbeatMs` of silence send a ping; if it fails, close. */
  #heartbeat(): void {
    const hb = this.#limits.heartbeatMs;
    if (!(hb > 0)) return;
    const arm = (ms: number) => {
      this.#hb = unref(setTimeout(tick, Math.max(1, ms)));
    };
    const tick = () => {
      if (this.#closed || this.#peer.closed) return;
      const idle = Date.now() - this.#peer.lastSeen;
      if (idle >= hb) {
        this.#peer.ping(this.#limits.reqTimeoutMs).catch(() => {
          if (!this.#closed) this.#peer.bye('E_TIMEOUT', 'heartbeat failed');
        });
        arm(hb);
      } else arm(hb - idle);
    };
    arm(hb);
  }

  #clearHeartbeat(): void {
    if (this.#hb !== undefined) clearTimeout(this.#hb);
    this.#hb = undefined;
  }
}

class Handle implements SurfaceHandle {
  readonly manifest: Manifest;
  readonly grant: Grant;
  #info: SurfaceInfo;
  #c: Client;
  #events = new Emitter<Topic>();
  #level: Level = DEFAULT_LEVEL;
  #rules = new Map<string, Decision>();
  #chatRelay = false;
  #gone: string | undefined;
  #nodes: UiNode[] = [];
  #rev: number | undefined;
  #boxes = false;
  #queue: Promise<unknown> = Promise.resolve();

  constructor(c: Client, r: AttachResult) {
    this.#c = c;
    this.#info = r.surface;
    this.manifest = r.manifest;
    this.grant = r.grant;
    // What the person tightened for this agent before stays for this grant (SPEC 8): the
    // level `strict` and the rules `confirm` and `deny`. Nothing else is read from it.
    const kept = r.kept;
    if (kept && typeof kept === 'object') {
      if (kept.level === 'strict') this.#level = 'strict';
      if (kept.rules && typeof kept.rules === 'object') {
        for (const [name, d] of Object.entries(kept.rules)) if (d === 'confirm' || d === 'deny') this.#rules.set(name, d);
      }
    }
  }

  get info(): SurfaceInfo {
    return this.#info;
  }
  get nodes(): UiNode[] {
    return this.#nodes;
  }
  get attached(): boolean {
    return this.#gone === undefined;
  }
  get level(): Level {
    return this.#level;
  }
  get rules(): Readonly<Record<string, Decision>> {
    return Object.fromEntries(this.#rules);
  }
  get chatRelay(): boolean {
    return this.#chatRelay;
  }

  card(): string {
    return renderCard(this.manifest, { surface: this.#info, scopes: this.grant.scopes });
  }

  /** An event from the hub about this surface. */
  deliver(topic: Topic, d: unknown): void {
    const k = (d as { kind?: string } | undefined)?.kind;
    if (topic === 'grant') {
      if (k === 'scopes') {
        // The person switched scopes of this grant off or back on: these are in force now.
        const list = (d as { scopes?: unknown }).scopes;
        if (Array.isArray(list)) this.grant.scopes = capScopes(list.filter((x): x is Scope => typeof x === 'string'));
      } else if (k === undefined || k === 'revoked' || k === 'expired') this.#end(k ?? 'revoked');
      // A kind this SDK does not know ends nothing.
    } else if (topic === 'user') {
      const u = d as { level?: unknown; a?: unknown; d?: unknown; on?: unknown } | undefined;
      if (k === 'relay') {
        if (typeof u?.on === 'boolean') this.#chatRelay = u.on;
      } else if (k === 'level') {
        const level = LEVELS.find((l) => l === u?.level);
        if (level !== undefined) this.#level = level;
      } else if (k === 'rule' && typeof u?.a === 'string') {
        if (u.d === null) this.#rules.delete(u.a);
        else if (u.d === 'allow' || u.d === 'confirm' || u.d === 'deny') this.#rules.set(u.a, u.d);
      }
    } else if (topic === 'surface') {
      const surface = (d as { surface?: SurfaceInfo } | undefined)?.surface;
      if (k === 'gone') this.#end('gone');
      else if (k === 'changed' && surface) this.#info = surface;
    } else if (topic === 'chat') {
      // Listeners get a message rebuilt from its checked fields, or nothing.
      const m: ChatMessage | undefined = chatMessage(d);
      if (m !== undefined) this.#events.emit('chat', m);
      return;
    }
    this.#events.emit(topic, d);
  }

  #end(why: string): void {
    if (this.#gone !== undefined) return;
    this.#gone = why;
    this.#c.forget(this);
  }

  async #call<R>(m: string, p: object = {}, timeoutMs?: number): Promise<R> {
    if (this.#gone !== undefined) throw new ReinsError('E_NOT_ATTACHED', `surface ${this.#info.s} is not attached`);
    try {
      return await this.#c.request<R>(m, { s: this.#info.s, ...clean({ ...p }) }, timeoutMs);
    } catch (e) {
      if (e instanceof ReinsError && e.code === 'E_NOT_ATTACHED') this.#end('not attached');
      throw e;
    }
  }

  // ── observe ──

  observe(opts: { full?: boolean; boxes?: boolean } = {}): Promise<Observation> {
    return this.#serial(async () => (await this.#observe(opts)).o);
  }

  observeText(opts: { full?: boolean } = {}): Promise<string> {
    return this.#serial(async () => {
      const { o, prev } = await this.#observe(opts);
      return renderObservation(o, prev);
    });
  }

  #serial<T>(fn: () => Promise<T>): Promise<T> {
    const run = this.#queue.then(fn);
    this.#queue = run.catch(() => undefined);
    return run;
  }

  async #observe(opts: { full?: boolean; boxes?: boolean }): Promise<{ o: Observation; prev: UiNode[] | undefined }> {
    const boxes = opts.boxes === true;
    const since = !opts.full && this.#rev !== undefined && boxes === this.#boxes ? this.#rev : undefined;
    let o = await this.#call<Observation>('observe', { since, boxes: boxes ? true : undefined });
    if (o.ops !== undefined && (since === undefined || o.base !== since)) {
      // A delta we cannot apply: ask for a snapshot instead.
      o = await this.#call<Observation>('observe', { boxes: boxes ? true : undefined });
    }
    const before = this.#nodes;
    if (o.ops !== undefined) this.#nodes = applyOps(before, o.ops);
    else if (o.nodes !== undefined) this.#nodes = o.nodes;
    else throw new ReinsError('E_INTERNAL', 'observation carries neither nodes nor ops');
    this.#rev = o.rev;
    this.#boxes = boxes;
    return { o, prev: o.ops !== undefined ? before : undefined };
  }

  // ── reads ──

  async read(h?: Target, max?: number): Promise<string> {
    return (await this.readText(h, max)).text;
  }

  async readText(h?: Target, max?: number): Promise<{ text: string; truncated: boolean }> {
    const r = await this.#call<{ text: string; truncated?: boolean }>('read', { h, max });
    return { text: typeof r.text === 'string' ? r.text : '', truncated: r.truncated === true };
  }

  async state(name?: string): Promise<Record<string, unknown>> {
    return (await this.#call<{ state: Record<string, unknown> }>('state.get', { name })).state;
  }

  // ── commands ──

  async act<R = unknown>(action: string, args?: object): Promise<R> {
    const r = await this.#call<{ result?: unknown }>('act', { a: action, args }, this.#c.consentTimeoutMs);
    return r.result as R;
  }

  async click(h: Target): Promise<void> {
    await this.#call('ui.click', { h });
  }
  async type(h: Target, text: string, opts: { clear?: boolean; enter?: boolean } = {}): Promise<void> {
    await this.#call('ui.type', { h, text, clear: opts.clear, enter: opts.enter });
  }
  async select(h: Target, value: string): Promise<void> {
    await this.#call('ui.select', { h, value });
  }
  async scroll(opts: { h?: Target; dx?: number; dy?: number; to?: 'top' | 'bottom' | 'view' }): Promise<void> {
    await this.#call('ui.scroll', { h: opts.h, dx: opts.dx, dy: opts.dy, to: opts.to });
  }
  async key(key: UiKey, h?: Target): Promise<void> {
    await this.#call('ui.key', { key, h });
  }

  readonly cursor = {
    move: (to: Target | Point, opts: { ms?: number; wait?: boolean } = {}): Promise<Point> => this.#call<Point>('cursor.move', { to, ms: opts.ms, wait: opts.wait }),
    show: async (label?: string, color?: string): Promise<void> => {
      await this.#call('cursor.set', { visible: true, label, color });
    },
    hide: async (): Promise<void> => {
      await this.#call('cursor.set', { visible: false });
    },
  };

  readonly show = {
    toast: async (text: string, kind?: ToastKind, ms?: number): Promise<void> => {
      await this.#call('show.toast', { text, kind, ms });
    },
    highlight: async (h: Target, label?: string, ms?: number): Promise<void> => {
      await this.#call('show.highlight', { h, label, ms });
    },
    view: async (view: string, data?: unknown): Promise<unknown> => (await this.#call<{ result?: unknown }>('show.view', { view, data })).result,
    clear: async (): Promise<void> => {
      await this.#call('show.clear', {});
    },
  };

  async go(url: string): Promise<void> {
    await this.#call('nav.go', { url });
  }

  readonly chat = {
    say: (text: string, opts: { to?: string } = {}): Promise<{ id: number }> => this.#call<{ id: number }>('chat.say', { text, to: opts.to }),
    read: (opts: { since?: number; max?: number } = {}): Promise<ChatReadResult> => this.#call<ChatReadResult>('chat.read', { since: opts.since, max: opts.max }),
    status: async (state: ChatState, note?: string): Promise<void> => {
      await this.#call('chat.status', { state, note });
    },
  };

  async pointer(): Promise<PointerStream> {
    const r = await this.#call<{ ch: number; credit: number }>('stream.open', { kind: 'pointer' });
    return this.#c.openStream(r.ch, r.credit);
  }

  async subscribe(topics: Topic[]): Promise<void> {
    await this.#call('sub', { topics });
  }

  on(event: Topic, fn: (d: any) => void): () => void {
    return this.#events.on(event, fn);
  }

  async detach(): Promise<void> {
    if (this.#gone !== undefined) return;
    try {
      await this.#c.request('surface.detach', { s: this.#info.s });
    } finally {
      this.#end('detached');
    }
  }
}
