/** Version of this hub implementation, sent in `challenge.hub.ver` and `hub.info`. */
export const HUB_VERSION = '0.1.0';

/** Shortest agent, surface or audit key the broker accepts, in characters. */
export const MIN_KEY_CHARS = 32;

export interface AgentCredential {
  kid: string;
  /** The shared secret, at least 32 characters. Never logged, never sent. */
  key: string;
  /** Display name shown to the user (consent prompt, indicator). Overrides the name the agent declares. */
  name?: string;
  /** Cap on the scopes this agent may hold. */
  scopes?: Scope[];
  /** Browser origins this agent may connect from. Without it, browser-origin connections are refused. */
  origins?: string[];
  /** Surface origin patterns this agent may attach to, and hear about. Without it, any admitted surface. */
  surfaces?: string[];
  /** Concurrent sessions allowed for this credential. Default 4. */
  maxSessions?: number;
}

/**
 * Validated by the constructor, which throws a TypeError on anything malformed: a
 * mistyped restriction never means "any".
 */
export interface BrokerConfig {
  name?: string;
  agents: AgentCredential[];
  /**
   * `keys`: surface key by app id. A surface claiming an app id that has a key must prove
   * it, with or without `requireKey`; `requireKey` refuses every surface without a key.
   */
  surfaces: { origins: string[]; requireKey?: boolean; keys?: Record<string, string>; pins?: Record<string, string> };
  policy?: PolicyInput;
  limits?: Partial<Limits>;
  audit?: AuditSink;
  /** Key the audit chain: each record's hash is HMAC-SHA256 under this key (at least 32 characters). */
  auditKey?: string;
  maxSurfaces?: number;
  maxAgents?: number;
  maxStreams?: number;
  /**
   * Surface connections admitted per origin: a token bucket, `rate` per second (default 2)
   * holding at most `burst` (default 2 x `maxSurfaces`, so 128: a full set of tabs can
   * reconnect at once after a hub restart, and again). Every attempt from an allowed origin
   * while the hub has room takes a token; without one the connection is refused with
   * `E_RATE`. A full hub refuses with `E_BUSY` first. All origins together get 5 x `rate`
   * and 2 x `burst`.
   */
  surfaceAdmission?: { rate?: number; burst?: number };
  /** Agent sessions admitted per credential, after a good proof: default 2 a second, burst 20. */
  agentAdmission?: { rate?: number; burst?: number };
  now?: () => number;
}

export interface LinkMeta {
  /** The connection's Origin header, or the embedding page's origin for in-page links. */
  origin?: string;
  remote?: string;
  /**
   * The only role this link may take; a `hello` with the other one is refused with
   * `E_ORIGIN`. A hub that links its surfaces in-process accepts its socket with `agent`.
   */
  role?: Role;
  /**
   * The code that built this link vouches for what is at its far end: the page of `origin`
   * that it linked itself (an Electron main process and a window it registered; a command
   * and a page it adopted). Nothing else can be there, so a surface on such a link is
   * listed as `verified`, as one that proved a key is. Never set for a socket.
   */
  vouched?: boolean;
}

// ───────────────────────────── constants ─────────────────────────────

const HANDSHAKE_MS = 5_000;
/** Failed proofs within this window make the next failure answer slower. */
const FAIL_WINDOW_MS = 60_000;
const FAIL_DELAY_MS = 200;
const FAIL_DELAY_MAX_MS = 3_000;
/** Handshakes pending or waiting out a failure delay, at most. */
const MAX_HANDSHAKES = 16;
const DEFAULT_MAX_SESSIONS = 4;
/** `surface.attach`: per credential and surface, a burst of 3 refilling one every 2 s. */
const ATTACH_RATE = 0.5;
const ATTACH_BURST = 3;
/** Droppable pointer frames are dropped while the surface's send buffer holds more than this. */
const DROP_BUFFER_BYTES = 256 * 1024;
/** A pointer stream whose surface send buffer passes this is closed as an overrun. */
const STALL_BUFFER_BYTES = 1024 * 1024;
/**
 * Any peer, agent or surface, whose send buffer passes this (or 4 text frames, if more)
 * after a send is not reading: it is sent `bye {code:"E_BUSY"}` and closed.
 */
const PEER_BUFFER_MAX_BYTES = 8 * 1024 * 1024;
/** A connection that has not authenticated has at most this much held in its inbound queue. */
const PREAUTH_MESSAGES = 16;
const PREAUTH_BYTES = 64 * 1024;
/** `hub.info` and `surfaces.list` together, per credential: a burst of 20 refilling 10 a second. */
const HUB_METHOD_RATE = 10;
const HUB_METHOD_BURST = 20;
/**
 * Admission defaults. Per surface origin (`surfaceAdmission`): 2 a second, with a burst of
 * 2 x `maxSurfaces` (so every tab can reconnect at once after a hub restart). Surfaces from
 * all origins together: 5 times the rate, twice the burst. Per agent credential
 * (`agentAdmission`): 2 a second, burst 20.
 */
const SURFACE_ADMIT_RATE = 2;
const AGENT_ADMIT_RATE = 2;
const AGENT_ADMIT_BURST = 20;
/** Origins and credentials tracked for the admission rate, at most. */
const MAX_ADMIT_KEYS = 1024;
/** More records than this waiting to be written: the audit is unavailable. */
const AUDIT_BACKLOG_MAX = 1_000;
/** Beyond this the queue takes no more records; they are counted and summarised as `lost`. */
const AUDIT_QUEUE_MAX = 10_000;
const AUDIT_RETRY_MS = 1_000;
/** Refusal records per second, per connection and for failed connections overall. */
const REFUSALS_PER_SEC = 20;
/**
 * Changes to what the person set (a level, a rule, the scopes) that one grant may report in
 * a second. A person does not make more; a grant whose surface reports more is ended.
 */
const PERSON_CHANGES_PER_SEC = 20;
/**
 * Chat messages of the person the hub relays to one agent: this many a second, after a burst.
 * A budget of its own for each agent that listens: nothing an agent sends uses it up.
 */
const PERSON_CHAT_RATE = 5;
const PERSON_CHAT_BURST = 10;
/** "Not delivered" notices a surface is sent in a second (`chat.undelivered`). */
const UNDELIVERED_PER_SEC = 20;
/** Senders one grant keeps a relay budget for before those that left are forgotten. */
const CHAT_SENDERS_MAX = 64;

/**
 * The params of `chat.say` as they are forwarded, and digested for the audit record: the text
 * as the room keeps it (trimmed) and `to`. Padding and any other param change neither what
 * is on record nor what is said. A text that is no chat text is left as it came, and refused.
 */
function chatSayParams(p: Record<string, unknown>): Record<string, unknown> {
  const text = chatText(p.text);
  if (text === undefined) return p;
  const out: Record<string, unknown> = { text };
  if (p.s !== undefined) out.s = p.s;
  if (p.to !== undefined) out.to = p.to;
  return out;
}
const MAX_TIMER_MS = 2_147_483_647;
const MAX_REASON_CHARS = 500;
const MAX_AGENT_NAME = 64;
const MAX_TITLE_CHARS = 200;
const MAX_URL_CHARS = 4096;
/** C0/C1 controls and the bidirectional overrides that could disguise a name. */
const NAME_STRIP = /[\p{Cc}‎‏‪-‮⁦-⁩]/gu;

type Timer = ReturnType<typeof setTimeout>;

function unref<T>(t: T): T {
  (t as { unref?: () => unknown }).unref?.();
  return t;
}

function fail(code: ErrorCode, msg: string): never {
  throw new ReinsError(code, msg);
}

function hasOwn(o: object | undefined, k: string): boolean {
  return o !== undefined && Object.prototype.hasOwnProperty.call(o, k);
}

function isObject(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

function noop(): void {}

function isStringArray(v: unknown): v is string[] {
  return Array.isArray(v) && v.every((x) => typeof x === 'string');
}

function isPositiveInt(v: unknown): v is number {
  return typeof v === 'number' && Number.isSafeInteger(v) && v > 0;
}

/**
 * Methods whose every call is audited, besides refusals. `cursor.*`, `show.clear`, `chat.read`,
 * `chat.status` and pointer frames are not.
 */
function audited(m: string): boolean {
  return (
    m === 'act' ||
    m === 'show.view' ||
    m === 'show.toast' ||
    m === 'show.highlight' ||
    m === 'stream.open' ||
    m === 'chat.say' ||
    m.startsWith('ui.') ||
    m.startsWith('nav.')
  );
}

/**
 * The scope a grant needs for its holder to hear each topic a surface emits:
 *
 *   ui       observe   (the tree changed: a page-content signal)
 *   state    observe   (app state patches)
 *   nav      observe   (full URL and title)
 *   user     any live grant  (pause / resume / override: tells the agent to stand back);
 *            `level` and `rule` are checked, audited and go to the one agent they name
 *   grant    by kind: `revoked` from a surface ends grants at the hub, `scopes` narrows or
 *            restores one grant and is told to its agent; any other kind is dropped
 *   surface  never accepted from a surface: the hub alone sends it
 *   chat     chat    (a message of the page's room). Never broadcast: it goes to the one grant
 *            its `ag` names, checked and rebuilt by `#chatEvent`
 */
const TOPIC_SCOPE: Readonly<Record<string, Scope | null>> = { ui: 'observe', state: 'observe', nav: 'observe', user: null, chat: 'chat' };

/** Methods the hub answers itself. */
const HUB_METHOD_NAMES: ReadonlySet<string> = new Set(['hub.info', 'surfaces.list', 'surface.attach', 'surface.detach', 'stream.open', 'stream.close']);

/** At most `max` characters (code points) with control characters removed. */
function cleanName(name: string, max: number): string {
  return Array.from(name.replace(NAME_STRIP, '')).slice(0, max).join('');
}

/**
 * Counts refusals in one-second windows. Beyond the limit they are only counted; once a
 * full second passes without one, `summary` is called with the count.
 */
class RefusalLimiter {
  #windowStart = Number.NEGATIVE_INFINITY;
  #inWindow = 0;
  #suppressed = 0;
  #sinceTick = 0;
  #timer: Timer | undefined;

  constructor(
    readonly now: () => number,
    readonly summary: (count: number) => void,
  ) {}

  /** May this refusal be recorded? */
  allow(): boolean {
    const t = this.now();
    if (t - this.#windowStart >= 1000 || t < this.#windowStart) {
      this.#windowStart = t;
      this.#inWindow = 0;
    }
    if (this.#inWindow < REFUSALS_PER_SEC) {
      this.#inWindow++;
      return true;
    }
    this.#suppressed++;
    this.#sinceTick++;
    if (this.#timer === undefined) this.#arm();
    return false;
  }

  #arm(): void {
    this.#timer = unref(
      setTimeout(() => {
        this.#timer = undefined;
        if (this.#sinceTick > 0) {
          this.#sinceTick = 0;
          this.#arm();
        } else this.flush();
      }, 1000),
    );
  }

  /** Write the summary now, if anything was suppressed. */
  flush(): void {
    if (this.#timer !== undefined) clearTimeout(this.#timer);
    this.#timer = undefined;
    const n = this.#suppressed;
    this.#suppressed = 0;
    this.#sinceTick = 0;
    if (n > 0) this.summary(n);
  }
}

// ───────────────────────────── internal records ─────────────────────────────

interface Conn {
  readonly id: string;
  peer: Peer;
  lastPing: number;
}

interface AgentConn extends Conn {
  readonly role: 'agent';
  readonly name: string;
  readonly cred: AgentCredential;
  /** By surface id. */
  readonly grants: Map<string, GrantRec>;
  /** By channel. */
  readonly streams: Map<number, StreamRec>;
  /** Surface ids this session's attach request was sent to and has no answer from yet. */
  readonly attaching: Set<string>;
  readonly refusals: RefusalLimiter;
}

interface SurfaceConn extends Conn {
  readonly role: 'surface';
  readonly origin: string;
  url: string;
  title: string;
  readonly manifest: Manifest;
  readonly digest: string;
  /** The surface proved the key the hub holds for its app id. */
  readonly verified: boolean;
  readonly actions: Map<string, ActionDef>;
  /** By agent id. */
  readonly grants: Map<string, GrantRec>;
  /** Bounds the `person` audit records one surface can cause. */
  readonly person: RefusalLimiter;
  /** Bounds the records of relays of one agent's words to another that the hub dropped. */
  readonly chat: RefusalLimiter;
  /** Bounds the `chat.undelivered` notices this surface is sent. */
  readonly undelivered: TokenBucket;
}

interface GrantRec {
  readonly id: string;
  readonly agent: AgentConn;
  readonly surface: SurfaceConn;
  /** The scopes in force: `granted`, without those the person switched off on the page. */
  scopes: Scope[];
  /** The scopes granted at attach. A surface's report never widens the grant beyond them. */
  readonly granted: readonly Scope[];
  /** The level the surface last reported for this grant. A new grant starts at `ask`. */
  level: Level;
  /** The person's rules the surface reported and this hub took, by action name. A new grant has none. */
  readonly rules: Map<string, 'allow' | 'confirm' | 'deny'>;
  /** Changes reported in the one-second window that began at `changesAt` (PERSON_CHANGES_PER_SEC). */
  changes: number;
  changesAt: number;
  /**
   * The surface reported that the person lets this agent hear, and be heard by, the other
   * agents they switched on in the chat. Read where this hub's `chatRelay` is `person`.
   */
  relay: boolean;
  /** What this hub still relays to this agent: of the person's messages, and of each other agent's, by its id. */
  chatPerson?: TokenBucket;
  readonly chatIn: Map<string, TokenBucket>;
  readonly exp: number;
  used: number;
  timer?: Timer;
}

interface StreamRec {
  readonly ch: number;
  readonly agent: AgentConn;
  readonly surface: SurfaceConn;
  readonly credit: CreditWindow;
  ready: boolean;
  /** Closed by the hub for exceeding its rate or credit; kept until the agent closes it. */
  overrun: boolean;
}

interface Handshake {
  readonly link: Link;
  timer: Timer | undefined;
  delay: Timer | undefined;
  finish(): void;
  /** Set while the session is being confirmed: drop it without a clear-text bye. */
  abort?: () => void;
}

/**
 * `level`: the surface reported a level that this hub's policy does not offer. `reports`:
 * it reported more changes in a second than a person makes. `audit`: it reported a change
 * that lets the agent do or hear more while the audit log could not be written.
 */
type GrantEnd = 'agent' | 'surface' | 'expired' | 'idle' | 'revoked' | 'replaced' | 'hub' | 'level' | 'reports' | 'audit';

type Admitted =
  | { ok: true; role: 'agent'; cred: AgentCredential; proof: string }
  | { ok: true; role: 'surface'; manifest: Manifest; digest: string; url: string; title: string; origin: string; proof?: string; key?: string }
  | { ok: false; code: ErrorCode; msg: string; badProof?: true };

interface AuditInput {
  kind: AuditKind;
  outcome: string;
  agent?: string;
  surface?: string;
  role?: Role;
  origin?: string;
  kid?: string;
  method?: string;
  action?: string;
  value?: string;
  chars?: number;
  ms?: number;
  ref?: number;
  count?: number;
}

interface QueuedRecord {
  readonly rec: Record<string, unknown>;
  /** Canonical JSON of the request params, digested into `args` when the record is hashed. */
  readonly args?: string;
  hashed: boolean;
  done?: { resolve(): void; reject(e: unknown): void };
}

/** Per request: the canonical JSON of its params, and the `seq` of its `accepted` audit record once written. */
interface ReqCtx {
  args: string;
  accepted?: number;
}

// ───────────────────────────── broker ─────────────────────────────

export class Broker {
  readonly #name: string;
  readonly #creds = new Map<string, AgentCredential>();
  readonly #surfaceCfg: BrokerConfig['surfaces'];
  readonly #policy: Policy;
  readonly #limits: Limits;
  readonly #sink: AuditSink | undefined;
  readonly #auditKey: string | undefined;
  readonly #maxSurfaces: number;
  readonly #maxAgents: number;
  readonly #maxStreams: number;
  readonly #now: () => number;
  /** Stands in for the key of an unknown kid, so that path costs the same HMAC. */
  readonly #dummyKey = randomToken(32);

  readonly #agents = new Map<string, AgentConn>();
  readonly #surfaces = new Map<string, SurfaceConn>();
  readonly #streams = new Map<number, StreamRec>();
  readonly #handshakes = new Set<Handshake>();
  /**
   * Rate buckets by `${kid}\n${surface}|${scope}` (scope also `attach` and `pointer`), and
   * `${kid}\n|hub` for hub methods: shared by every session of a credential.
   */
  readonly #buckets = new Map<string, TokenBucket>();
  /** `${kid}\n${surface}` with an attach in flight, held until the surface answers. */
  readonly #attaching = new Set<string>();
  /** Admission buckets by `o\n${origin}` (surfaces) and `k\n${kid}` (agents). */
  readonly #admits = new Map<string, { bucket: TokenBucket; last: number }>();
  readonly #surfaceAdmits: TokenBucket;
  readonly #surfaceAdmit: { rate: number; burst: number };
  readonly #agentAdmit: { rate: number; burst: number };
  readonly #peerOpts: { limits: Limits; now: () => number; maxBuffered: number };
  #agentSeq = 0;
  #surfaceSeq = 0;
  #grantSeq = 0;
  #chSeq = 0;
  /** Times of recent failed proofs, for the failure delay. */
  #failures: number[] = [];
  #closed = false;
  #heartbeat: ReturnType<typeof setInterval> | undefined;

  #auditSeq = 0;
  #auditPrev = '';
  #auditHead: AuditHead | undefined;
  readonly #auditQueue: QueuedRecord[] = [];
  #auditDraining: Promise<void> | undefined;
  /** The sink threw and the record at the head of the queue is not written yet. */
  #auditFailed = false;
  #auditRetry: Timer | undefined;
  #auditLost = 0;
  readonly #connRefusals: RefusalLimiter;

  constructor(config: BrokerConfig) {
    if (!isObject(config)) throw new TypeError('broker config must be an object');
    if (!Array.isArray(config.agents)) throw new TypeError('config.agents must be an array');
    for (const c of config.agents) {
      if (!isObject(c) || typeof c.kid !== 'string' || c.kid === '' || c.kid.includes('\n')) throw new TypeError('agent credential needs a kid');
      const who = `agent credential ${c.kid.slice(0, 64)}`;
      if (typeof c.key !== 'string' || c.key.length === 0) throw new TypeError(`${who} needs a key`);
      if (c.key.length < MIN_KEY_CHARS) throw new TypeError(`${who}: key must be at least ${MIN_KEY_CHARS} characters`);
      if (c.maxSessions !== undefined && !isPositiveInt(c.maxSessions)) throw new TypeError(`${who}: maxSessions must be a positive integer`);
      if (c.name !== undefined && typeof c.name !== 'string') throw new TypeError(`${who}: name must be a string`);
      if (c.scopes !== undefined && !(Array.isArray(c.scopes) && c.scopes.every((x) => (SCOPES as readonly unknown[]).includes(x)))) {
        throw new TypeError(`${who}: scopes must be a list of known scopes (${SCOPES.join(', ')})`);
      }
      // Present but not a list of strings is an error, never "any".
      if (c.origins !== undefined && !isStringArray(c.origins)) throw new TypeError(`${who}: origins must be a list of origin strings`);
      if (c.surfaces !== undefined && !isStringArray(c.surfaces)) throw new TypeError(`${who}: surfaces must be a list of origin patterns`);
      if (this.#creds.has(c.kid)) throw new TypeError(`duplicate agent kid ${c.kid.slice(0, 64)}`);
      const copy: AgentCredential = { ...c };
      if (c.scopes !== undefined) copy.scopes = [...c.scopes];
      if (c.origins !== undefined) copy.origins = [...c.origins];
      if (c.surfaces !== undefined) copy.surfaces = [...c.surfaces];
      this.#creds.set(c.kid, copy);
    }
    if (!isObject(config.surfaces) || !isStringArray(config.surfaces.origins)) throw new TypeError('config.surfaces.origins must be a list of origin patterns');
    const sc = config.surfaces;
    if (sc.requireKey !== undefined && typeof sc.requireKey !== 'boolean') throw new TypeError('surfaces.requireKey must be true or false');
    if (sc.keys !== undefined && !isObject(sc.keys)) throw new TypeError('surfaces.keys must be an object of app id to key');
    if (sc.pins !== undefined && !(isObject(sc.pins) && Object.values(sc.pins).every((x) => typeof x === 'string'))) {
      throw new TypeError('surfaces.pins must be an object of app id to manifest digest');
    }
    const keys = { ...(sc.keys ?? {}) };
    for (const [id, k] of Object.entries(keys)) {
      if (typeof k !== 'string' || k.length < MIN_KEY_CHARS) throw new TypeError(`surface key for ${id.slice(0, 64)} must be a string of at least ${MIN_KEY_CHARS} characters`);
    }
    this.#surfaceCfg = {
      origins: [...sc.origins],
      requireKey: sc.requireKey === true,
      keys,
      pins: { ...(sc.pins ?? {}) },
    };
    for (const k of ['maxSurfaces', 'maxAgents', 'maxStreams'] as const) {
      if (config[k] !== undefined && !isPositiveInt(config[k])) throw new TypeError(`${k} must be a positive integer`);
    }
    if (config.auditKey !== undefined && (typeof config.auditKey !== 'string' || config.auditKey.length < MIN_KEY_CHARS)) {
      throw new TypeError(`auditKey must be a string of at least ${MIN_KEY_CHARS} characters`);
    }
    this.#auditKey = config.auditKey;
    this.#name = typeof config.name === 'string' && config.name ? config.name : 'reins-hub';
    this.#policy = resolvePolicy(config.policy);
    this.#limits = { ...DEFAULT_LIMITS, ...(config.limits ?? {}) };
    for (const [k, v] of Object.entries(this.#limits)) {
      if (typeof v !== 'number' || !Number.isFinite(v) || v <= 0) throw new TypeError(`limits.${k} must be a positive number`);
    }
    this.#sink = config.audit;
    this.#maxSurfaces = config.maxSurfaces ?? 64;
    this.#maxAgents = config.maxAgents ?? 32;
    this.#maxStreams = config.maxStreams ?? 8;
    this.#now = config.now ?? Date.now;
    const admission = (k: 'surfaceAdmission' | 'agentAdmission', rate: number, burst: number): { rate: number; burst: number } => {
      const v = config[k];
      if (v === undefined) return { rate, burst };
      const num = (x: unknown) => x === undefined || (typeof x === 'number' && Number.isFinite(x) && x > 0);
      if (!isObject(v) || !num(v.rate) || !num(v.burst)) throw new TypeError(`${k} must be { rate?, burst? } with positive numbers`);
      return { rate: v.rate ?? rate, burst: v.burst ?? burst };
    };
    this.#surfaceAdmit = admission('surfaceAdmission', SURFACE_ADMIT_RATE, 2 * this.#maxSurfaces);
    this.#agentAdmit = admission('agentAdmission', AGENT_ADMIT_RATE, AGENT_ADMIT_BURST);
    this.#surfaceAdmits = new TokenBucket(5 * this.#surfaceAdmit.rate, 2 * this.#surfaceAdmit.burst, this.#now);
    this.#peerOpts = { limits: this.#limits, now: this.#now, maxBuffered: Math.max(PEER_BUFFER_MAX_BYTES, 4 * this.#limits.maxText) };
    const last = this.#sink?.last;
    if (last && Number.isSafeInteger(last.seq) && last.seq >= 0 && typeof last.hash === 'string') {
      this.#auditSeq = last.seq;
      this.#auditPrev = last.hash;
      if (last.seq > 0) this.#auditHead = { seq: last.seq, hash: last.hash };
    }
    this.#connRefusals = new RefusalLimiter(this.#now, (count) => this.#audit({ kind: 'connect', outcome: 'suppressed', count }));
    const hb = this.#limits.heartbeatMs;
    this.#heartbeat = unref(setInterval(() => this.#tick(), Math.max(10, Math.min(1000, Math.floor(hb / 4)))));
  }

  /** Totals, for the hub's owner. Agents get `#infoFor`. */
  info(): HubInfo {
    return {
      name: this.#name,
      ver: HUB_VERSION,
      v: [...SUPPORTED_VERSIONS],
      profile: this.#policy.profile,
      surfaces: this.#surfaces.size,
      agents: this.#agents.size,
    };
  }

  /**
   * `hub.info` as an agent sees it: `surfaces` counts only surfaces its credential may
   * attach to, and `agents` only the sessions of its own credential.
   */
  #infoFor(a: AgentConn): HubInfo {
    let surfaces = 0;
    for (const s of this.#surfaces.values()) if (this.#mayAttachTo(a, s)) surfaces++;
    return { ...this.info(), surfaces, agents: this.#sessionsOf(a.cred) };
  }

  /** Where the written audit chain ends, or undefined before the first record. */
  auditHead(): AuditHead | undefined {
    return this.#auditHead ? { ...this.#auditHead } : undefined;
  }

  /** Resolves once every queued audit record is written, or the sink is failing. */
  async flushAudit(): Promise<void> {
    for (let i = 0; i < 1000 && this.#auditQueue.length > 0 && !this.#auditFailed; i++) {
      await (this.#auditDraining ?? this.#drainAudit());
    }
  }

  /** Send `bye {code:"OK"}` to every peer, stop every timer, refuse new links. */
  close(): void {
    if (this.#closed) return;
    this.#closed = true;
    if (this.#heartbeat !== undefined) clearInterval(this.#heartbeat);
    this.#heartbeat = undefined;
    for (const h of [...this.#handshakes]) {
      if (h.abort) {
        // Being confirmed: the peer only accepts sealed frames now, so just drop it.
        h.abort();
        continue;
      }
      h.finish();
      this.#refuse(h.link, 'OK', 'hub shutting down');
    }
    this.#handshakes.clear();
    for (const a of [...this.#agents.values()]) a.peer.bye('OK', 'hub shutting down');
    for (const s of [...this.#surfaces.values()]) s.peer.bye('OK', 'hub shutting down');
    // Close handlers have run synchronously; clear anything they left.
    for (const a of this.#agents.values()) for (const g of a.grants.values()) clearTimeout(g.timer);
    this.#connRefusals.flush();
    if (this.#auditRetry !== undefined) clearTimeout(this.#auditRetry);
    this.#auditRetry = undefined;
  }

  // ───────────────────────────── handshake ─────────────────────────────

  accept(link: Link, meta: LinkMeta = {}): void {
    const origin = typeof meta.origin === 'string' ? meta.origin : undefined;
    const only = meta.role === 'agent' || meta.role === 'surface' ? meta.role : undefined;
    const vouched = meta.vouched === true;
    if (this.#closed) {
      this.#refuse(link, 'E_BUSY', 'hub is shutting down');
      return;
    }
    if (this.#handshakes.size >= MAX_HANDSHAKES) {
      this.#refuse(link, 'E_BUSY', 'too many pending handshakes');
      this.#auditConnFailure({ kind: 'connect', outcome: 'E_BUSY', origin });
      return;
    }
    // Until it has authenticated, a connection gets only a small inbound queue.
    link.limitInbound?.(PREAUTH_MESSAGES, PREAUTH_BYTES);
    const nonce = randomToken(32);
    // Kept as sent: the seal keys are bound to these exact bytes.
    const challengeText = encodeFrame({ t: 'challenge', v: [...SUPPORTED_VERSIONS], nonce, hub: { name: this.#name, ver: HUB_VERSION } });
    let done = false;
    /** Give up the handshake slot and its timers, leaving the link's handlers alone. */
    const release = () => {
      done = true;
      clearTimeout(entry.timer);
      clearTimeout(entry.delay);
      this.#handshakes.delete(entry);
    };
    const entry: Handshake = {
      link,
      timer: undefined,
      delay: undefined,
      finish: () => {
        release();
        link.onmessage = null;
        link.onclose = null;
      },
    };
    const refuse = (code: ErrorCode, msg: string, role?: Role, kid?: string): void => {
      if (done) return;
      entry.finish();
      this.#refuse(link, code, msg);
      this.#auditConnFailure({ kind: 'connect', outcome: code, role, origin, kid });
    };
    entry.timer = unref(setTimeout(() => refuse('E_TIMEOUT', 'handshake timed out'), HANDSHAKE_MS));
    this.#handshakes.add(entry);
    link.onclose = () => {
      // A connection waiting out a failure delay keeps its slot until the delay is over.
      if (!done && entry.delay === undefined) entry.finish();
    };
    link.onmessage = (data) => {
      // Hold anything after `hello` in the link's queue until the Peer takes over.
      link.onmessage = null;
      if (typeof data !== 'string') return refuse('E_BAD_FRAME', 'expected hello');
      let f: Frame;
      try {
        f = decodeFrame(data, this.#limits.maxText);
      } catch (e) {
        const code = e instanceof ReinsError && e.code === 'E_TOO_LARGE' ? 'E_TOO_LARGE' : 'E_BAD_FRAME';
        return refuse(code, code === 'E_TOO_LARGE' ? 'frame too large' : 'malformed frame');
      }
      if (f.t !== 'hello') return refuse('E_BAD_FRAME', 'expected hello');
      const hello = f;
      const kid = hello.role === 'agent' && hello.auth ? hello.auth.kid.slice(0, 64) : undefined;
      // Whoever accepted this link bound it to one role: where it comes from does not take the other.
      if (only !== undefined && hello.role !== only) return refuse('E_ORIGIN', `this connection does not take the ${hello.role === 'surface' ? 'surface' : 'agent'} role`, hello.role, kid);
      if (!SUPPORTED_VERSIONS.includes(hello.v)) return refuse('E_VERSION', 'no common protocol version', hello.role, kid);
      // From here the answer may wait out a failure delay: give it room.
      clearTimeout(entry.timer);
      entry.timer = unref(setTimeout(() => refuse('E_TIMEOUT', 'handshake timed out'), HANDSHAKE_MS + FAIL_DELAY_MAX_MS));
      this.#admit(hello, nonce, origin).then(
        (r) => {
          if (done) return;
          if (this.#closed) return refuse('E_BUSY', 'hub is shutting down', hello.role, kid);
          if (!r.ok) {
            if (!r.badProof) return refuse(r.code, r.msg, hello.role, kid);
            // A failed proof is answered late, and holds its handshake slot until then. Nothing
            // it sends from here on is kept: drop what is queued and whatever comes next.
            link.onmessage = noop;
            entry.delay = unref(setTimeout(() => refuse(r.code, r.msg, hello.role, kid), this.#failureDelay()));
            return;
          }
          const full = this.#capacityRefusal(r);
          if (full) return refuse('E_BUSY', full, r.role, kid);
          const key = r.role === 'agent' ? r.cred.key : r.key;
          if (key === undefined) {
            // A surface without a key: unsealed, admitted at once.
            entry.finish();
            if (!link.open) return;
            link.limitInbound?.();
            const id = `s${++this.#surfaceSeq}`;
            this.#welcome(link, hello.v, id, 'surface', undefined);
            this.#addSurface(link, r as Extract<Admitted, { role: 'surface' }>, id, vouched);
            return;
          }
          // Keyed: `welcome` in clear, then seal and confirm. Nothing from `hello` is acted on
          // until the peer has shown it saw the same `hello` and `welcome`; the slot stays held.
          if (!link.open) return entry.finish();
          clearTimeout(entry.timer);
          clearTimeout(entry.delay);
          link.onclose = null;
          const id = r.role === 'agent' ? `a${++this.#agentSeq}` : `s${++this.#surfaceSeq}`;
          const welcomeText = this.#welcome(link, hello.v, id, r.role, r.proof);
          entry.abort = () => {
            release();
            link.close();
          };
          hubSeal(link, { key, nonce, cnonce: hello.cnonce, challengeText, helloText: data, welcomeText }).then(
            (sealed) => {
              if (done) return sealed.close();
              release();
              // Confirmed: the raw link feeds the sealed one, which has the normal bound.
              link.limitInbound?.();
              if (this.#closed) return this.#refuse(sealed, 'OK', 'hub shutting down');
              // Capacity may have filled while this session was being confirmed.
              const late = this.#capacityRefusal(r);
              if (late) {
                this.#refuse(sealed, 'E_BUSY', late);
                this.#auditConnFailure({ kind: 'connect', outcome: 'E_BUSY', role: r.role, origin, kid });
                return;
              }
              if (r.role === 'agent') this.#addAgent(sealed, hello, r.cred, id, origin);
              else this.#addSurface(sealed, r, id, vouched);
            },
            () => {
              if (done) return;
              release();
              this.#auditConnFailure({ kind: 'connect', outcome: 'E_AUTH', role: r.role, origin, kid });
            },
          );
        },
        () => refuse('E_INTERNAL', 'handshake failed', hello.role, kid),
      );
    };
    try {
      link.send(challengeText);
    } catch {
      refuse('E_GONE', 'connection closed');
    }
  }

  /** Why admitting `r` now would exceed a capacity, or undefined. */
  #capacityRefusal(r: Extract<Admitted, { ok: true }>): string | undefined {
    if (r.role === 'agent') {
      if (this.#agents.size >= this.#maxAgents) return 'too many agents';
      if (this.#sessionsOf(r.cred) >= (r.cred.maxSessions ?? DEFAULT_MAX_SESSIONS)) return 'too many sessions for this credential';
      return undefined;
    }
    return this.#surfaces.size >= this.#maxSurfaces ? 'too many surfaces' : undefined;
  }

  #refuse(link: Link, code: ErrorCode | 'OK', msg: string): void {
    try {
      if (link.open) link.send(encodeFrame({ t: 'bye', code, msg }));
    } catch {
      // ignore
    }
    link.close();
  }

  #sessionsOf(cred: AgentCredential): number {
    let n = 0;
    for (const a of this.#agents.values()) if (a.cred.kid === cred.kid) n++;
    return n;
  }

  /** Count a failed proof and say how long to wait before answering it. */
  #failureDelay(): number {
    const now = this.#now();
    this.#failures = this.#failures.filter((t) => now - t < FAIL_WINDOW_MS && t <= now);
    this.#failures.push(now);
    if (this.#failures.length > 64) this.#failures.splice(0, this.#failures.length - 64);
    const n = this.#failures.length;
    return Math.min(FAIL_DELAY_MAX_MS, FAIL_DELAY_MS * 2 ** Math.min(n - 1, 16));
  }

  /** Take an admission token for `key`: `o\n<origin>` for a surface, `k\n<kid>` for an agent. */
  #admitAllowed(key: string): boolean {
    const now = this.#now();
    let e = this.#admits.get(key);
    if (e === undefined) {
      if (this.#admits.size >= MAX_ADMIT_KEYS) {
        // Forget buckets that have had time to refill: they hold no state worth keeping.
        const full = Math.max(this.#surfaceAdmit.burst / this.#surfaceAdmit.rate, this.#agentAdmit.burst / this.#agentAdmit.rate) * 1000;
        for (const [k, v] of this.#admits) if (now - v.last >= full || v.last > now) this.#admits.delete(k);
        if (this.#admits.size >= MAX_ADMIT_KEYS) return false;
      }
      const cfg = key.startsWith('o\n') ? this.#surfaceAdmit : this.#agentAdmit;
      e = { bucket: new TokenBucket(cfg.rate, cfg.burst, this.#now), last: now };
      this.#admits.set(key, e);
    }
    e.last = now;
    return e.bucket.take();
  }

  /** Compute the expected peer proof; null when the fields are unusable. */
  async #expectedProof(key: string, role: Role, kid: string, nonce: string, cnonce: string): Promise<string | null> {
    try {
      return await peerProof(key, { role, kid, nonce, cnonce });
    } catch {
      return null;
    }
  }

  async #admit(f: HelloFrame, nonce: string, origin: string | undefined): Promise<Admitted> {
    if (f.role === 'agent') {
      if (!f.auth) return { ok: false, code: 'E_AUTH', msg: 'authentication required', badProof: true };
      const cred = this.#creds.get(f.auth.kid);
      const expected = await this.#expectedProof(cred ? cred.key : this.#dummyKey, 'agent', f.auth.kid, nonce, f.cnonce);
      const match = expected !== null && timingSafeEqual(f.auth.proof, expected);
      if (!cred || !match) return { ok: false, code: 'E_AUTH', msg: 'authentication failed', badProof: true };
      if (origin !== undefined && !(Array.isArray(cred.origins) && originAllowed(origin, cred.origins))) {
        return { ok: false, code: 'E_ORIGIN', msg: 'origin not allowed for this agent' };
      }
      if (!this.#admitAllowed(`k\n${cred.kid}`)) return { ok: false, code: 'E_RATE', msg: 'too many connections for this credential' };
      const proof = await hubProof(cred.key, { role: 'agent', kid: f.auth.kid, nonce, cnonce: f.cnonce });
      return { ok: true, role: 'agent', cred, proof };
    }

    // Surface.
    if (origin === undefined || !originAllowed(origin, this.#surfaceCfg.origins)) return { ok: false, code: 'E_ORIGIN', msg: 'origin not allowed' };
    // A full hub says so (E_BUSY) without spending an admission token.
    if (this.#surfaces.size >= this.#maxSurfaces) return { ok: false, code: 'E_BUSY', msg: 'too many surfaces' };
    // Every other attempt from an allowed origin counts, so connection churn is bounded per origin and overall.
    if (!this.#admitAllowed(`o\n${origin}`) || !this.#surfaceAdmits.take()) return { ok: false, code: 'E_RATE', msg: 'too many surface connections' };
    const sh = f.surface;
    if (!sh) return { ok: false, code: 'E_BAD_ARGS', msg: 'surface hello missing' };
    let url: URL;
    try {
      if (sh.url.length > MAX_URL_CHARS) throw new Error('long');
      url = new URL(sh.url);
    } catch {
      return { ok: false, code: 'E_BAD_ARGS', msg: 'invalid surface url' };
    }
    // Compared as SPEC 5 defines the origin of a URL, not as this engine's URL parser reports it:
    // for a file: or app-scheme page the parser says `null` in Node and something else in a page.
    if (!urlHasOrigin(sh.url, origin)) return { ok: false, code: 'E_ORIGIN', msg: 'surface url does not match origin' };
    let manifest: Manifest;
    try {
      manifest = validateManifest(sh.manifest);
    } catch (e) {
      if (e instanceof ReinsError) return { ok: false, code: e.code, msg: e.message.slice(0, 200) };
      return { ok: false, code: 'E_BAD_ARGS', msg: 'invalid manifest' };
    }
    let proof: string | undefined;
    let surfaceKey: string | undefined;
    const keys = this.#surfaceCfg.keys;
    // An app id the hub holds a key for must prove it, whether or not every surface must.
    if (this.#surfaceCfg.requireKey || f.auth || hasOwn(keys, manifest.app.id)) {
      if (!f.auth) return { ok: false, code: 'E_AUTH', msg: 'surface key required' };
      const kid = f.auth.kid;
      const key = kid === manifest.app.id && hasOwn(keys, kid) && typeof keys![kid] === 'string' ? keys![kid]! : undefined;
      const expected = await this.#expectedProof(key ?? this.#dummyKey, 'surface', kid, nonce, f.cnonce);
      const match = expected !== null && timingSafeEqual(f.auth.proof, expected);
      if (key === undefined || !match) return { ok: false, code: 'E_AUTH', msg: 'authentication failed', badProof: true };
      proof = await hubProof(key, { role: 'surface', kid, nonce, cnonce: f.cnonce });
      surfaceKey = key;
    }
    const digest = await manifestDigest(manifest);
    const pins = this.#surfaceCfg.pins;
    if (hasOwn(pins, manifest.app.id) && pins![manifest.app.id] !== digest) {
      return { ok: false, code: 'E_DENIED', msg: 'manifest does not match the pinned digest' };
    }
    const r: Admitted = { ok: true, role: 'surface', manifest, digest, url: url.href, title: sh.title.slice(0, MAX_TITLE_CHARS), origin };
    if (proof !== undefined) {
      r.proof = proof;
      r.key = surfaceKey;
    }
    return r;
  }

  /** Send `welcome` and return its text exactly as sent. */
  #welcome(link: Link, v: string, session: string, role: Role, proof: string | undefined): string {
    const w: WelcomeFrame = { t: 'welcome', v, session, role, limits: { ...this.#limits } };
    if (proof !== undefined) w.proof = proof;
    const text = encodeFrame(w);
    link.send(text);
    return text;
  }

  /** The name shown to the user: the credential's, else the declared one, cleaned. */
  #displayName(cred: AgentCredential, declared: unknown): string {
    if (typeof cred.name === 'string' && cred.name !== '') return cleanName(cred.name, MAX_AGENT_NAME);
    const name = typeof declared === 'string' ? cleanName(declared, MAX_AGENT_NAME) : '';
    return name !== '' ? name : cleanName(cred.kid, MAX_AGENT_NAME);
  }

  /** Register a confirmed agent session; `welcome` (with session `id`) has been sent. */
  #addAgent(link: Link, hello: HelloFrame, cred: AgentCredential, id: string, origin: string | undefined): void {
    const a: AgentConn = {
      id,
      role: 'agent',
      name: this.#displayName(cred, hello.name),
      cred,
      grants: new Map(),
      streams: new Map(),
      attaching: new Set(),
      refusals: new RefusalLimiter(this.#now, (count) => this.#audit({ kind: 'request', outcome: 'suppressed', agent: id, count })),
      lastPing: 0,
      peer: undefined as unknown as Peer,
    };
    this.#agents.set(id, a);
    a.peer = new Peer(
      link,
      {
        request: (m, p) => this.#agentRequest(a, m, p),
        binary: (bytes) => this.#agentBinary(a, bytes),
        close: (code) => this.#agentGone(a, code),
      },
      this.#peerOpts,
    );
    this.#audit({ kind: 'connect', outcome: 'ok', role: 'agent', agent: id, origin, kid: cred.kid.slice(0, 64) });
  }

  /** Register a surface session (confirmed when keyed); `welcome` (with session `id`) has been sent. */
  #addSurface(link: Link, r: Extract<Admitted, { role: 'surface' }>, id: string, vouched = false): void {
    const s: SurfaceConn = {
      id,
      role: 'surface',
      origin: r.origin,
      url: r.url,
      title: r.title,
      manifest: r.manifest,
      digest: r.digest,
      // It proved a key, or the code that linked it in-process vouches for it.
      verified: r.key !== undefined || vouched,
      actions: new Map(r.manifest.actions.map((x) => [x.name, x])),
      grants: new Map(),
      person: new RefusalLimiter(this.#now, (count) => this.#audit({ kind: 'person', outcome: 'suppressed', surface: id, count })),
      chat: new RefusalLimiter(this.#now, (count) => this.#audit({ kind: 'chat', outcome: 'suppressed', surface: id, method: 'relay', count })),
      undelivered: new TokenBucket(UNDELIVERED_PER_SEC, UNDELIVERED_PER_SEC, this.#now),
      lastPing: 0,
      peer: undefined as unknown as Peer,
    };
    this.#surfaces.set(id, s);
    s.peer = new Peer(
      link,
      {
        request: () => fail('E_UNKNOWN_METHOD', 'unknown method'),
        event: (f) => this.#surfaceEvent(s, f),
        flow: (f) => this.#surfaceFlow(s, f),
        close: (code) => this.#surfaceGone(s, code),
      },
      this.#peerOpts,
    );
    this.#audit({ kind: 'connect', outcome: 'ok', role: 'surface', surface: id, origin: r.origin });
    this.#broadcastSurface('added', s);
  }

  // ───────────────────────────── disconnects ─────────────────────────────

  #agentGone(a: AgentConn, code: string): void {
    if (this.#agents.get(a.id) !== a) return;
    this.#agents.delete(a.id);
    // Withdraw every attach still waiting at a surface (a consent prompt, typically).
    for (const sid of a.attaching) {
      const s = this.#surfaces.get(sid);
      if (s && !this.#closed && !s.peer.closed) s.peer.request('detach', { why: 'agent' }, { ag: a.id }).catch(noop);
    }
    a.attaching.clear();
    for (const g of [...a.grants.values()]) this.#endGrant(g, 'agent');
    for (const st of [...a.streams.values()]) this.#dropStream(st, true);
    a.refusals.flush();
    this.#audit({ kind: 'disconnect', outcome: code, role: 'agent', agent: a.id });
  }

  #surfaceGone(s: SurfaceConn, code: string): void {
    if (this.#surfaces.get(s.id) !== s) return;
    this.#surfaces.delete(s.id);
    for (const g of [...s.grants.values()]) this.#endGrant(g, 'surface');
    for (const st of [...this.#streams.values()]) if (st.surface === s) this.#dropStream(st, false);
    const mark = `\n${s.id}|`;
    for (const k of [...this.#buckets.keys()]) if (k.includes(mark)) this.#buckets.delete(k);
    s.person.flush();
    s.chat.flush();
    this.#audit({ kind: 'disconnect', outcome: code, role: 'surface', surface: s.id });
    if (!this.#closed) this.#broadcastSurface('gone', s);
  }

  // ───────────────────────────── surface info and events ─────────────────────────────

  /** May this agent's credential attach to (and so hear about) this surface? */
  #mayAttachTo(a: AgentConn, s: SurfaceConn): boolean {
    return !Array.isArray(a.cred.surfaces) || originAllowed(s.origin, a.cred.surfaces);
  }

  /** The agent's grant on `s` if it is live, without ending it when it is not. */
  #currentGrant(a: AgentConn, s: SurfaceConn): GrantRec | undefined {
    const g = a.grants.get(s.id);
    return g !== undefined && this.#expiry(g) === null && this.#surfaces.get(s.id) === s ? g : undefined;
  }

  /**
   * What an agent may know about a surface. The full URL and title only go to an agent
   * whose live grant includes `observe`; anyone else gets the origin and the app's name.
   */
  #surfaceInfo(s: SurfaceConn, a: AgentConn): SurfaceInfo {
    const g = this.#currentGrant(a, s);
    const full = g !== undefined && g.scopes.includes('observe');
    return {
      s: s.id,
      origin: s.origin,
      url: full ? s.url : s.origin,
      title: full ? s.title : s.manifest.app.name,
      app: { ...s.manifest.app },
      profile: s.manifest.profile,
      digest: s.digest,
      attached: g !== undefined,
      verified: s.verified,
    };
  }

  #broadcastSurface(kind: 'added' | 'gone' | 'changed', s: SurfaceConn): void {
    for (const a of this.#agents.values()) {
      if (!this.#mayAttachTo(a, s)) continue;
      if (kind === 'changed' && this.#currentGrant(a, s) === undefined) continue;
      try {
        a.peer.event('surface', { kind, surface: this.#surfaceInfo(s, a) });
      } catch {
        // a closed or oversize send must not stop the others
      }
    }
  }

  #surfaceEvent(s: SurfaceConn, f: EvtFrame): void {
    if (this.#surfaces.get(s.id) !== s) return;
    const topic = f.topic as string;
    if (topic === 'grant') {
      // What a surface says about a grant is acted on by kind, and never relayed as it came.
      const d = f.d;
      if (!isObject(d)) return;
      if (d.kind === 'revoked') {
        if (f.ag !== undefined) {
          const g = s.grants.get(f.ag);
          if (g) this.#endGrant(g, 'revoked');
        } else {
          // Stop without a named agent revokes every grant on this surface.
          for (const g of [...s.grants.values()]) this.#endGrant(g, 'revoked');
        }
      } else if (d.kind === 'scopes') this.#personScopes(s, f.ag, d.scopes);
      // Any other kind is dropped.
      return;
    }
    if (topic === 'user' && isObject(f.d) && f.d.kind === 'relay') {
      this.#personRelay(s, f.ag, f.d);
      return;
    }
    if (topic === 'user' && isObject(f.d) && (f.d.kind === 'level' || f.d.kind === 'rule')) {
      this.#personSetting(s, f.ag, f.d);
      return;
    }
    if (topic === 'chat') {
      this.#chatEvent(s, f);
      return;
    }
    if (!(TOPICS as readonly string[]).includes(topic) || !hasOwn(TOPIC_SCOPE, topic)) return;
    if (topic === 'nav' && !this.#applyNav(s, f.d)) return;
    // Only holders of a live grant with the scope this topic needs (TOPIC_SCOPE) hear it.
    const need = TOPIC_SCOPE[topic];
    const hears = (g: GrantRec | undefined): g is GrantRec => g !== undefined && this.#live(g) && (need === null || need === undefined || g.scopes.includes(need));
    let targets: AgentConn[];
    if (f.ag !== undefined) {
      const g = s.grants.get(f.ag);
      targets = hears(g) ? [g.agent] : [];
    } else {
      targets = [...s.grants.values()].filter(hears).map((g) => g.agent);
    }
    for (const a of targets) {
      try {
        a.peer.event(f.topic, f.d, { s: s.id });
      } catch {
        // oversize after adding `s`: drop for this agent
      }
    }
  }

  /** The live grant a surface event names with `ag`, or undefined. */
  #namedGrant(s: SurfaceConn, ag: string | undefined): GrantRec | undefined {
    const g = ag === undefined ? undefined : s.grants.get(ag);
    return g !== undefined && this.#live(g) ? g : undefined;
  }

  /**
   * A report that changes nothing this hub holds: one that repeats the value it has, or one
   * it does not take. Its record is bounded per surface: beyond the rate such records are
   * counted and summarised. No change of what the hub holds or relays goes through here.
   */
  #personNoted(g: GrantRec, outcome: 'ok' | 'refused', method: 'level' | 'rule' | 'scopes' | 'relay', value: string, action?: string): void {
    if (g.surface.person.allow()) this.#audit({ kind: 'person', outcome, agent: g.agent.id, surface: g.surface.id, method, value, action });
  }

  /**
   * A report that changes what this hub holds for the grant, and what it tells the agent: it
   * is always recorded, whatever else the surface sent in the same second. Returns false,
   * and ends the grant, when the grant reports more changes in a second than a person makes:
   * that one is recorded as refused and is neither kept nor relayed. `loosens`: the change
   * lets the agent do or hear more than before; such a change also ends the grant when the
   * audit log cannot be written.
   */
  #personChange(g: GrantRec, method: 'level' | 'rule' | 'scopes' | 'relay', value: string, loosens: boolean, action?: string): boolean {
    // Fail closed. A change that lets the agent do or hear more is in force on the surface
    // already; a hub that cannot put it on record does not let the grant go on under it. A
    // change that only tightens is taken: its record waits with the others.
    if (loosens && this.#auditUnavailable()) {
      this.#audit({ kind: 'person', outcome: 'refused', agent: g.agent.id, surface: g.surface.id, method, value, action });
      this.#endGrant(g, 'audit');
      return false;
    }
    const t = this.#now();
    if (t - g.changesAt >= 1000 || t < g.changesAt) {
      g.changesAt = t;
      g.changes = 0;
    }
    const ok = g.changes < PERSON_CHANGES_PER_SEC;
    this.#audit({ kind: 'person', outcome: ok ? 'ok' : 'refused', agent: g.agent.id, surface: g.surface.id, method, value, action });
    if (ok) g.changes++;
    else this.#endGrant(g, 'reports');
    return ok;
  }

  /**
   * A surface reports the level the person set for one grant, or a rule for one action
   * (`evt user {kind:"level"|"rule"}` with `ag`). Malformed reports are dropped.
   *
   *  - A level this hub's policy does not offer (`auto` or `bypass` that `human.levels` lacks)
   *    ends the grant: an honest surface was told the levels at attach and offers no other.
   *    `strict` and `ask` are always on offer.
   *  - A rule `allow` this hub's policy would not let waive anything (the hub denies the
   *    action, or wants it confirmed and offers no level that would waive that) is recorded as
   *    refused and neither kept nor relayed. The grant goes on: the hub still marks or refuses
   *    every request for that action itself.
   *  - A report that repeats what the hub holds changes nothing and is not relayed.
   *  - Anything else is a change: kept, always recorded, and told to that agent alone, in an
   *    event built from the checked values.
   */
  #personSetting(s: SurfaceConn, ag: string | undefined, d: Record<string, unknown>): void {
    const g = this.#namedGrant(s, ag);
    if (!g) return;
    const offered = capLevels(this.#policy.human.levels);
    let payload: Record<string, unknown>;
    if (d.kind === 'level') {
      const level = LEVELS.find((l) => l === d.level);
      if (level === undefined) return;
      if (!offered.includes(level)) {
        this.#audit({ kind: 'person', outcome: 'refused', agent: g.agent.id, surface: s.id, method: 'level', value: level });
        this.#endGrant(g, 'level');
        return;
      }
      if (g.level === level) return this.#personNoted(g, 'ok', 'level', level);
      if (!this.#personChange(g, 'level', level, LEVELS.indexOf(level) > LEVELS.indexOf(g.level))) return;
      g.level = level;
      payload = { kind: 'level', level };
    } else {
      const def = typeof d.a === 'string' ? s.actions.get(d.a) : undefined;
      const rule = d.d;
      if (!def || (rule !== null && rule !== 'allow' && rule !== 'confirm' && rule !== 'deny')) return;
      if (rule === 'allow') {
        const mine = decideAction(this.#policy, def);
        if (mine === 'deny' || (mine === 'confirm' && !allowRulePermitted(def.risk, offered))) return this.#personNoted(g, 'refused', 'rule', 'allow', def.name);
      }
      if ((g.rules.get(def.name) ?? null) === rule) return this.#personNoted(g, 'ok', 'rule', rule ?? 'none', def.name);
      // How much a rule holds an action back: `deny` most, then `confirm`, none, `allow`.
      const holds = (r: unknown): number => (r === 'deny' ? 2 : r === 'confirm' ? 1 : r === 'allow' ? -1 : 0);
      if (!this.#personChange(g, 'rule', rule ?? 'none', holds(rule) < holds(g.rules.get(def.name)), def.name)) return;
      if (rule === null) g.rules.delete(def.name);
      else g.rules.set(def.name, rule);
      payload = { kind: 'rule', a: def.name, d: rule };
    }
    try {
      g.agent.peer.event('user', payload, { s: s.id });
    } catch {
      // ignore
    }
  }

  /**
   * A surface reports that the person lets one agent hear, and be heard by, the other agents
   * they switched on in the chat, or no longer does (`evt user {kind:"relay"}` with `ag`).
   * A malformed report, and one for a grant that was never granted `chat`, is dropped.
   *
   *  - `on` under a hub policy that relays nothing (`chatRelay: "off"`), or for a grant whose
   *    `chat` scope is switched off, is recorded as refused and not kept. The grant goes on:
   *    the hub decides for itself what it relays, whatever a surface reports.
   *  - A report that repeats what the hub holds changes nothing and is not relayed.
   *  - Anything else is a change: kept, always recorded, and told to that agent alone, in an
   *    event built from the checked value.
   */
  #personRelay(s: SurfaceConn, ag: string | undefined, d: Record<string, unknown>): void {
    const g = this.#namedGrant(s, ag);
    if (!g || typeof d.on !== 'boolean' || !g.granted.includes('chat')) return;
    const on = d.on;
    if (on && (this.#policy.chatRelay === 'off' || !g.scopes.includes('chat'))) return this.#personNoted(g, 'refused', 'relay', 'on');
    if (g.relay === on) return this.#personNoted(g, 'ok', 'relay', on ? 'on' : 'off');
    if (!this.#personChange(g, 'relay', on ? 'on' : 'off', on)) return;
    g.relay = on;
    try {
      g.agent.peer.event('user', { kind: 'relay', on }, { s: s.id });
    } catch {
      // ignore
    }
  }

  /** Does this hub's policy let `listener` be sent what `sender` says: always under `on`, never under `off`, and under `person` when the person switched both on. */
  #hears(listener: GrantRec, sender: GrantRec): boolean {
    const mode = this.#policy.chatRelay;
    return mode === 'on' || (mode === 'person' && listener.relay && sender.relay);
  }

  /**
   * The budget of what this hub still relays to one grant from one sender. The person's
   * messages have their own, which nothing an agent sends uses up. An agent's words reach
   * another agent no faster than that agent's own `chat` rate lets it speak, with room for a
   * second's worth that arrives late: a surface that relays what `chat.say` let through is
   * never cut short, and one that sends more is.
   */
  #chatBudget(g: GrantRec, sender: GrantRec | undefined): TokenBucket {
    if (!sender) return (g.chatPerson ??= new TokenBucket(PERSON_CHAT_RATE, PERSON_CHAT_BURST, this.#now));
    const id = sender.agent.id;
    let b = g.chatIn.get(id);
    if (!b) {
      if (g.chatIn.size >= CHAT_SENDERS_MAX) for (const k of [...g.chatIn.keys()]) if (!g.surface.grants.has(k)) g.chatIn.delete(k);
      const rate = this.#policy.rates.chat;
      b = new TokenBucket(rate, rate * 2, this.#now);
      g.chatIn.set(id, b);
    }
    return b;
  }

  /**
   * A message of the person was not relayed to the agent it was for. The surface is told, so
   * that the page shows the message as not delivered to that agent (`chat.undelivered` with
   * `ag` and the message's id), and the hub puts it on record, without the text.
   */
  #chatUndelivered(s: SurfaceConn, g: GrantRec, m: ChatMessage, why: string): void {
    if (s.person.allow()) this.#audit({ kind: 'person', outcome: why, agent: g.agent.id, surface: s.id, method: 'chat', chars: m.text.length });
    if (!s.undelivered.take() || s.peer.closed) return;
    s.peer.request('chat.undelivered', { id: m.id }, { ag: g.agent.id }).catch(noop);
  }

  /**
   * A surface sends one message of its chat room to one agent (`evt chat` with `ag`). It is
   * relayed only to the grant it names, only while that grant is live and holds `chat`, and
   * only in an event rebuilt from the checked fields. Everything else is dropped:
   *
   *  - no `ag`, or an `ag` that names no live grant on this surface: a surface speaks to its
   *    own grants and to nobody else, and a chat message is never broadcast;
   *  - a message that is not well-shaped, or addressed (`to`) to anyone but that agent: one
   *    for another agent, and an agent's message for the person alone (`to: "person"`);
   *  - another agent's words when this hub's policy does not let this agent hear them
   *    (`chatRelay`: never under `off`, and under `person` only when the person switched both
   *    agents on), when their sender holds no live `chat` grant here, or when they would go
   *    back to their sender.
   *
   * The sender's name is the one this hub gave that agent, never the one in the event. What
   * the person said is on record as a `person` record with a digest and a length, never the
   * text, before it is relayed; where the audit log cannot take the record, the message is
   * not relayed. What an agent said was recorded when its `chat.say` passed.
   *
   * Each sender has its own budget for each agent that listens (`#chatBudget`). A message of
   * the person the hub does not relay is told to the surface (`#chatUndelivered`); a relay of
   * an agent's words beyond that agent's budget is dropped and counted in a `chat` record.
   */
  #chatEvent(s: SurfaceConn, f: EvtFrame): void {
    const g = this.#namedGrant(s, f.ag);
    if (!g || !g.scopes.includes('chat')) return;
    const m = chatMessage(f.d);
    if (!m) return;
    if (m.to !== undefined && m.to !== g.agent.id) return;
    const d: ChatMessage = { id: m.id, from: { kind: 'person' }, text: m.text, ts: m.ts };
    if (m.to !== undefined) d.to = m.to;
    if (m.from.kind === 'agent') {
      const sender = this.#namedGrant(s, m.from.id);
      if (!sender || sender === g || !sender.scopes.includes('chat')) return;
      if (!this.#hears(g, sender)) {
        // The surface relays what this hub's policy does not let this agent hear: not sent,
        // and on record, within the same bound as relays dropped for their budget.
        if (s.chat.allow()) this.#audit({ kind: 'chat', outcome: 'refused', agent: sender.agent.id, surface: s.id, method: 'relay' });
        return;
      }
      // Fails closed, like the person's own message below: nothing is relayed that could not be put on record.
      if (this.#auditUnavailable()) return;
      if (!this.#chatBudget(g, sender).take()) {
        if (s.chat.allow()) this.#audit({ kind: 'chat', outcome: 'dropped', agent: sender.agent.id, surface: s.id, method: 'relay' });
        return;
      }
      d.from = { kind: 'agent', id: sender.agent.id, name: sender.agent.name };
    } else {
      if (!this.#chatBudget(g, undefined).take()) return this.#chatUndelivered(s, g, m, 'E_RATE');
      // Fails closed, like an audited request: what cannot be put on record is not relayed.
      if (this.#auditUnavailable()) return this.#chatUndelivered(s, g, m, 'E_INTERNAL');
      // The same shape a `chat.say` request is digested in, so that one text gives one digest.
      const said: Record<string, unknown> = { text: m.text };
      if (m.to !== undefined) said.to = m.to;
      this.#audit({ kind: 'person', outcome: 'ok', agent: g.agent.id, surface: s.id, method: 'chat', chars: m.text.length }, canonicalJson(said));
    }
    try {
      g.agent.peer.event('chat', d, { s: s.id });
    } catch {
      // Too large once `s` was added: not sent. The person's message is shown as not delivered.
      if (d.from.kind === 'person') this.#chatUndelivered(s, g, m, 'E_TOO_LARGE');
    }
  }

  /**
   * A surface reports the scopes now in force for one grant (`evt grant {kind:"scopes"}`
   * with `ag`): the person switched some off, or back on. The grant then carries the
   * reported scopes that were granted at attach, never more. Without `cursor` the agent's
   * pointer streams on the surface are closed.
   */
  #personScopes(s: SurfaceConn, ag: string | undefined, list: unknown): void {
    const g = this.#namedGrant(s, ag);
    if (!g || !Array.isArray(list)) return;
    const a = g.agent;
    const scopes = capScopes(list.filter((x): x is Scope => typeof x === 'string'), [...g.granted]);
    const value = scopes.length > 0 ? scopes.join(' ') : 'none';
    // The scopes the grant already carries: nothing changes, and nothing is relayed.
    if (scopes.length === g.scopes.length && scopes.every((x) => g.scopes.includes(x))) return this.#personNoted(g, 'ok', 'scopes', value);
    if (!this.#personChange(g, 'scopes', value, scopes.some((x) => !g.scopes.includes(x)))) return;
    g.scopes = scopes;
    // Out of the chat, it hears no other agent when it comes back: the person says so again first.
    if (!scopes.includes('chat')) g.relay = false;
    if (!scopes.includes('cursor')) for (const st of [...a.streams.values()]) if (st.surface === s) this.#dropStream(st, true);
    try {
      a.peer.event('grant', { kind: 'scopes', scopes: [...scopes] }, { s: s.id });
      // What the agent may know about the surface follows its `observe` scope.
      a.peer.event('surface', { kind: 'changed', surface: this.#surfaceInfo(s, a) });
    } catch {
      // ignore
    }
  }

  /** A surface reports a same-origin navigation. Returns whether it was accepted. */
  #applyNav(s: SurfaceConn, d: unknown): boolean {
    if (!isObject(d) || typeof d.url !== 'string' || typeof d.title !== 'string' || d.url.length > MAX_URL_CHARS) return false;
    let u: URL;
    try {
      u = new URL(d.url);
    } catch {
      return false;
    }
    // By SPEC 5, not by this engine's URL parser, which says `null` for every file: and app-scheme URL.
    if (!urlHasOrigin(d.url, s.origin)) return false;
    const title = d.title.slice(0, MAX_TITLE_CHARS);
    if (u.href !== s.url || title !== s.title) {
      s.url = u.href;
      s.title = title;
      this.#broadcastSurface('changed', s);
    }
    return true;
  }

  #surfaceFlow(s: SurfaceConn, f: FlowFrame): void {
    const st = this.#streams.get(f.ch);
    if (!st || st.surface !== s || st.overrun || !st.ready) return;
    if (!(Number.isFinite(f.credit) && f.credit > 0)) return;
    st.credit.grant(f.credit);
    try {
      st.agent.peer.flow(f.ch, f.credit);
    } catch {
      // ignore
    }
  }

  // ───────────────────────────── grants ─────────────────────────────

  /** Why `g` has ended by time, or null while it is live. */
  #expiry(g: GrantRec): 'expired' | 'idle' | null {
    const now = this.#now();
    if (now >= g.exp) return 'expired';
    if (now - g.used >= this.#policy.idleMs) return 'idle';
    return null;
  }

  #live(g: GrantRec): boolean {
    const why = this.#expiry(g);
    if (why === null) return true;
    this.#endGrant(g, why);
    return false;
  }

  /** The agent's live grant on `s`, ending it first if it has run out. */
  #liveGrant(a: AgentConn, s: SurfaceConn): GrantRec | undefined {
    const g = a.grants.get(s.id);
    return g && this.#live(g) ? g : undefined;
  }

  #schedule(g: GrantRec): void {
    if (g.timer !== undefined) clearTimeout(g.timer);
    if (this.#closed) return;
    const due = Math.min(g.exp, g.used + this.#policy.idleMs) - this.#now();
    g.timer = unref(
      setTimeout(
        () => {
          g.timer = undefined;
          if (g.agent.grants.get(g.surface.id) !== g) return;
          const why = this.#expiry(g);
          if (why) this.#endGrant(g, why);
          else this.#schedule(g);
        },
        Math.max(0, Math.min(MAX_TIMER_MS, due)),
      ),
    );
  }

  #endGrant(g: GrantRec, why: GrantEnd): void {
    const { agent: a, surface: s } = g;
    if (a.grants.get(s.id) !== g) return;
    a.grants.delete(s.id);
    if (s.grants.get(a.id) === g) s.grants.delete(a.id);
    if (g.timer !== undefined) clearTimeout(g.timer);
    g.timer = undefined;
    if (why !== 'replaced') {
      for (const st of [...a.streams.values()]) if (st.surface === s) this.#dropStream(st, why !== 'surface');
    }
    if (!this.#closed) {
      if (why === 'agent' || why === 'expired' || why === 'idle' || why === 'hub' || why === 'level' || why === 'reports' || why === 'audit') {
        const reason = why === 'idle' ? 'expired' : why === 'level' || why === 'reports' || why === 'audit' ? 'hub' : why;
        if (!s.peer.closed) s.peer.request('detach', { why: reason }, { ag: a.id }).catch(noop);
      }
      if (why === 'expired' || why === 'idle' || why === 'revoked' || why === 'level' || why === 'reports' || why === 'audit') {
        try {
          a.peer.event('grant', { kind: why === 'expired' || why === 'idle' ? 'expired' : 'revoked' }, { s: s.id });
        } catch {
          // ignore
        }
      }
    }
    this.#audit({ kind: 'grant.end', outcome: why, agent: a.id, surface: s.id });
  }

  /**
   * The rate bucket of a credential (shared by all its sessions) on a surface, by scope;
   * `pointer` is the point budget of all its pointer streams there (`policy.pointerRate`).
   */
  #bucket(a: AgentConn, s: SurfaceConn, scope: Scope | 'attach' | 'pointer'): TokenBucket {
    const k = `${a.cred.kid}\n${s.id}|${scope}`;
    let b = this.#buckets.get(k);
    if (!b) {
      const rate = scope === 'attach' ? ATTACH_RATE : scope === 'pointer' ? this.#policy.pointerRate : this.#policy.rates[scope];
      b = new TokenBucket(rate, scope === 'attach' ? ATTACH_BURST : undefined, this.#now);
      this.#buckets.set(k, b);
    }
    return b;
  }

  /** The bucket `hub.info` and `surfaces.list` draw on, per credential. */
  #hubBucket(a: AgentConn): TokenBucket {
    const k = `${a.cred.kid}\n|hub`;
    let b = this.#buckets.get(k);
    if (!b) {
      b = new TokenBucket(HUB_METHOD_RATE, HUB_METHOD_BURST, this.#now);
      this.#buckets.set(k, b);
    }
    return b;
  }

  // ───────────────────────────── agent requests ─────────────────────────────

  #requestRecord(a: AgentConn, kind: AuditKind, m: string, p: Record<string, unknown>, outcome: string): AuditInput {
    const rec: AuditInput = { kind, outcome, agent: a.id, method: m.slice(0, 64) };
    if (typeof p.s === 'string') rec.surface = p.s.slice(0, 32);
    if (m === 'act' && typeof p.a === 'string') rec.action = p.a.slice(0, 64);
    // A chat message is on record by its length and, in `args`, its digest: never its text.
    if (m === 'chat.say' && typeof p.text === 'string') rec.chars = p.text.length;
    return rec;
  }

  async #agentRequest(a: AgentConn, m: string, p: Record<string, unknown>): Promise<unknown> {
    const started = this.#now();
    // A chat message is forwarded and recorded as its text and `to`, and as nothing else.
    if (m === 'chat.say') p = chatSayParams(p);
    const kind: AuditKind = m === 'surface.attach' ? 'attach' : m === 'surface.detach' ? 'detach' : 'request';
    const { s: _s, ...args } = p;
    // Params the audit cannot digest (nested too deeply) are refused, never forwarded.
    let canonical: string | undefined;
    try {
      canonical = canonicalJson(args);
    } catch {
      canonical = undefined;
    }
    const ctx: ReqCtx = { args: canonical ?? '' };
    const record = (outcome: string): void => {
      const rec = this.#requestRecord(a, kind, m, p, outcome);
      rec.ms = Math.max(0, this.#now() - started);
      if (ctx.accepted !== undefined) rec.ref = ctx.accepted;
      this.#audit(rec, canonical);
    };
    try {
      // First of all, so the answer depends neither on the params nor on the state of the audit log.
      if (!HUB_METHOD_NAMES.has(m) && methodScope(m) === undefined) fail('E_UNKNOWN_METHOD', `unknown method ${m.slice(0, 64)}`);
      if (canonical === undefined) fail('E_BAD_ARGS', 'params are nested too deeply');
      if ((audited(m) || m === 'surface.attach') && this.#auditUnavailable()) fail('E_INTERNAL', 'audit unavailable');
      const r = await this.#dispatch(a, m, p, ctx);
      if (ctx.accepted !== undefined || kind !== 'request' || audited(m)) record('ok');
      return r;
    } catch (e) {
      const err = e instanceof ReinsError ? e : new ReinsError('E_INTERNAL', 'internal error');
      // The outcome of an accepted request is always recorded; refusals by the hub are bounded.
      if (ctx.accepted !== undefined || a.refusals.allow()) record(err.code);
      throw err;
    }
  }

  /**
   * Write the `accepted` record of an audited request and wait until the sink has it.
   * Refuses with `E_INTERNAL` when the audit is unavailable.
   */
  async #acceptRecord(a: AgentConn, m: string, p: Record<string, unknown>, ctx: ReqCtx): Promise<void> {
    if (!this.#sink) return;
    if (this.#auditUnavailable()) fail('E_INTERNAL', 'audit unavailable');
    const kind: AuditKind = m === 'surface.attach' ? 'attach' : 'request';
    const q = this.#audit(this.#requestRecord(a, kind, m, p, 'accepted'), ctx.args, true);
    if (q === undefined) fail('E_INTERNAL', 'audit unavailable');
    ctx.accepted = q.seq;
    try {
      await q.written;
    } catch {
      fail('E_INTERNAL', 'audit unavailable');
    }
  }

  #dispatch(a: AgentConn, m: string, p: Record<string, unknown>, ctx: ReqCtx): unknown {
    switch (m) {
      case 'hub.info':
        if (!this.#hubBucket(a).take()) fail('E_RATE', 'too many hub requests');
        return this.#infoFor(a);
      case 'surfaces.list':
        if (!this.#hubBucket(a).take()) fail('E_RATE', 'too many hub requests');
        return { surfaces: [...this.#surfaces.values()].filter((s) => this.#mayAttachTo(a, s)).map((s) => this.#surfaceInfo(s, a)) };
      case 'surface.attach':
        return this.#attach(a, p, ctx);
      case 'surface.detach':
        return this.#detach(a, p);
      case 'stream.open':
        return this.#streamOpen(a, p, ctx);
      case 'stream.close':
        return this.#streamClose(a, p);
      default:
        return this.#forward(a, m, p, ctx);
    }
  }

  /**
   * The surface named by `p.s`. One the agent's credential may not attach to is refused
   * exactly like one that does not exist (same code, same message), on every method.
   */
  #surfaceArg(a: AgentConn, p: Record<string, unknown>): SurfaceConn {
    if (typeof p.s !== 'string') fail('E_BAD_ARGS', 's must be a surface id');
    const s = this.#surfaces.get(p.s);
    if (!s || !this.#mayAttachTo(a, s)) fail('E_NO_SURFACE', 'no such surface');
    return s;
  }

  #requireGrant(a: AgentConn, s: SurfaceConn): GrantRec {
    const g = this.#liveGrant(a, s);
    if (!g) fail('E_NOT_ATTACHED', 'not attached to this surface');
    g.used = this.#now();
    return g;
  }

  async #attach(a: AgentConn, p: Record<string, unknown>, ctx: ReqCtx): Promise<unknown> {
    // The credential may not attach: E_NO_SURFACE, exactly as for an id that does not exist.
    const s = this.#surfaceArg(a, p);
    if (!Array.isArray(p.scopes) || !p.scopes.every((x) => typeof x === 'string')) fail('E_BAD_ARGS', 'scopes must be a list of scopes');
    const reason = p.reason;
    if (reason !== undefined && (typeof reason !== 'string' || reason.length > MAX_REASON_CHARS)) fail('E_BAD_ARGS', 'reason must be a short string');
    const scopes = capScopes(p.scopes as Scope[], a.cred.scopes, this.#policy.scopes);
    if (scopes.length === 0) fail('E_SCOPE', 'none of the requested scopes is permitted');
    const decision = this.#policy.attach;
    if (decision === 'deny') fail('E_DENIED', 'attach denied by hub policy');
    // One attach in flight per credential and surface, across all its sessions, until the surface answers.
    const guard = `${a.cred.kid}\n${s.id}`;
    if (this.#attaching.has(guard)) fail('E_BUSY', 'an attach to this surface is already pending');
    if (!this.#bucket(a, s, 'attach').take()) fail('E_RATE', 'too many attach requests');

    this.#attaching.add(guard);
    let sent = false;
    let r: unknown;
    try {
      await this.#acceptRecord(a, 'surface.attach', p, ctx);
      if (this.#surfaces.get(s.id) !== s) fail('E_GONE', 'surface gone');
      if (this.#agents.get(a.id) !== a) fail('E_GONE', 'agent gone');
      // `levels`: what this hub's policy lets the person switch the grant to. The surface offers no more.
      // `decisions`: what this hub's policy decides for each action of the surface, so that the
      // person's panel knows which actions the hub confirms (`c:1`) and which it refuses.
      // `cred`: the id of the agent's credential. It is what stays the same when an agent
      // attaches again under another session id or name, so the surface can keep what the
      // person tightened for it.
      const params: Record<string, unknown> = { agent: { id: a.id, name: a.name }, scopes, levels: [...this.#policy.human.levels], decisions: actionDecisions(this.#policy, s.manifest.actions), chatRelay: this.#policy.chatRelay, cred: a.cred.kid.slice(0, 64) };
      if (typeof reason === 'string') params.reason = reason;
      const opts: { ag: string; timeoutMs: number; c?: 1 } = { ag: a.id, timeoutMs: this.#limits.reqTimeoutMs + this.#limits.consentTimeoutMs };
      if (decision === 'confirm') opts.c = 1;
      // From here until the answer, a disconnect of this session withdraws the attach (#agentGone).
      a.attaching.add(s.id);
      sent = true;
      r = await s.peer.request<unknown>('attach', params, opts);
    } finally {
      this.#attaching.delete(guard);
      if (sent) a.attaching.delete(s.id);
    }

    if (this.#surfaces.get(s.id) !== s) fail('E_GONE', 'surface gone');
    // Gone while waiting: #agentGone has already sent the surface `detach {why:"agent"}`.
    if (this.#agents.get(a.id) !== a) fail('E_GONE', 'agent gone');
    if (!isObject(r) || !Array.isArray(r.scopes)) {
      s.peer.request('detach', { why: 'hub' }, { ag: a.id }).catch(noop);
      fail('E_INTERNAL', 'bad answer from surface');
    }
    const granted = capScopes(r.scopes.filter((x): x is Scope => typeof x === 'string'), scopes);
    if (granted.length === 0) {
      s.peer.request('detach', { why: 'hub' }, { ag: a.id }).catch(noop);
      fail('E_SCOPE', 'the surface granted no scopes');
    }
    const ttl = typeof r.ttlMs === 'number' && Number.isFinite(r.ttlMs) && r.ttlMs >= 0 ? Math.min(this.#policy.ttlMs, r.ttlMs) : this.#policy.ttlMs;

    const old = a.grants.get(s.id);
    if (old) {
      this.#endGrant(old, 'replaced');
      if (!granted.includes('cursor')) for (const st of [...a.streams.values()]) if (st.surface === s) this.#dropStream(st, true);
    }
    const now = this.#now();
    // A new grant, also one that replaces another, starts at the level `ask`, without rules and
    // with every granted scope on, except for what the surface says stays of what the person
    // tightened for this agent before (`kept`): the level `strict`, rules `confirm` and
    // `deny` for actions the surface declares, scopes switched off. Nothing else is read from
    // it: no surface loosens a grant with its attach answer.
    const kept = keptSettings(r.kept, granted, s.actions.keys());
    const inForce = granted.filter((x) => !kept.off.includes(x));
    const g: GrantRec = {
      id: `g${++this.#grantSeq}`,
      agent: a,
      surface: s,
      scopes: inForce,
      granted: [...granted],
      level: kept.level ?? DEFAULT_LEVEL,
      rules: new Map(kept.rules),
      changes: 0,
      changesAt: Number.NEGATIVE_INFINITY,
      relay: false,
      chatIn: new Map(),
      exp: now + ttl,
      used: now,
    };
    a.grants.set(s.id, g);
    s.grants.set(a.id, g);
    this.#schedule(g);
    if (!inForce.includes('cursor')) for (const st of [...a.streams.values()]) if (st.surface === s) this.#dropStream(st, true);
    // On record with the grant they start: what the person set earlier and that still holds.
    if (kept.level) this.#audit({ kind: 'person', outcome: 'kept', agent: a.id, surface: s.id, method: 'level', value: kept.level });
    for (const [name, d] of kept.rules) this.#audit({ kind: 'person', outcome: 'kept', agent: a.id, surface: s.id, method: 'rule', value: d, action: name });
    if (kept.off.length) this.#audit({ kind: 'person', outcome: 'kept', agent: a.id, surface: s.id, method: 'scopes', value: inForce.length ? inForce.join(' ') : 'none' });
    const result: Record<string, unknown> = { grant: { id: g.id, s: s.id, scopes: [...inForce], exp: g.exp }, surface: this.#surfaceInfo(s, a), manifest: s.manifest };
    if (kept.level || kept.rules.size) {
      const k: { level?: 'strict'; rules?: Record<string, 'confirm' | 'deny'> } = {};
      if (kept.level) k.level = kept.level;
      if (kept.rules.size) k.rules = Object.fromEntries(kept.rules);
      result.kept = k;
    }
    return result;
  }

  #detach(a: AgentConn, p: Record<string, unknown>): unknown {
    const s = this.#surfaceArg(a, p);
    const g = this.#liveGrant(a, s);
    if (!g) fail('E_NOT_ATTACHED', 'not attached to this surface');
    this.#endGrant(g, 'agent');
    return {};
  }

  async #forward(a: AgentConn, m: string, p: Record<string, unknown>, ctx: ReqCtx): Promise<unknown> {
    // An unknown method is E_UNKNOWN_METHOD whatever its params (SPEC 16): checked first.
    const scope = methodScope(m);
    if (scope === undefined) fail('E_UNKNOWN_METHOD', `unknown method ${m.slice(0, 64)}`);
    const s = this.#surfaceArg(a, p);
    const g = this.#requireGrant(a, s);
    if (!g.scopes.includes(scope)) fail('E_SCOPE', `grant lacks scope ${scope}`);
    if (!this.#bucket(a, s, scope).take()) fail('E_RATE', 'rate limit exceeded');
    let c: 1 | undefined;
    if (m === 'act') {
      if (typeof p.a !== 'string') fail('E_BAD_ARGS', 'a must be an action name');
      const def = s.actions.get(p.a);
      if (!def) fail('E_BAD_ARGS', 'unknown action');
      const d = decideAction(this.#policy, def);
      if (d === 'deny') fail('E_DENIED', 'action denied by hub policy');
      if (d === 'confirm') c = 1;
    }
    if (m === 'nav.go' && (typeof p.url !== 'string' || !navAllowed(this.#policy, p.url, s.url))) fail('E_DENIED', 'navigation not allowed');
    if (m === 'chat.say') {
      if (chatText(p.text) === undefined) fail('E_BAD_ARGS', `text must be 1 to ${CHAT_MAX_TEXT} characters`);
      // `to: "person"` is for the person alone and always allowed. Any other `to` addresses
      // an agent: refused, before the name is looked at, for an agent this hub lets no other
      // agent hear, so that the answer says nothing about who else is attached.
      if (p.to !== undefined && p.to !== CHAT_TO_PERSON) {
        if (typeof p.to !== 'string' || p.to.length < 1 || p.to.length > 64) fail('E_BAD_ARGS', 'to must be an agent id, or person');
        const mode = this.#policy.chatRelay;
        if (mode === 'off' || (mode === 'person' && !g.relay)) fail('E_DENIED', 'no other agent hears you under this hub policy');
      }
    }
    const fwd: Record<string, unknown> = { ...p };
    delete fwd.s;
    const timeoutMs = m === 'act' ? this.#limits.reqTimeoutMs + this.#limits.consentTimeoutMs : this.#limits.reqTimeoutMs;
    const opts: { ag: string; timeoutMs: number; c?: 1 } = { ag: a.id, timeoutMs };
    if (c === 1) opts.c = 1;
    if (audited(m)) {
      // On record before it can happen: a crash from here on leaves an `accepted` record.
      await this.#acceptRecord(a, m, p, ctx);
      if (this.#surfaces.get(s.id) !== s) fail('E_GONE', 'surface gone');
      if (this.#currentGrant(a, s) !== g) fail('E_NOT_ATTACHED', 'not attached to this surface');
    }
    return s.peer.request(m, fwd, opts);
  }

  // ───────────────────────────── pointer streams ─────────────────────────────

  #allocChannel(): number | undefined {
    for (let i = 0; i < 0xffff; i++) {
      const ch = (this.#chSeq++ % 0xffff) + 1;
      if (!this.#streams.has(ch)) return ch;
    }
    return undefined;
  }

  #dropStream(st: StreamRec, tellSurface: boolean): void {
    if (this.#streams.get(st.ch) === st) this.#streams.delete(st.ch);
    if (st.agent.streams.get(st.ch) === st) st.agent.streams.delete(st.ch);
    if (tellSurface && !st.overrun && !this.#closed && !st.surface.peer.closed) {
      st.surface.peer.request('stream.close', { ch: st.ch }, { ag: st.agent.id }).catch(noop);
    }
  }

  async #streamOpen(a: AgentConn, p: Record<string, unknown>, ctx: ReqCtx): Promise<unknown> {
    const s = this.#surfaceArg(a, p);
    // A pointer stream draws the cursor at any point: off wherever raw coordinates are.
    if (!this.#policy.coordinates) fail('E_DENIED', 'pointer streams are off under this hub policy');
    const g = this.#requireGrant(a, s);
    if (!g.scopes.includes('cursor')) fail('E_SCOPE', 'grant lacks scope cursor');
    if (!this.#bucket(a, s, 'cursor').take()) fail('E_RATE', 'rate limit exceeded');
    if (p.kind !== 'pointer') fail('E_BAD_ARGS', 'kind must be pointer');
    if (a.streams.size >= this.#maxStreams) fail('E_BUSY', 'too many open streams');
    // Audited: on record before the surface hears of it (the frames themselves are not).
    await this.#acceptRecord(a, 'stream.open', p, ctx);
    if (this.#surfaces.get(s.id) !== s) fail('E_GONE', 'surface gone');
    if (this.#currentGrant(a, s) !== g) fail('E_NOT_ATTACHED', 'not attached to this surface');
    if (a.streams.size >= this.#maxStreams) fail('E_BUSY', 'too many open streams');
    const ch = this.#allocChannel();
    if (ch === undefined) fail('E_BUSY', 'too many open streams');
    const st: StreamRec = {
      ch,
      agent: a,
      surface: s,
      credit: new CreditWindow(0),
      ready: false,
      overrun: false,
    };
    this.#streams.set(ch, st);
    a.streams.set(ch, st);
    let r: unknown;
    try {
      r = await s.peer.request('stream.open', { kind: 'pointer', ch }, { ag: a.id });
    } catch (e) {
      this.#dropStream(st, false);
      throw e;
    }
    if (this.#streams.get(ch) !== st) fail('E_GONE', 'stream closed');
    const offered = isObject(r) ? r.credit : undefined;
    const credit = typeof offered === 'number' && Number.isFinite(offered) && offered >= 0 ? offered : PTR_INITIAL_CREDIT;
    st.credit.grant(credit);
    st.ready = true;
    return { ch, credit };
  }

  #streamClose(a: AgentConn, p: Record<string, unknown>): unknown {
    const ch = p.ch;
    if (typeof ch !== 'number' || !Number.isInteger(ch)) fail('E_BAD_ARGS', 'ch must be a channel number');
    const st = this.#streams.get(ch);
    if (!st || st.agent !== a) fail('E_BAD_ARGS', 'unknown stream');
    const overrun = st.overrun;
    this.#dropStream(st, true);
    if (overrun) fail('E_RATE', 'stream closed for exceeding its rate or credit');
    return {};
  }

  #overrun(st: StreamRec): void {
    st.overrun = true;
    if (!st.surface.peer.closed) st.surface.peer.request('stream.close', { ch: st.ch }, { ag: st.agent.id }).catch(noop);
    this.#audit({ kind: 'stream', outcome: 'E_RATE', agent: st.agent.id, surface: st.surface.id, method: 'stream.open' });
  }

  #agentBinary(a: AgentConn, bytes: Uint8Array): void {
    let f: PointerFrame;
    try {
      f = decodePointer(bytes);
    } catch {
      return;
    }
    const st = this.#streams.get(f.ch);
    if (!st || st.agent !== a || st.overrun || !st.ready) return;
    const g = this.#liveGrant(a, st.surface);
    if (!g || !g.scopes.includes('cursor')) {
      this.#dropStream(st, true);
      return;
    }
    const n = f.points.length;
    const end = (f.flags & PTR_FLAG_END) !== 0;
    // A frame with no points carries nothing to draw unless it ends the stroke.
    if (n === 0 && !end) return;
    // Every forwarded frame costs at least one token, so empty END frames are bounded too. The
    // budget is the credential's on this surface, shared by all its streams and sessions.
    if (!this.#bucket(a, st.surface, 'pointer').take(Math.max(1, n)) || !st.credit.consume(n)) {
      this.#overrun(st);
      return;
    }
    const buffered = st.surface.peer.bufferedAmount;
    if (buffered > STALL_BUFFER_BYTES) {
      // The surface is not draining what it is sent: stop feeding it.
      this.#overrun(st);
      return;
    }
    if ((f.flags & PTR_FLAG_DROPPABLE) !== 0 && !end && buffered > DROP_BUFFER_BYTES) {
      // The surface never sees these points, so it will never return their credit: refund it.
      st.credit.grant(n);
      try {
        a.peer.flow(st.ch, n);
      } catch {
        // ignore
      }
      return;
    }
    try {
      st.surface.peer.sendBinary(bytes);
    } catch {
      // ignore
    }
  }

  // ───────────────────────────── heartbeat ─────────────────────────────

  #tick(): void {
    if (this.#closed) return;
    const now = this.#now();
    const hb = this.#limits.heartbeatMs;
    const conns: Conn[] = [...this.#agents.values(), ...this.#surfaces.values()];
    for (const c of conns) {
      if (c.peer.closed) continue;
      const silent = now - c.peer.lastSeen;
      if (silent > 2.5 * hb) {
        c.peer.bye('E_TIMEOUT', 'heartbeat timeout');
        continue;
      }
      if (silent >= hb && now - c.lastPing >= hb) {
        c.lastPing = now;
        c.peer.ping(hb).catch(noop);
      }
    }
  }

  // ───────────────────────────── audit ─────────────────────────────

  /** True while audited requests must be refused: the sink failed, or the backlog is too long. */
  #auditUnavailable(): boolean {
    return this.#sink !== undefined && (this.#auditFailed || this.#auditQueue.length > AUDIT_BACKLOG_MAX);
  }

  #auditConnFailure(input: AuditInput): void {
    if (this.#connRefusals.allow()) this.#audit(input);
  }

  /**
   * Queue a record. Its `seq` is fixed now, so records keep the order of events. With
   * `wait`, also returns a promise that settles when the sink has taken the record, or
   * rejects when the sink throws on it. Returns undefined when nothing was queued.
   * `args` is the canonical JSON of the request params.
   */
  #audit(input: AuditInput, args?: string, wait = false): { seq: number; written: Promise<void> } | undefined {
    const sink = this.#sink;
    if (!sink) return undefined;
    if (this.#auditQueue.length >= AUDIT_QUEUE_MAX) {
      this.#auditLost++;
      return undefined;
    }
    const rec: Record<string, unknown> = { seq: ++this.#auditSeq, ts: this.#now() };
    for (const [k, v] of Object.entries(input)) if (v !== undefined) rec[k] = v;
    const q: QueuedRecord = { rec, hashed: false };
    if (args !== undefined) (q as { args?: string }).args = args;
    let written: Promise<void> = Promise.resolve();
    if (wait) {
      written = new Promise<void>((resolve, reject) => {
        q.done = { resolve, reject };
      });
    }
    this.#auditQueue.push(q);
    if (!this.#auditFailed) void this.#drainAudit();
    return { seq: rec.seq as number, written };
  }

  /** Write queued records in order. One drain runs at a time. */
  #drainAudit(): Promise<void> {
    if (this.#auditDraining) return this.#auditDraining;
    const sink = this.#sink;
    if (!sink) return Promise.resolve();
    let release!: () => void;
    // Set before the loop starts, so a record queued from inside it joins this drain.
    this.#auditDraining = new Promise<void>((r) => (release = r));
    const running = this.#auditDraining;
    this.#runDrain(sink)
      .catch((e: unknown) => this.#auditSinkFailed(e))
      .finally(() => {
        this.#auditDraining = undefined;
        release();
        // Anything queued between the loop's last look and now.
        if (this.#auditQueue.length > 0 && !this.#auditFailed) void this.#drainAudit();
      });
    return running;
  }

  async #runDrain(sink: AuditSink): Promise<void> {
    for (;;) {
      const q = this.#auditQueue[0];
      if (q === undefined) {
        if (this.#auditLost > 0) {
          const count = this.#auditLost;
          this.#auditLost = 0;
          this.#audit({ kind: 'audit', outcome: 'lost', count });
          continue;
        }
        // Drained, and the last write (if any) went through.
        this.#auditFailed = false;
        return;
      }
      if (!q.hashed) {
        if (q.args !== undefined) {
          // Keyed: an HMAC, so a reader of the log cannot test guesses of low-entropy params.
          q.rec.args = this.#auditKey !== undefined ? await hmacSha256(this.#auditKey, q.args) : await sha256(q.args);
        }
        q.rec.prev = this.#auditPrev;
        q.rec.hash = await auditHash(this.#auditPrev, q.rec as unknown as AuditRecord, this.#auditKey);
        q.hashed = true;
      }
      try {
        sink.write(q.rec as unknown as AuditRecord);
      } catch (e) {
        // Fail closed: keep the record (its hash is already chained) and try again later.
        this.#auditSinkFailed(e);
        return;
      }
      this.#auditQueue.shift();
      this.#auditPrev = q.rec.hash as string;
      this.#auditHead = { seq: q.rec.seq as number, hash: q.rec.hash as string };
      q.done?.resolve();
    }
  }

  #auditSinkFailed(e: unknown): void {
    this.#auditFailed = true;
    for (const w of this.#auditQueue) {
      w.done?.reject(e);
      w.done = undefined;
    }
    if (!this.#closed && this.#auditRetry === undefined) {
      this.#auditRetry = unref(
        setTimeout(() => {
          this.#auditRetry = undefined;
          void this.#drainAudit();
        }, AUDIT_RETRY_MS),
      );
    }
  }
}
