import { DEFAULT_LIMITS, ReinsError, SEAL_CONFIRM_MS, SEAL_CONTEXT, SEAL_KIND, SEAL_MAC_BYTES, SEAL_MAC_TEXT_LENGTH, SEAL_SEPARATOR } from './protocol.js';
import type { Link } from './protocol.js';
import { b64urlEncode, timingSafeEqual, wellFormed } from './crypto.js';
import { decodeFrame, encodeFrame, utf8Length } from './codec.js';
import { QueueLink } from './link.js';

type Msg = string | Uint8Array;

/**
 * The two directional keys of one end of a sealed session. Opaque: create with
 * `deriveSealKeys`, hand to `sealLink`. The CryptoKeys are non-extractable.
 */
export interface SealKeys {
  /** Seals what this end sends. */
  readonly send: CryptoKey;
  /** Opens what this end receives. */
  readonly recv: CryptoKey;
}

const enc = new TextEncoder();
const HMAC = { name: 'HMAC', hash: 'SHA-256' } as const;
const SEP = SEAL_SEPARATOR.charCodeAt(0);

function subtle(): SubtleCrypto {
  const c = (globalThis as { crypto?: Crypto }).crypto;
  if (!c || !c.subtle) throw new ReinsError('E_INTERNAL', 'WebCrypto is not available');
  return c.subtle;
}

/** What the seal keys are bound to: the handshake nonces and the exact texts of its three frames. */
export interface SealTranscript {
  nonce: string;
  cnonce: string;
  /** The `challenge` frame exactly as it went over the wire. */
  challengeText: string;
  /** The `hello` frame exactly as it went over the wire. */
  helloText: string;
  /** The `welcome` frame exactly as it went over the wire. */
  welcomeText: string;
}

/** Each text as UTF-8, behind its byte length as a u32 BE: no two lists of texts share an encoding. */
function lengthPrefixed(texts: string[]): Uint8Array<ArrayBuffer> {
  const parts = texts.map((t) => enc.encode(t));
  const out = new Uint8Array(parts.reduce((n, p) => n + 4 + p.length, 0));
  const dv = new DataView(out.buffer);
  let at = 0;
  for (const p of parts) {
    dv.setUint32(at, p.length);
    out.set(p, at + 4);
    at += 4 + p.length;
  }
  return out;
}

/**
 * Derive the directional seal keys from the shared secret and the handshake transcript:
 * th     = base64url(SHA-256(L(c) || c || L(h) || h || L(w) || w)), where c, h and w are the
 *          UTF-8 bytes of the challenge, hello and welcome texts and L(x) is the length of x
 *          in bytes as an unsigned 32-bit big-endian integer,
 * k_peer = HMAC-SHA256(key, "reins.v1.seal.peer\n" + nonce + "\n" + cnonce + "\n" + th),
 * k_hub  = HMAC-SHA256(key, "reins.v1.seal.hub\n"  + nonce + "\n" + cnonce + "\n" + th).
 * `side` is the end calling: a peer sends with k_peer and receives with k_hub, the hub
 * the other way round. A relay that changed any byte of `challenge`, `hello` or `welcome`
 * leaves the two ends with different keys. Throws `E_AUTH` if a field is not a string, a
 * nonce contains a newline, or a text is not well-formed Unicode.
 */
export async function deriveSealKeys(key: string, t: SealTranscript, side: 'peer' | 'hub'): Promise<SealKeys> {
  const { nonce, cnonce, challengeText, helloText, welcomeText } = (t ?? {}) as Partial<SealTranscript>;
  if (
    typeof key !== 'string' ||
    typeof nonce !== 'string' ||
    typeof cnonce !== 'string' ||
    nonce.includes('\n') ||
    cnonce.includes('\n') ||
    typeof challengeText !== 'string' ||
    typeof helloText !== 'string' ||
    typeof welcomeText !== 'string' ||
    !wellFormed(challengeText) ||
    !wellFormed(helloText) ||
    !wellFormed(welcomeText)
  ) {
    throw new ReinsError('E_AUTH', 'invalid seal fields');
  }
  if (side !== 'peer' && side !== 'hub') throw new ReinsError('E_BAD_ARGS', 'invalid seal side');
  const s = subtle();
  const th = b64urlEncode(new Uint8Array(await s.digest('SHA-256', lengthPrefixed([challengeText, helloText, welcomeText]))));
  const root = await s.importKey('raw', enc.encode(key), HMAC, false, ['sign']);
  const derive = async (context: string): Promise<CryptoKey> => {
    const raw = new Uint8Array(await s.sign('HMAC', root, enc.encode(`${context}\n${nonce}\n${cnonce}\n${th}`)));
    try {
      return await s.importKey('raw', raw, HMAC, false, ['sign']);
    } finally {
      raw.fill(0);
    }
  };
  const [kPeer, kHub] = await Promise.all([derive(SEAL_CONTEXT.peer), derive(SEAL_CONTEXT.hub)]);
  return Object.freeze(side === 'peer' ? { send: kPeer, recv: kHub } : { send: kHub, recv: kPeer });
}

/** HMAC-SHA256(k, seq as u64 BE || kind || payload). */
async function mac(k: CryptoKey, seq: number, kind: number, payload: Msg): Promise<Uint8Array> {
  const body = typeof payload === 'string' ? enc.encode(payload) : payload;
  const input = new Uint8Array(9 + body.length);
  const dv = new DataView(input.buffer);
  dv.setUint32(0, Math.floor(seq / 0x1_0000_0000));
  dv.setUint32(4, seq >>> 0);
  input[8] = kind;
  input.set(body, 9);
  return new Uint8Array(await subtle().sign('HMAC', k, input));
}

function bytesEqual(a: Uint8Array, b: Uint8Array): boolean {
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a[i]! ^ b[i]!;
  return diff === 0;
}

function size(m: Msg): number {
  return typeof m === 'string' ? utf8Length(m) : m.length;
}

class SealedLink extends QueueLink {
  #inner: Link;
  #keys: SealKeys;
  #sendSeq = 0;
  #recvSeq = 0;
  #sendChain: Promise<void> = Promise.resolve();
  #recvChain: Promise<void> = Promise.resolve();
  #pending = 0;
  #failed = false;

  constructor(inner: Link, keys: SealKeys) {
    super();
    this.#inner = inner;
    this.#keys = keys;
    // Assigning the handler makes the inner link flush anything it had queued, in order.
    inner.onmessage = (d) => this.#inbound(d);
    inner.onclose = () => {
      // After every message already being opened has been delivered.
      this.#recvChain = this.#recvChain.then(() => this.markClosed());
    };
  }

  get bufferedAmount(): number {
    return this.#inner.bufferedAmount + this.#pending;
  }

  protected transmit(data: Msg): void {
    if (!this.#inner.open) return;
    // A lone surrogate has no UTF-8 encoding of its own, so its MAC would cover a different string.
    if (typeof data === 'string' && !wellFormed(data)) throw new ReinsError('E_BAD_FRAME', 'text is not well-formed Unicode');
    const seq = this.#sendSeq++;
    const text = typeof data === 'string';
    // Copy now: the caller may reuse its buffer before the MAC is ready.
    const payload: Msg = text ? data : data.slice();
    const n = size(payload);
    this.#pending += n;
    const tag = mac(this.#keys.send, seq, text ? SEAL_KIND.text : SEAL_KIND.binary, payload);
    this.#sendChain = this.#sendChain
      .then(() => tag)
      .then(
        (m) => {
          if (this.#failed) return;
          if (typeof payload === 'string') this.#inner.send(b64urlEncode(m) + SEAL_SEPARATOR + payload);
          else {
            const out = new Uint8Array(payload.length + SEAL_MAC_BYTES);
            out.set(payload, 0);
            out.set(m, payload.length);
            this.#inner.send(out);
          }
        },
        () => this.#fail(),
      )
      .finally(() => {
        this.#pending -= n;
      });
  }

  protected shutdown(): void {
    if (this.#failed) return;
    // Let everything sent before close() (a `bye`, typically) reach the wire first.
    this.#sendChain = this.#sendChain.then(() => this.#inner.close());
  }

  #inbound(data: Msg): void {
    if (this.#failed) return;
    const seq = this.#recvSeq++;
    let check: Promise<Msg | null>;
    if (typeof data === 'string') {
      if (data.length < SEAL_MAC_TEXT_LENGTH + 1 || data.charCodeAt(SEAL_MAC_TEXT_LENGTH) !== SEP || !wellFormed(data)) check = Promise.resolve(null);
      else {
        const got = data.slice(0, SEAL_MAC_TEXT_LENGTH);
        const text = data.slice(SEAL_MAC_TEXT_LENGTH + 1);
        // Compare encodings, not decoded bytes: base64url's spare bits would make the MAC malleable.
        check = mac(this.#keys.recv, seq, SEAL_KIND.text, text).then((m) => (timingSafeEqual(got, b64urlEncode(m)) ? text : null));
      }
    } else if (data.length < SEAL_MAC_BYTES) check = Promise.resolve(null);
    else {
      const body = data.slice(0, data.length - SEAL_MAC_BYTES);
      const got = data.subarray(data.length - SEAL_MAC_BYTES);
      check = mac(this.#keys.recv, seq, SEAL_KIND.binary, body).then((m) => (bytesEqual(got, m) ? body : null));
    }
    this.#recvChain = this.#recvChain
      .then(() => check)
      .then(
        (msg) => {
          if (this.#failed) return;
          if (msg === null) return this.#fail();
          this.receive(msg);
        },
        () => this.#fail(),
      );
  }

  #fail(): void {
    if (this.#failed) return;
    this.#failed = true;
    this.markClosed();
    this.#inner.onmessage = null;
    this.#inner.close();
  }
}

/**
 * Seal a link after `welcome`: every message sent is MACed under `keys.send` with a
 * per-direction counter from 0, every message received is opened under `keys.recv`
 * with the expected counter. A message that fails to open closes the underlying link
 * and the sealed link; it and anything after it are never delivered.
 *
 * Wire format (seq is implicit: the transport is ordered):
 *   mac  = HMAC-SHA256(k, u64be(seq) || kind || payload), kind 0x74 text / 0x62 binary,
 *          payload of a text message = its UTF-8 bytes
 *   text = base64url(mac) (43 chars) + "." + text
 *   binary = bytes || mac (32 bytes)
 *
 * Takes over `link.onmessage` and `link.onclose`; messages the link already queued are
 * opened in order. The returned link honours the Link contract. `close()` closes the
 * underlying link only after everything sent before it has been sealed and sent.
 *
 * Hub side: derive the keys before sending `welcome` (or keep `onmessage` null until
 * `sealLink` is called), send `welcome` on the raw link, then call `sealLink` at once,
 * so the peer's first sealed frame is never handled by anything else.
 */
export function sealLink(link: Link, keys: SealKeys): Link {
  return new SealedLink(link, keys);
}

// ───────────────────────────── key confirmation ─────────────────────────────

/**
 * The first message on `link`, after which `onmessage` and `onclose` are null again, so
 * everything later stays queued. Rejects if the link closes first or after `ms`.
 */
function firstMessage(link: Link, ms: number): Promise<Msg> {
  return new Promise<Msg>((resolve, reject) => {
    let settled = false;
    const done = (fn: () => void) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      link.onmessage = null;
      link.onclose = null;
      fn();
    };
    const timer = setTimeout(() => done(() => reject(new ReinsError('E_TIMEOUT', 'timed out'))), ms);
    link.onclose = () => done(() => reject(new ReinsError('E_GONE', 'connection closed')));
    link.onmessage = (d) => done(() => resolve(d));
  });
}

/** The `ping` or `pong` timestamp in a confirmation frame, or undefined. */
function confirmTs(m: Msg, t: 'ping' | 'pong'): number | undefined {
  if (typeof m !== 'string') return undefined;
  try {
    const f = decodeFrame(m, DEFAULT_LIMITS.maxText);
    return f.t === t ? f.ts : undefined;
  } catch {
    return undefined;
  }
}

/** Peer side of key confirmation; used by `clientConnect`. Closes the link and throws `E_AUTH` on failure. */
export async function peerConfirm(link: Link, keys: SealKeys, timeoutMs: number = SEAL_CONFIRM_MS): Promise<Link> {
  const sealed = sealLink(link, keys);
  const ts = Date.now();
  sealed.send(encodeFrame({ t: 'ping', ts }));
  let first: Msg;
  try {
    first = await firstMessage(sealed, timeoutMs);
  } catch {
    sealed.close();
    throw new ReinsError('E_AUTH', 'hub did not confirm the session');
  }
  if (confirmTs(first, 'pong') !== ts) {
    sealed.close();
    throw new ReinsError('E_AUTH', 'hub did not confirm the session');
  }
  return sealed;
}

export interface HubSealInput extends SealTranscript {
  /** The key the peer authenticated with. */
  key: string;
}

/**
 * Hub side of a sealed session. Call it right after sending `welcome` in clear, with the
 * link's `onmessage` still null (it is set to null here too): derives the keys (side
 * `hub`), seals the link, waits for the peer's sealed `ping {ts}`, answers with a sealed
 * `pong {ts}` and returns the sealed link. Only then has the peer shown that it saw the
 * same `hello` and `welcome`: act on nothing from `hello` before this resolves. On a
 * wrong first frame, a close, a verification failure or after `timeoutMs` (default
 * SEAL_CONFIRM_MS) it closes the link and throws `E_AUTH`. Frames the peer sends after
 * its ping stay queued on the returned link, and the pong is queued before anything the
 * caller sends, so nothing is lost or reordered in either direction.
 */
export async function hubSeal(link: Link, s: HubSealInput, opts: { timeoutMs?: number } = {}): Promise<Link> {
  link.onmessage = null;
  const timeoutMs = opts.timeoutMs ?? SEAL_CONFIRM_MS;
  let keys: SealKeys;
  try {
    keys = await deriveSealKeys(s.key, s, 'hub');
  } catch {
    link.close();
    throw new ReinsError('E_AUTH', 'session confirmation failed');
  }
  const sealed = sealLink(link, keys);
  let first: Msg;
  try {
    first = await firstMessage(sealed, timeoutMs);
  } catch {
    sealed.close();
    throw new ReinsError('E_AUTH', 'session confirmation failed');
  }
  const ts = confirmTs(first, 'ping');
  if (ts === undefined) {
    sealed.close();
    throw new ReinsError('E_AUTH', 'session confirmation failed');
  }
  sealed.send(encodeFrame({ t: 'pong', ts }));
  return sealed;
}
