import type { Observation, TreeOp, UiNode } from './protocol.js';
import { jsonLine } from './schema.js';
import { deepEqual } from './util.js';

/*
 * Delta semantics (shared by diffNodes and applyOps), applied op by op:
 *
 *   del h  removes the node with handle h, if present.
 *   set n  when n.h is present, replaces that node in place.
 *          when n.h is new, inserts n right after the node written by the immediately
 *          preceding op if that op is a `set`, else at the front of the list.
 *
 * diffNodes emits every `del` first (removed nodes, and nodes that moved), then walks the
 * new list in document order. A changed node is a `set` in place. A new or moved node is
 * a `set` right after its predecessor; when the preceding op is not already the
 * predecessor, the predecessor is re-sent unchanged as an anchor.
 */

function cloneNode(n: UiNode): UiNode {
  const c: UiNode = { ...n };
  if (n.st) c.st = [...n.st];
  if (n.box) c.box = [...n.box] as UiNode['box'];
  return c;
}

/** Indices of a longest strictly increasing subsequence of `a` (patience sorting, O(n log n)). */
function lisIndices(a: number[]): Set<number> {
  const tails: number[] = [];
  const prev = new Array<number>(a.length).fill(-1);
  for (let i = 0; i < a.length; i++) {
    let lo = 0;
    let hi = tails.length;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (a[tails[mid]!]! < a[i]!) lo = mid + 1;
      else hi = mid;
    }
    if (lo > 0) prev[i] = tails[lo - 1]!;
    tails[lo] = i;
  }
  const out = new Set<number>();
  let k = tails.length ? tails[tails.length - 1]! : -1;
  while (k >= 0) {
    out.add(k);
    k = prev[k]!;
  }
  return out;
}

/** Ops that turn `prev` into `next`: `applyOps(prev, diffNodes(prev, next))` deep-equals `next`. */
export function diffNodes(prev: UiNode[], next: UiNode[]): TreeOp[] {
  const prevIndex = new Map<string, number>();
  prev.forEach((n, i) => prevIndex.set(n.h, i));
  const nextHandles = new Set(next.map((n) => n.h));

  // Survivors in next order; those on a longest increasing run of old positions stay put.
  const survivors: number[] = []; // positions in `next`
  const oldPos: number[] = [];
  next.forEach((n, i) => {
    const p = prevIndex.get(n.h);
    if (p !== undefined) {
      survivors.push(i);
      oldPos.push(p);
    }
  });
  const stay = new Set<number>();
  for (const k of lisIndices(oldPos)) stay.add(survivors[k]!);

  const ops: TreeOp[] = [];
  const movedHandles = new Set<string>();
  next.forEach((n, i) => {
    if (prevIndex.has(n.h) && !stay.has(i)) movedHandles.add(n.h);
  });
  for (const n of prev) {
    if (!nextHandles.has(n.h) || movedHandles.has(n.h)) ops.push({ op: 'del', h: n.h });
  }

  next.forEach((n, i) => {
    if (stay.has(i)) {
      if (!deepEqual(prev[prevIndex.get(n.h)!], n)) ops.push({ op: 'set', n: cloneNode(n) });
      return;
    }
    if (i > 0) {
      const before = next[i - 1]!;
      const last = ops[ops.length - 1];
      if (!(last && last.op === 'set' && last.n.h === before.h)) ops.push({ op: 'set', n: cloneNode(before) });
    }
    // i === 0: only `del` ops precede, so applyOps inserts at the front.
    ops.push({ op: 'set', n: cloneNode(n) });
  });
  return ops;
}

/** Apply ops (semantics above) to a copy of `nodes`. */
export function applyOps(nodes: UiNode[], ops: TreeOp[]): UiNode[] {
  const out = nodes.map(cloneNode);
  const indexOf = (h: string) => out.findIndex((n) => n.h === h);
  let lastSet: string | null = null;
  for (const op of ops) {
    if (op.op === 'del') {
      const i = indexOf(op.h);
      if (i >= 0) out.splice(i, 1);
      lastSet = null;
      continue;
    }
    if (op.op !== 'set' || !op.n || typeof op.n.h !== 'string') continue;
    const n = cloneNode(op.n);
    const i = indexOf(n.h);
    if (i >= 0) out[i] = n;
    else if (lastSet === null) out.unshift(n);
    else {
      const a = indexOf(lastSet);
      out.splice(a < 0 ? out.length : a + 1, 0, n);
    }
    lastSet = n.h;
  }
  return out;
}

// ───────────────────────────── text rendering ─────────────────────────────

const BARE = /^[A-Za-z0-9_][A-Za-z0-9_.:-]*$/;

/**
 * Page-supplied tokens are printed bare only when they cannot break the line format. What is
 * quoted is quoted with `jsonLine`: no character in it ends the line for any reader.
 */
function token(s: string): string {
  return BARE.test(s) ? s : jsonLine(s);
}

/** URLs print bare when they are printable ASCII without spaces or quotes. */
const BARE_URL = /^[!#-~]+$/;
function urlToken(s: string): string {
  return BARE_URL.test(s) ? s : jsonLine(s);
}

function nodeLine(n: UiNode): string {
  let s = `${token(String(n.h))} ${token(String(n.role))}`;
  if (n.name !== undefined && n.name !== '') s += ` ${jsonLine(String(n.name))}`;
  if (n.id !== undefined) s += ` #${token(String(n.id))}`;
  if (n.val !== undefined) s += ` = ${jsonLine(String(n.val))}`;
  if (n.st && n.st.length) s += ` [${n.st.map((x) => token(String(x))).join(' ')}]`;
  if (n.box) s += ` @${n.box.map((x) => Math.round(Number(x))).join(',')}`;
  return s;
}

/** One node per line, children indented one space per level under their `p`. */
export function renderTree(nodes: UiNode[]): string {
  const byHandle = new Map<string, UiNode>();
  for (const n of nodes) byHandle.set(n.h, n);
  const depthCache = new Map<string, number>();
  const depth = (n: UiNode): number => {
    const cached = depthCache.get(n.h);
    if (cached !== undefined) return cached;
    let d = 0;
    let cur = n;
    const seen = new Set<string>([n.h]);
    while (cur.p !== undefined && byHandle.has(cur.p) && !seen.has(cur.p)) {
      seen.add(cur.p);
      cur = byHandle.get(cur.p)!;
      d++;
    }
    depthCache.set(n.h, d);
    return d;
  };
  return nodes.map((n) => ' '.repeat(depth(n)) + nodeLine(n)).join('\n');
}

/**
 * Delta lines: `+ node` for a new handle, `~ node` for a replaced one, `- h` for a removal.
 * Given `prev` (the tree the ops apply to), sets are classified exactly and anchor sets that
 * change nothing are left out. Without `prev`, every set is shown as `~`, except a handle the
 * same ops deleted first (a move), which is shown as `~` without its `-` line.
 */
export function renderOps(ops: TreeOp[], prev?: UiNode[]): string {
  const known = prev ? new Map(prev.map((n) => [n.h, n] as const)) : null;
  const wasKnown = new Set(prev ? prev.map((n) => n.h) : []);
  const setLater = new Set<string>();
  for (const op of ops) if (op.op === 'set') setLater.add(op.n.h);
  const lines: string[] = [];
  for (const op of ops) {
    if (op.op === 'del') {
      if (!setLater.has(op.h)) lines.push(`- ${token(String(op.h))}`);
      known?.delete(op.h);
      continue;
    }
    if (known) {
      const before = known.get(op.n.h);
      if (before && deepEqual(before, op.n)) continue;
      lines.push(`${before || wasKnown.has(op.n.h) ? '~' : '+'} ${nodeLine(op.n)}`);
      known.set(op.n.h, op.n);
    } else {
      lines.push(`~ ${nodeLine(op.n)}`);
    }
  }
  return lines.join('\n');
}

/**
 * Header line, then the tree (full snapshot) or the delta lines.
 * Header: `# rev 12 | url <url> | title "<title>" | vp 1280x720`, with `| since <base>` after
 * the revision on a delta and `| paused` at the end while paused.
 */
export function renderObservation(o: Observation, prev?: UiNode[]): string {
  const parts = [`# rev ${Number(o.rev)}`];
  if (o.base !== undefined) parts.push(`since ${Number(o.base)}`);
  parts.push(`url ${urlToken(String(o.url ?? ''))}`, `title ${jsonLine(String(o.title ?? ''))}`);
  if (Array.isArray(o.vp)) parts.push(`vp ${Number(o.vp[0])}x${Number(o.vp[1])}`);
  if (o.paused) parts.push('paused');
  const head = parts.join(' | ');
  let body: string;
  if (o.ops !== undefined) body = renderOps(o.ops, prev) || '(no changes)';
  else body = renderTree(o.nodes ?? []) || '(empty)';
  return `${head}\n${body}`;
}
