/** Internal helpers shared by the core modules. Not part of the public API. */

/** Keys that can reach an object's prototype chain when assigned with `obj[key] = v`. */
export const FORBIDDEN_KEYS: ReadonlySet<string> = new Set(['__proto__', 'constructor', 'prototype']);

/** Maximum nesting depth the recursive helpers accept, so hostile input cannot exhaust the stack. */
export const MAX_DEPTH = 100;

export function isPlainObject(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

export function hasOwn(o: object, k: string): boolean {
  return Object.prototype.hasOwnProperty.call(o, k);
}

/** Read an own property only, never an inherited one (`constructor`, `toString`, ...). */
export function own<T = unknown>(o: object, k: string): T | undefined {
  return hasOwn(o, k) ? ((o as Record<string, unknown>)[k] as T) : undefined;
}

/** Assign as an own data property, so a `__proto__` key can never change a prototype. */
export function setOwn(o: Record<string, unknown>, k: string, v: unknown): void {
  Object.defineProperty(o, k, { value: v, enumerable: true, writable: true, configurable: true });
}

export function deepEqual(a: unknown, b: unknown, depth = 0): boolean {
  if (a === b) return true;
  if (depth > MAX_DEPTH) return false;
  if (typeof a !== 'object' || typeof b !== 'object' || a === null || b === null) {
    return typeof a === 'number' && typeof b === 'number' && Number.isNaN(a) && Number.isNaN(b);
  }
  if (Array.isArray(a) !== Array.isArray(b)) return false;
  if (Array.isArray(a)) {
    const bb = b as unknown[];
    if (a.length !== bb.length) return false;
    for (let i = 0; i < a.length; i++) if (!deepEqual(a[i], bb[i], depth + 1)) return false;
    return true;
  }
  const ka = Object.keys(a).filter((k) => (a as Record<string, unknown>)[k] !== undefined);
  const kb = Object.keys(b).filter((k) => (b as Record<string, unknown>)[k] !== undefined);
  if (ka.length !== kb.length) return false;
  for (const k of ka) {
    if (!hasOwn(b, k)) return false;
    if (!deepEqual((a as Record<string, unknown>)[k], (b as Record<string, unknown>)[k], depth + 1)) return false;
  }
  return true;
}

/** Deep copy of JSON-like data with own-property assignment throughout. */
export function safeClone<T>(v: T, depth = 0): T {
  if (typeof v !== 'object' || v === null) return v;
  if (depth > MAX_DEPTH) throw new RangeError('value nested too deeply');
  if (Array.isArray(v)) return v.map((x) => safeClone(x, depth + 1)) as T;
  const out: Record<string, unknown> = {};
  for (const k of Object.keys(v)) setOwn(out, k, safeClone((v as Record<string, unknown>)[k], depth + 1));
  return out as T;
}
