/**
 * Test hook: the closed shadow root behind a host. Not exported from the package entry
 * point, so a bundle of `index.ts` drops it; the WeakMap itself is module-private and
 * unreachable from page script.
 */
const shadows = new WeakMap<Element, ShadowRoot>();
export function shadowOf(host: Element): ShadowRoot | undefined {
  return shadows.get(host);
}

/**
 * Test hook, like `shadowOf`: whether the overlay behind a host can be relied on right now
 * (`Overlay.check`), and why not. `scripts/browser-check.mjs` asks a real browser this way.
 */
const checks = new WeakMap<Element, () => string>();
export function soundOf(host: Element): string | undefined {
  return checks.get(host)?.();
}

/**
 * Allow ignores activation for this long after a card appears (or moves). So does the confirm
 * button of every step that lets an agent do more without asking: "Always allow" on a card,
 * and the confirm step in the panel.
 */
export const ALLOW_ARM_MS = 500;


