/**
 * How a prompt ended: Allow, "Always allow" (allow, and the person's rule `allow` for the
 * action), an explicit refusal (Deny or Escape), the timeout, or cancelled by the driver
 * (agent detached, Stop, disconnect) without the person answering.
 */
export type ConsentOutcome = 'allow' | 'always' | 'deny' | 'timeout' | 'cancel';

/** How long a withdrawn prompt shows "Request withdrawn" before any next card. */
export const WITHDRAWN_MS = 1500;

/**
 * After a key that types (a character, Backspace or Delete, a chord with Ctrl, Alt or Meta), no
 * key answers a consent card for this long: the person is typing, and what they type is meant
 * for the page. Counted from the last such key, also one pressed just before the card came up.
 */
export const KEY_LOCK_MS = 3000;

/** Shown on a card while keys that type have locked the keyboard out of answering it. */
export const KEYS_NOTE = 'Keys do not answer this request right now, because something was just typed. Use the pointer, or wait a moment and press the key again.';

/** A key that types text or edits it, as opposed to one that moves the focus or presses a control. */
function typesText(e: KeyboardEvent, onButton: boolean): boolean {
  const k = typeof e.key === 'string' ? e.key : '';
  // A modifier by itself types nothing; the key that follows it does.
  if (k === 'Shift' || k === 'Control' || k === 'Alt' || k === 'Meta' || k === 'AltGraph' || k === 'CapsLock' || k === 'NumLock' || k === 'Fn') return false;
  if (e.ctrlKey || e.altKey || e.metaKey) return true;
  if (k === 'Backspace' || k === 'Delete' || k === 'Process' || k === 'Dead' || k === 'Unidentified' || k === '') return true;
  // Space on a button presses it; anywhere else it is a space.
  if (k === ' ' || k === 'Spacebar') return !onButton;
  return Array.from(k).length === 1;
}

/** Shown where a click was not taken because the overlay could not be relied on at that moment. */
export const HELD_NOTE = 'A click here was not taken: for a moment this page covered these controls or changed how they are shown. Check what you see, then choose again.';

