// Browser stand-in for keys.ts. Bundlers and the esbuild bundles swap it in, so no `node:`
// import can reach a page. A page has no token files: the key must be passed as `options.key`.
import { ReinsError } from '@offensiveadhd/reins/core';

/** A page cannot read a token file. Always throws E_AUTH. */
export async function readTokenFile(_path: string): Promise<string> {
  throw new ReinsError('E_AUTH', 'token files are not available in a browser: pass options.key');
}

/** A page has no environment to look in: no key. */
export async function findNodeKey(_url?: string): Promise<string | undefined> {
  return undefined;
}

/** A page cannot see the user's Reins folder: no announcement. */
export async function announcedHub(_url?: string): Promise<undefined> {
  return undefined;
}
