import { ReinsError } from './protocol.js';
import { MAX_DEPTH, deepEqual, hasOwn, isPlainObject, safeClone, setOwn } from './util.js';

/*
 * RFC 7396 JSON Merge Patch. Objects are built with own-property definitions, so a
 * `__proto__` key is kept as plain data and never reaches a prototype. Merge patch cannot
 * express a property whose value is null: such a property reads as absent.
 */

function tooDeep(): never {
  throw new ReinsError('E_BAD_ARGS', 'value nested too deeply');
}

/** Apply `patch` to `target` and return the result. Neither input is modified. */
export function mergeApply(target: unknown, patch: unknown): unknown {
  return apply(target, patch, 0);
}

function apply(target: unknown, patch: unknown, depth: number): unknown {
  if (depth > MAX_DEPTH) tooDeep();
  if (!isPlainObject(patch)) return safeCloneOrThrow(patch);
  const out: Record<string, unknown> = {};
  if (isPlainObject(target)) for (const k of Object.keys(target)) setOwn(out, k, target[k]);
  for (const k of Object.keys(patch)) {
    const v = patch[k];
    if (v === null) delete out[k];
    else if (v !== undefined) setOwn(out, k, apply(hasOwn(out, k) ? out[k] : undefined, v, depth + 1));
  }
  return out;
}

function safeCloneOrThrow<T>(v: T): T {
  try {
    return safeClone(v);
  } catch {
    tooDeep();
  }
}

/**
 * The merge patch that turns `from` into `to`, or undefined when they are equal.
 * Undefined properties count as absent, and so do properties whose value is null, in
 * `from` as in `to`; a top-level undefined `to` is `null`.
 */
export function mergeDiff(from: unknown, to: unknown): unknown {
  return diff(from, to === undefined ? null : to, 0);
}

function diff(from: unknown, to: unknown, depth: number): unknown {
  if (depth > MAX_DEPTH) tooDeep();
  if (!isPlainObject(to) || !isPlainObject(from)) return deepEqual(from, to) ? undefined : safeCloneOrThrow(to);
  const patch: Record<string, unknown> = {};
  let changed = false;
  for (const k of Object.keys(from)) {
    // A null in `from` is already absent to the reader: there is nothing to remove.
    if (from[k] !== undefined && from[k] !== null && (!hasOwn(to, k) || to[k] === undefined || to[k] === null)) {
      setOwn(patch, k, null);
      changed = true;
    }
  }
  for (const k of Object.keys(to)) {
    const t = to[k];
    if (t === undefined || t === null) continue;
    const f = hasOwn(from, k) ? from[k] : undefined;
    const d = f === undefined ? safeCloneOrThrow(t) : diff(f, t, depth + 1);
    if (d !== undefined) {
      setOwn(patch, k, d);
      changed = true;
    }
  }
  return changed ? patch : undefined;
}
