import { DEFAULT_LIMITS, ERROR_CODES, ReinsError, SUPPORTED_VERSIONS } from './protocol.js';
import type {
  ByeFrame,
  ErrorCode,
  EvtFrame,
  FlowFrame,
  Frame,
  HelloFrame,
  Limits,
  Link,
  ReqFrame,
  Role,
  SurfaceHello,
  Topic,
  WelcomeFrame,
} from './protocol.js';
import { decodeFrame, encodeFrame, utf8Length } from './codec.js';
import { hubProof, peerProof, randomToken, timingSafeEqual } from './crypto.js';
import { deriveSealKeys, peerConfirm } from './seal.js';
import type { SealKeys } from './seal.js';

export interface PeerHandlers {
  /** Answer a request. Throw a ReinsError to refuse; anything else thrown becomes `E_INTERNAL`. */
  request?(m: string, p: Record<string, unknown>, frame: ReqFrame): unknown | Promise<unknown>;
  event?(frame: EvtFrame): void;
  binary?(bytes: Uint8Array): void;
  flow?(frame: FlowFrame): void;
  /** Called once when the connection ends: the `bye` code received or sent, else `E_GONE`. */
  close?(code: ErrorCode | 'OK' | 'E_GONE', msg?: string): void;
}

function isErrorCode(c: unknown): c is ErrorCode {
  return typeof c === 'string' && (ERROR_CODES as readonly string[]).includes(c);
}

interface Pending {
  resolve(v: unknown): void;
  reject(e: ReinsError): void;
  timer: ReturnType<typeof setTimeout>;
}

/**
 * One side of an established connection: requests with ids and timeouts, events, flow
 * credit, binary frames, ping and bye. Answers `ping` itself. Closes the link on a
 * malformed or oversize frame. Pending requests fail with `E_GONE` when the link closes.
 */
export class Peer {
  #link: Link;
  #h: PeerHandlers;
  #limits: Limits;
  #now: () => number;
  #nextId = 0;
  #pending = new Map<number, Pending>();
  #pings = new Map<number, Array<{ resolve(rtt: number): void; reject(e: ReinsError): void; timer: ReturnType<typeof setTimeout> }>>();
  #closed = false;
  #closeCode: ErrorCode | 'OK' | undefined;
  #closeMsg: string | undefined;
  #lastSeen: number;
  #maxBuffered: number | undefined;
  #overflowing = false;

  /**
   * `maxBuffered`: when the link's send buffer holds more than this many bytes after a
   * send, the far end is not reading: the Peer sends `bye {code:"E_BUSY"}` and closes.
   */
  constructor(link: Link, handlers: PeerHandlers, opts: { limits?: Partial<Limits>; now?: () => number; maxBuffered?: number } = {}) {
    this.#link = link;
    this.#h = handlers;
    this.#limits = { ...DEFAULT_LIMITS, ...(opts.limits ?? {}) };
    this.#now = opts.now ?? Date.now;
    const mb = opts.maxBuffered;
    this.#maxBuffered = typeof mb === 'number' && Number.isFinite(mb) && mb > 0 ? mb : undefined;
    this.#lastSeen = this.#now();
    link.onmessage = (d) => this.#onMessage(d);
    link.onclose = () => this.#finish();
  }

  get closed(): boolean {
    return this.#closed || !this.#link.open;
  }
  /** Time (per `now`) the last frame arrived. */
  get lastSeen(): number {
    return this.#lastSeen;
  }
  get bufferedAmount(): number {
    return this.#link.bufferedAmount;
  }

  request<R = unknown>(m: string, p?: object, opts: { timeoutMs?: number; ag?: string; c?: 1 } = {}): Promise<R> {
    if (this.closed) return Promise.reject(new ReinsError('E_GONE', 'connection closed'));
    const id = ++this.#nextId;
    const frame: ReqFrame = { t: 'req', id, m };
    if (p !== undefined) frame.p = p as Record<string, unknown>;
    if (opts.ag !== undefined) frame.ag = opts.ag;
    if (opts.c === 1) frame.c = 1;
    let text: string;
    try {
      text = encodeFrame(frame);
    } catch {
      return Promise.reject(new ReinsError('E_BAD_ARGS', 'params are not JSON'));
    }
    if (utf8Length(text) > this.#limits.maxText) return Promise.reject(new ReinsError('E_TOO_LARGE', 'request too large'));
    const timeoutMs = opts.timeoutMs ?? this.#limits.reqTimeoutMs;
    return new Promise<R>((resolve, reject) => {
      const timer = setTimeout(() => {
        this.#pending.delete(id);
        reject(new ReinsError('E_TIMEOUT', `${m} timed out`));
      }, timeoutMs);
      this.#pending.set(id, { resolve: resolve as (v: unknown) => void, reject, timer });
      this.#send(text);
    });
  }

  event(topic: Topic, d?: unknown, extra: { s?: string; ag?: string } = {}): void {
    const f: EvtFrame = { t: 'evt', topic };
    if (extra.s !== undefined) f.s = extra.s;
    if (extra.ag !== undefined) f.ag = extra.ag;
    if (d !== undefined) f.d = d;
    this.#sendFrame(f, true);
  }

  sendBinary(bytes: Uint8Array): void {
    if (this.closed) return;
    if (bytes.length > this.#limits.maxBinary) throw new ReinsError('E_TOO_LARGE', 'binary frame too large');
    this.#send(bytes);
  }

  flow(ch: number, credit: number): void {
    this.#sendFrame({ t: 'flow', ch, credit }, true);
  }

  /** Round-trip time in ms. Rejects with `E_TIMEOUT` or `E_GONE`. */
  ping(timeoutMs: number = this.#limits.reqTimeoutMs): Promise<number> {
    if (this.closed) return Promise.reject(new ReinsError('E_GONE', 'connection closed'));
    const ts = this.#now();
    return new Promise<number>((resolve, reject) => {
      const list = this.#pings.get(ts) ?? [];
      const entry = {
        resolve,
        reject,
        timer: setTimeout(() => {
          const l = this.#pings.get(ts);
          if (l) {
            const i = l.indexOf(entry);
            if (i >= 0) l.splice(i, 1);
            if (!l.length) this.#pings.delete(ts);
          }
          reject(new ReinsError('E_TIMEOUT', 'ping timed out'));
        }, timeoutMs),
      };
      list.push(entry);
      this.#pings.set(ts, list);
      this.#sendFrame({ t: 'ping', ts }, false);
    });
  }

  /** Send `bye` and close. */
  bye(code: ErrorCode | 'OK' = 'OK', msg?: string): void {
    if (this.closed) return;
    const f: ByeFrame = { t: 'bye', code };
    if (msg !== undefined) f.msg = msg;
    this.#sendFrame(f, false);
    this.#closeCode = code;
    this.#closeMsg = msg;
    this.#link.close();
    this.#finish();
  }

  #sendFrame(f: Frame, checkSize: boolean): void {
    if (this.closed) return;
    const text = encodeFrame(f);
    if (checkSize && utf8Length(text) > this.#limits.maxText) throw new ReinsError('E_TOO_LARGE', 'frame too large');
    this.#send(text);
  }

  /** Put a message on the link, then close if the far end has stopped reading. */
  #send(data: string | Uint8Array): void {
    this.#link.send(data);
    if (this.#maxBuffered === undefined || this.#overflowing || this.#link.bufferedAmount <= this.#maxBuffered) return;
    this.#overflowing = true;
    this.bye('E_BUSY', 'not reading: send buffer full');
  }

  #onMessage(data: string | Uint8Array): void {
    if (this.#closed) return;
    this.#lastSeen = this.#now();
    if (typeof data !== 'string') {
      if (data.length > this.#limits.maxBinary) return this.bye('E_TOO_LARGE', 'binary frame too large');
      this.#safe(() => this.#h.binary?.(data));
      return;
    }
    let f: Frame;
    try {
      f = decodeFrame(data, this.#limits.maxText);
    } catch (e) {
      const code = e instanceof ReinsError ? e.code : 'E_BAD_FRAME';
      return this.bye(code, code === 'E_TOO_LARGE' ? 'frame too large' : 'malformed frame');
    }
    switch (f.t) {
      case 'req':
        void this.#serve(f);
        return;
      case 'res': {
        const p = this.#pending.get(f.re);
        if (!p) return;
        this.#pending.delete(f.re);
        clearTimeout(p.timer);
        if (f.ok) p.resolve(f.r);
        else p.reject(new ReinsError(isErrorCode(f.e.code) ? f.e.code : 'E_INTERNAL', String(f.e.msg), f.e.data));
        return;
      }
      case 'evt':
        this.#safe(() => this.#h.event?.(f));
        return;
      case 'flow':
        this.#safe(() => this.#h.flow?.(f));
        return;
      case 'ping':
        this.#sendFrame({ t: 'pong', ts: f.ts }, false);
        return;
      case 'pong': {
        const list = this.#pings.get(f.ts);
        if (!list) return;
        this.#pings.delete(f.ts);
        const rtt = Math.max(0, this.#now() - f.ts);
        for (const w of list) {
          clearTimeout(w.timer);
          w.resolve(rtt);
        }
        return;
      }
      case 'bye':
        this.#closeCode = f.code === 'OK' || isErrorCode(f.code) ? f.code : 'E_GONE';
        this.#closeMsg = f.msg;
        this.#link.close();
        this.#finish();
        return;
      default:
        // Handshake frames after the handshake are a protocol violation.
        this.bye('E_BAD_FRAME', 'unexpected frame');
    }
  }

  async #serve(f: ReqFrame): Promise<void> {
    let res: Frame;
    try {
      if (!this.#h.request) throw new ReinsError('E_UNKNOWN_METHOD', `unknown method ${f.m.slice(0, 64)}`);
      const r = await this.#h.request(f.m, f.p ?? {}, f);
      res = r === undefined ? { t: 'res', re: f.id, ok: true } : { t: 'res', re: f.id, ok: true, r };
    } catch (e) {
      const err = e instanceof ReinsError ? e : new ReinsError('E_INTERNAL', 'internal error');
      res = { t: 'res', re: f.id, ok: false, e: err.toWire() };
    }
    if (this.closed) return;
    let text: string;
    try {
      text = encodeFrame(res);
    } catch {
      text = encodeFrame({ t: 'res', re: f.id, ok: false, e: { code: 'E_INTERNAL', msg: 'result is not JSON' } });
    }
    if (utf8Length(text) > this.#limits.maxText) text = encodeFrame({ t: 'res', re: f.id, ok: false, e: { code: 'E_TOO_LARGE', msg: 'result too large' } });
    this.#send(text);
  }

  #safe(fn: () => void): void {
    try {
      fn();
    } catch {
      // A failing handler must not take the connection down.
    }
  }

  #finish(): void {
    if (this.#closed) return;
    this.#closed = true;
    const gone = () => new ReinsError('E_GONE', 'connection closed');
    for (const p of this.#pending.values()) {
      clearTimeout(p.timer);
      p.reject(gone());
    }
    this.#pending.clear();
    for (const list of this.#pings.values()) {
      for (const w of list) {
        clearTimeout(w.timer);
        w.reject(gone());
      }
    }
    this.#pings.clear();
    const code = this.#closeCode ?? 'E_GONE';
    this.#safe(() => this.#h.close?.(code, this.#closeMsg));
  }
}

/**
 * Peer side of an unauthenticated handshake: wait for `challenge`, pick a version, send
 * `hello`, wait for `welcome` or `bye`. On failure it sends `bye` where appropriate, closes
 * the link and throws a ReinsError. On success `link.onmessage` and `link.onclose` are left
 * null, so later frames stay queued for the Peer created next.
 *
 * It does not authenticate: given a `key` it rejects with `E_BAD_ARGS` without touching the
 * link. A keyed session must be sealed and confirmed: use `clientConnect`.
 */
export function clientHandshake(
  link: Link,
  hello: { role: Role; name: string; kid?: string; key?: string; surface?: SurfaceHello },
  opts: { timeoutMs?: number } = {},
): Promise<WelcomeFrame> {
  if (hello.key !== undefined) {
    return Promise.reject(new ReinsError('E_BAD_ARGS', 'clientHandshake does not seal an authenticated session: use clientConnect with a key'));
  }
  return runHandshake(link, hello, opts).then((r) => r.welcome);
}

/**
 * Connect as a peer. Runs the handshake (with an auth proof when `key` is given; `kid`
 * defaults to `default`) and verifies the hub's proof. With a key it then seals the
 * session: derives the seal keys (side `peer`) from the key, the nonces and the exact
 * `hello` and `welcome` texts, sends a sealed `ping {ts}` and resolves only once the hub's
 * sealed `pong {ts}` verifies, so both ends saw the same handshake before anything in
 * `welcome` is trusted. A hub that does not confirm within `confirmTimeoutMs` (default
 * SEAL_CONFIRM_MS) fails with `E_AUTH` and the link is closed. Without a key it returns
 * the same link, unsealed. Build the Peer on the returned `link`: frames the hub sends
 * after its pong stay queued on it.
 */
export async function clientConnect(
  link: Link,
  hello: { role: Role; name: string; kid?: string; key?: string; surface?: SurfaceHello },
  opts: { timeoutMs?: number; confirmTimeoutMs?: number } = {},
): Promise<{ welcome: WelcomeFrame; link: Link; sealed: boolean }> {
  const r = await runHandshake(link, hello, opts);
  if (hello.key === undefined) return { welcome: r.welcome, link, sealed: false };
  let keys: SealKeys;
  try {
    keys = await deriveSealKeys(hello.key, r, 'peer');
  } catch {
    link.close();
    throw new ReinsError('E_AUTH', 'could not derive session keys');
  }
  const sealed = await peerConfirm(link, keys, opts.confirmTimeoutMs);
  return { welcome: r.welcome, link: sealed, sealed: true };
}

interface HandshakeResult {
  welcome: WelcomeFrame;
  nonce: string;
  cnonce: string;
  challengeText: string;
  helloText: string;
  welcomeText: string;
}

function runHandshake(
  link: Link,
  hello: { role: Role; name: string; kid?: string; key?: string; surface?: SurfaceHello },
  opts: { timeoutMs?: number },
): Promise<HandshakeResult> {
  const timeoutMs = opts.timeoutMs ?? 10_000;
  return new Promise<HandshakeResult>((resolve, reject) => {
    let done = false;
    let stage: 'challenge' | 'welcome' = 'challenge';
    let sent: { v: string; kid: string; nonce: string; cnonce: string; challengeText: string; helloText: string } | undefined;

    const finish = () => {
      done = true;
      clearTimeout(timer);
      link.onmessage = null;
      link.onclose = null;
    };
    const fail = (code: ErrorCode, msg: string, sendBye: boolean) => {
      if (done) return;
      finish();
      if (sendBye && link.open) {
        try {
          link.send(encodeFrame({ t: 'bye', code, msg }));
        } catch {
          // ignore
        }
      }
      link.close();
      reject(new ReinsError(code, msg));
    };
    const timer = setTimeout(() => fail('E_TIMEOUT', 'handshake timed out', true), timeoutMs);

    const onFrame = async (data: string | Uint8Array): Promise<void> => {
      if (typeof data !== 'string') return fail('E_BAD_FRAME', 'unexpected binary frame', true);
      let f: Frame;
      try {
        f = decodeFrame(data, DEFAULT_LIMITS.maxText);
      } catch (e) {
        const code = e instanceof ReinsError ? e.code : 'E_BAD_FRAME';
        return fail(code, code === 'E_TOO_LARGE' ? 'frame too large' : 'malformed frame', true);
      }
      if (f.t === 'bye') {
        const code: ErrorCode = isErrorCode(f.code) ? f.code : 'E_GONE';
        return fail(code, f.msg ? f.msg.slice(0, 200) : 'refused by hub', false);
      }
      if (stage === 'challenge') {
        if (f.t !== 'challenge') return fail('E_BAD_FRAME', 'expected challenge', true);
        const v = f.v.find((x) => SUPPORTED_VERSIONS.includes(x));
        if (v === undefined) return fail('E_VERSION', 'no common protocol version', true);
        const cnonce = randomToken(32);
        const kid = hello.kid ?? 'default';
        const frame: HelloFrame = { t: 'hello', v, role: hello.role, name: hello.name, cnonce };
        if (hello.key !== undefined) frame.auth = { kid, proof: await peerProof(hello.key, { role: hello.role, kid, nonce: f.nonce, cnonce }) };
        if (hello.surface !== undefined) frame.surface = hello.surface;
        if (done) return;
        const helloText = encodeFrame(frame);
        sent = { v, kid, nonce: f.nonce, cnonce, challengeText: data, helloText };
        stage = 'welcome';
        link.send(helloText);
        return;
      }
      if (f.t !== 'welcome' || !sent) return fail('E_BAD_FRAME', 'expected welcome', true);
      if (f.v !== sent.v) return fail('E_VERSION', 'hub answered with another version', true);
      if (f.role !== hello.role) return fail('E_BAD_FRAME', 'hub answered with another role', true);
      if (hello.key !== undefined) {
        if (typeof f.proof !== 'string') return fail('E_AUTH', 'hub did not prove the key', true);
        const expected = await hubProof(hello.key, { role: hello.role, kid: sent.kid, nonce: sent.nonce, cnonce: sent.cnonce });
        if (!timingSafeEqual(f.proof, expected)) return fail('E_AUTH', 'hub proof mismatch', true);
      }
      if (done) return;
      finish();
      resolve({ welcome: f, nonce: sent.nonce, cnonce: sent.cnonce, challengeText: sent.challengeText, helloText: sent.helloText, welcomeText: data });
    };

    const handler = (data: string | Uint8Array) => {
      // Hold later frames in the link's queue while this one is processed.
      link.onmessage = null;
      onFrame(data)
        .catch(() => fail('E_INTERNAL', 'handshake failed', true))
        .finally(() => {
          if (!done) link.onmessage = handler;
        });
    };
    link.onclose = () => fail('E_GONE', 'connection closed during handshake', false);
    link.onmessage = handler;
  });
}
