import { MAX_ACTIONS, MAX_MANIFEST_BYTES, MAX_VIEWS, NAME_PATTERN, POLICY_PRESETS, ReinsError } from './protocol.js';
import type { ActionDef, AppInfo, Exposure, Manifest, Policy, PolicyProfile, Risk, Schema, Scope, StateDef, SurfaceInfo, ViewDef } from './protocol.js';
import { utf8Length } from './codec.js';
import { sha256 } from './crypto.js';
import { capScopes, decideAction } from './policy.js';
import { checkSchema, schemaSignature } from './schema.js';
import { MAX_DEPTH, hasOwn, isPlainObject } from './util.js';

// ───────────────────────────── canonical JSON ─────────────────────────────

/**
 * JSON with object keys sorted by UTF-16 code units and no whitespace. Follows
 * `JSON.stringify` for values it cannot represent (undefined properties are left out,
 * undefined array items and non-finite numbers become null, `toJSON` is honoured).
 * A top-level undefined is `null`. Cycles, BigInt and nesting deeper than 100 throw `E_BAD_ARGS`.
 */
export function canonicalJson(v: unknown): string {
  const out = canon(v, 0, new Set());
  return out === undefined ? 'null' : out;
}

function canon(v: unknown, depth: number, stack: Set<object>): string | undefined {
  if (v === null) return 'null';
  if (typeof v === 'object' && typeof (v as { toJSON?: unknown }).toJSON === 'function') v = (v as { toJSON(): unknown }).toJSON();
  switch (typeof v) {
    case 'string':
      return JSON.stringify(v);
    case 'number':
      return Number.isFinite(v) ? JSON.stringify(v) : 'null';
    case 'boolean':
      return v ? 'true' : 'false';
    case 'undefined':
    case 'function':
    case 'symbol':
      return undefined;
    case 'bigint':
      throw new ReinsError('E_BAD_ARGS', 'value is not JSON');
  }
  if (v === null) return 'null';
  const o = v as object;
  if (depth > MAX_DEPTH) throw new ReinsError('E_BAD_ARGS', 'value nested too deeply');
  if (stack.has(o)) throw new ReinsError('E_BAD_ARGS', 'value is cyclic');
  stack.add(o);
  let out: string;
  if (Array.isArray(o)) {
    out = `[${o.map((x) => canon(x, depth + 1, stack) ?? 'null').join(',')}]`;
  } else {
    const parts: string[] = [];
    for (const k of Object.keys(o).sort()) {
      const s = canon((o as Record<string, unknown>)[k], depth + 1, stack);
      if (s !== undefined) parts.push(`${JSON.stringify(k)}:${s}`);
    }
    out = `{${parts.join(',')}}`;
  }
  stack.delete(o);
  return out;
}

// ───────────────────────────── validation ─────────────────────────────

const APP_ID = /^[a-z][a-z0-9_-]*(\.[a-z][a-z0-9_-]*)*$/;
const RISKS: readonly Risk[] = ['safe', 'sensitive', 'dangerous'];
const EXPOSURES: readonly Exposure[] = ['auto', 'annotated', 'none'];
const PROFILES: readonly PolicyProfile[] = ['open', 'guarded', 'kiosk'];
const MAX_NAME_LEN = 64;

function bad(path: string, why: string): never {
  throw new ReinsError('E_BAD_ARGS', `manifest${path}: ${why}`);
}
function reqStr(o: Record<string, unknown>, k: string, path: string): string {
  const v = hasOwn(o, k) ? o[k] : undefined;
  if (typeof v !== 'string') bad(`${path}.${k}`, 'must be a string');
  return v;
}
function optStr(o: Record<string, unknown>, k: string, path: string): string | undefined {
  const v = hasOwn(o, k) ? o[k] : undefined;
  if (v === undefined) return undefined;
  if (typeof v !== 'string') bad(`${path}.${k}`, 'must be a string');
  return v;
}
function name(o: Record<string, unknown>, path: string, seen: Set<string>): string {
  const n = reqStr(o, 'name', path);
  if (n.length > MAX_NAME_LEN || !NAME_PATTERN.test(n)) bad(`${path}.name`, 'invalid name');
  if (seen.has(n)) bad(`${path}.name`, 'duplicate name');
  seen.add(n);
  return n;
}
function list(m: Record<string, unknown>, k: string, max: number): Record<string, unknown>[] {
  const v = hasOwn(m, k) ? m[k] : undefined;
  if (!Array.isArray(v)) bad(`.${k}`, 'must be an array');
  if (v.length > max) throw new ReinsError('E_TOO_LARGE', `manifest.${k}: more than ${max} entries`);
  v.forEach((x, i) => {
    if (!isPlainObject(x)) bad(`.${k}[${i}]`, 'must be an object');
  });
  return v as Record<string, unknown>[];
}
function params(o: Record<string, unknown>, path: string, mustBeObject: boolean): Schema | undefined {
  const s = hasOwn(o, 'params') ? o.params : undefined;
  if (s === undefined) return undefined;
  const err = checkSchema(s);
  if (err) bad(`${path}.params`, err.replace(/^\$/, 'schema'));
  if (mustBeObject && (s as Schema).type !== 'object') bad(`${path}.params`, 'must be an object schema');
  return s as Schema;
}

/**
 * Validate a manifest and return a clean copy holding only the defined fields.
 * Throws `E_TOO_LARGE` over 64 KiB, 256 actions or 64 views, `E_BAD_ARGS` otherwise.
 */
export function validateManifest(m: unknown): Manifest {
  if (!isPlainObject(m)) bad('', 'must be an object');
  let text: string;
  try {
    text = canonicalJson(m);
  } catch {
    bad('', 'must be JSON');
  }
  if (utf8Length(text) > MAX_MANIFEST_BYTES) throw new ReinsError('E_TOO_LARGE', 'manifest larger than 64 KiB');

  const reins = reqStr(m, 'reins', '');
  if (reins.length === 0 || reins.length > 16) bad('.reins', 'invalid version');

  const a = hasOwn(m, 'app') ? m.app : undefined;
  if (!isPlainObject(a)) bad('.app', 'must be an object');
  const app: AppInfo = { id: reqStr(a, 'id', '.app'), name: reqStr(a, 'name', '.app') };
  if (app.id.length > MAX_NAME_LEN || !APP_ID.test(app.id)) bad('.app.id', 'invalid id');
  if (app.name.trim().length === 0) bad('.app.name', 'must not be empty');
  const version = optStr(a, 'version', '.app');
  if (version !== undefined) app.version = version;
  const description = optStr(a, 'description', '.app');
  if (description !== undefined) app.description = description;

  const seenA = new Set<string>();
  const actions: ActionDef[] = list(m, 'actions', MAX_ACTIONS).map((x, i) => {
    const path = `.actions[${i}]`;
    const def: ActionDef = { name: name(x, path, seenA), description: reqStr(x, 'description', path), risk: x.risk as Risk };
    if (!RISKS.includes(def.risk)) bad(`${path}.risk`, 'must be safe, sensitive or dangerous');
    const p = params(x, path, true);
    if (p !== undefined) def.params = p;
    const returns = optStr(x, 'returns', path);
    if (returns !== undefined) def.returns = returns;
    return def;
  });

  const seenV = new Set<string>();
  const views: ViewDef[] = list(m, 'views', MAX_VIEWS).map((x, i) => {
    const path = `.views[${i}]`;
    const def: ViewDef = { name: name(x, path, seenV), description: reqStr(x, 'description', path) };
    const p = params(x, path, false);
    if (p !== undefined) def.params = p;
    return def;
  });

  const seenS = new Set<string>();
  const state: StateDef[] = list(m, 'state', MAX_ACTIONS).map((x, i) => {
    const path = `.state[${i}]`;
    const def: StateDef = { name: name(x, path, seenS) };
    const d = optStr(x, 'description', path);
    if (d !== undefined) def.description = d;
    return def;
  });

  const exposure = m.exposure as Exposure;
  if (!EXPOSURES.includes(exposure)) bad('.exposure', 'must be auto, annotated or none');
  const profile = m.profile as PolicyProfile;
  if (!PROFILES.includes(profile)) bad('.profile', 'must be open, guarded or kiosk');

  // Schemas came from parsed JSON and were checked; copy them so the result shares nothing with the input.
  return JSON.parse(JSON.stringify({ reins, app, actions, views, state, exposure, profile })) as Manifest;
}

/** base64url SHA-256 of the manifest's canonical JSON. */
export function manifestDigest(m: Manifest): Promise<string> {
  return sha256(canonicalJson(m));
}

// ───────────────────────────── prompt card ─────────────────────────────

/** One line of free text: control characters and runs of whitespace become one space. */
function line(s: string | undefined): string {
  // eslint-disable-next-line no-control-regex
  return (s ?? '').replace(/[\u0000-\u001f\u007f-\u009f\u2028\u2029\s]+/g, ' ').trim();
}

/**
 * The prompt card (SPEC section 7). Decision tags come from `ctx.policy` when given,
 * else from the preset named by `manifest.profile`. `allow` has no tag.
 */
export function renderCard(m: Manifest, ctx: { surface?: SurfaceInfo; scopes?: Scope[]; policy?: Policy } = {}): string {
  const policy = ctx.policy ?? POLICY_PRESETS[m.profile] ?? POLICY_PRESETS.guarded;
  const out: string[] = [];

  let head = '# Reins surface';
  if (ctx.surface) head += ` ${line(ctx.surface.s)}`;
  head += `: ${line(m.app.name)}`;
  if (m.app.version) head += ` ${line(m.app.version)}`;
  head += ` (${line(m.app.id)})`;
  out.push(head);
  if (m.app.description && line(m.app.description)) out.push(line(m.app.description));

  const meta: string[] = [];
  if (ctx.surface) meta.push(`origin ${line(ctx.surface.origin)}`);
  meta.push(`profile ${policy.profile}`);
  if (ctx.scopes) meta.push(`scopes ${capScopes(ctx.scopes).join(' ')}`);
  out.push(meta.join(' | '));
  out.push('Prefer actions over ui ops. [confirm] asks the user on screen. [deny] is blocked.');

  if (m.actions.length) {
    out.push('', '## actions');
    for (const a of m.actions) {
      let s = `${a.name}${schemaSignature(a.params)}`;
      if (a.returns && line(a.returns)) s += ` -> ${line(a.returns)}`;
      const d = decideAction(policy, a);
      if (d !== 'allow') s += ` [${d}]`;
      if (line(a.description)) s += `. ${line(a.description)}`;
      out.push(s);
    }
  }
  if (m.views.length) {
    out.push('', '## views');
    for (const v of m.views) {
      let s = `${v.name}${schemaSignature(v.params)}`;
      if (line(v.description)) s += `. ${line(v.description)}`;
      out.push(s);
    }
  }
  if (m.state.length) {
    out.push('', '## state');
    for (const st of m.state) out.push(line(st.description) ? `${st.name}: ${line(st.description)}` : st.name);
  }
  return out.join('\n');
}
