import { PTR_INITIAL_CREDIT } from './protocol.js';
import type { PointerPoint } from './protocol.js';

function finiteNonNeg(v: number | undefined, fallback: number): number {
  return typeof v === 'number' && Number.isFinite(v) && v >= 0 ? v : fallback;
}

/** Token bucket: refills at `ratePerSec`, holds at most `burst` (default one second's worth). Starts full. */
export class TokenBucket {
  #rate: number;
  #burst: number;
  #tokens: number;
  #last: number;
  #now: () => number;

  constructor(ratePerSec: number, burst?: number, now: () => number = Date.now) {
    this.#rate = finiteNonNeg(ratePerSec, 0);
    this.#burst = finiteNonNeg(burst, this.#rate);
    this.#tokens = this.#burst;
    this.#now = now;
    this.#last = now();
  }

  /** Take `n` tokens if available. */
  take(n = 1): boolean {
    const t = this.#now();
    const elapsed = Math.max(0, t - this.#last);
    this.#last = t;
    this.#tokens = Math.min(this.#burst, this.#tokens + (elapsed * this.#rate) / 1000);
    if (!(n >= 0)) return false;
    if (this.#tokens + 1e-9 >= n) {
      this.#tokens = Math.max(0, this.#tokens - n);
      return true;
    }
    return false;
  }
}

/** Sender side of a credit window: never more outstanding units than granted. */
export class CreditWindow {
  #available: number;
  constructor(initial: number = PTR_INITIAL_CREDIT) {
    this.#available = finiteNonNeg(initial, 0);
  }
  get available(): number {
    return this.#available;
  }
  /** Spend `n` units if the window allows it; otherwise spend nothing. */
  consume(n: number): boolean {
    if (!(Number.isFinite(n) && n >= 0) || n > this.#available) return false;
    this.#available -= n;
    return true;
  }
  grant(n: number): void {
    if (Number.isFinite(n) && n > 0) this.#available += n;
  }
}

/** Receiver side: batches returned credit, releasing it once a quarter of the window has been consumed. */
export class CreditGranter {
  #threshold: number;
  #pending = 0;
  constructor(window: number) {
    this.#threshold = Math.max(1, Math.ceil(finiteNonNeg(window, 0) / 4));
  }
  /** Record `n` consumed units. Returns the credit to send now, or 0. */
  consumed(n: number): number {
    if (Number.isFinite(n) && n > 0) this.#pending += n;
    if (this.#pending < this.#threshold) return 0;
    const c = this.#pending;
    this.#pending = 0;
    return c;
  }
}

const MAX_DT = 0xffff;

/**
 * Bounded sender backlog. On overflow it drops every second interior point and folds the
 * dropped `dt` into the following point, so the stroke keeps its shape and total duration.
 * The first and last queued points are never dropped, nor a point whose fold would overflow 65535 ms.
 */
export class PointerCoalescer {
  #max: number;
  #queue: PointerPoint[] = [];
  #dropped = 0;

  constructor(maxBacklog = 1024) {
    this.#max = Math.max(3, Math.floor(finiteNonNeg(maxBacklog, 1024)));
  }
  get size(): number {
    return this.#queue.length;
  }
  get dropped(): number {
    return this.#dropped;
  }

  push(p: PointerPoint): void {
    this.#queue.push({ x: p.x, y: p.y, dt: p.dt });
    if (this.#queue.length > this.#max) this.#coalesce();
  }

  take(max: number): PointerPoint[] {
    const n = Math.max(0, Math.min(this.#queue.length, Math.floor(Number.isFinite(max) ? max : 0)));
    return this.#queue.splice(0, n);
  }

  #coalesce(): void {
    const q = this.#queue;
    const out: PointerPoint[] = [q[0]!];
    let i = 1;
    for (; i < q.length - 1; i += 2) {
      const drop = q[i]!;
      const next = q[i + 1]!;
      if (drop.dt + next.dt <= MAX_DT) {
        next.dt += drop.dt;
        this.#dropped++;
      } else out.push(drop);
      out.push(next);
    }
    // With an even interior count the last step pushes q[length-1]; otherwise add it here.
    if (out[out.length - 1] !== q[q.length - 1]) out.push(q[q.length - 1]!);
    this.#queue = out;
  }
}

/** Playback speed for a receiver queue holding `queuedMs` of motion: 1 up to 120 ms, linear to 4 at 600 ms. */
export function playbackRate(queuedMs: number): number {
  if (!(queuedMs > 120)) return 1;
  if (queuedMs >= 600) return 4;
  return 1 + (3 * (queuedMs - 120)) / 480;
}
