/**
 * The UI tree (SPEC section 10): which elements are exposed, how they are described,
 * their handles, visible text for `read`, and target resolution.
 *
 * Everything read from the page here is untrusted data. Nothing in this module builds a
 * selector from page or agent strings: lookups compare attribute values directly.
 */
import { MAX_NAME_CHARS, MAX_VALUE_CHARS, ReinsError } from '@offensiveadhd/reins/core';
import type { Exposure, UiNode, UiState } from '@offensiveadhd/reins/core';

/** Upper bounds that keep one observation well inside a 256 KiB frame (SPEC rule 12). */
export const MAX_NODES = 1500;
const MAX_TREE_BYTES = 180_000;
const MAX_DEPTH = 256;
const MAX_ID_CHARS = 120;

const SKIP_TAGS = new Set(['script', 'style', 'template', 'noscript', 'head', 'meta', 'link', 'title', 'base', 'iframe', 'object', 'embed', 'frame', 'frameset', 'datalist']);
const PRIVATE_AUTOCOMPLETE = new Set(['cc-number', 'cc-csc', 'cc-exp', 'cc-exp-month', 'cc-exp-year', 'one-time-code', 'current-password', 'new-password']);
const INTERACTIVE_ROLES = new Set([
  'button', 'link', 'checkbox', 'radio', 'switch', 'tab', 'menuitem', 'menuitemcheckbox', 'menuitemradio', 'option',
  'textbox', 'searchbox', 'combobox', 'slider', 'spinbutton', 'listbox', 'treeitem', 'gridcell', 'scrollbar',
]);
const LANDMARK_ROLES = new Set(['navigation', 'main', 'complementary', 'banner', 'contentinfo', 'region', 'search', 'form']);
/** Roles whose accessible name never comes from their content. */
const NO_CONTENT_NAME = new Set([
  'textbox', 'searchbox', 'combobox', 'listbox', 'slider', 'spinbutton', 'dialog', 'alertdialog', 'navigation', 'main',
  'complementary', 'banner', 'contentinfo', 'region', 'search', 'form', 'group', 'list', 'table', 'img', 'progressbar', 'meter', 'tree', 'grid', 'tablist', 'menu', 'menubar', 'toolbar', 'radiogroup',
]);
const BLOCK_TAGS = new Set([
  'address', 'article', 'aside', 'blockquote', 'dd', 'details', 'dialog', 'div', 'dl', 'dt', 'fieldset', 'figcaption', 'figure', 'footer', 'form',
  'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'header', 'hr', 'li', 'main', 'nav', 'ol', 'p', 'pre', 'section', 'summary', 'table', 'tr', 'ul', 'caption', 'legend', 'option',
]);
const INLINE_FORMAT = new Set(['b', 'i', 'em', 'strong', 'u', 's', 'small', 'sub', 'sup', 'mark', 'abbr', 'code', 'kbd', 'q', 'cite', 'dfn', 'var', 'time', 'bdi', 'bdo', 'wbr', 'del', 'ins']);
const TEXT_INPUT_TYPES = new Set(['', 'text', 'search', 'email', 'tel', 'url', 'password', 'number']);
const NO_VALUE_INPUT_TYPES = new Set(['checkbox', 'radio', 'button', 'submit', 'reset', 'image', 'file', 'hidden']);

export function collapse(s: string): string {
  return s.replace(/\s+/g, ' ').trim();
}
export function clip(s: string, max: number): string {
  if (s.length <= max) return s;
  // Do not split a surrogate pair.
  let end = max;
  const c = s.charCodeAt(end - 1);
  if (c >= 0xd800 && c <= 0xdbff) end--;
  return s.slice(0, end);
}

/**
 * Privacy is sticky: every element ever classified private stays private for its lifetime,
 * so a page's own "show password" toggle (type=password to type=text), or a script that
 * drops `autocomplete` or `data-reins="private"`, does not expose it afterwards.
 */
const privateSeen = new WeakSet<Element>();
/** Elements classified private as a field (password type, private autocomplete), not by a marker. */
const fieldSeen = new WeakSet<Element>();

/** Remember `el` as private for the rest of its lifetime (`field`: as a private field). */
export function markPrivate(el: Element, field = false): void {
  privateSeen.add(el);
  if (field) fieldSeen.add(el);
}

function privateFieldNow(el: Element): boolean {
  if (el.localName === 'input' && ((el as HTMLInputElement).type || '').toLowerCase() === 'password') return true;
  const ac = el.getAttribute('autocomplete');
  if (ac) for (const t of ac.toLowerCase().split(/\s+/)) if (PRIVATE_AUTOCOMPLETE.has(t)) return true;
  return false;
}

/**
 * Private text-entry fields that left the document, so that a "show password" toggle that
 * swaps the node for a fresh `type=text` one does not expose the value: a text entry seen
 * later with the same non-empty `id`, `name` or `data-reins-id`, or one inserted under the
 * same parent within SWAP_MS, is private for its lifetime. Bounded to the last MAX_GONE.
 */
interface Gone {
  id: string;
  name: string;
  rid: string;
  parent: Element | null;
  at: number;
}
const gone: Gone[] = [];
const MAX_GONE = 32;
const SWAP_MS = 1000;
const TEXT_ENTRY_SELECTOR = 'input,textarea,[contenteditable]';

function matchesGone(el: Element): boolean {
  const id = el.getAttribute('id') || '';
  const name = el.getAttribute('name') || '';
  const rid = el.getAttribute('data-reins-id') || '';
  return gone.some((g) => (g.id !== '' && g.id === id) || (g.name !== '' && g.name === name) || (g.rid !== '' && g.rid === rid));
}

function withTextEntries(node: Element): Element[] {
  const out: Element[] = [node];
  try {
    out.push(...Array.from(node.querySelectorAll(TEXT_ENTRY_SELECTOR)));
  } catch {
    // ignore
  }
  return out.filter((e) => isTextEntry(e));
}

/** `node` was removed from `parent`: remember the private text entries it took along. */
export function notePrivateRemoved(node: Element, parent: Element | null): void {
  if (node.nodeType !== 1) return;
  const parentPrivate = parent !== null && isPrivate(parent);
  for (const e of withTextEntries(node)) {
    if (!(parentPrivate || privateSeen.has(e) || isPrivate(e))) continue;
    gone.push({
      id: e.getAttribute('id') || '',
      name: e.getAttribute('name') || '',
      rid: e.getAttribute('data-reins-id') || '',
      parent: e === node ? parent : e.parentElement,
      at: Date.now(),
    });
    if (gone.length > MAX_GONE) gone.shift();
  }
}

/** `node` was inserted under `parent`: classify it, including as a swapped-in private field. */
export function notePrivateAdded(node: Element, parent: Element | null): void {
  if (node.nodeType !== 1) return;
  if (gone.length) {
    const now = Date.now();
    const swapped = parent !== null && gone.some((g) => g.parent === parent && now - g.at <= SWAP_MS);
    for (const e of withTextEntries(node)) if (swapped || matchesGone(e)) markSwapped(e);
  }
  notePrivate(node);
}

/** A private field: now (password type, private autocomplete token) or at any time before. */
export function isPrivateField(el: Element): boolean {
  if (privateSeen.has(el)) return true;
  if (privateFieldNow(el)) {
    privateSeen.add(el);
    fieldSeen.add(el);
    return true;
  }
  if (gone.length && isTextEntry(el) && matchesGone(el)) {
    markSwapped(el);
    return true;
  }
  return false;
}

/**
 * Private only as a field (a password or private-autocomplete input outside any private
 * subtree): such a node may still be named by its own attributes and its (non-private)
 * labels. Any other private node is named by `data-reins-label` alone.
 */
function privateAsFieldOnly(el: Element): boolean {
  if (!fieldSeen.has(el) && !privateFieldNow(el)) return false;
  if (el.getAttribute('data-reins') === 'private') return false;
  // An ancestor marked now, or remembered as private (not as a field), is a private subtree.
  for (let e = el.parentElement; e; e = e.parentElement) {
    if (e.getAttribute('data-reins') === 'private' || (privateSeen.has(e) && !fieldSeen.has(e))) return false;
  }
  return true;
}

function markSwapped(el: Element): void {
  markPrivate(el, true);
}

/** `el` itself is private: a private field, or marked `data-reins="private"` now or before. */
export function isPrivateSelf(el: Element): boolean {
  if (isPrivateField(el)) return true;
  if (el.getAttribute('data-reins') === 'private') {
    privateSeen.add(el);
    return true;
  }
  return false;
}

/** Element inside a `data-reins="private"` subtree, or itself a private field. */
export function isPrivate(el: Element, stop?: Element | null): boolean {
  if (isPrivateField(el)) return true;
  for (let e: Element | null = el; e; e = e.parentElement) {
    if (isPrivateSelf(e)) {
      privateSeen.add(el);
      return true;
    }
    if (e === stop) break;
  }
  return false;
}

/** Classify every private element under `root` now, so later changes cannot unmark it. */
export function notePrivate(root: Element | null | undefined): void {
  if (!root || root.nodeType !== 1) return;
  isPrivateSelf(root);
  try {
    for (const e of Array.from(root.querySelectorAll('input,[autocomplete],[data-reins="private"]'))) isPrivateSelf(e);
  } catch {
    // ignore
  }
}

/** Was the old value of an attribute one that made the element private? */
export function wasPrivateAttr(el: Element, attr: string | null, old: string | null): boolean {
  if (old === null) return false;
  const v = old.toLowerCase();
  if (attr === 'type') return el.localName === 'input' && v.trim() === 'password';
  if (attr === 'autocomplete') return v.split(/\s+/).some((t) => PRIVATE_AUTOCOMPLETE.has(t));
  if (attr === 'data-reins') return v === 'private';
  return false;
}

export function isAnnotated(el: Element): boolean {
  return el.hasAttribute('data-reins-id') || el.getAttribute('data-reins') === 'expose';
}

export function roleOf(el: Element): string {
  const explicit = (el.getAttribute('role') || '').trim().split(/\s+/)[0]?.toLowerCase() ?? '';
  if (explicit && /^[a-z]{1,32}$/.test(explicit) && explicit !== 'none' && explicit !== 'presentation') return explicit;
  const tag = el.localName;
  switch (tag) {
    case 'a':
    case 'area':
      return el.hasAttribute('href') ? 'link' : 'generic';
    case 'button':
    case 'summary':
      return 'button';
    case 'input': {
      const type = ((el as HTMLInputElement).type || 'text').toLowerCase();
      if (type === 'button' || type === 'submit' || type === 'reset' || type === 'image') return 'button';
      if (type === 'checkbox') return 'checkbox';
      if (type === 'radio') return 'radio';
      if (type === 'range') return 'slider';
      if (type === 'number') return 'spinbutton';
      if (type === 'search') return el.hasAttribute('list') ? 'combobox' : 'searchbox';
      if (el.hasAttribute('list')) return 'combobox';
      return 'textbox';
    }
    case 'select': {
      const s = el as HTMLSelectElement;
      return s.multiple || (s.size || 0) > 1 ? 'listbox' : 'combobox';
    }
    case 'textarea':
      return 'textbox';
    case 'h1':
    case 'h2':
    case 'h3':
    case 'h4':
    case 'h5':
    case 'h6':
      return 'heading';
    case 'img':
      return 'img';
    case 'dialog':
      return 'dialog';
    case 'nav':
      return 'navigation';
    case 'main':
      return 'main';
    case 'aside':
      return 'complementary';
    case 'header':
      return 'banner';
    case 'footer':
      return 'contentinfo';
    case 'section':
      return 'region';
    case 'search':
      return 'search';
    case 'form':
      return 'form';
    case 'output':
      return 'status';
    case 'option':
      return 'option';
    case 'progress':
      return 'progressbar';
    case 'meter':
      return 'meter';
    case 'ul':
    case 'ol':
    case 'menu':
      return 'list';
    case 'li':
      return 'listitem';
    case 'table':
      return 'table';
    case 'tr':
      return 'row';
    case 'td':
      return 'cell';
    case 'th':
      return 'columnheader';
    case 'fieldset':
    case 'details':
      return 'group';
    case 'p':
      return 'paragraph';
    case 'article':
      return 'article';
    case 'label':
      return 'label';
    case 'hr':
      return 'separator';
    case 'figure':
      return 'figure';
  }
  if (isEditable(el)) return 'textbox';
  return 'generic';
}

export function isEditable(el: Element): boolean {
  const ce = el.getAttribute('contenteditable');
  return ce !== null && (ce === '' || ce.toLowerCase() === 'true' || ce.toLowerCase() === 'plaintext-only');
}

export function isDisabled(el: Element): boolean {
  if ((el as HTMLButtonElement).disabled === true) return true;
  if (el.getAttribute('aria-disabled') === 'true') return true;
  const tag = el.localName;
  if (tag === 'button' || tag === 'input' || tag === 'select' || tag === 'textarea') {
    for (let e = el.parentElement; e; e = e.parentElement) {
      if (e.localName === 'fieldset' && (e as HTMLFieldSetElement).disabled) {
        // Controls inside the fieldset's first legend stay enabled.
        const legend = Array.from(e.children).find((c) => c.localName === 'legend');
        if (!legend || !legend.contains(el)) return true;
      }
    }
  }
  return false;
}

function isTextEntry(el: Element): boolean {
  if (el.localName === 'textarea') return true;
  if (el.localName === 'input') return TEXT_INPUT_TYPES.has(((el as HTMLInputElement).type || '').toLowerCase());
  return isEditable(el);
}
export { isTextEntry };

type Skip = false | 'self' | 'subtree';

export interface TreeOptions {
  root: () => Element | null;
  exposure: Exposure;
  /** The driver's overlay host: never exposed, never readable, never a target. */
  isOverlay: (el: Element) => boolean;
}

export interface Snapshot {
  rev: number;
  nodes: UiNode[];
}

/**
 * Builds the exposed tree, keeps handles and the revision counter, resolves targets and
 * extracts visible text.
 */
export class UiTree {
  #o: TreeOptions;
  #handles = new WeakMap<Element, string>();
  #byHandle = new Map<string, Element>();
  #counter = 0;
  #rev = 0;
  #lastKey = '[]';
  /** Whether the last `text()` call stopped at its limit with content left over. */
  #cut = false;

  constructor(o: TreeOptions) {
    this.#o = o;
  }

  get rev(): number {
    return this.#rev;
  }

  // ───────── exposure ─────────

  #win(el: Element): Window | null {
    return el.ownerDocument.defaultView;
  }

  #skip(el: Element): Skip {
    const tag = el.localName;
    if (SKIP_TAGS.has(tag)) return 'subtree';
    if (this.#o.isOverlay(el)) return 'subtree';
    if (el.getAttribute('data-reins') === 'ignore') return 'subtree';
    if (el.hasAttribute('hidden') || el.hasAttribute('inert') || el.getAttribute('aria-hidden') === 'true') return 'subtree';
    if (tag === 'input' && ((el as HTMLInputElement).type || '').toLowerCase() === 'hidden') return 'subtree';
    const parent = el.parentElement;
    if (parent && parent.localName === 'details' && !(parent as HTMLDetailsElement).open && tag !== 'summary') return 'subtree';
    if (tag === 'dialog' && !(el as HTMLDialogElement).open) return 'subtree';
    const win = this.#win(el);
    if (win && typeof win.getComputedStyle === 'function') {
      let cs: CSSStyleDeclaration | null = null;
      try {
        cs = win.getComputedStyle(el);
      } catch {
        cs = null;
      }
      if (cs) {
        if (cs.display === 'none') return 'subtree';
        if (cs.visibility === 'hidden' || cs.visibility === 'collapse') return 'self';
      }
    }
    return false;
  }

  #candidate(el: Element): boolean {
    const mode = this.#o.exposure;
    if (mode === 'none') return false;
    if (isAnnotated(el)) return true;
    if (mode !== 'auto') return false;
    const tag = el.localName;
    if (tag === 'a' && el.hasAttribute('href')) return true;
    if (tag === 'button' || tag === 'select' || tag === 'textarea' || tag === 'summary') return true;
    if (tag === 'input') return true; // type=hidden was skipped already
    if (el.hasAttribute('tabindex')) return true;
    if (isEditable(el)) return true;
    const role = roleOf(el);
    if (INTERACTIVE_ROLES.has(role)) return true;
    if (role === 'heading' || role === 'dialog' || role === 'alertdialog' || role === 'status' || role === 'alert') return true;
    const live = el.getAttribute('aria-live');
    if (live === 'polite' || live === 'assertive') return true;
    if (role === 'img') return tag === 'img' ? (el.getAttribute('alt') || '').trim() !== '' : this.#explicitName(el) !== '';
    if (LANDMARK_ROLES.has(role)) return this.#explicitName(el) !== '';
    return false;
  }

  /** Name from attributes only (no content), used to decide whether a landmark is named. */
  #explicitName(el: Element): string {
    return collapse(el.getAttribute('data-reins-label') || el.getAttribute('aria-label') || this.#labelledBy(el) || el.getAttribute('title') || '');
  }

  /** Is `el` connected, inside the root, not hidden or ignored, and exposed under the current mode. */
  exposedNow(el: Element): boolean {
    const root = this.#o.root();
    if (!root || !el.isConnected) return false;
    if (el !== root && !root.contains(el)) return false;
    let first = true;
    for (let e: Element | null = el; e; e = e.parentElement) {
      const s = this.#skip(e);
      if (s === 'subtree' || (s === 'self' && first)) return false;
      first = false;
    }
    return this.#candidate(el);
  }

  // ───────── handles ─────────

  #handle(el: Element): string {
    let h = this.#handles.get(el);
    if (h === undefined) {
      h = `e${(++this.#counter).toString(36)}`;
      this.#handles.set(el, h);
    }
    this.#byHandle.set(h, el);
    return h;
  }

  /** Handle already assigned to `el`, if any. */
  handleOf(el: Element): string | undefined {
    return this.#handles.get(el);
  }

  /**
   * Resolve `e12` or `#semantic.id` to a live, exposed element, else `E_NO_TARGET`.
   * Never builds a selector from the target string.
   */
  resolve(target: unknown): Element {
    if (typeof target !== 'string' || target.length === 0 || target.length > 130) throw new ReinsError('E_NO_TARGET', 'unknown target');
    let el: Element | undefined;
    if (/^e[0-9a-z]{1,12}$/.test(target)) {
      el = this.#byHandle.get(target);
      if (el && !el.isConnected) el = undefined;
    } else if (target.startsWith('#') && target.length > 1) {
      const id = target.slice(1);
      const root = this.#o.root();
      if (root) {
        const all = [root, ...Array.from(root.querySelectorAll('[data-reins-id]'))];
        el = all.find((e) => e.getAttribute('data-reins-id') === id && this.exposedNow(e));
        if (el) this.#handle(el);
      }
    }
    if (!el || !this.exposedNow(el)) throw new ReinsError('E_NO_TARGET', 'target not found or not exposed');
    return el;
  }

  // ───────── nodes ─────────

  /**
   * May the text of `ref`, an element another node points at (a label, an `aria-labelledby`
   * reference), name that node? Only when it is inside the root, connected, and neither it
   * nor an ancestor is private, ignored, hidden, inert or the overlay.
   */
  #nameSource(ref: Element): boolean {
    const root = this.#o.root();
    if (!root || !ref.isConnected) return false;
    if (ref !== root && !root.contains(ref)) return false;
    if (isPrivate(ref)) return false;
    let first = true;
    for (let e: Element | null = ref; e; e = e.parentElement) {
      const s = this.#skip(e);
      if (s === 'subtree' || (s === 'self' && first)) return false;
      first = false;
    }
    return true;
  }

  #labelledBy(el: Element): string {
    const ids = (el.getAttribute('aria-labelledby') || '').trim();
    if (!ids) return '';
    const doc = el.ownerDocument;
    const parts: string[] = [];
    for (const id of ids.split(/\s+/).slice(0, 8)) {
      const ref = doc.getElementById(id);
      if (ref && this.#nameSource(ref)) parts.push(this.text(ref, MAX_NAME_CHARS, true));
    }
    return collapse(parts.join(' '));
  }

  #labelText(el: Element): string {
    const tag = el.localName;
    if (tag !== 'input' && tag !== 'select' && tag !== 'textarea' && tag !== 'button' && tag !== 'meter' && tag !== 'output' && tag !== 'progress') return '';
    let labels: Element[] = [];
    const native = (el as HTMLInputElement).labels;
    if (native && typeof native.length === 'number') labels = Array.from(native);
    else {
      const wrap = el.closest('label');
      if (wrap) labels.push(wrap);
      const id = el.getAttribute('id');
      if (id) for (const l of Array.from(el.ownerDocument.getElementsByTagName('label'))) if ((l as HTMLLabelElement).htmlFor === id && l !== wrap) labels.push(l);
    }
    return collapse(labels.filter((l) => this.#nameSource(l)).map((l) => this.text(l, MAX_NAME_CHARS, true)).join(' '));
  }

  /**
   * Accessible name. `priv` is false for a public node, 'field' for a node private only as
   * a field (named by its attributes and public labels, never by its content), and
   * 'subtree' for any other private node, which only `data-reins-label` names.
   */
  name(el: Element, role: string, priv: false | 'field' | 'subtree'): string {
    const attr = (a: string) => collapse(el.getAttribute(a) || '');
    if (priv === 'subtree') return clip(attr('data-reins-label'), MAX_NAME_CHARS);
    let s = attr('data-reins-label') || attr('aria-label') || this.#labelledBy(el) || this.#labelText(el) || attr('placeholder');
    if (!s && !priv) s = attr('alt');
    if (!s) s = attr('title');
    if (!s && !priv && el.localName === 'input') {
      const type = ((el as HTMLInputElement).type || '').toLowerCase();
      if (type === 'button' || type === 'submit' || type === 'reset') s = collapse((el as HTMLInputElement).value || (type === 'submit' ? 'Submit' : type === 'reset' ? 'Reset' : ''));
    }
    if (!s && !priv && !NO_CONTENT_NAME.has(role) && !isEditable(el)) s = collapse(this.text(el, MAX_NAME_CHARS + 1, true));
    return clip(s, MAX_NAME_CHARS);
  }

  value(el: Element, role: string): string | undefined {
    const tag = el.localName;
    let v: string | undefined;
    if (tag === 'input') {
      const type = ((el as HTMLInputElement).type || '').toLowerCase();
      if (!NO_VALUE_INPUT_TYPES.has(type)) v = (el as HTMLInputElement).value;
    } else if (tag === 'textarea') v = (el as HTMLTextAreaElement).value;
    else if (tag === 'select') {
      const opts = Array.from((el as HTMLSelectElement).options || []).filter((o) => o.selected);
      v = opts.map((o) => collapse(o.label || o.text || o.value)).join(', ');
    } else if (isEditable(el)) v = collapse(this.text(el, MAX_VALUE_CHARS + 1, false));
    else if (role === 'slider' || role === 'spinbutton' || role === 'progressbar' || role === 'meter') {
      v = el.getAttribute('aria-valuetext') || el.getAttribute('aria-valuenow') || undefined;
    }
    if (v === undefined || v === '') return undefined;
    return clip(v, MAX_VALUE_CHARS);
  }

  states(el: Element, priv: boolean): UiState[] {
    const st: UiState[] = [];
    const aria = (a: string) => el.getAttribute(a);
    const tag = el.localName;
    if (priv) {
      // A private control reveals nothing about its content: not checked, selected,
      // expanded, required, invalid or read-only, only that it is there.
      if (isDisabled(el)) st.push('disabled');
      if (el.ownerDocument.activeElement === el) st.push('focused');
      st.push('private');
      return st;
    }
    if (isDisabled(el)) st.push('disabled');
    if ((tag === 'input' && (el as HTMLInputElement).checked) || aria('aria-checked') === 'true' || aria('aria-pressed') === 'true') st.push('checked');
    if ((tag === 'option' && (el as HTMLOptionElement).selected) || aria('aria-selected') === 'true' || (aria('aria-current') !== null && aria('aria-current') !== 'false')) st.push('selected');
    if (aria('aria-expanded') === 'true' || (tag === 'details' && (el as HTMLDetailsElement).open) || (tag === 'summary' && el.parentElement?.localName === 'details' && (el.parentElement as HTMLDetailsElement).open)) st.push('expanded');
    if (el.ownerDocument.activeElement === el) st.push('focused');
    if ((el as HTMLInputElement).required === true || aria('aria-required') === 'true') st.push('required');
    if (aria('aria-invalid') === 'true') st.push('invalid');
    if ((isTextEntry(el) && (el as HTMLInputElement).readOnly === true) || aria('aria-readonly') === 'true') st.push('readonly');
    return st;
  }

  #node(el: Element, parent: string | undefined, priv: boolean, boxes: boolean): UiNode {
    const role = roleOf(el);
    const n: UiNode = { h: this.#handle(el), role };
    const id = el.getAttribute('data-reins-id');
    if (id) n.id = clip(id, MAX_ID_CHARS);
    const name = this.name(el, role, !priv ? false : privateAsFieldOnly(el) ? 'field' : 'subtree');
    if (name) n.name = name;
    if (!priv) {
      const v = this.value(el, role);
      if (v !== undefined) n.val = v;
    }
    const st = this.states(el, priv);
    if (st.length) n.st = st;
    if (parent !== undefined) n.p = parent;
    if (boxes) {
      try {
        const r = el.getBoundingClientRect();
        n.box = [Math.round(r.x || r.left || 0), Math.round(r.y || r.top || 0), Math.round(r.width || 0), Math.round(r.height || 0)];
      } catch {
        n.box = [0, 0, 0, 0];
      }
    }
    return n;
  }

  /** Build the exposed tree in document order, bounded in count and size. */
  build(boxes = false): UiNode[] {
    const root = this.#o.root();
    const out: UiNode[] = [];
    if (!root || !root.isConnected || this.#o.exposure === 'none') return out;
    // Forget handles of elements that left the document; the WeakMap keeps them for re-attachment.
    for (const [h, el] of this.#byHandle) if (!el.isConnected) this.#byHandle.delete(h);
    // Skip state of the root's ancestors (an ignored or hidden ancestor hides everything).
    for (let e = root.parentElement; e; e = e.parentElement) if (this.#skip(e) === 'subtree') return out;
    const startPriv = isPrivate(root);
    let bytes = 2;
    const visit = (el: Element, parent: string | undefined, priv: boolean, depth: number): void => {
      if (out.length >= MAX_NODES || bytes > MAX_TREE_BYTES || depth > MAX_DEPTH) return;
      const skip = this.#skip(el);
      if (skip === 'subtree') return;
      // Classify every visited element, exposed or not, so that privacy sticks to it.
      const p = isPrivateSelf(el) || priv;
      if (p) markPrivate(el);
      let h = parent;
      if (skip !== 'self' && this.#candidate(el)) {
        const node = this.#node(el, parent, p, boxes);
        bytes += JSON.stringify(node).length + 1;
        if (bytes > MAX_TREE_BYTES) return;
        out.push(node);
        h = node.h;
      }
      // A native select's options belong to the select; they are not separate controls.
      if (el.localName === 'select') return;
      for (const c of Array.from(el.children)) visit(c, h, p, depth + 1);
    };
    visit(root, undefined, startPriv, 0);
    return out;
  }

  /** Build, and bump the revision when the tree (ignoring boxes) changed. */
  snapshot(boxes = false): Snapshot {
    const nodes = this.build(boxes);
    const key = JSON.stringify(boxes ? nodes.map(({ box: _box, ...rest }) => rest) : nodes);
    if (key !== this.#lastKey) {
      this.#lastKey = key;
      this.#rev++;
    }
    return { rev: this.#rev, nodes };
  }

  // ───────── text ─────────

  /**
   * Visible text of `el`, leaving out private, ignored and hidden subtrees, the overlay,
   * and form-control contents. `flat` collapses everything to one line (names); otherwise
   * block elements start new lines (read). Stops once `limit` characters are collected.
   */
  text(el: Element, limit: number, flat: boolean): string {
    let out = '';
    let cut = false;
    const push = (s: string) => {
      if (out.length < limit) out += s;
      else if (s.trim()) cut = true;
    };
    const sep = (s: string) => {
      if (!out.length || out.length >= limit) return;
      if (s === '\n') {
        out = out.replace(/[ \t]+$/, '');
        if (!out.endsWith('\n')) out += '\n';
      } else if (!/\s$/.test(out)) out += ' ';
    };
    const walk = (node: Node, depth: number): void => {
      if (depth > MAX_DEPTH) return;
      if (out.length >= limit) {
        if ((node.textContent || '').trim()) cut = true;
        return;
      }
      if (node.nodeType === 3) {
        push((node.nodeValue || '').replace(/\s+/g, ' '));
        return;
      }
      if (node.nodeType !== 1) return;
      const e = node as Element;
      const skip = this.#skip(e);
      if (depth > 0) {
        if (skip === 'subtree') return;
        if (isPrivateSelf(e)) return;
      }
      // visibility:hidden or collapse hides the element's own text; a child that sets
      // visibility:visible again is judged by its own style.
      const selfHidden = skip === 'self';
      const tag = e.localName;
      if (tag === 'textarea' || tag === 'select' || tag === 'input') return;
      if (tag === 'br') {
        sep(flat ? ' ' : '\n');
        return;
      }
      const block = BLOCK_TAGS.has(tag);
      const boundary = block ? (flat ? ' ' : '\n') : INLINE_FORMAT.has(tag) ? '' : ' ';
      if (depth > 0 && boundary) sep(boundary);
      if (tag === 'img' && depth > 0 && !selfHidden) {
        const alt = collapse(e.getAttribute('alt') || '');
        if (alt) push(alt);
      }
      for (const c of Array.from(e.childNodes)) {
        if (selfHidden && c.nodeType !== 1) continue;
        walk(c, depth + 1);
      }
      if (depth > 0 && boundary) sep(boundary);
    };
    walk(el, 0);
    this.#cut = cut;
    if (flat) return collapse(out);
    return out
      .split('\n')
      .map((l) => collapse(l))
      .filter((l, i, a) => l !== '' || (i > 0 && a[i - 1] !== ''))
      .join('\n')
      .trim();
  }

  /**
   * Text for `read`. With `el`, that element's text (it must already be resolved). Without,
   * the root's text, or under `annotated` exposure the text of the outermost annotated regions.
   */
  readText(el: Element | null, max: number): { text: string; truncated: boolean } {
    const mode = this.#o.exposure;
    const root = this.#o.root();
    let text = '';
    let cut = false;
    const one = (e: Element, limit: number) => {
      const t = this.text(e, limit, false);
      if (this.#cut) cut = true;
      return t;
    };
    if (mode === 'none' || !root) text = '';
    else if (el) text = isPrivate(el) ? '' : one(el, max + 1);
    else if (mode === 'auto') text = isPrivate(root) ? '' : one(root, max + 1);
    else {
      const parts: string[] = [];
      let total = 0;
      const visit = (e: Element, depth: number) => {
        if (depth > MAX_DEPTH) return;
        const skip = this.#skip(e);
        if (skip === 'subtree' || isPrivateSelf(e)) return;
        if (skip !== 'self' && isAnnotated(e)) {
          if (total > max) {
            cut = true;
            return;
          }
          const t = one(e, max + 1 - total);
          if (t) {
            parts.push(t);
            total += t.length + 1;
          }
          return;
        }
        for (const c of Array.from(e.children)) visit(c, depth + 1);
      };
      if (!isPrivate(root)) visit(root, 0);
      text = parts.join('\n');
    }
    const truncated = cut || text.length > max;
    return { text: truncated ? clip(text, max) : text, truncated };
  }
}
