/**
 * Audit records and the hash chain (SPEC 13). Isomorphic: no Node imports.
 */
import { canonicalJson, hmacSha256, sha256, timingSafeEqual } from '@offensiveadhd/reins/core';
import type { Role } from '@offensiveadhd/reins/core';

/**
 * `audit` records are about the log itself (`outcome: "lost"`). `person` records are what
 * the person did for one agent on the page: set its level, a rule for one action or its
 * scopes, let it hear the other agents in the chat, or sent it a chat message. `chat` records
 * are relays of one agent's words to another that the hub dropped.
 */
export type AuditKind = 'connect' | 'disconnect' | 'attach' | 'detach' | 'grant.end' | 'request' | 'stream' | 'audit' | 'person' | 'chat';

/**
 * One audit record. `hash = sha256(prev + "\n" + canonicalJson(record without hash))`,
 * or, when the hub has an audit key, `HMAC-SHA256(key, same text)`. Arguments appear only
 * as `args`: `HMAC-SHA256(key, canonical JSON)` with an audit key, else its plain SHA-256
 * (which a reader of the log can test guesses against). Params that cannot be
 * canonicalised are refused (`E_BAD_ARGS`), never forwarded. Fields that do not apply are absent.
 *
 * An audited request (`act`, `ui.*`, `nav.*`, `show.view`, `show.toast`, `show.highlight`,
 * `stream.open`, `surface.attach`; not `cursor.*`, `show.clear` or pointer frames) that passes
 * the hub's checks produces two records: one with `outcome: "accepted"`, written before
 * the request is forwarded to the surface, then one with the final outcome and `ref`, the
 * `seq` of its `accepted` record. A refusal by the hub itself is a single record.
 *
 * When refusals come faster than the hub records them (20 per second per connection,
 * 20 failed connections per second overall), the excess is counted and summarised by one
 * record with `outcome: "suppressed"` and `count`. Records that could not be queued while
 * the sink was failing are summarised the same way with `outcome: "lost"`.
 *
 * A `person` record has `method` `level`, `rule` or `scopes`, the agent and the surface, and
 * `value`: the level, the rule's decision (`none` when the rule was removed, with the action
 * name in `action`), or the scopes now in force separated by spaces (`none` for no scope).
 * Its `outcome` is `ok`, or `refused` when the hub's policy does not offer what was reported
 * and the hub ended the grant. More than 20 a second per surface are summarised as
 * `suppressed`.
 *
 * Chat is recorded without its text. A `chat.say` request is an audited request like `act`:
 * `args` is the digest of the canonical JSON of `{text}` (with `to` when it has one), the
 * text as the room keeps it, and `chars` is the length of that text. Nothing else the agent
 * sent with the request is in the digest, or forwarded. A message of the person that the hub
 * relays to an agent is a `person` record with `method` `chat`, that agent, `chars`, and
 * `args`, a digest of the same shape: one text gives one digest, whoever said it. A message
 * of the person the hub did not relay is a `person` record with `method` `chat` and the
 * reason as `outcome` (`E_RATE`, `E_INTERNAL`, `E_TOO_LARGE`), bounded like the other
 * `person` records. `relay` is the `method` of the `person` record written when the person
 * lets an agent hear the others in the chat (`value` `on`) or no longer does (`off`).
 *
 * A `chat` record (`method` `relay`, `outcome` `dropped`, `agent` the one that spoke) is a
 * relay of an agent's words to another agent that the hub dropped because the surface sent
 * more of them than that agent's `chat` rate lets it say. More than 20 a second per surface
 * are summarised as `suppressed`.
 */
export interface AuditRecord {
  seq: number;
  /** Epoch milliseconds. */
  ts: number;
  kind: AuditKind;
  /** Agent session id. */
  agent?: string;
  /** Surface session id. */
  surface?: string;
  /** Connection records: the role the peer asked for. */
  role?: Role;
  /** Connection records: the connection's origin, when it had one. */
  origin?: string;
  /** Connection records of agents: the credential id the agent named. */
  kid?: string;
  method?: string;
  /** `act`, and `person` records of a rule: the action name. */
  action?: string;
  /** `person` records: the level, the rule's decision, or the scopes in force. */
  value?: string;
  /** `chat.say` requests and `person` records of a chat message: the length of the text in characters. */
  chars?: number;
  /** `ok`, an error code, or for `grant.end` the reason the grant ended. */
  outcome: string;
  /** base64url HMAC-SHA256 under the audit key (SHA-256 without one) of the canonical JSON of the request params (without `s`). */
  args?: string;
  /** Duration in milliseconds. */
  ms?: number;
  /** Outcome records of accepted requests: the `seq` of the `accepted` record. */
  ref?: number;
  /** `suppressed` and `lost` summaries: how many records they stand for. */
  count?: number;
  /** Hash of the previous record; empty for the first record of a chain. */
  prev: string;
  hash: string;
}

export interface AuditSink {
  /** Persist one record. Throwing marks the audit unavailable: the hub then fails closed. */
  write(record: AuditRecord): void;
  /** Where an existing log ends, so a new broker continues the same chain. Optional. */
  readonly last?: { seq: number; hash: string };
}

/** Where a chain ends: the `seq` and `hash` of its last record. */
export interface AuditHead {
  seq: number;
  hash: string;
}

export interface VerifyOptions {
  /** The audit key: verify a keyed (HMAC-SHA256) chain. */
  key?: string;
  /** Also require the log to end exactly here. This is what reveals a cut-off tail. */
  head?: AuditHead;
}

/** An in-memory sink, mostly for tests and in-page brokers. */
export function memoryAudit(): AuditSink & { records: AuditRecord[] } {
  const records: AuditRecord[] = [];
  return {
    records,
    write(record: AuditRecord): void {
      records.push(record);
    },
  };
}

/**
 * The hash a record must carry, given the previous record's hash: SHA-256, or
 * HMAC-SHA256 under `key` for a keyed chain.
 */
export function auditHash(prev: string, record: Omit<AuditRecord, 'hash'> & { hash?: string }, key?: string): Promise<string> {
  const { hash: _ignored, ...rest } = record;
  const text = `${prev}\n${canonicalJson(rest)}`;
  return key !== undefined ? hmacSha256(key, text) : sha256(text);
}

/**
 * Check a whole log: sequence numbers count up from 1 without gaps, every `prev` is the
 * previous record's `hash` (the first is empty), and every `hash` matches its record.
 * With `opts.key` the hashes must be the keyed HMAC; with `opts.head` the log must end
 * exactly at that record. `badSeq` is the sequence number of the first record that
 * fails, or for a log that ends early, the first missing one.
 */
export async function verifyAuditChain(records: AuditRecord[], opts: VerifyOptions = {}): Promise<{ ok: boolean; badSeq?: number }> {
  if (!Array.isArray(records)) return { ok: false };
  const key = opts?.key;
  if (key !== undefined && (typeof key !== 'string' || key.length === 0)) return { ok: false };
  let prev = '';
  let seq = 0;
  for (const r of records) {
    if (r === null || typeof r !== 'object') return { ok: false, badSeq: seq + 1 };
    const badSeq = typeof r.seq === 'number' ? r.seq : seq + 1;
    if (r.seq !== seq + 1 || r.prev !== prev || typeof r.hash !== 'string') return { ok: false, badSeq };
    let h: string;
    try {
      h = await auditHash(prev, r, key);
    } catch {
      return { ok: false, badSeq };
    }
    if (!timingSafeEqual(h, r.hash)) return { ok: false, badSeq };
    prev = r.hash;
    seq = r.seq;
  }
  const head = opts?.head;
  if (head !== undefined) {
    if (head === null || typeof head !== 'object' || !Number.isSafeInteger(head.seq) || typeof head.hash !== 'string') return { ok: false };
    if (seq !== head.seq) return { ok: false, badSeq: Math.min(seq, head.seq) + 1 };
    if (seq === 0 ? head.hash !== '' : !timingSafeEqual(prev, head.hash)) return { ok: false, badSeq: seq };
  }
  return { ok: true };
}
