/**
 * The overlay's stylesheet, made safe from the page's.
 *
 * A closed shadow root keeps page selectors away from the overlay's elements, but two things
 * still reach in from the page's stylesheet, with no script at all:
 *
 *  - Custom properties. They inherit through the host, a page rule on the host beats a
 *    `:host` rule, and `@property` in the page can make any name non-inheriting or give it a
 *    syntax that turns the overlay's value invalid. So the stylesheet reads none. The source
 *    is written with `var(--r-name)` for the theme colours, and `sealCss` writes the values
 *    in: the light ones in each rule, the dark ones in a media rule right after it.
 *  - Font families. `@font-face` in the page can define any family name, also one the
 *    overlay only hoped the system had. So only generic families are used, which a page
 *    cannot define: `system-ui`, `sans-serif`, `monospace`, `serif`.
 *
 * `sealCss` takes a plain subset of CSS and refuses the rest. It does not try to recognise
 * every way of spelling what it forbids: it throws on any stylesheet it cannot read as that
 * subset. So it throws on an escape (`v\61r(`), on a comment (which can sit inside a name),
 * on a property name that is not lower case, on a function, an at-rule or a selector form it
 * does not list (`url()`, `@import`, `@font-face`, `:host-context()`), on a system colour,
 * and on `inherit` and its kin in a `:host` rule, where they would read the page's value. A
 * font list it can read is cut down to generic families; one it cannot read is refused. The
 * styles of a panel tab written elsewhere go through the same door.
 *
 * What it does not judge is taste or layout: a tab can still draw badly. And it is about the
 * stylesheet text only. What the page's own rules can do to the host element is `overlay.ts`'s
 * to pin and `check()`'s to notice.
 */

type Theme = Record<string, string>;

/** The theme colours. `var(--r-<name>)` in the source stands for one of these. */
export const LIGHT: Theme = {
  fg: '#16161d',
  muted: '#5c5d6e',
  card: '#fff',
  line: 'rgba(22,22,40,.12)',
  soft: '#f0f0f5',
  'soft-h': '#e5e5ee',
  accent: '#5b5bf6',
  'accent-h': '#4a49e6',
  ok: '#16a34a',
  warn: '#d97706',
  danger: '#dc2626',
  'danger-h': '#c11f1f',
  shadow: '0 10px 30px rgba(16,16,48,.16),0 2px 6px rgba(16,16,48,.10)',
};

export const DARK: Theme = {
  ...LIGHT,
  fg: '#f1f1f6',
  muted: '#a3a4b5',
  card: '#1d1d25',
  line: 'rgba(255,255,255,.12)',
  soft: '#2b2b36',
  'soft-h': '#363644',
  accent: '#7c7cff',
  'accent-h': '#8f8fff',
  shadow: '0 10px 30px rgba(0,0,0,.45),0 2px 6px rgba(0,0,0,.35)',
};

const TOKEN = /var\(--r-([a-z-]+)\)/g;

function fail(what: string): never {
  throw new Error(`overlay stylesheet: ${what}`);
}

function paint(css: string, theme: Theme): string {
  return css.replace(TOKEN, (_, name: string) => {
    if (!Object.prototype.hasOwnProperty.call(theme, name)) fail(`unknown colour --r-${name}`);
    return theme[name]!;
  });
}

/** The text names a colour that is not the same in the dark theme. */
function themed(css: string): boolean {
  for (const m of css.matchAll(TOKEN)) if (DARK[m[1]!] !== LIGHT[m[1]!]) return true;
  return false;
}

/** The rules at the top level of a stylesheet, each with its whole block. */
function topLevel(css: string): string[] {
  const out: string[] = [];
  let depth = 0;
  let start = 0;
  for (let i = 0; i < css.length; i++) {
    const ch = css[i];
    if (ch === '{') depth++;
    else if (ch === '}') {
      depth--;
      if (depth < 0) fail('unbalanced braces');
      if (depth === 0) {
        out.push(css.slice(start, i + 1).trim());
        start = i + 1;
      }
    }
  }
  if (depth !== 0 || css.slice(start).trim() !== '') fail('unbalanced braces, or a rule without a block');
  return out;
}

/** Generic families: no `@font-face` rule can define them. Only these are left in a font list. */
export const SAFE_FAMILIES: ReadonlySet<string> = new Set(['system-ui', 'sans-serif', 'monospace', 'serif']);
const WIDE = new Set(['inherit', 'initial', 'unset', 'revert', 'revert-layer']);
const IMPORTANT = /\s*!important\s*$/;

function families(value: string): string {
  const important = IMPORTANT.test(value) ? '!important' : '';
  const list = value.replace(IMPORTANT, '').trim();
  if (WIDE.has(list)) return `${list}${important}`;
  // A quoted name is never a generic family, whatever it spells.
  const kept = list
    .split(',')
    .map((f) => f.trim())
    .filter((f) => SAFE_FAMILIES.has(f));
  return `${kept.length ? kept.join(',') : 'sans-serif'}${important}`;
}

/** `font: [style and weight] size[/line-height] families`. */
const SHORTHAND = /^(.*?\d*\.?\d+(?:px|em|rem|pt|%)(?:\s*\/\s*[\d.]+(?:px|em|rem|%)?)?)\s+(.+)$/;

function shorthand(value: string): string {
  if (WIDE.has(value.replace(IMPORTANT, '').trim())) return value.trim();
  const m = SHORTHAND.exec(value.trim());
  if (!m) fail(`cannot read the font in "${value.trim()}"`);
  return `${m[1]} ${families(m[2]!)}`;
}

// ───────────────────────────── what is let through ─────────────────────────────

/** The at-rules a stylesheet may use. No `@import`, `@font-face`, `@property`, `@container` or `@layer`. */
const AT_RULES = /^@(media|keyframes)\b/;
/**
 * The functions a value or a selector may call. None of them fetches anything, and none reads
 * a value from outside the stylesheet: no `url()`, `image-set()`, `attr()`, `env()`, and `var()`
 * only as a theme colour, which never reaches the browser.
 */
const FUNCTIONS: ReadonlySet<string> = new Set([
  'rgb', 'rgba', 'hsl', 'hsla', 'calc', 'min', 'max', 'clamp', 'translate', 'translateX', 'translateY', 'translate3d', 'scale', 'scaleX', 'scaleY', 'rotate',
  'cubic-bezier', 'steps', 'drop-shadow', 'blur', 'inset', 'linear-gradient', 'radial-gradient', 'repeat', 'minmax', 'fit-content',
  'not', 'is', 'where', 'nth-child', 'nth-last-child', 'nth-of-type',
]);
/**
 * Colours the system defines. What they resolve to depends on `color-scheme` and on forced
 * colours, not on this stylesheet, so a surface the person has to read names none of them.
 * `currentcolor` is not one: it is the element's own `color`, which this stylesheet sets.
 */
const SYSTEM_COLOURS: ReadonlySet<string> = new Set([
  'accentcolor', 'accentcolortext', 'activetext', 'buttonborder', 'buttonface', 'buttontext', 'canvas', 'canvastext', 'field', 'fieldtext', 'graytext', 'highlight',
  'highlighttext', 'linktext', 'mark', 'marktext', 'selecteditem', 'selecteditemtext', 'visitedtext',
  // The deprecated names, which browsers still resolve.
  'activeborder', 'activecaption', 'appworkspace', 'background', 'buttonhighlight', 'buttonshadow', 'captiontext', 'inactiveborder', 'inactivecaption', 'inactivecaptiontext',
  'infobackground', 'infotext', 'menu', 'menutext', 'scrollbar', 'threeddarkshadow', 'threedface', 'threedhighlight', 'threedlightshadow', 'threedshadow', 'window', 'windowframe',
  'windowtext',
]);
/** Selector forms that read the page: what stands around the host, or what the page put on it or into it. */
const SELECTOR_READS_PAGE = /:host-context|:host\(|::part|::slotted|:root\b/;
const PROPERTY = /^-?[a-z][a-z0-9-]*$/;

/** `text` with quoted strings taken out. A string holds no rule of its own; an unclosed one is refused. */
function unquoted(text: string): string {
  let out = '';
  let quote = '';
  for (const ch of text) {
    if (quote) {
      if (ch === quote) quote = '';
      else if (ch === '\n') fail('a string that runs over a line');
    } else if (ch === '"' || ch === "'") quote = ch;
    else out += ch;
  }
  if (quote) fail('a string that is not closed');
  return out;
}

function checkFunctions(text: string, where: string): void {
  for (const m of text.matchAll(/([A-Za-z_-][A-Za-z0-9_-]*)\(/g)) {
    const name = m[1]!;
    if (name === 'var') {
      if (!/^var\(--r-[a-z-]+\)/.test(text.slice(m.index))) fail(`var() that is not a theme colour, in ${where}`);
      continue;
    }
    if (!FUNCTIONS.has(name)) fail(`${name}() is not let through, in ${where}`);
  }
  // A parenthesis with nothing before it is grouping inside calc() or a media query: fine.
}

/** The declarations of one block, checked, with font lists cut down to generic families. */
function declarations(block: string, hostRule: boolean): string {
  const out: string[] = [];
  // No `;` stands inside a value here: strings with one are not used, and url() is refused.
  for (const raw of block.split(';')) {
    const decl = raw.trim();
    if (decl === '') continue;
    const colon = decl.indexOf(':');
    if (colon < 0) fail(`not a declaration: "${decl}"`);
    const prop = decl.slice(0, colon).trim();
    let value = decl.slice(colon + 1).trim();
    if (!PROPERTY.test(prop)) fail(`a property name that is not plain lower case: "${prop}"`);
    if (prop.startsWith('--')) fail('a custom property is declared');
    const bare = unquoted(value);
    checkFunctions(bare, `"${prop}"`);
    const words = bare.toLowerCase().match(/[a-z-]+/g) ?? [];
    // A transition names properties, and `background` is one: there it is no colour.
    const namesProperties = prop === 'transition' || prop === 'transition-property' || prop === 'will-change';
    if (!namesProperties) for (const w of words) if (SYSTEM_COLOURS.has(w)) fail(`a system colour (${w}) in "${prop}"`);
    // In a `:host` rule these would take the page's value for the host.
    if (hostRule && words.some((w) => w === 'inherit' || w === 'unset' || w === 'revert' || w === 'revert-layer')) fail(`"${prop}" takes its value from the page in a :host rule`);
    if (prop === 'font-family') value = families(value);
    else if (prop === 'font') value = shorthand(value);
    else if (prop === 'src') fail('a font or image source');
    out.push(`${prop}:${value}`);
  }
  return out.join(';');
}

/** One rule, checked and rewritten: a style rule, or `@media` and `@keyframes` with the rules inside them. */
function rule(text: string): string {
  const open = text.indexOf('{');
  const head = text.slice(0, open).trim();
  const body = text.slice(open + 1, text.lastIndexOf('}'));
  if (head.startsWith('@')) {
    if (!AT_RULES.test(head)) fail(`${head.split(/[\s{(]/)[0]} is not let through`);
    checkFunctions(unquoted(head), head);
    return `${head}{${topLevel(body).map(rule).join('')}}`;
  }
  const selector = unquoted(head);
  if (SELECTOR_READS_PAGE.test(selector)) fail(`a selector that reads the page: "${head}"`);
  checkFunctions(selector, `"${head}"`);
  if (body.includes('{')) fail(`a block inside the rule "${head}"`);
  return `${head}{${declarations(body, /:host\b/.test(selector))}}`;
}

/**
 * The stylesheet the overlay adopts, from its source: checked against the subset this file
 * lets through, theme colours written in as values, dark ones in
 * `@media (prefers-color-scheme:dark)` right after the rule they belong to (so the order of
 * the cascade is that of the source), and font lists cut down to generic families. The result
 * reads no custom property and declares none. Throws on anything it cannot prove to be so.
 */
export function sealCss(source: string): string {
  // Before anything is read: the two things that let one spelling stand for another.
  if (source.includes('\\')) fail('an escape');
  if (source.includes('/*') || source.includes('*/')) fail('a comment');
  if (/<!--|-->/.test(source)) fail('a comment');
  let out = '';
  for (const text of topLevel(source)) {
    const checked = rule(text);
    out += `${paint(checked, LIGHT)}\n`;
    if (!themed(checked)) continue;
    if (checked.startsWith('@')) {
      // A conditional group or keyframes: the whole of it again, for the dark theme.
      out += `@media (prefers-color-scheme:dark){${paint(checked, DARK)}}\n`;
      continue;
    }
    const open = checked.indexOf('{');
    const dark = checked
      .slice(open + 1, checked.lastIndexOf('}'))
      .split(';')
      .filter(themed)
      .join(';');
    out += `@media (prefers-color-scheme:dark){${checked.slice(0, open)}{${paint(dark, DARK)}}}\n`;
  }
  if (/var\s*\(/i.test(out) || /(^|[{;\s])--[\w-]+\s*:/.test(out)) fail('a custom property is left in it');
  return out;
}
