/**
 * The panel the person opens from the indicator: a small tabbed dialog in the overlay's
 * closed shadow root. Two tabs today. Permissions shows, per attached agent, the level, the
 * app's actions with the person's rules, and the scopes of the grant. Activity lists the
 * last commands.
 *
 * Nothing in the protocol reaches this file. The panel opens, closes and changes only on
 * the person's own input: every control is built with the overlay's button, which takes a
 * natively trusted click dispatched to itself and nothing else (`primordials.ts`), so
 * neither an agent nor a synthetic event can press one.
 *
 * Whatever lets an agent do more without asking goes through a confirm step whose button
 * is armed after a delay: a level under which an action stops asking, a rule `allow`, and a
 * reset after which an action runs unasked. Such a click is also not taken while the list
 * has just changed under the pointer (`settle`), or while the overlay cannot be relied on
 * (`kit.sound`). Whatever makes an agent ask more, or do less, applies at once.
 *
 * What the panel shows as happening is what happens: it reasons from the stricter of the
 * app's decision and the hub's for each action (the hub says which actions it confirms, at
 * attach), from the person's rules, and from approvals the driver remembers.
 *
 * Built like the rest of the overlay: `textContent` only, styles from the overlay's
 * constructable stylesheet, no `style` attribute.
 */
import { LEVELS, allowRulePermitted, decideAct, stricter } from '@offensiveadhd/reins/core';
import type { Decision, Level, Risk, Scope } from '@offensiveadhd/reins/core';
import { listen, prevent, stop, trustedAt } from './primordials.js';
import type { Timer } from './primordials.js';
import { agentLabel } from './text.js';

// ───────────────────────────── the tab API ─────────────────────────────

/** One tab of the panel. A later tab (chat) registers the same way. */
export interface PanelTab {
  /** Stable id, used for element ids: lowercase letters. */
  id: string;
  label: string;
  /** Build the tab's content into `body`. Called when the tab is shown and on `refresh()`. */
  render(body: HTMLElement): void;
  /** The overlay moved, or the panel opened: restart every arming delay in the tab. */
  rearm?(): void;
  /**
   * What is under the pointer just changed without the person choosing it (a consent card
   * went away from over the panel): controls that let an agent do more take no click for
   * `kit.armMs`.
   */
  settle?(): void;
  /** The tab is no longer showing (another tab was chosen, or the panel closed). */
  hidden?(): void;
}

export interface TabHandle {
  /** Render the tab again, if it is the one showing. */
  refresh(): void;
  /** A short mark next to the tab's label, such as an unread count. Empty removes it. */
  badge(text: string): void;
  /** Whether this tab is the one showing in an open panel. */
  readonly showing: boolean;
}

/** What the overlay lends the panel: element and timer helpers, and its trusted-only button. */
export interface PanelKit {
  doc: Document;
  el<K extends keyof HTMLElementTagNameMap>(tag: K, cls?: string, text?: string): HTMLElementTagNameMap[K];
  /** A button that reacts to the person's own activation only: a trusted click dispatched to it. */
  button(label: string, cls: string, act: (e: MouseEvent) => void): HTMLButtonElement;
  later(fn: () => void, ms: number): Timer;
  cancel(t: Timer): void;
  /** A string an agent or the hub wrote, made safe to display (`visible`, shortened). */
  show(s: string, max: number): string;
  /** How long a confirm button ignores activation after it appears or moves. */
  armMs: number;
  /** A clock for arming delays: it does not go back, and a page cannot move it. */
  now(): number;
  /**
   * May a control that lets an agent do more take this click: can the overlay be relied on
   * right now (`Overlay.check`)? When not, the click is not taken and the overlay says so
   * once it can.
   */
  sound(): boolean;
}

interface TabRec {
  tab: PanelTab;
  btn: HTMLButtonElement;
  mark: HTMLElement;
  body: HTMLElement;
}

export const PANEL_ID = 'reins-panel';

export class Panel {
  readonly el: HTMLElement;
  #kit: PanelKit;
  #tablist: HTMLElement;
  #closeBtn: HTMLButtonElement;
  #tabs: TabRec[] = [];
  #active: string | undefined;
  #open = false;
  #onToggle: (open: boolean, byPerson: boolean) => void;
  /** A line under the tabs, from the overlay: why a click was not taken. */
  #notice: HTMLElement;

  /** `onToggle(open, byPerson)`: `byPerson` is true when the panel was closed from inside (Escape, the close button). */
  constructor(kit: PanelKit, onToggle: (open: boolean, byPerson: boolean) => void) {
    this.#kit = kit;
    this.#onToggle = onToggle;
    this.el = kit.el('div', 'panel');
    this.el.id = PANEL_ID;
    this.el.setAttribute('role', 'dialog');
    this.el.setAttribute('aria-label', 'AI agent permissions and activity');
    this.el.hidden = true;
    const head = kit.el('div', 'tabs');
    this.#tablist = kit.el('div', 'tablist');
    this.#tablist.setAttribute('role', 'tablist');
    this.#closeBtn = kit.button('×', 'x', () => this.close(true));
    this.#closeBtn.setAttribute('aria-label', 'Close');
    head.append(this.#tablist, this.#closeBtn);
    this.#notice = kit.el('p', 'held');
    this.#notice.setAttribute('role', 'status');
    this.#notice.hidden = true;
    this.el.append(head, this.#notice);
    // Keys typed in the panel stay in the panel; Escape closes it.
    const el = this.el;
    listen(el, 'keydown', (e: KeyboardEvent) => {
      const mine = trustedAt(e, el);
      stop(e);
      if (!mine) return;
      if (e.key === 'Escape') {
        prevent(e);
        this.close(true);
      } else if (e.key === 'ArrowDown' || e.key === 'ArrowUp' || e.key === 'ArrowLeft' || e.key === 'ArrowRight') this.#arrow(e);
    });
    listen(el, 'click', stop);
  }

  /** Show a line under the tabs, or with `null` take it away. The overlay's words, never an agent's. */
  notice(text: string | null): void {
    this.#notice.textContent = text ?? '';
    this.#notice.hidden = text === null;
  }

  get isOpen(): boolean {
    return this.#open;
  }

  addTab(tab: PanelTab): TabHandle {
    const kit = this.#kit;
    const btn = kit.button(tab.label, 'tab', () => this.#select(tab.id, true));
    btn.id = `${PANEL_ID}-tab-${tab.id}`;
    btn.setAttribute('role', 'tab');
    btn.setAttribute('aria-controls', `${PANEL_ID}-body-${tab.id}`);
    const mark = kit.el('span', 'tb');
    mark.hidden = true;
    btn.append(mark);
    const body = kit.el('div', 'pbody');
    body.id = `${PANEL_ID}-body-${tab.id}`;
    body.setAttribute('role', 'tabpanel');
    body.setAttribute('aria-labelledby', btn.id);
    body.hidden = true;
    const rec: TabRec = { tab, btn, mark, body };
    this.#tabs.push(rec);
    this.#tablist.append(btn);
    this.el.append(body);
    if (this.#active === undefined) this.#active = tab.id;
    this.#sync();
    const showing = () => this.#open && this.#active === tab.id;
    return {
      refresh: () => {
        if (showing()) tab.render(body);
      },
      badge: (text: string) => {
        mark.textContent = text;
        mark.hidden = text === '';
      },
      get showing() {
        return showing();
      },
    };
  }

  #rec(id: string | undefined): TabRec | undefined {
    return this.#tabs.find((t) => t.tab.id === id);
  }

  #sync(): void {
    for (const t of this.#tabs) {
      const on = t.tab.id === this.#active;
      t.btn.setAttribute('aria-selected', String(on));
      t.btn.tabIndex = on ? 0 : -1;
      t.body.hidden = !on;
    }
  }

  #select(id: string, focus = false): void {
    const next = this.#rec(id);
    if (!next) return;
    if (this.#active !== id) this.#rec(this.#active)?.tab.hidden?.();
    this.#active = id;
    this.#sync();
    if (this.#open) {
      next.tab.render(next.body);
      next.tab.rearm?.();
    }
    if (focus) this.#focus(next.btn);
  }

  #focus(el: HTMLElement | null | undefined): void {
    try {
      el?.focus({ preventScroll: true });
    } catch {
      // ignore
    }
  }

  /**
   * Arrow keys move focus inside a tab list or a radio group and choose nothing: choosing is
   * a click, Enter or Space on the control, which the browser delivers as a trusted click.
   */
  #arrow(e: KeyboardEvent): void {
    const from = (this.el.getRootNode() as ShadowRoot | Document).activeElement as HTMLElement | null;
    const group = from?.closest('[role="tablist"],[role="radiogroup"]');
    if (!from || !group) return;
    const items = Array.from(group.querySelectorAll<HTMLElement>('[role="tab"],[role="radio"]'));
    const i = items.indexOf(from);
    if (i < 0) return;
    prevent(e);
    const step = e.key === 'ArrowDown' || e.key === 'ArrowRight' ? 1 : -1;
    this.#focus(items[(i + step + items.length) % items.length]);
  }

  open(): void {
    if (this.#open || !this.#tabs.length) return;
    this.#open = true;
    this.el.hidden = false;
    const cur = this.#rec(this.#active) ?? this.#tabs[0]!;
    this.#active = cur.tab.id;
    this.#sync();
    cur.tab.render(cur.body);
    cur.tab.rearm?.();
    this.#onToggle(true, false);
    this.#focus(cur.btn);
  }

  /** `byPerson`: closed from inside the panel, so focus goes back to the control that opened it. */
  close(byPerson = false): void {
    if (!this.#open) return;
    this.#open = false;
    this.el.hidden = true;
    for (const t of this.#tabs) {
      t.tab.hidden?.();
      t.body.replaceChildren();
    }
    this.#onToggle(false, byPerson);
  }

  /** The overlay moved to another place on screen: nothing armed may take a click aimed at what was there. */
  rearm(): void {
    if (this.#open) this.#rec(this.#active)?.tab.rearm?.();
  }

  /**
   * What is under the pointer changed without the person choosing it: a consent card or its
   * backdrop went away from over the panel. For a moment, nothing in the tab that is showing
   * that lets an agent do more takes a click.
   */
  settle(): void {
    if (this.#open) this.#rec(this.#active)?.tab.settle?.();
  }
}

// ───────────────────────────── the Permissions tab ─────────────────────────────

export interface PanelAction {
  name: string;
  risk: Risk;
  /** What the app's policy says for the action. */
  base: Decision;
}

export interface PanelAgent {
  ag: string;
  name: string;
  level: Level;
  /** The levels on offer for this grant, least to most permissive. */
  offered: Level[];
  /** The person's rules for this agent, by action name. */
  rules: Record<string, Decision>;
  /**
   * What the hub's policy decides for each action, by name, as the hub said when the agent
   * attached: which actions it confirms and which it refuses. Null when it did not say; the
   * hub may then confirm any action, and the panel reasons as if it confirmed each.
   */
  hub: Record<string, Decision> | null;
  /**
   * Actions the person approved on a prompt and the driver remembers for this grant
   * (`consent.remember: session`): they run without asking again.
   */
  remembered: string[];
  /** Every scope granted at attach, and whether it is switched on now. */
  scopes: { scope: Scope; on: boolean }[];
}

export interface PanelModel {
  agents: PanelAgent[];
  actions: PanelAction[];
  /** The driver could not verify the hub. */
  unverified: boolean;
  /** The policy lets the person end a grant (`human.stop`). */
  canStop: boolean;
}

/** What the person does in the panel. The driver checks each call again before it applies. */
export interface PanelHooks {
  setLevel(ag: string, level: Level): void;
  /** `null` resets: the person's rule goes, and so does a remembered approval, and the action follows the level again. */
  setRule(ag: string, action: string, rule: Decision | null): void;
  setScope(ag: string, scope: Scope, on: boolean): void;
  disconnect(ag: string): void;
}

export const LEVEL_LABEL: Record<Level, string> = { strict: 'Strict', ask: 'Ask', auto: 'Auto', bypass: 'Bypass' };

/** One plain line per level, as the panel shows it. */
export const LEVEL_MEANING: Record<Level, string> = {
  strict: 'Asks you before every action.',
  ask: 'Asks you when the app or the hub says an action needs your approval.',
  auto: 'Runs actions without asking, except those marked dangerous.',
  bypass: 'Runs every action without asking. Actions the app or the hub blocks stay blocked.',
};

const UNVERIFIED_HUB =
  'Unverified hub: this page cannot confirm that this agent comes through your Reins hub. Any program on this computer could be behind it. Continue only if you started this agent yourself.';

type Pending = { ag: string; kind: 'level'; level: Level } | { ag: string; kind: 'rule'; action: string } | { ag: string; kind: 'reset'; action: string };

function rankOf(l: Level): number {
  return LEVELS.indexOf(l);
}

/** An own entry of a record keyed by action name: an action may be called `constructor`. */
function own<T>(o: Record<string, T> | null | undefined, k: string): T | undefined {
  return o && Object.prototype.hasOwnProperty.call(o, k) ? o[k] : undefined;
}

/** The hub's decision for an action. Where the hub did not say, `confirm`: it may ask about anything. */
export function hubOf(agent: PanelAgent, name: string): Decision {
  const d = own(agent.hub, name);
  return d === 'allow' || d === 'confirm' || d === 'deny' ? d : 'confirm';
}

/**
 * The decision the panel reasons from for an action and an agent: the stricter of the
 * app's and the hub's. A request for an action the hub confirms arrives marked `c:1`, and
 * one for an action the hub denies never arrives.
 */
export function baseOf(a: PanelAction, agent: PanelAgent): Decision {
  return stricter(a.base, hubOf(agent, a.name));
}

/** What happens when an agent calls an action: `decideAct`'s outcome, or `run` by an approval the driver remembers. */
export interface Standing {
  outcome: 'run' | 'prompt' | 'denied' | 'blocked';
  by?: 'policy' | 'level' | 'rule' | 'remembered';
}

/**
 * What happens to an action now when this agent calls it: the decision procedure as the
 * driver runs it, from the stricter of the app's decision and the hub's, the person's rule
 * and level, and the approvals the driver remembers. `over` asks about a change instead.
 */
export function standing(a: PanelAction, agent: PanelAgent, over: { level?: Level; rule?: Decision | null; forget?: boolean } = {}): Standing {
  const rule = over.rule === null ? undefined : (over.rule ?? own(agent.rules, a.name));
  const q: Parameters<typeof decideAct>[0] = { base: baseOf(a, agent), risk: a.risk, level: over.level ?? agent.level, offered: agent.offered };
  if (rule !== undefined) q.rule = rule;
  const v = decideAct(q);
  // An approval is remembered only from a request the hub did not mark, and answers only such requests.
  if (v.outcome === 'prompt' && v.remember === true && !over.forget && agent.remembered.includes(a.name)) return { outcome: 'run', by: 'remembered' };
  return v;
}

/**
 * The actions that do not run without asking now (they ask, or the person blocked them) and
 * would after the change: a level, a rule for one action, or with `d: null` its reset.
 */
export function stopsAsking(model: PanelModel, agent: PanelAgent, change: { level?: Level; rule?: { action: string; d: Decision | null } }): string[] {
  const out: string[] = [];
  for (const a of model.actions) {
    const now = standing(a, agent).outcome;
    if (now === 'run' || now === 'denied') continue;
    const r = change.rule;
    const after = r && r.action === a.name ? standing(a, agent, { rule: r.d, forget: r.d === null }) : standing(a, agent, change.level === undefined ? {} : { level: change.level });
    if (after.outcome === 'run') out.push(a.name);
  }
  return out;
}

export class PermissionsTab implements PanelTab {
  readonly id = 'permissions';
  readonly label = 'Permissions';
  #kit: PanelKit;
  #hooks: PanelHooks;
  #model: PanelModel = { agents: [], actions: [], unverified: false, canStop: false };
  #pending: Pending | null = null;
  #armedAt = 0;
  #armTimer: Timer | undefined;
  #confirmBtn: HTMLButtonElement | null = null;
  /** Where the tab is drawn, while it is the one showing. */
  #body: HTMLElement | null = null;
  #seq = 0;
  /** A hook is running: the change that comes back is the person's own. */
  #acting = false;
  /** Until then the controls that let an agent do more ignore activation: what is under the pointer just changed. */
  #settleAt = 0;
  /** A confirm step was just opened: the next draw scrolls it into view. */
  #reveal = false;

  constructor(kit: PanelKit, hooks: PanelHooks) {
    this.#kit = kit;
    this.#hooks = hooks;
  }

  /** A new state from the driver. Returns whether anything the tab shows changed. */
  update(model: PanelModel): boolean {
    const changed = JSON.stringify(model) !== JSON.stringify(this.#model);
    this.#model = model;
    // Something other than the person's own click redrew the list while it was showing (an
    // agent attached or left): a click aimed at what was there must not land on what is.
    if (changed && !this.#acting && this.#body) this.settle();
    // A confirm step for an agent that left, or for a change that no longer applies, is dropped.
    if (this.#pending && !this.#stillPending(this.#pending)) this.#drop();
    return changed;
  }

  /**
   * What is under the pointer changed, or is about to, without the person aiming at it: the
   * list was redrawn, a confirm step or a consent card went away. For `armMs` no control
   * that lets an agent do more takes a click, so neither a click on its way nor the second
   * half of a double click lands on one.
   */
  settle(): void {
    this.#settleAt = this.#kit.now() + this.#kit.armMs;
  }

  #agent(ag: string): PanelAgent | undefined {
    return this.#model.agents.find((a) => a.ag === ag);
  }

  #find(name: string): PanelAction | undefined {
    return this.#model.actions.find((x) => x.name === name);
  }

  #stillPending(p: Pending): boolean {
    const agent = this.#agent(p.ag);
    if (!agent) return false;
    if (p.kind === 'level') return agent.offered.includes(p.level) && agent.level !== p.level;
    const a = this.#find(p.action);
    if (a === undefined || baseOf(a, agent) === 'deny') return false;
    if (p.kind === 'reset') return own(agent.rules, p.action) !== undefined || agent.remembered.includes(p.action);
    return own(agent.rules, p.action) !== 'allow' && this.#mayAllow(a, agent);
  }

  /**
   * May the person set the rule `allow` for this action: never where the app or the hub
   * denies it, and where either asks about it only if a level on offer would waive the same
   * prompt. Where the hub did not say what it asks about, it counts as asking.
   */
  #mayAllow(a: PanelAction, agent: PanelAgent): boolean {
    const base = baseOf(a, agent);
    return base === 'allow' || (base === 'confirm' && allowRulePermitted(a.risk, agent.offered));
  }

  /**
   * Open the confirm step for a change that lets an agent do more. It comes up under or
   * near the pointer and moves what is there, so nothing else that loosens takes a click for
   * a moment; its own button is armed after the same delay.
   */
  #ask(p: Pending): void {
    this.#pending = p;
    this.#reveal = true;
    this.settle();
    this.#redraw();
  }

  /**
   * May a control that lets an agent do more take this click: not while what is under the
   * pointer has just changed, and not while the overlay cannot be relied on.
   */
  #mayLoosen(): boolean {
    return this.#settled() && this.#kit.sound();
  }

  #drop(): void {
    this.#pending = null;
    this.#confirmBtn = null;
    if (this.#armTimer) this.#kit.cancel(this.#armTimer);
    this.#armTimer = undefined;
    this.#armedAt = 0;
  }

  hidden(): void {
    this.#drop();
    this.#body = null;
    this.#settleAt = 0;
  }

  /** Run one of the driver's hooks for a click of the person. */
  #apply(fn: () => void): void {
    this.#acting = true;
    try {
      fn();
    } finally {
      this.#acting = false;
    }
    // Whether or not the driver took it, the tab shows what is true now.
    this.#redraw();
  }

  #settled(): boolean {
    return this.#kit.now() >= this.#settleAt;
  }

  /** Start the arming delay of the confirm step again. */
  rearm(): void {
    if (!this.#pending) return;
    if (this.#armTimer) this.#kit.cancel(this.#armTimer);
    this.#armedAt = this.#kit.now() + this.#kit.armMs;
    this.#armTimer = this.#kit.later(() => {
      this.#armTimer = undefined;
      // The delay has run: do not ask the clock again (a timer can fire a moment early).
      this.#armedAt = 0;
      this.#showArmed();
    }, this.#kit.armMs);
    this.#showArmed();
  }

  #showArmed(): void {
    const b = this.#confirmBtn;
    if (!b) return;
    const wait = this.#kit.now() < this.#armedAt;
    b.classList.toggle('wait', wait);
    if (wait) b.setAttribute('aria-disabled', 'true');
    else b.removeAttribute('aria-disabled');
  }

  #redraw(): void {
    if (this.#body) this.render(this.#body);
  }

  render(body: HTMLElement): void {
    const kit = this.#kit;
    this.#body = body;
    // Keep the person's place: the control that had focus gets it back by its key.
    const root = body.getRootNode() as ShadowRoot | Document;
    const active = root.activeElement as HTMLElement | null;
    const key = active && body.contains(active) ? active.getAttribute('data-k') : null;
    const scroll = body.scrollTop;
    this.#confirmBtn = null;
    body.replaceChildren();
    if (!this.#model.agents.length) body.append(kit.el('p', 'empty', 'No AI agent is connected.'));
    for (const agent of this.#model.agents) body.append(this.#section(agent));
    if (this.#pending) this.rearm();
    body.scrollTop = scroll;
    // A confirm step that has just come up is brought into view: the person reads what they confirm.
    if (this.#reveal) {
      this.#reveal = false;
      try {
        // Drawing the sections set the button of the step that is showing.
        (this.#confirmBtn as HTMLButtonElement | null)?.closest('.confirm')?.scrollIntoView({ block: 'nearest' });
      } catch {
        // no layout
      }
    }
    if (key !== null) {
      const again = Array.from(body.querySelectorAll<HTMLElement>('[data-k]')).find((e) => e.getAttribute('data-k') === key);
      try {
        again?.focus({ preventScroll: true });
      } catch {
        // ignore
      }
    }
  }

  #heading(text: string): HTMLElement {
    const h = this.#kit.el('h4', undefined, text);
    h.id = `${PANEL_ID}-h${++this.#seq}`;
    return h;
  }

  #section(agent: PanelAgent): HTMLElement {
    const kit = this.#kit;
    // The agent's own name, quoted, and its session id: two agents with one name are two headings.
    const name = agentLabel(agent.name, agent.ag);
    const sec = kit.el('section', 'agent');
    sec.setAttribute('aria-label', name);

    const head = kit.el('div', 'ahead');
    head.append(kit.el('h3', undefined, name));
    if (this.#model.unverified) {
      const flag = kit.el('span', 'flag', 'Unverified hub');
      flag.title = 'This page could not verify the Reins hub it is connected to';
      head.append(flag);
    }
    if (this.#model.canStop) {
      const off = kit.button('Disconnect', 'danger sm', () => this.#apply(() => this.#hooks.disconnect(agent.ag)));
      off.setAttribute('aria-label', `Disconnect ${name} and revoke its access`);
      off.setAttribute('data-k', `off:${agent.ag}`);
      head.append(off);
    }
    sec.append(head);

    // ── level ──
    const lh = this.#heading('How much it asks you');
    const group = kit.el('div', 'opts');
    group.setAttribute('role', 'radiogroup');
    group.setAttribute('aria-labelledby', lh.id);
    for (const level of agent.offered) {
      const on = level === agent.level;
      const b = kit.button('', `opt l-${level}`, () => this.#chooseLevel(agent.ag, level));
      b.setAttribute('role', 'radio');
      b.setAttribute('aria-checked', String(on));
      b.setAttribute('data-k', `level:${agent.ag}:${level}`);
      b.tabIndex = on ? 0 : -1;
      b.append(kit.el('span', 'mk'), kit.el('span', 'ol', LEVEL_LABEL[level]), kit.el('span', 'od', LEVEL_MEANING[level]));
      group.append(b);
    }
    sec.append(lh, group);
    if (!agent.offered.includes('auto') && !agent.offered.includes('bypass')) sec.append(kit.el('p', 'note', 'This app or its hub offers no level that asks less.'));
    const p = this.#pending;
    if (p && p.ag === agent.ag && p.kind === 'level') sec.append(this.#confirmLevel(agent, p.level));

    // ── actions ──
    if (this.#model.actions.length) {
      sec.append(this.#heading('Actions'), kit.el('p', 'note', 'A rule you set here covers that action with any arguments, until this agent disconnects.'));
      if (agent.hub === null) sec.append(kit.el('p', 'note', 'This hub did not say which actions it asks about, so each is shown as asking.'));
      const list = kit.el('ul', 'acts');
      for (const a of this.#model.actions) list.append(this.#action(agent, a));
      sec.append(list);
    }

    // ── scopes ──
    if (agent.scopes.length) {
      sec.append(this.#heading('What it may do'));
      const list = kit.el('ul', 'scopes');
      for (const s of agent.scopes) {
        const li = kit.el('li');
        const sw = kit.button('', 'sw', () => {
          // Switching off always applies. Switching back on lets the agent do more.
          if (!s.on && !this.#mayLoosen()) return;
          this.#apply(() => this.#hooks.setScope(agent.ag, s.scope, !s.on));
        });
        sw.setAttribute('role', 'switch');
        sw.setAttribute('aria-checked', String(s.on));
        sw.setAttribute('data-k', `scope:${agent.ag}:${s.scope}`);
        sw.append(kit.el('span', 'tr'), kit.el('span', 'sk', s.scope), kit.el('span', 'sd', SCOPE_MEANING[s.scope] ?? s.scope));
        li.append(sw);
        list.append(li);
      }
      sec.append(list);
    }
    return sec;
  }

  #action(agent: PanelAgent, a: PanelAction): HTMLElement {
    const kit = this.#kit;
    const li = kit.el('li', 'act');
    const row = kit.el('div', 'arow');
    row.append(kit.el('span', 'an', kit.show(a.name, 80)), kit.el('span', `risk ${a.risk}`, a.risk));
    li.append(row);
    // The stricter of the app's decision and the hub's is what the request meets.
    if (baseOf(a, agent) === 'deny') {
      row.append(kit.el('span', 'blocked', a.base === 'deny' ? 'Blocked by app' : 'Blocked by hub'));
      return li;
    }
    const hubAsks = a.base === 'allow' && hubOf(agent, a.name) === 'confirm';
    const st = standing(a, agent);
    const now: Decision = st.outcome === 'run' ? 'allow' : st.outcome === 'prompt' ? 'confirm' : 'deny';
    const rule = own(agent.rules, a.name);
    const mayAllow = this.#mayAllow(a, agent);
    const seg = kit.el('span', 'seg');
    seg.setAttribute('role', 'group');
    seg.setAttribute('aria-label', `${kit.show(a.name, 80)}: what happens when ${agentLabel(agent.name, agent.ag, { lead: true })} calls it`);
    const choices: [Decision, string][] = [
      ['allow', 'Allow'],
      ['confirm', 'Ask'],
      ['deny', 'Block'],
    ];
    for (const [d, label] of choices) {
      const b = kit.button(label, `b-${d}`, () => this.#chooseRule(agent.ag, a, d));
      b.setAttribute('aria-pressed', String(now === d));
      b.setAttribute('data-k', `rule:${agent.ag}:${a.name}:${d}`);
      if (d === 'allow' && !mayAllow) {
        b.setAttribute('aria-disabled', 'true');
        b.title = 'Not available for this action here';
      }
      seg.append(b);
    }
    row.append(seg);

    // Why it stands as it does: the person's rule, an approval the driver remembers, or the
    // level. Reset takes away the first two.
    const sub = kit.el('div', 'asub');
    const remembered = rule === undefined && st.by === 'remembered';
    if (rule !== undefined) sub.append(kit.el('span', 'src', 'Your rule'));
    else if (remembered) sub.append(kit.el('span', 'src', agent.hub === null ? 'You approved it earlier. The hub may still ask' : 'You approved it earlier'));
    else sub.append(kit.el('span', 'src', 'Follows the level'));
    if (hubAsks && agent.hub !== null) sub.append(kit.el('span', 'src', 'The hub asks about it'));
    if (rule !== undefined || remembered) {
      const reset = kit.button('Reset', 'link', () => this.#chooseRule(agent.ag, a, null));
      reset.setAttribute('aria-label', `Reset ${kit.show(a.name, 80)} to follow the level`);
      reset.setAttribute('data-k', `rule:${agent.ag}:${a.name}:reset`);
      sub.append(reset);
    }
    li.append(sub);
    if (!mayAllow) {
      const need = a.risk === 'dangerous' ? LEVEL_LABEL.bypass : LEVEL_LABEL.auto;
      const who = a.base === 'confirm' ? 'the app asks about this action' : agent.hub === null ? 'the hub may ask about this action' : 'the hub asks about this action';
      li.append(kit.el('p', 'why', `Allow is off: ${who}, and only the ${need} level could waive that. This app or its hub does not offer it.`));
    }
    const p = this.#pending;
    if (p && p.ag === agent.ag && p.kind !== 'level' && p.action === a.name) {
      if (p.kind === 'rule') li.append(this.#confirmRule(agent, a));
      else if (p.kind === 'reset') li.append(this.#confirmReset(agent, a));
    }
    return li;
  }

  // ── choosing ──

  /**
   * Every click that can make an action run without asking takes the confirm step, armed
   * after a delay: there is no exception, so no single click loosens anything. That is the
   * levels `auto` and `bypass` above the present one, any level under which an action that
   * asks now would stop asking (`ask` after `strict`), the rule `allow`, and a reset after
   * which the action runs unasked. Everything else applies at once.
   */
  #chooseLevel(ag: string, level: Level): void {
    const agent = this.#agent(ag);
    if (!agent || !agent.offered.includes(level)) return;
    if (level === agent.level) {
      if (this.#pending) {
        this.#drop();
        this.#redraw();
      }
      return;
    }
    const up = rankOf(level) > rankOf(agent.level);
    if ((up && (level === 'auto' || level === 'bypass')) || stopsAsking(this.#model, agent, { level }).length > 0) {
      if (!this.#mayLoosen()) return;
      this.#ask({ ag, kind: 'level', level });
      return;
    }
    this.#drop();
    this.#apply(() => this.#hooks.setLevel(ag, level));
  }

  #chooseRule(ag: string, a: PanelAction, d: Decision | null): void {
    const agent = this.#agent(ag);
    if (!agent || baseOf(a, agent) === 'deny') return;
    const now = standing(a, agent).outcome;
    if (d === 'allow') {
      if (!this.#mayAllow(a, agent) || own(agent.rules, a.name) === 'allow') return;
      // Whatever it waives today, the rule lets the action run unasked from here on, also
      // under a stricter level: always confirmed.
      if (!this.#mayLoosen()) return;
      this.#ask({ ag, kind: 'rule', action: a.name });
      return;
    }
    // Reset takes the person's rule away, and an approval the driver remembers. Where the
    // action then runs without asking (their own Ask or Block was all that held it), that is
    // a change like Allow.
    if (d === null && now !== 'run' && standing(a, agent, { rule: null, forget: true }).outcome === 'run') {
      if (!this.#mayLoosen()) return;
      this.#ask({ ag, kind: 'reset', action: a.name });
      return;
    }
    // Ask, Block, and a reset after which the action asks. Lifting a Block lets the agent do
    // more, so it waits for the list to settle; the rest applies at once.
    if (d !== 'deny' && now === 'blocked' && !this.#mayLoosen()) return;
    this.#drop();
    this.#apply(() => this.#hooks.setRule(ag, a.name, d));
  }

  // ── the confirm step ──

  #confirmBox(title: string, lines: (string | string[])[], action: string, apply: () => void): HTMLElement {
    const kit = this.#kit;
    const box = kit.el('div', 'confirm');
    box.setAttribute('role', 'group');
    box.setAttribute('aria-label', title);
    box.append(kit.el('p', 'ct', title));
    if (this.#model.unverified) box.append(kit.el('p', 'warn', UNVERIFIED_HUB));
    for (const l of lines) {
      if (typeof l === 'string') box.append(kit.el('p', undefined, l));
      else {
        const ul = kit.el('ul', 'cl');
        for (const x of l) ul.append(kit.el('li', undefined, x));
        box.append(ul);
      }
    }
    const row = kit.el('div', 'cb');
    // When this box goes, what was below it comes under the pointer: `settle` keeps the
    // second half of a double click from landing on a control that lets the agent do more.
    const cancel = kit.button('Cancel', 'sm', () => {
      this.#drop();
      this.settle();
      this.#redraw();
    });
    cancel.setAttribute('data-k', 'confirm:cancel');
    const go = kit.button(action, 'primary sm', () => {
      if (kit.now() < this.#armedAt || !kit.sound()) return;
      const p = this.#pending;
      this.#drop();
      this.settle();
      if (p && this.#stillPending(p)) apply();
      else this.#redraw();
    });
    go.setAttribute('data-k', 'confirm:go');
    this.#confirmBtn = go;
    row.append(cancel, go);
    box.append(row);
    return box;
  }

  #confirmLevel(agent: PanelAgent, level: Level): HTMLElement {
    const kit = this.#kit;
    const name = agentLabel(agent.name, agent.ag);
    // Every action that asks now and would not: also those only the hub asks about.
    const stops = stopsAsking(this.#model, agent, { level }).map((n) => kit.show(n, 80));
    const lines: (string | string[])[] = [];
    if (stops.length) {
      lines.push(`${name} will then run ${stops.length === 1 ? 'this action' : 'these actions'} without asking you, with any arguments:`, stops);
    } else lines.push(`No action of this app asks you about ${name} right now, so nothing changes at once.`);
    lines.push(
      level === 'auto'
        ? 'Actions marked dangerous still ask. Actions the app or the hub blocks stay blocked, and your own Ask and Block rules stay.'
        : level === 'bypass'
          ? 'This includes actions marked dangerous. Actions the app or the hub blocks stay blocked, and your own Ask and Block rules stay.'
          : 'Actions the app or the hub wants confirmed still ask, and your own Ask and Block rules stay.',
      'It lasts until this agent disconnects or you change it here.',
    );
    return this.#confirmBox(`Set ${name} to ${LEVEL_LABEL[level]}?`, lines, `Set to ${LEVEL_LABEL[level]}`, () => this.#apply(() => this.#hooks.setLevel(agent.ag, level)));
  }

  #confirmRule(agent: PanelAgent, a: PanelAction): HTMLElement {
    const kit = this.#kit;
    const name = agentLabel(agent.name, agent.ag);
    const action = kit.show(a.name, 80);
    const lines = [`${name} will then run ${action} without asking you, with any arguments${a.risk === 'safe' ? '' : `. The app marks this action ${a.risk}`}.`];
    if (a.base === 'allow' && hubOf(agent, a.name) === 'confirm') lines.push(agent.hub === null ? 'The hub may want this action confirmed. This rule answers that for you from now on.' : 'The hub wants this action confirmed. This rule answers that for you from now on.');
    lines.push('It lasts until this agent disconnects or you change it here, whatever the level.');
    return this.#confirmBox(`Always allow ${action}?`, lines, 'Always allow', () => this.#apply(() => this.#hooks.setRule(agent.ag, a.name, 'allow')));
  }

  /** Reset, where the action would then run without asking: the person's own Ask or Block is all that holds it. */
  #confirmReset(agent: PanelAgent, a: PanelAction): HTMLElement {
    const kit = this.#kit;
    const name = agentLabel(agent.name, agent.ag);
    const action = kit.show(a.name, 80);
    const after = standing(a, agent, { rule: null, forget: true });
    const lines = [
      `Your rule for ${action} goes. ${name} will then run it without asking you, with any arguments: ${after.by === 'level' ? `the ${LEVEL_LABEL[agent.level]} level lets it` : 'nothing else asks about it'}${a.risk === 'safe' ? '' : `. The app marks this action ${a.risk}`}.`,
      'It lasts until this agent disconnects or you change it here.',
    ];
    return this.#confirmBox(`Reset ${action}?`, lines, 'Reset', () => this.#apply(() => this.#hooks.setRule(agent.ag, a.name, null)));
  }
}

// ───────────────────────────── the Activity tab ─────────────────────────────

/**
 * One line of the activity log. It holds a time, the agent's name, a method or action name
 * and an outcome: never arguments, results or page text.
 */
export interface ActivityEntry {
  /** Epoch milliseconds of the latest occurrence. */
  t: number;
  /** The agent's display name. */
  agent: string;
  /** The agent's session id: two agents with one name are two agents here too. */
  ag: string;
  /** A protocol method, the name of a declared action, or what the person changed. */
  what: string;
  /** `ok`, an error code, or empty for a change the person made. */
  outcome: string;
  /** For an action that ran: who let it. The person on a prompt, the level, a rule, or an earlier approval. */
  by?: 'person' | 'level' | 'rule' | 'remembered';
  /** The person did this in the panel (a level, a rule, a scope switch). */
  you?: boolean;
  /** How many times in a row. */
  n: number;
}

export const ACTIVITY_MAX = 50;

const BY_TEXT: Record<NonNullable<ActivityEntry['by']>, string> = {
  person: 'you approved',
  level: 'allowed by the level',
  rule: 'allowed by your rule',
  remembered: 'approved earlier',
};

function clock(t: number): string {
  const d = new Date(t);
  const two = (n: number) => String(n).padStart(2, '0');
  return `${two(d.getHours())}:${two(d.getMinutes())}:${two(d.getSeconds())}`;
}

export class ActivityTab implements PanelTab {
  readonly id = 'activity';
  readonly label = 'Activity';
  #kit: PanelKit;
  #entries: readonly ActivityEntry[] = [];

  constructor(kit: PanelKit) {
    this.#kit = kit;
  }

  /** The log, newest last, at most ACTIVITY_MAX entries. */
  update(entries: readonly ActivityEntry[]): void {
    this.#entries = entries;
  }

  render(body: HTMLElement): void {
    const kit = this.#kit;
    const scroll = body.scrollTop;
    body.replaceChildren();
    if (!this.#entries.length) {
      body.append(kit.el('p', 'empty', 'Nothing yet. Commands from AI agents show up here.'));
      return;
    }
    body.append(kit.el('p', 'note', `The last ${ACTIVITY_MAX} commands, newest first. Arguments and page content are not kept here.`));
    const list = kit.el('ul', 'log');
    for (let i = this.#entries.length - 1; i >= 0; i--) {
      const e = this.#entries[i]!;
      const li = kit.el('li', e.you ? 'you' : '');
      const time = kit.el('time', 'lt', clock(e.t));
      const what = kit.el('span', 'lw', `${kit.show(e.what, 80)}${e.n > 1 ? ` ×${e.n}` : ''}`);
      // The name in quotation marks with the session id, as wherever the overlay names an agent.
      const name = agentLabel(e.agent, e.ag, { max: 40 });
      const who = kit.el('span', 'la', e.you ? `You, for ${name}` : name);
      li.append(time, what);
      if (e.outcome) li.append(kit.el('span', `lo ${e.outcome === 'ok' ? 'ok' : 'err'}`, e.outcome === 'ok' ? 'ok' : kit.show(e.outcome, 24)));
      li.append(who);
      if (e.by) li.append(kit.el('span', 'lb', BY_TEXT[e.by]));
      list.append(li);
    }
    body.append(list);
    body.scrollTop = scroll;
  }
}

