import type { Schema } from './protocol.js';
import { FORBIDDEN_KEYS, hasOwn, isPlainObject, own } from './util.js';

/** Property names a schema may declare. `__proto__`, `constructor` and `prototype` are refused. */
const PROP_NAME = /^[A-Za-z_][A-Za-z0-9_.-]{0,63}$/;
/** Deepest schema nesting `checkSchema` accepts. Bounds the recursion of `validate` too. */
const MAX_SCHEMA_DEPTH = 16;

const ALLOWED_KEYS: Record<string, readonly string[]> = {
  string: ['type', 'description', 'enum', 'minLength', 'maxLength', 'pattern'],
  number: ['type', 'description', 'minimum', 'maximum'],
  integer: ['type', 'description', 'minimum', 'maximum'],
  boolean: ['type', 'description'],
  array: ['type', 'description', 'items', 'minItems', 'maxItems'],
  object: ['type', 'description', 'properties', 'required'],
};

const regexCache = new WeakMap<object, RegExp>();
function patternOf(schema: { pattern?: string }): RegExp | null {
  if (schema.pattern === undefined) return null;
  let re = regexCache.get(schema);
  if (!re) {
    re = new RegExp(schema.pattern, 'u');
    regexCache.set(schema, re);
  }
  return re;
}

function codePoints(s: string): number {
  let n = 0;
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    if (c >= 0xd800 && c <= 0xdbff && i + 1 < s.length) {
      const d = s.charCodeAt(i + 1);
      if (d >= 0xdc00 && d <= 0xdfff) i++;
    }
    n++;
  }
  return n;
}

/**
 * A string as a JSON string that is one line to every reader. `JSON.stringify` escapes the
 * line feed and the other C0 controls, and leaves U+007F to U+009F, U+2028 and U+2029 as
 * they are, although a reader may end a line at U+0085, U+2028 or U+2029 and a terminal acts
 * on the rest. Here they are written as `\uXXXX` too. The result is JSON for the same string.
 * Every text a page chose that is printed quoted (a name or a value in the tree, an enum
 * value on the prompt card) is printed with this.
 */
export function jsonLine(s: string): string {
  // eslint-disable-next-line no-control-regex
  return JSON.stringify(s).replace(/[\u007f-\u009f\u2028\u2029]/g, (c) => `\\u${c.charCodeAt(0).toString(16).padStart(4, '0')}`);
}

function child(path: string, key: string): string {
  return /^[A-Za-z_][A-Za-z0-9_]*$/.test(key) ? `${path}.${key}` : `${path}[${jsonLine(key)}]`;
}

// ───────────────────────────── checkSchema ─────────────────────────────

function isCount(v: unknown): boolean {
  return typeof v === 'number' && Number.isSafeInteger(v) && v >= 0;
}

/** Is `schema` a well-formed schema-lite schema. Returns null, or `"path: reason"`. Unknown keywords are refused. */
export function checkSchema(schema: unknown): string | null {
  return checkAt(schema, '$', 0);
}

function checkAt(s: unknown, path: string, depth: number): string | null {
  if (depth > MAX_SCHEMA_DEPTH) return `${path}: nested too deeply`;
  if (!isPlainObject(s)) return `${path}: schema must be an object`;
  const type = own(s, 'type');
  if (typeof type !== 'string' || !hasOwn(ALLOWED_KEYS, type)) return `${path}: unknown type`;
  const allowed = ALLOWED_KEYS[type]!;
  for (const k of Object.keys(s)) if (!allowed.includes(k)) return `${path}: keyword ${jsonLine(k)} not allowed for ${type}`;
  if (s.description !== undefined && typeof s.description !== 'string') return `${path}: description must be a string`;
  switch (type) {
    case 'string': {
      if (s.enum !== undefined) {
        if (!Array.isArray(s.enum) || s.enum.length === 0 || !s.enum.every((x) => typeof x === 'string')) return `${path}: enum must be a non-empty string array`;
      }
      if (s.minLength !== undefined && !isCount(s.minLength)) return `${path}: minLength must be a non-negative integer`;
      if (s.maxLength !== undefined && !isCount(s.maxLength)) return `${path}: maxLength must be a non-negative integer`;
      if (s.minLength !== undefined && s.maxLength !== undefined && (s.minLength as number) > (s.maxLength as number)) return `${path}: minLength exceeds maxLength`;
      if (s.pattern !== undefined) {
        if (typeof s.pattern !== 'string') return `${path}: pattern must be a string`;
        try {
          new RegExp(s.pattern, 'u');
        } catch {
          return `${path}: invalid pattern`;
        }
      }
      return null;
    }
    case 'number':
    case 'integer': {
      for (const k of ['minimum', 'maximum'] as const) {
        const v = s[k];
        if (v !== undefined && (typeof v !== 'number' || !Number.isFinite(v))) return `${path}: ${k} must be a finite number`;
      }
      if (s.minimum !== undefined && s.maximum !== undefined && (s.minimum as number) > (s.maximum as number)) return `${path}: minimum exceeds maximum`;
      return null;
    }
    case 'boolean':
      return null;
    case 'array': {
      if (s.minItems !== undefined && !isCount(s.minItems)) return `${path}: minItems must be a non-negative integer`;
      if (s.maxItems !== undefined && !isCount(s.maxItems)) return `${path}: maxItems must be a non-negative integer`;
      if (s.minItems !== undefined && s.maxItems !== undefined && (s.minItems as number) > (s.maxItems as number)) return `${path}: minItems exceeds maxItems`;
      if (!hasOwn(s, 'items')) return `${path}: items is required`;
      return checkAt(s.items, `${path}[]`, depth + 1);
    }
    case 'object': {
      const props = own(s, 'properties');
      if (!isPlainObject(props)) return `${path}: properties must be an object`;
      for (const k of Object.keys(props)) {
        if (FORBIDDEN_KEYS.has(k) || !PROP_NAME.test(k)) return `${path}: invalid property name ${jsonLine(k)}`;
        const err = checkAt(props[k], child(path, k), depth + 1);
        if (err) return err;
      }
      if (s.required !== undefined) {
        const req = s.required;
        if (!Array.isArray(req)) return `${path}: required must be an array`;
        const seen = new Set<string>();
        for (const r of req) {
          if (typeof r !== 'string' || !hasOwn(props, r)) return `${path}: required names an undeclared property`;
          if (seen.has(r)) return `${path}: duplicate required property`;
          seen.add(r);
        }
      }
      return null;
    }
  }
  return `${path}: unknown type`;
}

// ───────────────────────────── validate ─────────────────────────────

/**
 * Validate `value` against `schema`. Returns null when valid, else `"path: reason"` with
 * `$` as the root. Objects reject undeclared properties. With no schema, only `undefined`
 * or an empty object is accepted (the action takes no arguments).
 */
export function validate(schema: Schema | undefined, value: unknown): string | null {
  if (schema === undefined) {
    if (value === undefined || (isPlainObject(value) && Object.keys(value).length === 0)) return null;
    return '$: takes no arguments';
  }
  return validateAt(schema, value, '$', 0);
}

function typeName(v: unknown): string {
  if (v === null) return 'null';
  if (Array.isArray(v)) return 'array';
  return typeof v;
}

function validateAt(s: Schema, v: unknown, path: string, depth: number): string | null {
  if (depth > MAX_SCHEMA_DEPTH || !isPlainObject(s)) return `${path}: invalid schema`;
  switch (s.type) {
    case 'string': {
      if (typeof v !== 'string') return `${path}: expected string, got ${typeName(v)}`;
      if (s.enum !== undefined && !s.enum.includes(v)) return `${path}: must be one of ${s.enum.map((x) => jsonLine(x)).join(', ')}`;
      if (s.minLength !== undefined || s.maxLength !== undefined) {
        const n = codePoints(v);
        if (s.minLength !== undefined && n < s.minLength) return `${path}: shorter than ${s.minLength}`;
        if (s.maxLength !== undefined && n > s.maxLength) return `${path}: longer than ${s.maxLength}`;
      }
      let re: RegExp | null;
      try {
        re = patternOf(s);
      } catch {
        return `${path}: invalid schema`;
      }
      if (re && !re.test(v)) return `${path}: does not match pattern`;
      return null;
    }
    case 'number':
    case 'integer': {
      if (typeof v !== 'number' || !Number.isFinite(v)) return `${path}: expected ${s.type === 'integer' ? 'integer' : 'number'}, got ${typeName(v)}`;
      if (s.type === 'integer' && !Number.isInteger(v)) return `${path}: expected integer`;
      if (s.minimum !== undefined && v < s.minimum) return `${path}: below minimum ${s.minimum}`;
      if (s.maximum !== undefined && v > s.maximum) return `${path}: above maximum ${s.maximum}`;
      return null;
    }
    case 'boolean':
      return typeof v === 'boolean' ? null : `${path}: expected boolean, got ${typeName(v)}`;
    case 'array': {
      if (!Array.isArray(v)) return `${path}: expected array, got ${typeName(v)}`;
      if (s.minItems !== undefined && v.length < s.minItems) return `${path}: fewer than ${s.minItems} items`;
      if (s.maxItems !== undefined && v.length > s.maxItems) return `${path}: more than ${s.maxItems} items`;
      for (let i = 0; i < v.length; i++) {
        const err = validateAt(s.items, v[i], `${path}[${i}]`, depth + 1);
        if (err) return err;
      }
      return null;
    }
    case 'object': {
      if (!isPlainObject(v)) return `${path}: expected object, got ${typeName(v)}`;
      const props = s.properties;
      for (const k of Object.keys(v)) {
        if (!isPlainObject(props) || !hasOwn(props, k)) return `${child(path, k)}: not allowed`;
      }
      for (const r of s.required ?? []) {
        if (!hasOwn(v, r) || v[r] === undefined) return `${child(path, r)}: required`;
      }
      for (const k of Object.keys(v)) {
        if (v[k] === undefined) continue;
        const err = validateAt(props[k]!, v[k], child(path, k), depth + 1);
        if (err) return err;
      }
      return null;
    }
  }
  return `${path}: invalid schema`;
}

// ───────────────────────────── signatures ─────────────────────────────

function range(min: number | undefined, max: number | undefined): string {
  if (min === undefined && max === undefined) return '';
  return ` ${min ?? ''}..${max ?? ''}`;
}

function typeSig(s: Schema): string {
  switch (s.type) {
    case 'string':
      return s.enum ? s.enum.map((x) => jsonLine(x)).join('|') : 'str';
    case 'integer':
      return `int${range(s.minimum, s.maximum)}`;
    case 'number':
      return `num${range(s.minimum, s.maximum)}`;
    case 'boolean':
      return 'bool';
    case 'array':
      return `[${typeSig(s.items)}]`;
    case 'object':
      return `{${propsSig(s)}}`;
  }
  return '?';
}

function propsSig(s: Extract<Schema, { type: 'object' }>): string {
  const req = new Set(s.required ?? []);
  return Object.keys(s.properties)
    .map((k) => `${k}${req.has(k) ? '' : '?'}: ${typeSig(s.properties[k]!)}`)
    .join(', ');
}

/** Compact signature for the prompt card: `(sku: "latte"|"mocha", qty?: int 1..9)`. */
export function schemaSignature(schema: Schema | undefined): string {
  if (schema === undefined) return '()';
  if (schema.type === 'object') return `(${propsSig(schema)})`;
  return `(${typeSig(schema)})`;
}
